(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-private-3-e", [{"sp": "HDR", "t": "Λόγοι ἰδιωτικοί Νʹ–ΝΘʹ"}, {"sp": "HDR", "t": "Πρὸς Πολυκλέα περὶ τοῦ ἐπιτριηραρχήματος", "st": "50"}, {"sp": "N", "t": "τοῖς τοιούτοις τῶν ἀγώνων, ὦ ἄνδρες δικασταί, καὶ τοὺς διαγνωσομένους προσήκει μάλιστα προσέχειν τὸν νοῦν. οὐ γὰρ ἐμὸς καὶ Πολυκλέους ἴδιός ἐστιν ὁ ἀγὼν μόνον, ἀλλὰ καὶ τῆς πόλεως κοινός. ὧν γὰρ τὰ μὲν ἐγκλήματα ἴδιά ἐστιν, αἱ δὲ βλάβαι κοιναί, πῶς οὐχ ὑπὲρ τούτων εἰκός ἐστιν ἀκούσαντας ὑμᾶς ὀρθῶς διαγνῶναι; εἰ μὲν γὰρ περὶ ἄλλου τινὸς συμβολαίου ἐγὼ διαφερόμενος πρὸς Πολυκλέα εἰσῄειν εἰς ὑμᾶς, ἐμὸς ἂν ἦν καὶ Πολυκλέους ὁ ἀγών· νῦν δὲ περί τε διαδοχῆς νεώς ἐστιν ὁ λόγος καὶ ἐπιτριηραρχήματος πέντε μηνῶν καὶ ἓξ ἡμερῶν ἀνηλωμένου, καὶ περὶ τῶν νόμων, πότερα κύριοί εἰσιν ἢ οὔ.", "st": "50.1"}, {"sp": "N", "t": "ἀναγκαῖον δή μοι δοκεῖ εἶναι ἅπαντα ἐξ ἀρχῆς διηγήσασθαι πρὸς ὑμᾶς. καὶ πρὸς θεῶν, ἄνδρες δικασταί, δέομαι ὑμῶν, μή με ἡγήσησθε ἀδολεσχεῖν, ἐὰν διὰ μακροτέρων διηγῶμαι τά τε ἀναλώματα καὶ τὰς πράξεις, ὡς ἐν καιρῷ τε ἕκασται καὶ χρήσιμοι τῇ πόλει ἐδιακονήθησαν. εἰ μὲν γάρ τις ἔχει με ἐπιδεῖξαι ὡς ψεύδομαι, ἀναστὰς ἐν τῷ ἐμῷ ὕδατι ἐξελεγξάτω, ὅ τι ἂν μὴ φῇ με ἀληθῆ λέγειν πρὸς ὑμᾶς· εἰ δ’ ἐστὶν ἀληθῆ καὶ μηδεὶς ἄν μοι ἀντείποι ἄλλος ἢ οὗτος, δέομαι ὑμῶν ἁπάντων δικαίαν δέησιν·", "st": "50.2"}, {"sp": "N", "t": "ὅσοι μὲν τῶν στρατιωτῶν ἐστε καὶ παρῆτε ἐκεῖ, αὐτοί τε ἀναμνήσθητε καὶ τοῖς παρακαθημένοις φράζετε τήν τ’ ἐμὴν προθυμίαν καὶ τὰ συμβάντα ἐν τῷ τότε καιρῷ τῇ πόλει πράγματα καὶ τὰς ἀπορίας, ἵνα ἐκ τούτων εἰδῆτε ὁποῖός τίς εἰμι περὶ ἃ ἂν προστάξητε ὑμεῖς· ὅσοι δὲ αὐτοῦ ἐπεδημεῖτε, σιγῇ μου ἀκοῦσαι διηγουμένου ἅπαντα πρὸς ὑμᾶς, καὶ ἐπὶ τούτων ἑκάστῳ, οἷς ἂν λέγω, τούς τε νόμους παρεχομένου καὶ τὰ ψηφίσματα, τά τε τῆς βουλῆς καὶ τὰ τοῦ δήμου, καὶ τὰς μαρτυρίας.", "st": "50.3"}, {"sp": "N", "t": "ἑβδόμῃ γὰρ φθίνοντος μεταγειτνιῶνος μηνὸς ἐπὶ Μόλωνος ἄρχοντος, ἐκκλησίας γενομένης καὶ εἰσαγγελθέντων ὑμῖν πολλῶν καὶ μεγάλων πραγμάτων, ἐψηφίσασθε τὰς ναῦς καθέλκειν τοὺς τριηράρχους· ὧν καὶ ἐγὼ ἦν. καὶ τὸν μὲν καιρὸν τὸν συμβεβηκότα τῇ πόλει τότε οὐκ ἐμὲ δεῖ διεξελθεῖν, ἀλλ’ ὑμᾶς αὐτοὺς ἀναμνησθῆναι, ὅτι Τῆνος μὲν καταληφθεῖσα ὑπ’ Ἀλεξάνδρου ἐξηνδραποδίσθη,", "st": "50.4"}, {"sp": "N", "t": "Μιλτοκύθης δὲ ἀφειστήκει ἀπὸ Κότυος καὶ πρέσβεις ἐπεπόμφει περὶ συμμαχίας, βοηθεῖν κελεύων καὶ τὴν Χερρόνησον ἀποδιδούς, Προκοννήσιοι δὲ σύμμαχοι ὄντες ἱκέτευον ὑμᾶς ἐν τῷ δήμῳ βοηθῆσαι αὑτοῖς, λέγοντες ὅτι ὑπὸ Κυζικηνῶν κατέχονται τῷ πολέμῳ καὶ κατὰ γῆν καὶ κατὰ θάλατταν, καὶ μὴ περιιδεῖν ἀπολομένους·", "st": "50.5"}, {"sp": "N", "t": "ὧν ἀκούοντες τότε ὑμεῖς ἐν τῷ δήμῳ αὐτῶν τε λεγόντων καὶ τῶν συναγορευόντων αὐτοῖς, ἔτι δὲ τῶν ἐμπόρων καὶ τῶν ναυκλήρων περὶ ἔκπλουν ὄντων ἐκ τοῦ Πόντου, καὶ Βυζαντίων καὶ Καλχηδονίων καὶ Κυζικηνῶν καταγόντων τὰ πλοῖα ἕνεκα τῆς ἰδίας χρείας τοῦ σίτου, καὶ ὁρῶντες ἐν τῷ Πειραιεῖ τὸν σῖτον ἐπιτιμώμενον καὶ οὐκ ὄντα ἄφθονον ὠνεῖσθαι, ἐψηφίσασθε τάς τε ναῦς καθέλκειν τοὺς τριηράρχους καὶ παρακομίζειν ἐπὶ τὸ χῶμα, καὶ τοὺς βουλευτὰς καὶ τοὺς δημάρχους καταλόγους ποιεῖσθαι τῶν δημοτῶν καὶ ἀποφέρειν ναύτας, καὶ διὰ τάχους τὸν ἀπόστολον ποιεῖσθαι καὶ βοηθεῖν ἑκασταχοῖ. καὶ ἐνίκησε τὸ Ἀριστοφῶντος ψήφισμα τουτί.", "st": "50.6"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "50.6"}, {"sp": "N", "t": "τοῦ μὲν ψηφίσματος τοίνυν ἀκηκόατε, ὦ ἄνδρες δικασταί. ἐγὼ δ’ ἐπειδή μοι οὐκ ἦλθον οἱ ναῦται οἱ καταλεγέντες ὑπὸ τῶν δημοτῶν, ἀλλ’ ἢ ὀλίγοι καὶ οὗτοι ἀδύνατοι, τούτους μὲν ἀφῆκα, ὑποθεὶς δὲ τὴν οὐσίαν τὴν ἐμαυτοῦ καὶ δανεισάμενος ἀργύριον πρῶτος ἐπληρωσάμην τὴν ναῦν, μισθωσάμενος ναύτας ὡς οἷόν τ’ ἦν ἀρίστους, δωρεὰς καὶ προδόσεις δοὺς ἑκάστῳ αὐτῶν μεγάλας. ἔτι δὲ σκεύεσιν ἰδίοις τὴν ναῦν ἅπασι κατεσκεύασα, καὶ τῶν δημοσίων ἔλαβον οὐδέν, καὶ κόσμῳ ὡς οἷόν τ’ ἦν κάλλιστα καὶ διαπρεπέστατα τῶν τριηράρχων. ὑπηρεσίαν τοίνυν ἣν ἐδυνάμην κρατίστην ἐμισθωσάμην.", "st": "50.7"}, {"sp": "N", "t": "οὐ μόνον τοίνυν, ὦ ἄνδρες δικασταί, τὰ κατὰ τὴν τριηραρχίαν ἀνήλισκον τότε οὕτω πολυτελῆ ὄντα, ἀλλὰ καὶ τῶν χρημάτων ὧν εἰς τὸν ἔκπλουν ἐψηφίσασθε εἰσενεχθῆναι μέρος οὐκ ἐλάχιστον ἐγὼ ὑμῖν προεισήνεγκα. δόξαν γὰρ ὑμῖν ὑπὲρ τῶν δημοτῶν τοὺς βουλευτὰς ἀπενεγκεῖν τοὺς προεισοίσοντας τῶν τε δημοτῶν καὶ τῶν ἐγκεκτημένων, προσαπηνέχθη μου τοὔνομα ἐν τριττοῖς δήμοις διὰ τὸ φανερὰν εἶναί μου τὴν οὐσίαν.", "st": "50.8"}, {"sp": "N", "t": "καὶ τούτων ἐγώ, οὐδεμίαν πρόφασιν ποιησάμενος, ὅτι τριηραρχῶ καὶ οὐκ ἂν δυναίμην δύο λῃτουργίας λῃτουργεῖν οὐδὲ οἱ νόμοι ἐῶσιν, ἔθηκα τὰς προεισφορὰς πρῶτος. καὶ οὐκ εἰσεπραξάμην διὰ τὸ τότε μὲν ἀποδημεῖν ὑπὲρ ὑμῶν τριηραρχῶν, ὕστερον δὲ καταπλεύσας καταλαβεῖν τὰ μὲν εὔπορα ὑφ’ ἑτέρων προεξειλεγμένα, τὰ δ’ ἄπορα ὑπόλοιπα.", "st": "50.9"}, {"sp": "N", "t": "καὶ ταῦτα ὅτι ἀληθῆ λέγω πρὸς ὑμᾶς, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας τῶν τε τὰ στρατιωτικὰ τότε εἰσπραττόντων καὶ τῶν ἀποστολέων, καὶ τοὺς μισθοὺς οὓς ταῖς ὑπηρεσίαις καὶ τοῖς ἐπιβάταις κατὰ μῆνα ἐδίδουν, παρὰ τῶν στρατηγῶν σιτηρέσιον μόνον λαμβάνων, πλὴν δυοῖν μηνοῖν μόνον μισθὸν ἐν πέντε μησὶν καὶ ἐνιαυτῷ, καὶ τοὺς ναύτας τοὺς μισθωθέντας, [καὶ] ὅσον ἕκαστος ἔλαβεν ἀργύριον, ἵν’ ἐκ τούτων εἰδῆτε τὴν ἐμὴν προθυμίαν, καὶ οὗτος δι’ ὅ τι παραλαβεῖν παρ’ ἐμοῦ τὴν ναῦν οὐκ ἤθελεν, ἐπειδή μοι ὁ χρόνος ἐξῆλθεν τῆς τριηραρχίας.", "st": "50.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "50.10"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐ ψεύδομαι πρὸς ὑμᾶς περὶ ὧν εἶπον, ὦ ἄνδρες δικασταί, τῶν μαρτυριῶν ἀναγιγνωσκομένων ἀκηκόατε. ἔτι δὲ περὶ ὧν μέλλω λέγειν, ἅπαντές μοι ὁμολογήσετε ὅτι ἀληθῆ ἐστιν. τριήρους γὰρ ὁμολογεῖται κατάλυσις εἶναι, πρῶτον μέν, ἐὰν μὴ μισθόν τις διδῷ, δεύτερον δέ, ἐὰν εἰς τὸν Πειραιᾶ μεταξὺ καταπλεύσῃ· ἀπόλειψίς τε γὰρ πλείστη γίγνεται, οἵ τε παραμένοντες τῶν ναυτῶν οὐκ ἐθέλουσιν πάλιν ἐμβαίνειν, ἐὰν μή τις αὐτοῖς ἕτερον ἀργύριον διδῷ ὥστε τὰ οἰκεῖα διοικήσασθαι. ἃ ἐμοὶ ἀμφότερα συνέβη, ὦ ἄνδρες δικασταί, ὥστε πολυτελεστέραν μοι γενέσθαι τὴν τριηραρχίαν.", "st": "50.11"}, {"sp": "N", "t": "καὶ γὰρ μισθὸν οὐδένα λαβὼν παρὰ τοῦ στρατηγοῦ ὀκτὼ μηνῶν, κατέπλευσα τοὺς πρέσβεις ἄγων διὰ τὸ ἄριστά μοι πλεῖν τὴν ναῦν, καὶ ἐνθένδε πάλιν, προσταχθέν μοι ὑπὸ τοῦ δήμου Μένωνα τὸν στρατηγὸν ἄγειν εἰς Ἑλλήσποντον ἀντὶ Αὐτοκλέους ἀποχειροτονηθέντος, ᾠχόμην ἀναγόμενος διὰ τάχους. καὶ ἀντὶ τῶν ἀπολιπόντων μὲν ναυτῶν ἑτέρους ἐμισθωσάμην ναύτας, δωρεὰς καὶ προδόσεις αὐτοῖς διδοὺς μεγάλας, τοῖς δὲ παραμείνασι τῶν ἀρχαίων ναυτῶν ἔδωκά τι εἰς διοίκησιν τῶν οἰκείων καταλιπεῖν πρὸς ᾧ πρότερον εἶχον, οὐκ ἀγνοῶν τὴν παροῦσαν χρείαν,", "st": "50.12"}, {"sp": "N", "t": "ὡς ἀναγκαία ἦν ἑκάστῳ, ἀπορῶν δὲ αὐτὸς ὡς μὰ τὸν Δία καὶ τὸν Ἀπόλλω οὐδεὶς ἄν μοι πιστεύσειεν, ὅστις μὴ ἀληθῶς παρηκολούθηκε τοῖς ἐμοῖς πράγμασιν. ὑποθεὶς δὲ τὸ χωρίον Θρασυλόχῳ καὶ Ἀρχένεῳ, καὶ δανεισάμενος τριάκοντα μνᾶς παρ’ αὐτῶν καὶ διαδοὺς τοῖς ναύταις, ᾠχόμην ἀναγόμενος, ἵνα μηδὲν ἐλλείποι τῷ δήμῳ ὧν προσέταξε τὸ κατ’ ἐμέ. καὶ ὁ δῆμος ἀκούσας ταῦτα ἐπῄνεσέν τέ με, καὶ ἐπὶ δεῖπνον εἰς τὸ πρυτανεῖον ἐκάλεσεν. καὶ ὡς ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν ἀναγνώσεται τὴν μαρτυρίαν καὶ τὸ ψήφισμα τὸ τοῦ δήμου.", "st": "50.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ. ΨΗΦΙΣΜΑ.", "st": "50.13"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν εἰς Ἑλλήσποντον ἤλθομεν, καὶ ὅ τε χρόνος ἐξεληλύθει μοι τῆς τριηραρχίας, καὶ μισθὸς οὐκ ἀπεδόθη τοῖς στρατιώταις ἀλλ’ ἢ δυοῖν μηνοῖν, ἕτερός τε στρατηγὸς ἧκεν Τιμόμαχος, καὶ οὗτος διαδόχους οὐκ ἄγων ἐπὶ τὰς ναῦς, ἀθυμήσαντές μοι πολλοὶ τοῦ πληρώματος ᾤχοντο ἀπολιπόντες τὴν ναῦν, οἱ μὲν εἰς τὴν ἤπειρον στρατευσόμενοι, οἱ δὲ εἰς τὰς Θασίων καὶ Μαρωνιτῶν ναῦς, μισθῷ μεγάλῳ πεισθέντες καὶ ἀργύριον πολὺ προλαβόντες καὶ ὑπὸ πολλῶν αὖ τῷ λόγῳ ἐξηπατημένοι.", "st": "50.14"}, {"sp": "N", "t": "καὶ τὰ μὲν παρ’ ἐμοῦ ἐξανηλωμένα ἤδη ὁρῶντες, τὰ δὲ τῆς πόλεως ἀμελῆ, τὰ δὲ τῶν συμμάχων ἄπορα, τὰ δὲ τῶν στρατηγῶν ἄπιστα, καὶ τὸν χρόνον ἐξήκοντα τῆς τριηραρχίας καὶ τὸν πλοῦν οὐκέτ’ ὄντα οἴκαδε, οὐδὲ διάδοχον ἥκοντα ἐπὶ τὴν ναῦν, παρ’ οὗ ἄν τις ἠξίωσεν ὠφεληθῆναι. ὅσῳ γὰρ φιλοτιμούμενος ἄμεινον ἐπληρωσάμην τὴν ναῦν ἐρετῶν ἀγαθῶν, τοσούτῳ μοι πλείστη ἀπόλειψις ἐγένετο τῶν ἄλλων τριηράρχων.", "st": "50.15"}, {"sp": "N", "t": "τοῖς μὲν γὰρ ἄλλοις, εἰ μή τι ἄλλο, οἵ γε ἐκ καταλόγου ἐλθόντες ἐπὶ τὴν ναῦν παρέμενον τηροῦντες τὴν οἴκαδε σωτηρίαν, ὁπότε αὐτοὺς ἀφήσει ὁ στρατηγός· οἱ δ’ ἐμοὶ ναῦται πιστεύοντες αὑτοῖς ἐπὶ τῷ δύνασθαι ἐλαύνειν, ὅπου ἔμελλον ἀργύριον πάλιν πλεῖστον λήψεσθαι, ἐνταῦθ’ ἀπῇσαν, ἡγούμενοι τὴν ἐν τῷ παρόντι εὐπορίαν κρείττω εἶναι αὑτοῖς τοῦ μέλλοντος φόβου, εἴ ποτε ληφθείησαν ὑπ’ ἐμοῦ.", "st": "50.16"}, {"sp": "N", "t": "τοιούτων τοίνυν μοι τῶν πραγμάτων συμβεβηκότων, καὶ τοῦ στρατηγοῦ ἅμα Τιμομάχου προστάξαντος πλεῖν ἐφ’ Ἱερὸν ἐπὶ τὴν παραπομπὴν τοῦ σίτου καὶ μισθὸν οὐ διδόντος, εἰσαγγελθέντων δὲ ὅτι Βυζάντιοι καὶ Καλχηδόνιοι πάλιν κατάγουσι τὰ πλοῖα καὶ ἀναγκάζουσι τὸν σῖτον ἐξαιρεῖσθαι, δανεισάμενος ἐγὼ ἀργύριον παρ’ Ἀρχεδήμου μὲν τοῦ Ἀναφλυστίου πεντεκαίδεκα μνᾶς ἐπίτοκον, ὀκτακοσίας δὲ δραχμὰς παρὰ Νικίππου τοῦ ναυκλήρου ναυτικὸν ἀνειλόμην, ὃς ἔτυχεν ὢν ἐν Σηστῷ, ἐπόγδοον, σωθέντος δὲ τοῦ πλοίου Ἀθήναζε ἀποδοῦναι αὐτὸ καὶ τοὺς τόκους,", "st": "50.17"}, {"sp": "N", "t": "καὶ πέμψας Εὐκτήμονα τὸν πεντηκόνταρχον εἰς Λάμψακον, δοὺς αὐτῷ ἀργύριον καὶ γράμματα πρὸς τοὺς ξένους τοῦ πατρὸς τοῦ ἐμοῦ, ἐκέλευσά μοι αὐτὸν ναύτας μισθώσασθαι ὡς ἂν δύνηται ἀρίστους· αὐτὸς δ’ ὑπομείνας ἐν Σηστῷ τοῖς τε παραμείνασι τῶν ἀρχαίων ναυτῶν ἔδωκά τι, ὅσον εἶχον, ἐπειδή μοι ὁ χρόνος ἐξῆκεν τῆς τριηραρχίας, καὶ ἑτέρους ναύτας ἐντελομίσθους προσέλαβον, ἐν ὅσῳ ὁ στρατηγὸς τὸν ἀνάπλουν τὸν ἐφ’ Ἱερὸν παρεσκευάζετο.", "st": "50.18"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὅ τε Εὐκτήμων ἧκεν ἐκ τῆς Λαμψάκου ἄγων τοὺς ναύτας οὓς ἐμισθώσατο, καὶ ὁ στρατηγὸς παρήγγειλεν ἀνάγεσθαι, τῷ μὲν Εὐκτήμονι ἀσθενῆσαι ἐξαίφνης συνέβη, καὶ πάνυ πονηρῶς διετέθη· τούτῳ μὲν οὖν ἀποδοὺς τὸν μισθὸν καὶ ἐφόδια προσθεὶς ἀπέπεμψα οἴκαδε· αὐτὸς δὲ πεντηκόνταρχον ἕτερον λαβὼν ἀνηγόμην ἐπὶ τὴν παραπομπὴν τοῦ σίτου, καὶ ἐκεῖ περιέμεινα πέντε καὶ τετταράκοντα ἡμέρας, ἕως ὁ ἔκπλους τῶν πλοίων τῶν μετ’ ἀρκτοῦρον ἐκ τοῦ Πόντου ἐγένετο.", "st": "50.19"}, {"sp": "N", "t": "ἀφικόμενος δὲ εἰς Σηστὸν ἐγὼ μὲν ᾤμην οἴκαδε καταπλεύσεσθαι, τοῦ τε χρόνου μοι ἐξήκοντος καὶ ἐπιτετριηραρχημένων ἤδη μοι δυοῖν μηνοῖν καὶ διαδόχου οὐχ ἥκοντος ἐπὶ τὴν ναῦν· ὁ δὲ στρατηγὸς Τιμόμαχος, ἀφικομένων ὡς αὐτὸν πρέσβεων Μαρωνιτῶν καὶ δεομένων αὑτοῖς τὰ πλοῖα παραπέμψαι τὰ σιτηγά, προσέταξεν ἡμῖν τοῖς τριηράρχοις ἀναδησαμένοις τὰ πλοῖα ἕλκειν εἰς Μαρώνειαν, πλοῦν καὶ πολὺν καὶ πελάγιον.", "st": "50.20"}, {"sp": "N", "t": "καὶ ταῦθ’ ὑμῖν διὰ τοῦτο ἅπαντα διηγησάμην ἐξ ἀρχῆς, ἵνα εἰδῆτε ὅσα ἀνηλωκὼς αὐτὸς καὶ ἡλίκης μοι γεγενημένης τῆς λῃτουργίας ὕστερον ὅσα ἀναλώματα ὑπὲρ τούτου ἀνήλωσα ἐπιτριηραρχῶν, οὐχ ἥκοντος τούτου ἐπὶ τὴν ναῦν, καὶ κινδύνους ὅσους ἐκινδύνευσα αὐτὸς πρός τε χειμῶνα καὶ πρὸς πολεμίους. μετὰ γὰρ τὴν παραπομπὴν τῶν πλοίων τὴν εἰς Μαρώνειαν καὶ τὴν ἄφιξιν τὴν εἰς Θάσον, ἀφικόμενος παρέπεμπε πάλιν ὁ Τιμόμαχος μετὰ τῶν Θασίων εἰς [τὴν] Στρύμην σῖτον καὶ πελταστάς, ὡς παραληψόμενος αὐτὸς τὸ χωρίον.", "st": "50.21"}, {"sp": "N", "t": "παραταξαμένων δὲ Μαρωνιτῶν ἡμῖν ταῖς ναυσὶν ὑπὲρ τοῦ χωρίου τούτου καὶ μελλόντων ναυμαχήσειν, καὶ τῶν στρατιωτῶν ἀπειρηκότων, πλοῦν πολὺν πεπλευκότων καὶ πλοῖα ἑλκόντων ἐκ Θάσου εἰς Στρύμην, ἔτι δὲ χειμῶνος ὄντος καὶ τοῦ χωρίου ἀλιμένου, καὶ ἐκβῆναι οὐκ ὂν οὐδὲ δειπνοποιήσασθαι πολεμίας τῆς χώρας οὔσης καὶ περικαθημένων κύκλῳ τὸ τεῖχος καὶ ξένων μισθοφόρων καὶ βαρβάρων προσοίκων, ἀναγκαῖον ἦν ἐπ’ ἀγκύρας ἀποσαλεύειν τὴν νύκτα μετεώρους, ἀσίτους καὶ ἀγρύπνους, φυλαττομένους μὴ τῆς νυκτὸς ἡμῖν ἐπιθῶνται αἱ Μαρωνιτῶν τριήρεις.", "st": "50.22"}, {"sp": "N", "t": "ἔτι δὲ συνέβη τῆς νυκτὸς ὥρᾳ ἔτους ὕδωρ καὶ βροντὰς καὶ ἄνεμον μέγαν γενέσθαι (ὑπ’ αὐτὰς γὰρ Πλειάδων δύσεις οἱ χρόνοι οὗτοι ἦσαν), ἐξ ὧν τίνα οὐκ οἴεσθε, ὦ ἄνδρες δικασταί, τοῖς στρατιώταις ἀθυμίαν ἐμπεσεῖν; πόσην δέ μοι μετὰ ταῦτα ἀπόλειψιν γενέσθαι πάλιν, τῶν ἀρχαίων ναυτῶν ταλαιπωρουμένων μὲν πολλά, ὠφελουμένων δὲ βραχέα, ὅσα ἐγὼ δυναίμην ἑκάστῳ δανειζόμενος ἐπαρκέσαι πρὸς ᾧ πρότερον εἶχον παρ’ ἐμοῦ, ἐπεὶ ὅ γε στρατηγὸς οὐδὲ τὸ ἐφ’ ἡμέραν αὐτοῖς τροφὴν διαρκῆ ἐδίδου. καὶ ἤδη τρεῖς μῆνες ἐπετετριηράρχηντό μοι, καὶ οὐδέπω οὗτος ἧκεν ἐπὶ τὴν ναῦν, ἀλλ’ ἐμισθούμην ναύτας ἀντὶ τῶν ἀπολιπόντων, δανειζόμενος ἀργύριον.", "st": "50.23"}, {"sp": "N", "t": "μόνῳ τοίνυν τούτῳ τῶν ἄλλων διαδόχων οὐκ ἔστι πρόφασις ὑπολειπομένη, δι’ ὅ τι οὐ πάλαι ἧκεν ἐπὶ τὴν ναῦν. ὁ γὰρ Εὐκτήμων ὁ πεντηκόνταρχος, ὡς ἐκ τοῦ Ἑλλησπόντου ἀπεστάλη οἴκαδε ἀσθενήσας, ἐπειδὴ κατέπλευσε καὶ ἤκουσε τοῦτον ἐμοὶ διάδοχον καθεστηκότα, εἰδὼς τόν τε χρόνον ἐξήκοντά μοι τῆς τριηραρχίας καὶ ἤδη ἐπιτριηραρχοῦντά με, παραλαβὼν Δεινίαν τὸν κηδεστὴν τὸν ἐμὸν προσέρχεται αὐτῷ ἐν τῷ δείγματι, καὶ ἐκέλευεν αὐτὸν ὡς τάχιστα ἐπὶ τὴν ναῦν ἀποπλεῖν, ὡς τῶν ἀναλωμάτων πολλῶν ὄντων ἃ καθ’ ἡμέραν ἑκάστην πρὸς τῷ παρὰ τοῦ στρατηγοῦ σιτηρεσίῳ εἰς τὴν ναῦν διδομένῳ ἀνηλίσκετο,", "st": "50.24"}, {"sp": "N", "t": "καθ’ ἕκαστον αὐτῷ διεξιὼν τούς τε μισθοὺς τοὺς τῇ ὑπηρεσίᾳ καὶ τοῖς ἐπιβάταις κατὰ μῆνα διδομένους, τοῖς τε ναύταις οὓς αὐτὸς ἐκ τῆς Λαμψάκου ἐμισθώσατο, καὶ τοῖς ὕστερον ἐπεμβᾶσιν ἀντὶ τῶν ἀπολιπόντων, ἔτι δὲ ὃ τῶν ἀρχαίων ναυτῶν ἑκάστῳ προσέθηκα δεηθέντι, ἐπειδή μοι ὁ χρόνος ἐξῆκε τῆς τριηραρχίας, καὶ τἄλλα ὅσα ἦν τὰ καθ’ ἡμέραν ἑκάστην ἀναλισκόμενα εἰς τὴν ναῦν, οὐκ ἀπείρως ἔχων· διὰ γὰρ ἐκείνου πεντηκονταρχοῦντος καὶ ἠγοράζετο καὶ ἀνηλίσκετο.", "st": "50.25"}, {"sp": "N", "t": "καὶ περὶ τῶν σκευῶν ἔφραζεν αὐτῷ ὅτι ἴδια ἔχοιμι καὶ δημόσιον οὐδέν· “ὡς οὖν”, ἔφη, “[ἢ] πείσων ἐκεῖνον διανοοῦ, ἢ σκεύη ἔχων σαυτῷ ἀνάπλει. οἶμαι δέ σοι”, ἔφη, “αὐτὸν οὐδὲν διοίσεσθαι· ὀφείλει γὰρ ἀργύριον ἐκεῖ, ὃ διαλῦσαι βουλήσεται ἐκ τῆς τιμῆς τῶν σκευῶν.” ἀκούσας δὲ οὗτος ταῦτα τοῦ τ’ Εὐκτήμονος καὶ τοῦ Δεινίου τοῦ κηδεστοῦ τοῦ ἐμοῦ, περὶ μὲν ὧν ἔλεγον αὐτῷ οὐδὲν αὐτοῖς ἀποκρίνεται, γελάσαντα δὲ ἔφασαν αὐτὸν εἰπεῖν “ἄρτι μῦς πίττης γεύεται· ἐβούλετο γὰρ Ἀθηναῖος εἶναι”.", "st": "50.26"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τοῦ Εὐκτήμονος καὶ τοῦ Δεινίου ἀκούσας οὐδὲν ἐφρόντιζεν, πάλιν αὐτῷ προσέρχονται ὕστερον Πυθόδωρός τε ὁ Ἀχαρνεὺς καὶ Ἀπολλόδωρος ὁ Λευκονοεύς, ἐπιτήδειοι ὄντες ἐμοὶ καὶ φίλοι, καὶ ἐκέλευον αὐτὸν ἐπί τε τὴν ναῦν ἀπιέναι ὡς διάδοχον ὄντα, καὶ περὶ τῶν σκευῶν ἔφραζον αὐτῷ, ὅτι ἴδια ἔχοιμι ἅπαντα καὶ δημόσιον οὐδέν·", "st": "50.27"}, {"sp": "N", "t": "“εἰ μὲν οὖν ἐκείνοις ἐθέλεις χρῆσθαι, κατάλιπε” ἔφασαν “ἀργύριον αὐτοῦ, καὶ μὴ διακινδύνευε ἐκεῖσε ἄγων”, ἵνα λύσωνταί μοι τὸ χωρίον, ἀποδόντες Ἀρχένεῳ καὶ Θρασυλόχῳ ⟨τὰς⟩ τριάκοντα μνᾶς. περὶ δὲ ἀποτριβῆς τῶν σκευῶν, ἤθελον αὐτῷ γράμματα γράφειν, καὶ ἐγγυηταὶ αὐτοὶ γίγνεσθαι ὑπὲρ ἐμοῦ ἦ μὴν ἔσεσθαι αὐτῷ ὅ τι ἂν καὶ τοῖς ἄλλοις τριηράρχοις πρὸς τοὺς διαδόχους ᾖ. ὡς οὖν πάντα ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "50.28"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "50.28"}, {"sp": "N", "t": "ἐκ πολλῶν μὲν τοίνυν τεκμηρίων οἶμαι ὑμῖν ἐπιδείξειν Πολυκλέα ὅτι οὔτε αὐτόθεν διενοεῖτο παραλαμβάνειν παρ’ ἐμοῦ τὴν ναῦν, οὔτε, ἐπειδὴ ὑφ’ ὑμῶν καὶ τοῦ ψηφίσματος τοῦ ὑμετέρου ἠναγκάσθη ἐπὶ τὴν ναῦν ἀπιέναι, ἐλθὼν ἠθέλησέ μοι διαδέξασθαι αὐτήν. οὗτος γὰρ ἐπειδὴ ἀφίκετο εἰς Θάσον ἤδη μου τέταρτον μῆνα ἐπιτριηραρχοῦντος, παραλαβὼν ἐγὼ μάρτυρας τῶν τε πολιτῶν ὡς ἐδυνάμην πλείστους καὶ τοὺς ἐπιβάτας καὶ τὴν ὑπηρεσίαν προσέρχομαι αὐτῷ ἐν Θάσῳ ἐν τῇ ἀγορᾷ, καὶ ἐκέλευον αὐτὸν τήν τε ναῦν παραλαμβάνειν παρ’ ἐμοῦ ὡς διάδοχον ὄντα, καὶ τοῦ ἐπιτετριηραρχημένου χρόνου ἀποδιδόναι μοι τἀναλώματα.", "st": "50.29"}, {"sp": "N", "t": "λογίσασθαι δ’ ἤθελον αὐτῷ καθ’ ἕκαστον, ἕως μοι μάρτυρες παρῆσαν τῶν ἀνηλωμένων οἵ τε ναῦται καὶ οἱ ἐπιβάται καὶ ἡ ὑπηρεσία, ἵν’ εἴ τι ἀντιλέγοι εὐθὺς ἐξελέγχοιμι. οὕτω γάρ μοι ἀκριβῶς ἐγέγραπτο, ὥστ’ οὐ μόνον αὐτά μοι τἀναλώματα ἐγέγραπτο, ἀλλὰ καὶ ὅποι ἀνηλώθη καὶ ὅ τι ποιούντων, καὶ ἡ τιμὴ τίς ἦν καὶ νόμισμα ποδαπόν, καὶ ὁπόσου ἡ καταλλαγὴ ἦν τῷ ἀργυρίῳ, ἵν’ εἴη ἀκριβῶς ἐξελέγξαι με τῷ διαδόχῳ, εἴ τι ἡγοῖτο ψεῦδος αὑτῷ λογίζεσθαι.", "st": "50.30"}, {"sp": "N", "t": "ἔτι δὲ καὶ πίστιν αὐτῷ ἐπιθεὶς ἠθέλησα λογίσασθαι τὰ ἀνηλωμένα. προκαλουμένου δέ μου ταῦτα, ἀπεκρίνατό μοι ὅτι οὐδὲν αὐτῷ μέλοι ὧν λέγοιμι. ἐν δὲ τούτῳ ὑπηρέτης ἥκων παρὰ τοῦ στρατηγοῦ ἐμοὶ παρήγγελλεν ἀνάγεσθαι, οὐ τούτῳ τῷ διαδόχῳ, οὗ ἡ λῃτουργία ἤδη ἐγίγνετο· τούτου δὲ τὸ αἴτιον ἐγὼ ὑμᾶς προϊόντος τοῦ λόγου διδάξω. τότε μὲν οὖν μοι ἐδόκει ἀνάγεσθαι καὶ πλεῖν οἷ ἐκέλευεν·", "st": "50.31"}, {"sp": "N", "t": "ἐπειδὴ δὲ κατέπλευσα πάλιν εἰς Θάσον, ἑλκύσας τὰ πλοῖα εἰς Στρύμην, οἷ προσέταξεν ὁ στρατηγός, κελεύσας τοὺς ναύτας ἐν τῇ νηὶ μένειν καὶ τοὺς ἐπιβάτας καὶ τὴν ὑπηρεσίαν, ἐκβὰς αὐτὸς πορεύομαι ἐπὶ τὴν οἰκίαν οὗ κατήγετο Τιμόμαχος ὁ στρατηγός, βουλόμενος κἀκείνου ἐναντίον παραδιδόναι τὴν ναῦν Πολυκλεῖ τουτῳὶ πλήρη.", "st": "50.32"}, {"sp": "N", "t": "καταλαμβάνω οὖν καὶ τοῦτον ἐκεῖ καὶ τοὺς τριηράρχους καὶ τοὺς διαδόχους καὶ ἄλλους τινὰς τῶν πολιτῶν, καὶ εἰσελθὼν εὐθὺς ἐναντίον τοῦ στρατηγοῦ λόγους πρὸς αὐτὸν ἐποιούμην, καὶ ἠξίουν αὐτὸν τήν τε ναῦν μοι παραλαμβάνειν καὶ τοῦ ἐπιτετριηραρχημένου χρόνου ἀποδιδόναι μοι τὰ ἀναλώματα, καὶ περὶ τῶν σκευῶν ἠρώτων αὐτόν, πότερα παραλήψεται ἢ ἴδια σκεύη ἔχων ἥκοι ἐπὶ τὴν ναῦν.", "st": "50.33"}, {"sp": "N", "t": "ταῦτα δέ μου προκαλουμένου αὐτόν, ἠρώτα με δι’ ὅ τι σκεύη τε ἴδια μόνος ἔχοιμι τῶν τριηράρχων, καὶ πότερα ἡ πόλις οὐκ εἰδείη τινὰς δυναμένους σκεύη παρασχεῖν ταῖς ναυσίν, ὥστε αὐτὴ μὴ παρέχειν. “ἢ σὺ τοσοῦτον” ἔφη “ὑπερπέπαικας πλούτῳ τοὺς ἄλλους, ὥστε καὶ σκεύη ἴδια ἔχειν καὶ κόσμον χρυσόπαστον μόνος τῶν τριηράρχων;”", "st": "50.34"}, {"sp": "N", "t": "“τίς ἂν οὖν δύναιτ’” ἔφη “τὴν σὴν μανίαν καὶ πολυτέλειαν ὑπομεῖναι, διεφθαρμένον μὲν πλήρωμα καὶ εἰωθὸς ἀργύριον πολὺ προλαμβάνειν καὶ ἀτελείας ἄγειν τῶν νομιζομένων ἐν τῇ νηὶ λῃτουργιῶν καὶ λοῦσθαι ἐν βαλανείῳ, τρυφῶντας δ’ ἐπιβάτας καὶ ὑπηρεσίαν ὑπὸ μισθοῦ πολλοῦ καὶ ἐντελοῦς; κακῶν δ’,” ἔφη, “διδάσκαλος γέγονας ἐν τῷ στρατεύματι, καὶ αἴτιος εἶ μέρος τι καὶ τοῖς ἄλλοις τριηράρχοις πονηροτέρους εἶναι τοὺς στρατιώτας, ζητοῦντας ταὐτὰ τοῖς παρὰ σοί· ἔδει γὰρ σὲ ταὐτὰ ποιεῖν τοῖς ἄλλοις τριηράρχοις.”", "st": "50.35"}, {"sp": "N", "t": "λέγοντος δὲ αὐτοῦ ταῦτα, ἀπεκρινάμην αὐτῷ ὅτι σκεύη μὲν διὰ τοῦτο οὐ λάβοιμι ἐκ τοῦ νεωρίου, “ὅτι σὺ ἀδόκιμα ἐποίησας αὐτά. ἀλλ’ εἰ μὲν βούλει, ταῦτα παράλαβε· εἰ δὲ μή, σκεύη σαυτῷ παρασκεύαζε. περὶ δὲ τῶν ναυτῶν καὶ τῶν ἐπιβατῶν καὶ τῆς ὑπηρεσίας, εἰ φὴς ὑπ’ ἐμοῦ αὐτοὺς διεφθάρθαι, παραλαβὼν τὴν τριήρη αὐτὸς σαυτῷ κατασκεύασαι καὶ ναύτας καὶ ἐπιβάτας καὶ ὑπηρεσίαν, οἵτινές σοι μηδὲν λαβόντες συμπλεύσονται. τὴν δὲ ναῦν παράλαβε· οὐ γὰρ ἔτι μοι προσήκει τριηραρχεῖν· ὅ τε γὰρ χρόνος ἐξήκει μοι τῆς τριηραρχίας, καὶ ἐπιτετριηράρχηκα τέτταρας μῆνας.”", "st": "50.36"}, {"sp": "N", "t": "λέγοντος δέ μου ταῦτα, ἀποκρίνεταί μοι ὅτι ὁ συντριήραρχος αὐτῷ οὐχ ἥκοι ἐπὶ τὴν ναῦν· “οὔκουν παραλήψομαι μόνος τὴν τριήρη.” ὡς οὖν ἀληθῆ ταῦτα λέγω πρὸς ὑμᾶς, καὶ ἐν μὲν τῇ ἀγορᾷ ἀπεκρίνατό μοι τὰ πρότερον, ὅτι οὐδὲν αὐτῷ μέλοι ὧν λέγοιμι, ἐν δὲ τῇ οἰκίᾳ οὗ ὁ Τιμόμαχος κατήγετο, ὅτι μόνος οὐ παραλήψεται τὴν ναῦν, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "50.37"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "50.37"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν, ὦ ἄνδρες δικασταί, ὡς οὔτε οὗτος ἤθελέ μοι τὴν ναῦν διαδέχεσθαι, οὔτε τὰ ἀναλώματα ἀπεδίδου τοῦ ἐπιτετριηραρχημένου χρόνου, ὅ τε στρατηγὸς προσέταττέ μοι ἀνάγεσθαι, προσελθὼν αὐτῷ ἐν Θάσῳ ἐν τῷ λιμένι ἐναντίον τοῦ στρατηγοῦ, πλήρους οὔσης τῆς τριήρους, ἔλεγον ἃ δίκαια μὲν οὐκ ἦν, ἀλλὰ πλεονεκτήματα τούτου, ἀναγκαῖα δέ μοι ἐκ τῶν παρόντων εἰπεῖν, “ἐπειδή σοι φής,”", "st": "50.38"}, {"sp": "N", "t": "“ὦ Πολύκλεις, τὸν συντριήραρχον οὐχ ἥκειν, τοῦ μὲν ἐπιτετριηραρχημένου χρόνου ἐκεῖνον ἐγὼ πράξομαι τὰ ἀναλώματα, ἂν δύνωμαι, τῶν τεττάρων μηνῶν· σὺ δὲ παραλαβὼν τὴν ναῦν πρῶτον μὲν τὸν ὑπὲρ σεαυτοῦ χρόνον τριηράρχησον, τοὺς ἓξ μῆνας· ἔπειτ’ ἐὰν μέν σοι ἔλθῃ ἐν τούτῳ ὁ συντριήραρχος, ἐκείνῳ παραδώσεις λῃτουργήσας, ἐὰν δὲ μή, οὐδὲν δεινὸν πείσει δύο μῆνας ἐπιτριηραρχήσας.”", "st": "50.39"}, {"sp": "N", "t": "“ἢ ἐγὼ μὲν ὁ τόν τε ὑπὲρ ἐμαυτοῦ χρόνον καὶ τοῦ συντριηράρχου λελῃτουργηκὼς ἐπετριηράρχησα ὑπὲρ ὑμῶν, σὺ δ’ οὐδὲν ἀνηλωκὼς οὐκ ἀξιοῖς οὐδὲ τὸν ὑπὲρ σεαυτοῦ χρόνον, παραλαβὼν τὴν ναῦν, λῃτουργῆσαι, οὐδὲ τὰ ἀναλώματ’ ἀποδοῦναι;” λέγοντος δέ μου ταῦτα, ἀπεκρίνατό μοι ὅτι μύθους λέγοιμι. ὁ δὲ στρατηγὸς ἐμβαίνειν με ἐκέλευεν εἰς τὴν ναῦν καὶ ἀνάγεσθαι μεθ’ ἑαυτοῦ. ὡς οὖν ταῦτ’ ἀπεκρίνατο, ἀνάγνωθί μοι τὴν μαρτυρίαν.", "st": "50.40"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "50.40"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν καὶ τεκμήριόν τι εἰπεῖν, ἵν’ εἰδῆτε ὅτι περιφανῶς ἠδίκημαι. Ἁγνίᾳ γὰρ καὶ Πραξικλεῖ ὑπὸ τὸν αὐτὸν χρόνον κατέστησαν διάδοχοι Μνησίλοχός τε ὁ Περιθοίδης καὶ Φρασιηρίδης ὁ Ἀναφλύστιος. οὐκ ἀφικομένου δὲ τοῦ Φρασιηρίδου ἐπὶ τὴν ναῦν, ὁ Μνησίλοχος ἐλθὼν εἰς τὴν Θάσον παρέλαβέ τε παρὰ τοῦ Ἁγνίου τὴν τριήρη,", "st": "50.41"}, {"sp": "N", "t": "καὶ τὸ ἐπιτριηράρχημα ἀπέδωκεν τῷ Ἁγνίᾳ τοῦ χρόνου οὗ ἐπανήλωσεν ὑπὲρ αὐτῶν, ὅσον ἔπεισεν, καὶ τὰ σκεύη παρὰ τοῦ Ἁγνίου ἐμισθώσατο, καὶ αὐτὸς ἐτριηράρχει. ὕστερον δ’ οἱ παρὰ τοῦ Φρασιηρίδου ἐλθόντες τῶν τε ἀνηλωμένων τὸ μέρος ἀπέδοσαν τῷ Μνησιλόχῳ, καὶ τοῦ λοιποῦ χρόνου ὅσα ἐδεῖτο εἰς τὴν ναῦν συνανήλισκον. καί μοι τούτων ἀνάγνωθι τὴν μαρτυρίαν.", "st": "50.42"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "50.42"}, {"sp": "N", "t": "ἴσως οὖν, ὦ ἄνδρες δικασταί, ποθεῖτε ἀκοῦσαι, διὰ τί ποτε ὁ στρατηγὸς οὐκ ἠνάγκαζε τοῦτον παραλαμβάνειν τὴν ναῦν, διάδοχον ἥκοντα ἐπ’ αὐτήν, τῶν νόμων οὕτως ἰσχυρῶν ὄντων. περὶ δὴ τούτων βούλομαι ὑμᾶς σαφῶς διδάξαι τὸ αἴτιον. Τιμόμαχος γάρ, ὦ ἄνδρες δικασταί, πρῶτον μὲν ἐβούλετο εὖ κατεσκευασμένῃ τῇ τριήρει πρὸς ἅπαντα χρῆσθαι.", "st": "50.43"}, {"sp": "N", "t": "ᾔδειν οὖν ὅτι οὗτος μὲν παραλαβὼν αὐτὴν κακῶς ἔμελλε τριηραρχήσειν· οὔτε γὰρ τῷ τριηραρχήματι οὔτε τοῖς ἐπιβάταις καὶ τῇ ὑπηρεσίᾳ χρήσοιτο· οὐδεὶς γὰρ αὐτῷ παραμενεῖ. ἔτι δὲ πρὸς τούτοις, ὁπότε μὴ διδοὺς ἀργύριον προστάττοι πλεῖν, οὐκ ἔμελλεν αὐτῷ ἀνάξεσθαι ὥσπερ ἐγώ, ἀλλὰ πράγματα παρέξειν. πρὸς δὲ τούτῳ δανείζεται παρ’ αὐτοῦ τριάκοντα μνᾶς, ὥστε μὴ ἀναγκάσαι παραλαβεῖν τὴν ναῦν.", "st": "50.44"}, {"sp": "N", "t": "ἐξ ὧν δὲ μάλιστά μοι ὀργισθεὶς ἐπηρέαζε καὶ οὐδὲ λόγον ἑκάστοτε ἐδίδου οὐδὲ περὶ ἑνός, βούλομαι ὑμῖν σαφῶς διηγήσασθαι, ἵν’ εἰδῆτε ὅτι οὐ περὶ πλείονος ἐποιούμην οὔτε τὴν ἐμαυτοῦ ῥᾳστώνην ἐν ἐκείνῳ τῷ χρόνῳ οὔτε τὴν ἐκείνου ῥώμην τοῦ δήμου τοῦ Ἀθηναίων καὶ τῶν νόμων, ἀλλ’ ἠνειχόμην καὶ ἔργῳ ἀδικούμενος καὶ λόγῳ προπηλακιζόμενος, ἃ πολλῷ μοι βαρύτερα ἦν τῶν ἀναλωμάτων.", "st": "50.45"}, {"sp": "N", "t": "ὡς γὰρ ἐν Θάσῳ διατριβαὶ τοῦ ναυτικοῦ ἐγίγνοντο, ἀφικνεῖται ἐκ Μεθώνης τῆς Μακεδονίας ὑπηρετικὸν εἰς Θάσον ἄγον ἄνδρα καὶ ἐπιστολὰς παρὰ Καλλιστράτου ὡς Τιμόμαχον, ἐν αἷς ἦν, ὡς ὕστερον ἐγὼ ταῦτ’ ἐπυθόμην, ἀποπέμψαι αὐτῷ τριήρη τὴν ἄριστα πλέουσαν, ἵν’ ἀφίκηται ὡς αὐτόν. εὐθὺς οὖν τῇ ὑστεραίᾳ ἅμα τῇ ἡμέρᾳ ὁ ὑπηρέτης ἐλθὼν ἐκέλευέ με καλεῖν εἰς τὴν ναῦν τοὺς ναύτας.", "st": "50.46"}, {"sp": "N", "t": "ἐπεὶ δὲ πλήρης ἦν, ἀναβαίνει Κάλλιππος ὁ Φίλωνος ὁ Αἰξωνεύς, καὶ φράζει πρὸς τὸν κυβερνήτην τὸν ἐπὶ Μακεδονίας πλοῦν πλεῖν. ἐπειδὴ δὲ ἀφικόμεθα εἰς χωρίον τι ἐν τῇ ἀπαντικρὺ ἠπείρῳ, Θασίων ἐμπόριον, καὶ ἐκβάντες ἠριστοποιούμεθα, προσέρχεταί μοι τῶν ναυτῶν Καλλικλῆς Ἐπιτρέφους Θριάσιος, λέγων ὅτι βούλοιτό μοι διαλεχθῆναι ἐμόν τι πρᾶγμα. κελεύσαντος δέ μου, λέγει ὅτι βούλοιτό μοι χάριν ἀποδοῦναι καθ’ ὅ τι δύναται ὧν αὐτῷ ἀπορηθέντι ἔδωκα·", "st": "50.47"}, {"sp": "N", "t": "“σὺ οὖν”, ἔφη, “τὸν πλοῦν τοῦτον οἶσθα ἐφ’ ὅ τι πλεῖς ἢ ποῖ;” ἀποκριναμένου δέ μου ὅτι οὐκ εἰδείην, “ἀλλ’ ἐγώ σοι”, ἔφη, “ἐρῶ· δεῖ γάρ σε ἀκούσαντα ὀρθῶς βουλεύσασθαι. μέλλεις γάρ”, ἔφη, “ἄγειν ἄνδρα φυγάδα, οὗ Ἀθηναῖοι θάνατον δὶς κατεψηφίσαντο, Καλλίστρατον ἐκ Μεθώνης εἰς Θάσον ὡς Τιμόμαχον τὸν κηδεστήν, ὡς ἐγώ”, ἔφη, “πέπυσμαι τῶν παίδων τῶν Καλλίππου. σὺ οὖν, ἐὰν σωφρονῇς, οὐδένα τῶν φευγόντων ἐάσεις ἐπὶ τὴν ναῦν ἀναβαίνειν· οὐ γὰρ ἐῶσιν οἱ νόμοι”.", "st": "50.48"}, {"sp": "N", "t": "ἀκούσας δ’ ἐγὼ ταῦτα τοῦ Καλλικλέους προσέρχομαι τῷ Καλλίππῳ, καὶ ἐρωτῶ αὐτὸν ὅποι τε τὸν πλοῦν ποιεῖται καὶ ἐπὶ τίνα. διαχλευάσαντος δ’ αὐτοῦ με καὶ ἀπειλήσαντος ἃ οὐδ’ ἂν ὑμεῖς ἀγνοήσαιτε (τοῦ γὰρ τρόπου τοῦ Καλλίππου οὐκ ἀπείρως ἔχετε), λέγω αὐτῷ ὅτι “ἀκούω σε πλεῖν ἐπὶ Καλλίστρατον. ἐγὼ οὖν τῶν φευγόντων οὐδένα ἄξω, οὐδὲ πλεύσομαι ἐπ’ αὐτόν· οἱ γὰρ νόμοι οὐκ ἐῶσιν ὑποδέχεσθαι τῶν φευγόντων οὐδένα, ἢ ἐν τοῖς αὐτοῖς κελεύουσιν ἐνέχεσθαι τὸν ὑποδεχόμενον τοὺς φεύγοντας. ἀποπλεύσομαι οὖν πάλιν ὡς τὸν στρατηγὸν εἰς Θάσον.”", "st": "50.49"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἐνέβησαν οἱ ναῦται, λέγω τῷ κυβερνήτῃ ἀποπλεῖν εἰς τὴν Θάσον. ἀντιλέγοντος δὲ τοῦ Καλλίππου καὶ κελεύοντος πλεῖν εἰς τὴν Μακεδονίαν, οἷ προσέταξεν ὁ στρατηγός, ἀποκρίνεται αὐτῷ Ποσείδιππος ὁ κυβερνήτης ὅτι τριήραρχός τε ἐγὼ τῆς νεὼς εἴην καὶ ὑπεύθυνος, καὶ τὸν μισθὸν παρ’ ἐμοῦ λαμβάνοι· πλεύσοιτο οὖν οἷ ἐγὼ κελεύω, εἰς Θάσον ὡς τὸν στρατηγόν.", "st": "50.50"}, {"sp": "N", "t": "ἀφικομένων δ’ ἡμῶν τῇ ὑστεραίᾳ εἰς τὴν Θάσον, μεταπέμπεταί με ὁ Τιμόμαχος, οὗ κατήγετο ἔξω τείχους. φοβούμενος δ’ ἐγὼ μὴ δεθείην διαβληθεὶς ὑπὸ τοῦ Καλλίππου, αὐτὸς μὲν οὐχ ὑπακούω, ἀλλὰ λέγω τῷ ὑπηρέτῃ ὅτι εἴ τι βούλοιτό μοι διαλέγεσθαι, ἐν τῇ ἀγορᾷ ἔσομαι, τὸν δὲ παῖδα συμπέμπω αὐτῷ, ἵν’ εἴ τί μοι προστάττοι, ἀκούσας ἀπαγγείλαι μοι.", "st": "50.51"}, {"sp": "N", "t": "διὰ μὲν ταύτας τὰς αἰτίας, ὦ ἄνδρες δικασταί, ἃς εἴρηκα πρὸς ὑμᾶς, ὁ Τιμόμαχος οὐκ ἠνάγκαζε παραλαμβάνειν τοῦτον τὴν ναῦν, ἔτι δὲ καὶ βουλόμενος αὐτὸς χρῆσθαι τῇ νηὶ ὡς ἄριστα πλεούσῃ. τὴν μὲν γὰρ [τοῦ] Θρασυλόχου τοῦ Ἀναγυρασίου τριήρη, ἐφ’ ἧς αὐτὸς ἔπλει, τὸν Θρασύλοχον τῷ Καλλίππῳ μισθῶσαι τὴν τριηραρχίαν ἔπεισεν, ἵν’ αὐτοκράτωρ ὢν ὁ Κάλλιππος τῆς νεὼς ἄγοι τὸν Καλλίστρατον· αὐτὸς δ’ ἀναβὰς ἐπὶ τὴν ἐμὴν ναῦν περιέπλει πανταχοῖ, ἕως ἀφίκετο εἰς Ἑλλήσποντον.", "st": "50.52"}, {"sp": "N", "t": "ἐπειδὴ δ’ οὐκέτι χρεία ἦν αὐτῷ τριήρων, ἐμβιβάσας μοι Λυκῖνον τὸν Παλληνέα ἄρχοντα εἰς τὴν ναῦν, καὶ προστάξας αὐτῷ καθ’ ἡμέραν ἀργύριον διδόναι τοῖς ναύταις, ἀποπλεῖν οἴκαδέ με ἐκέλευεν. ἐπειδὴ τοίνυν καταπλέοντες οἴκαδε ἦμεν ἐν Τενέδῳ, καὶ οὔτε ὁ Λυκῖνος, ᾧ προσέταξεν ὁ Τιμόμαχος, ἐδίδου τοῖς ναύταις σιτηρέσιον (οὐ γὰρ ἔφη ἔχειν, ἀλλ’ ἐκ Μυτιλήνης λήψεσθαι), οἵ τε στρατιῶται εἶχον οὐδὲν ὅτου ἂν ἐπεσιτίσαντο, ἄσιτοι δὲ οὐκ ἂν ἐδύναντο ἐλαύνειν,", "st": "50.53"}, {"sp": "N", "t": "πάλιν παραλαβὼν ἐγὼ μάρτυρας τῶν πολιτῶν, προσελθὼν Πολυκλεῖ τουτῳὶ ἐν Τενέδῳ, ἐκέλευον αὐτὸν τήν τε ναῦν παραλαμβάνειν ὡς διάδοχον ὄντα, καὶ τὸ ἐπιτριηράρχημα ἀποδιδόναι τοῦ χρόνου οὗ ἐπανήλωσα ὑπὲρ τούτου ἐπιτριηραρχῶν, ἵνα μὴ πρόφασις αὐτῷ γένοιτο ἀπολογίας πρὸς ὑμᾶς, ὡς ἐγὼ διὰ τοῦτο οὐκ ἤθελον αὐτῷ παραδοῦναι τὴν ναῦν φιλοτιμούμενος, ἵνα καταπλεύσαιμι οἴκαδε ἐπὶ νεὼς εὖ πλεούσης καὶ ἐνδειξαίμην ὑμῖν τὰ ἀναλώματα.", "st": "50.54"}, {"sp": "N", "t": "οὐκ ἐθέλοντος δ’ αὐτοῦ παραλαμβάνειν, τῶν δὲ ναυτῶν ἀργύριον αἰτούντων ἵνα ἀγοράσωνται τὰ ἐπιτήδεια, πάλιν αὐτῷ προσέρχομαι μάρτυρας ἔχων, καὶ ἠρώτων αὐτὸν εἰ ἀναπλεύσειεν ἔχων ἀργύριον ὡς διαδεξόμενός μοι τὴν ναῦν, ἢ οὔ. ἀποκριναμένου δ’ αὐτοῦ ὅτι ἔχων ἀργύριον ἥκοι, ἐκέλευον αὐτόν μοι δανεῖσαι ὑποθέμενον τὰ σκεύη τῆς νεώς, ἵν’ ἔχοιμι διαδοῦναι τοῖς ναύταις καὶ κατακομίσαι τὴν ναῦν, ἐπειδὴ οὐ βούλεται παραλαβεῖν διάδοχος ὤν.", "st": "50.55"}, {"sp": "N", "t": "δεομένου δέ μου ταῦτα, ἀπεκρίνατό μοι ὅτι οὐδ’ ἀκαρῆ δανείσοι. ἐγὼ μὲν οὖν παρὰ ξένων Τενεδίων τοῦ πατρός, Κλεάνακτος καὶ Ἐπηράτου, ἐδανεισάμην καὶ ἔδωκα τοῖς ναύταις τὸ σιτηρέσιον· διὰ γὰρ τὸ Πασίωνος εἶναι καὶ ἐκεῖνον ἐπεξενῶσθαι πολλοῖς καὶ πιστευθῆναι ἐν τῇ Ἑλλάδι οὐκ ἠπόρουν, ὅπου δεηθείην, δανείσασθαι. ὡς οὖν ταῦτα ἀληθῆ πρὸς ὑμᾶς λέγω, τούτων ὑμῖν τὰς μαρτυρίας παρέξομαι.", "st": "50.56"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "50.56"}, {"sp": "N", "t": "ὅσων μὲν τοίνυν ὑμῖν ἐδυνάμην τὰς μαρτυρίας παρασχέσθαι τῶν παραγενομένων, ὡς παρεδίδουν τὴν ναῦν Πολυκλεῖ πολλάκις, οὗτος δὲ οὐκ ἤθελεν παραλαβεῖν, ἀνέγνωκεν ὑμῖν· ἔτι δὲ καὶ ἐκ τεκμηρίων ἱκανῶν δεδήλωκα ὑμῖν, δι’ ὅ τι οὐκ ἤθελεν παραλαβεῖν τὴν ναῦν. βούλομαι δ’ ὑμῖν καὶ τὸν νόμον ἀναγνωσθῆναι τὸν περὶ τῶν διαδόχων, ἵν’ εἰδῆτε ἡλίκων τῶν ἐπιτιμίων ὄντων, ἐάν τις μὴ διαδέξηται τὴν ναῦν ἐν τῷ χρόνῳ τῷ εἰρημένῳ, κατεφρόνησεν οὐκ ἐμοῦ μόνον, ἀλλὰ καὶ ὑμῶν καὶ τῶν νόμων.", "st": "50.57"}, {"sp": "N", "t": "καὶ διὰ μὲν τοῦτον πάντα τῇ πόλει ἄπρακτα γέγονεν καὶ τοῖς συμμάχοις· οὔτε γὰρ ἀφίκετο ἐπὶ τὴν ναῦν κατὰ τὸν νόμον, οὔτ’ ἐπειδὴ ἦλθεν ἠθέλησε διαδέξασθαι· ἐγὼ δὲ καὶ τὸν ὑπὲρ ἐμαυτοῦ ὑμῖν χρόνον καὶ τὸν ὑπὲρ τοῦ συντριηράρχου ἐλῃτούργησα, καὶ ἐπειδὴ ἐξῆλθέ μοι ὁ χρόνος τῆς τριηραρχίας, προστάττοντός μοι τοῦ στρατηγοῦ πλεῖν ἐφ’ Ἱερὸν παρέπεμψα τῷ δήμῳ τὸν σῖτον,", "st": "50.58"}, {"sp": "N", "t": "ἵνα ἔχητε ἄφθονον ὠνεῖσθαι καὶ μηδὲν ὑμῖν ⟨τὸ⟩ κατ’ ἐμὲ ἐλλείπηται, καὶ ἄλλα ὅσα ἢ ἐμοὶ ἢ τῇ τριήρει ἐβουλήθη ὁ στρατηγὸς χρῆσθαι, παρέσχον αὐτῷ, οὐ μόνον τὴν οὐσίαν ἀναλίσκων, ἀλλὰ καὶ τῷ σώματι κινδυνεύων συνεπιπλέων, τῶν οἰκείων μοι πραγμάτων τοιούτων συμβεβηκότων ἐν τῷ τότε καιρῷ, ὥστε ὑμᾶς ἂν ἀκούσαντας ἐλεῆσαι.", "st": "50.59"}, {"sp": "N", "t": "ἡ μέν γε μήτηρ ἔκαμνε καὶ ἐπιθάνατος ἦν ἐμοῦ ἀποδημοῦντος, ὥστε μὴ δύνασθαι [ἂν] ἔτι αὐτὴν βοηθῆσαι τοῖς ἐμοῖς πράγμασιν ἀνηλωμένοις ἀλλ’ ἢ βραχέα. ἑκταῖος γὰρ ἥκων ἐτύγχανον, καὶ ἐκείνη ἰδοῦσά με καὶ προσειποῦσα τὴν ψυχὴν ἀφῆκεν, οὐκέτι τῶν ὄντων κυρία οὖσα ὥστε δοῦναι ὅσα ἐβούλετό μοι. πολλάκις δὲ πρότερον μετεπέμπετό με, ἀφικέσθαι δεομένη αὐτόν, εἰ μὴ τῇ τριήρει οἷόν τε εἴη.", "st": "50.60"}, {"sp": "N", "t": "ἡ δὲ γυνή, ἣν ἐγὼ περὶ πλείστου ποιοῦμαι, ἀσθενῶς διέκειτο πολὺν χρόνον ἐν τῇ ἐμῇ ἀποδημίᾳ· τὰ δὲ παιδία μικρά, ἡ δὲ οὐσία ὑπόχρεως· ἡ δὲ γῆ οὐχ ὅπως τινὰ καρπὸν ἤνεγκεν, ἀλλὰ καὶ τὸ ὕδωρ ἐν ἐκείνῳ τῷ ἐνιαυτῷ, ὡς πάντες ἴστε, ἐκ τῶν φρεάτων ἐπέλιπεν, ὥστε μηδὲ λάχανον γενέσθαι ἐν τῷ κήπῳ· οἱ δὲ δεδανεικότες ἧκον ἐπὶ τοὺς τόκους, ἐπειδὴ ὁ ἐνιαυτὸς ἐξῆλθεν, εἰ μή τις ἀποδοίη αὐτοῖς κατὰ τὰς συγγραφάς.", "st": "50.61"}, {"sp": "N", "t": "ὧν ἀκούοντά με καὶ παρὰ τῶν ἀφικνουμένων λόγῳ, τὰ δὲ καὶ δι’ ἐπιστολῶν παρὰ τῶν οἰκείων, τίνα με οἴεσθε ψυχὴν ἔχειν ἢ πόσα δάκρυα ἀφιέναι, τὰ μὲν ἐκλογιζόμενον περὶ τῶν παρόντων, τὰ δὲ καὶ ποθοῦντα ἰδεῖν παιδία καὶ γυναῖκα καὶ μητέρα, ἣν ἐγὼ οὐ πολλὰς ἐλπίδας εἶχον ζῶσαν καταλήψεσθαι; ὧν τί ἥδιόν ἐστιν ἀνθρώπῳ, ἢ τοῦ ἕνεκ’ ἄν τις εὔξαιτο τούτων στερηθεὶς ζῆν.", "st": "50.62"}, {"sp": "N", "t": "τοιούτων τοίνυν μοι συμβεβηκότων τῶν πραγμάτων, οὐ περὶ πλείονος ἐποιησάμην τὰ ἐμαυτοῦ ἴδια ἢ τὰ ὑμέτερα, ἀλλ’ ἡγούμην δεῖν καὶ χρημάτων ἀναλισκομένων κρείττων εἶναι καὶ τῶν οἴκοι ἀμελουμένων καὶ γυναικὸς καὶ μητρὸς νοσούσης, ὥστε μήτε τὴν τάξιν αἰτιᾶσθαί μέ τινα λιπεῖν μήτε τὴν τριήρη τῇ πόλει ἄχρηστον γενέσθαι.", "st": "50.63"}, {"sp": "N", "t": "ἀνθ’ ὧν ἁπάντων νῦν ὑμῶν δέομαι, ὥσπερ ἐγὼ ὑμῖν εὔτακτον καὶ χρήσιμον ἐμαυτὸν παρέσχον, οὕτω καὶ ὑμᾶς νυνὶ περὶ ἐμοῦ πρόνοιαν ποιησαμένους, καὶ ἀναμνησθέντας ἁπάντων ὧν τε διηγησάμην πρὸς ὑμᾶς, τῶν τε μαρτυριῶν ὧν παρεσχόμην καὶ τῶν ψηφισμάτων, βοηθῆσαι μὲν ἐμοὶ ἀδικουμένῳ, τιμωρήσασθαι δ’ ὑπὲρ ὑμῶν ⟨αὐτῶν⟩, εἰσπρᾶξαι δὲ τὰ ὑπὲρ τούτου ἀνηλωμένα. ἢ τίς ἐθελήσει φιλοτιμεῖσθαι πρὸς ὑμᾶς, ὅταν ὁρῶσι μήτε τοῖς χρηστοῖς καὶ εὐτάκτοις χάριν οὖσαν, μήτε τοῖς πονηροῖς καὶ ἀκοσμοῦσιν τιμωρίαν παρ’ ὑμῶν.", "st": "50.64"}, {"sp": "N", "t": "ἀναγνώσεται δὲ καὶ τὸν νόμον ὑμῖν καὶ τὰ ἀναλώματα τοῦ χρόνου οὗ ἐπετριηράρχησα ὑπὲρ τούτου, καθ’ ἕκαστον, καὶ τοὺς λιπόνεως, ὅσον ἕκαστος ἔχων ἀργύριον ἀπέδρα καὶ ὅπου, ἵνα εἰδῆτε ὅτι οὔτε νῦν πρὸς ὑμᾶς ψεῦδος οὐδὲν λέγω οὔτε ἐν τῷ πρόσθεν χρόνῳ, ἡγοῦμαί τε δεῖν τὸν μὲν ὑπὸ τῶν νόμων χρόνον ὡρισμένον ἀμέμπτως ὑμῖν λῃτουργεῖν, τοὺς δὲ καταφρονοῦντας καὶ ὑμῶν καὶ τῶν νόμων καὶ οὐκ ἐθέλοντας πείθεσθαι τοῖς νόμοις ἐξελέγξας ἀδικοῦντας ἐν ὑμῖν τιμωρήσασθαι.", "st": "50.65"}, {"sp": "N", "t": "εὖ δ’ ἴστε ὅτι οὐ περὶ τῶν ἐμῶν ἰδίων μᾶλλον τιμωρήσεσθε Πολυκλέα ἢ οὐχ ὑπὲρ ὑμῶν αὐτῶν, οὐδὲ περὶ τῶν παρεληλυθότων τριηράρχων ἐπιμέλειαν ποιήσεσθε μόνον, ἀλλὰ καὶ περὶ τῶν μελλόντων πρόνοιαν, ὥστε μήτε τοὺς λῃτουργοῦντας ἀθυμεῖν, μήτε τοὺς διαδόχους καταφρονεῖν τῶν νόμων, ἀλλ’ ἀπιέναι ἐπὶ τὰς ναῦς, ὅταν κατασταθῶσιν. ἃ προσήκει ὑμᾶς ἐνθυμηθέντας ὀρθῶς καὶ δικαίως διαγνῶναι περὶ ἁπάντων.", "st": "50.66"}, {"sp": "N", "t": "ἡδέως δ’ ἂν ὑμῶν πυθοίμην, ὦ ἄνδρες δικασταί, τίν’ ἄν ποτε γνώμην περὶ ἐμοῦ εἴχετε, εἰ τοῦ τε χρόνου ἐξήκοντος καὶ τούτου μὴ ἥκοντος ἐπὶ τὴν ναῦν μὴ ἐπετριηράρχησα κελεύοντος τοῦ στρατηγοῦ, ἀλλὰ πλέων ᾠχόμην. ἆρ’ οὐκ ἂν ὠργίζεσθέ μοι καὶ ἡγεῖσθε ἂν ἀδικεῖν; εἰ τοίνυν ἂν ἐμοὶ τότε ὠργίζεσθε, ὅτι οὐκ ἐπετριηράρχησα, πῶς οὐχὶ νῦν προσήκει ὑμᾶς τοῦτον εἰσπρᾶξαί μοι τὰ ἀναλώματα, ἃ ἐγὼ ὑπὲρ τούτου ἀνήλωσα, τὸν οὐ διαδεξάμενον τὴν ναῦν.", "st": "50.67"}, {"sp": "N", "t": "ὅτι δ’ οὐκ ἐμοὶ μόνῳ οὐ διεδέξατο τὴν ναῦν, ἀλλὰ καὶ πρότερον Εὐριπίδῃ συντριήραρχος ὢν καὶ συνθηκῶν οὐσῶν αὐτοῖς τοὺς ἓξ μῆνας ἑκάτερον πλεῖν, ἐπειδὴ Εὐριπίδης ἐξέπλευσεν καὶ ὁ χρόνος ἐξῆκεν, οὐ διεδέξατο τὴν ναῦν αὐτῷ, ἀναγνώσεται τὴν μαρτυρίαν.", "st": "50.68"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "50.68"}, {"sp": "HDR", "t": "Περὶ τοῦ Στεφάνου τῆς τριηραρκίας", "st": "51"}, {"sp": "N", "t": "εἰ μὲν ὅτῳ πλεῖστοι συνείποιεν, ὦ βουλή, τὸ ψήφισμ’ ἐκέλευε δοῦναι τὸν στέφανον, κἂν ἀνόητος ἦν εἰ λαβεῖν αὐτὸν ἠξίουν, Κηφισοδότου μόνου μοι συνειρηκότος, τούτοις δὲ παμπόλλων. νῦν δὲ τῷ πρώτῳ παρασκευάσαντι τὴν τριήρη τὸν ταμίαν προσέταξεν ὁ δῆμος δοῦναι, πεποίηκα δὲ τοῦτ’ ἐγώ· διό φημι δεῖν αὐτὸς στεφανοῦσθαι.", "st": "51.1"}, {"sp": "N", "t": "θαυμάζω δὲ καὶ τούτων, ὅτι τῆς τριήρους ἀμελήσαντες τοὺς ῥήτορας παρεσκεύασαν, καὶ δοκοῦσί μοι παντὸς διημαρτηκέναι τοῦ πράγματος, καὶ νομίζειν οὐχὶ τοῖς ποιοῦσιν ἃ δεῖ χάριν ὑμᾶς ἔχειν, ἀλλὰ τοῖς φάσκουσιν, οὐ τὸν αὐτὸν τρόπον ἐγνωκότες ὅνπερ ἐγὼ περὶ ὑμῶν. καὶ κατ’ αὐτὸ δὴ τοῦτο δικαίως ἂν ἔχοιτ’ εὐνοϊκωτέρως ἐμοί· φαίνομαι γὰρ βελτίους ὑμᾶς ὑπολαμβάνων ἢ οὗτοι.", "st": "51.2"}, {"sp": "N", "t": "ἐχρῆν μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, καὶ δίκαιον ἦν τοὺς τὸν στέφανον οἰομένους δεῖν παρ’ ὑμῶν λαβεῖν αὑτοὺς ἀξίους ἐπιδεικνύναι τούτου, μὴ ἐμὲ κακῶς λέγειν. ἐπειδὴ δὲ τοῦτο παρέντες ἐκεῖνο ποιοῦσιν, ἀμφότερ’ αὐτοὺς ἐπιδείξω ψευδομένους, ἅ θ’ αὑτοὺς ἐνεκωμίασαν καὶ ὅσ’ εἰς ἡμᾶς ἐβλασφήμησαν, ἐξ αὐτῶν τῶν πεπραγμένων ἑκατέροις.", "st": "51.3"}, {"sp": "N", "t": "ψήφισμα γὰρ ὑμῶν ποιησαμένων, ὃς ἂν μὴ πρὸ τῆς ἕνης καὶ νέας ἐπὶ χῶμα τὴν ναῦν περιορμίσῃ, δῆσαι καὶ δικαστηρίῳ παραδοῦναι, καὶ ταῦτα κυρωσάντων, ἐγὼ μὲν περιώρμισα καὶ στέφανον διὰ ταῦτα παρ’ ὑμῶν ἔλαβον, οὗτοι δ’ οὐδὲ καθείλκυσαν, ὥστ’ ἔνοχοι δεσμῷ γεγόνασιν. πῶς οὖν οὐκ ἀτοπώτατον ἂν διαπράξαισθ’ ἔργον, εἰ τοὺς καθ’ ἑαυτῶν ἐάσαντας τίμημα τοιοῦτον ἐπαχθῆναι, τούτους στεφανώσαντες ὑμεῖς φαίνοισθε;", "st": "51.4"}, {"sp": "N", "t": "τὰ σκεύη τοίνυν, ὅσα δεῖ παρέχειν τὴν πόλιν τοῖς τριηράρχοις, ἐγὼ μὲν ἐκ τῶν ἰδίων ἀνήλωσα καὶ τῶν δημοσίων ἔλαβον οὐδέν, οὗτοι δ’ ὑμετέροις κέχρηνται καὶ τῶν σφετέρων οὐδὲν εἰς ταῦτα προεῖνται. καὶ μὴν οὐδ’ ἂν ἐκεῖνό γ’ ἔχοιεν εἰπεῖν, ὡς ἀνεπειρῶντ’ ἐμοῦ πρότεροι· πρὶν γὰρ ἧφθαι μόνον τῆς τριήρους τούτους ἐπεπλήρωτό μοι, καὶ πάντες ἑωρᾶθ’ ὑμεῖς ἀναπειρωμένην τὴν ναῦν.", "st": "51.5"}, {"sp": "N", "t": "ἔτι τοίνυν ὑπηρεσίαν τὴν κρατίστην ἔλαβον, πολλῷ πλεῖστον ἀργύριον δούς. οὗτοι δ’ εἰ μὲν εἶχον χείρον’ ἡμῶν, οὐδὲν ἂν ἦν δεινόν· νῦν δ’ οὐδ’ ὁποιαντινοῦν μεμίσθωνται, περὶ τοῦ πλείονος ἀντιλέγοντες. καίτοι πῶς εἰσιν δίκαιοι ταῦτα μὲν ὕστερον ἐξαναπληροῦν, νῦν δ’ ὡς πρῶτοι παρασκευασάμενοι τὸν στέφανον λαβεῖν;", "st": "51.6"}, {"sp": "N", "t": "ἡγοῦμαι τοίνυν, ὅτι μὲν δικαιότατ’ ἂν στεφανώσαιτ’ ἐμέ, καὶ μηδὲν εἰπόντος ἐμοῦ γιγνώσκειν ὑμᾶς· ὅτι δ’ οὐκ ἔνεστι μόνοις τούτοις περὶ τοῦ στεφάνου λόγος, τοῦτ’ ἐπιδεῖξαι βούλομαι. πόθεν οὖν τοῦτο μάλιστ’ ἔσται δῆλον; ἀφ’ ὧν αὐτοὶ πεποιήκασιν· σκεψάμενοι γὰρ τὸν ἐξ ἐλαχίστου τριηραρχεῖν βουλόμενον, μεμισθώκασι τὴν λῃτουργίαν. καίτοι πῶς οὐκ ἄδικον τῶν μὲν ἀναλωμάτων ἀφεστηκέναι, τῶν δὲ γιγνομένων δι’ ἐκεῖνα τιμῶν ἀξιοῦν αὑτοῖς μετεῖναι; καὶ τοῦ μὲν μὴ περιορμίσαι τὴν ναῦν τότε τὸν μεμισθωμένον αἰτιᾶσθαι, τῶν δὲ καλῶς δεδιακονημένων νῦν αὑτοῖς κελεύειν χάριν ὑμᾶς ἔχειν;", "st": "51.7"}, {"sp": "N", "t": "δεῖ τοίνυν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, μὴ μόνον ἐκ τούτων σκοπεῖν τὸ δίκαιον, ἀλλὰ καὶ ἐξ ὧν αὐτοὶ πρότερον πεποιήκατε ταὐτὰ τινῶν διαπραξαμένων τούτοις. ὅτε γὰρ τῇ ναυμαχίᾳ τῇ πρὸς Ἀλέξανδρον ἐνικήθητε, τότε τῶν τριηράρχων τοὺς μεμισθωκότας τὰς τριηραρχίας αἰτιωτάτους τοῦ γεγενημένου νομίζοντες παρεδώκατ’ εἰς τὸ δεσμωτήριον, καταχειροτονήσαντες προδεδωκέναι τὰς ναῦς καὶ λελοιπέναι τὴν τάξιν.", "st": "51.8"}, {"sp": "N", "t": "καὶ κατηγόρει μὲν Ἀριστοφῶν, ἐδικάζετε δ’ ὑμεῖς· εἰ δὲ μὴ μετριωτέραν ἔσχετε τὴν ὀργὴν τῆς ἐκείνων πονηρίας, οὐδὲν αὐτοὺς ἐκώλυε τεθνάναι. ταὐτὰ τοίνυν εἰδότες οὗτοι πεπραγμέν’ αὑτοῖς καὶ ἐκείνοις, οὐχὶ φρίττουσιν ἐν ὑμῖν ὑπὲρ ὧν προσήκει παθεῖν αὐτούς, ἀλλὰ δημηγοροῦσι κατ’ ἄλλων καὶ στεφανοῦν κελεύουσιν αὑτούς. καίτοι σκέψασθε τίν’ ἄν ποτε δόξαιτε βεβουλεῦσθαι τρόπον, εἰ διὰ τὴν αὐτὴν πρόφασιν τοὺς μὲν θανάτου κρίναντες, τοὺς δὲ στεφανώσαντες φανείητε.", "st": "51.9"}, {"sp": "N", "t": "καὶ μὴν οὐ μόνον εἰ τοῦτο ποιήσαιτε, δοκεῖτ’ ἂν ἁμαρτεῖν, ἀλλ’ εἰ μὴ καὶ κολάσαιτε τοὺς τὰ τοιαῦτα ποιοῦντας, ἔχοντες. οὐ γὰρ ἐπειδὰν ἐάσητέ τι τῶν ὑμετέρων ἀπολέσθαι, τότε χρὴ χαλεπαίνειν, ἀλλ’ ἐν ᾧ τὰ μὲν ὑμέτερ’ ἐστὶν σᾶ, καθορᾶτε δὲ τοὺς ἐφεστηκότας δι’ αἰσχροκερδίαν οὐχὶ προσήκουσαν πρόνοιαν περὶ σωτηρίας αὐτῶν ποιουμένους. καὶ μηδεὶς ὑμῶν ἐπιτιμήσῃ τῷ λόγῳ, πικρὸν εἶναι νομίσας, ἀλλὰ τοῖς τὸ ἔργον αὐτὸ πεποιηκόσιν· διὰ γὰρ τούτους τοιοῦτός ἐστιν.", "st": "51.10"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε, τί δή ποτε τῶν μὲν ναυτῶν τοὺς ἀπολειπομένους, ὧν τριάκοντα δραχμὰς ἕκαστος ἔχει μόνας, δοῦσι καὶ κολάζουσιν οὗτοι· τῶν δὲ τριηράρχων τοὺς μὴ συμπλέοντας, ὧν τριάκοντα μνᾶς εἰς ἔκπλουν εἴληφεν ἕκαστος, οὐ ταὐτὰ ποιεῖθ’ ὑμεῖς· ἀλλ’ ἐὰν μὲν πένης ὤν τις δι’ ἔνδειαν ἁμάρτῃ, τοῖς ἐσχάτοις ἐπιτιμίοις ἐνέξεται, ἐὰν δὲ πλούσιος ὢν δι’ αἰσχροκερδίαν ταὐτὰ ποιήσῃ, συγγνώμης τεύξεται; καὶ ποῦ τὸ πάντας ἔχειν ἴσον καὶ δημοκρατεῖσθαι φαίνεται, τοῦτον τὸν τρόπον ὑμῶν ταῦτα βραβευόντων;", "st": "51.11"}, {"sp": "N", "t": "ἔτι τοίνυν ἔμοιγε δοκεῖ κἀκεῖν’ ἀλόγως ἔχειν, τὸν μὲν εἰπόντα τι μὴ κατὰ τοὺς νόμους, ἐὰν ἁλῷ τὸ τρίτον, μέρος ἠτιμῶσθαι τοῦ σώματος, τοὺς δὲ μὴ λόγον, ἀλλ’ ἔργον παράνομον πεποιηκότας μηδεμίαν δοῦναι δίκην. καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, πάντες ὑμεῖς φήσετε τὸ πρὸς τὰ τοιαῦτα πράως ἔχειν προδιδάσκειν ἑτέρους ἀδικεῖν εἶναι.", "st": "51.12"}, {"sp": "N", "t": "βούλομαι τοίνυν, ἐπειδήπερ παρῆλθον, καὶ τὰ συμβαίνοντ’ ἀπὸ τῶν τοιούτων ὑμῖν διεξελθεῖν. ἐπειδὰν γάρ τις μισθωσάμενος τριηραρχίαν ἐκπλεύσῃ, πάντας ἀνθρώπους ἄγει καὶ φέρει, καὶ τὰς μὲν ὠφελίας ἰδίᾳ καρποῦται, τὰς δὲ δίκας τούτων ὁ τυχὼν δίδωσιν ὑμῶν, καὶ μόνοις ὑμῖν οὐδαμόσε ἔστιν ἄνευ κηρυκείου βαδίσαι διὰ τὰς ὑπὸ τούτων ἀνδροληψίας καὶ σύλας κατεσκευασμένας·", "st": "51.13"}, {"sp": "N", "t": "ὥστε τῇ γ’ ἀληθείᾳ σκοπῶν ἄν τις εὕροι τὰς τοιαύτας τριήρεις οὐχ ὑπὲρ ὑμῶν, ἀλλὰ καθ’ ὑμῶν ἐκπεπλευκυίας. τὸν γὰρ ὑπὲρ τῆς πόλεως τριήραρχον οὐκ ἀπὸ τῶν κοινῶν προσδοκᾶν χρὴ πλουτήσειν, ἀλλ’ ἀπὸ τῶν ἰδίων τὰ τῆς πόλεως ἐπανορθώσειν, εἴπερ ἔσται τι τῶν δεόντων ὑμῖν. τούτων δὲ τἀναντί’ ἕκαστος ἐγνωκὼς ἐκπλεῖ· καὶ γάρ τοι τὰ τῶν αὑτῶν τρόπων ἁμαρτήματα ταῖς ὑμετέραις βλάβαις ἐπανορθοῦνται.", "st": "51.14"}, {"sp": "N", "t": "καὶ τούτων οὐδέν ἐστιν ἄλογον. δεδώκατε γὰρ τοῖς βουλομένοις ἀδικεῖν, ἂν μὲν λάθωσιν, ἔχειν, ἐὰν δὲ ληφθῶσι, συγγνώμης τυχεῖν· τοῖς οὖν ἠμεληκόσι δόξης ἄδεια ποιεῖν ὅ τι ἂν βούλωνται γέγονεν. τῶν μὲν τοίνυν ἰδιωτῶν τοὺς μετὰ τοῦ παθεῖν μανθάνοντας ἀπροσκέπτους ὀνομάζομεν· ὑμᾶς δέ, οἵτινες οὐδὲ πεπονθότες πολλάκις ἤδη φυλάττεσθε, τί τις καλέσειεν ἄν;", "st": "51.15"}, {"sp": "N", "t": "ἄξιον τοίνυν καὶ περὶ τῶν συνειρηκότων εἰπεῖν. οὕτως γὰρ ἡγοῦνταί τινες ἐξουσίαν εἶναι σφίσιν καὶ ποιεῖν ὅ τι βούλονται καὶ λέγειν παρ’ ὑμῖν, ὥστε τῶν τότε συγκατηγορούντων μετ’ Ἀριστοφῶντος καὶ πικρῶν ὄντων τοῖς μεμισθωκόσι τὰς τριηραρχίας νῦν κελεύουσί τινες τούτους στεφανῶσαι, καὶ δυοῖν θάτερον ἐξελέγχουσιν αὑτούς, ἢ τότ’ ἐκείνους ἀδίκως συκοφαντοῦντες, ἢ νῦν τοῖσδ’ ἐπὶ μισθῷ συνηγοροῦντες.", "st": "51.16"}, {"sp": "N", "t": "καὶ χαρίσασθαι κελεύουσιν ὑμᾶς, ὥσπερ περὶ δωρεᾶς, ἀλλ’ οὐ περὶ νικητηρίων τῶν λόγων ὄντων, ἢ καὶ χάριν τιθεμένων διὰ τῶν τοιούτων τοῖς ἀμελοῦσιν ὑμῶν, ἀλλ’ οὐ διὰ τῶν βελτιόνων τοῖς ὑπηρετοῦσιν ἃ δεῖ χαρίζεσθαι προσῆκον. ἔπειθ’ οὕτως ὀλιγωροῦσιν τοῦ δοκεῖν ἐπιεικεῖς εἶναι, καὶ παντελῶς τἄλλα πάρεργα πρὸς τὸ λαβεῖν νομίζουσιν, ὥστ’ οὐ μόνον τοῖς πρότερον ῥηθεῖσιν ὑφ’ αὑτῶν ἐναντία τολμῶσιν δημηγορεῖν, ἀλλὰ καὶ νῦν οὐ ταὐτὰ λέγουσιν ἑαυτοῖς, οἵτινες τοὺς μὲν ναύτας φασὶ δεῖν οἰκείους εἶναι τῆς τριήρους τῆς ληψομένης τὸν στέφανον, τῶν δὲ τριηράρχων τοὺς ἠλλοτριωκότας αὑτοὺς ἀπὸ τῆς λῃτουργίας, τούτους στεφανῶσαι κελεύουσι.", "st": "51.17"}, {"sp": "N", "t": "καὶ φασὶ μὲν οὐδένα τούτων πρότερον παρασκευάσασθαι, κελεύουσι δὲ κοινῇ στεφανοῦν ἡμᾶς, τοῦ ψηφίσματος οὐ ταῦτα λέγοντος. ἐγὼ δὲ τοσούτου δέω τοῦτο συγχωρεῖν ὅσουπερ καὶ μεμισθωκέναι τὴν τριηραρχίαν· οὔτε γὰρ τοῦθ’ ὑπομείναιμ’ ἂν οὔτ’ ἐκεῖν’ ἐποίησα. προσποιοῦνται μὲν τοίνυν ὑπὲρ τοῦ δικαίου συνηγορεῖν, σπουδάζουσιν δὲ μᾶλλον ἢ προῖκ’ ἄν τις ὑμῶν πράττων, ὥσπερ ἄξια τοῦ μισθοῦ ποιῆσαι προσῆκον ἑαυτοῖς, ἀλλ’ οὐ γνώμην ἀποφήνασθαι.", "st": "51.18"}, {"sp": "N", "t": "εἶθ’ ὥσπερ οὐχὶ πολιτείας κοινῆς μετέχοντες καὶ διὰ ταῦτα τῷ βουλομένῳ λέγειν ἐξόν, ἀλλ’ ἱερωσύνην ἰδίαν αὐτοί τινα ταύτην ἔχοντες, ἐὰν ὑπὲρ τῶν δικαίων ἐν ὑμῖν τις εἴπῃ, δεινὰ πάσχουσιν καὶ θρασὺν εἶναί φασιν. καὶ εἰς τοσοῦτον ἀναισθησίας προήκουσιν, ὥστ’ οἴονται τὸν ἅπαξ εἰρηκότ’ ἂν καλέσωσιν ἀναιδῆ, σφᾶς αὐτοὺς πάντ’ ⟨ἂν⟩ τὸν βίον καλοὺς κἀγαθοὺς νομίζεσθαι.", "st": "51.19"}, {"sp": "N", "t": "καίτοι διὰ μὲν τὰς τούτων δημηγορίας πολλὰ χεῖρον ἔχει, διὰ τοὺς δ’ οἰομένους δεῖν τὰ δίκαι’ ἀντιλέγειν οὐ πάντ’ ἀπόλωλεν. τοιούτους τοίνυν τοὺς συνεροῦντας αὑτοῖς παρεσκευασμένοι, καὶ τοσαύτην βλασφημίαν εἰδότες οὖσαν καθ’ ἑαυτῶν τοῖς βουλομένοις τι λέγειν φλαῦρον, ὅμως εἰς λόγον ἠξίωσαν καταστῆναι καὶ κακῶς τιν’ ἐτόλμησαν εἰπεῖν, οἷς ἀγαπητὸν ἦν μὴ πάσχουσιν κακῶς αὐτοῖς.", "st": "51.20"}, {"sp": "N", "t": "τοῦ τοίνυν τούτους ἀδίκους εἶναι καὶ θρασεῖς οὐδένες ὑμῶν εἰσιν αἰτιώτεροι· παρὰ γὰρ τῶν λεγόντων, οὓς ἴστ’ ἐπὶ μισθῷ τοῦτο πράττοντας, πυνθάνεσθε ποῖόν τιν’ ἕκαστον δεῖ νομίζειν, οὐκ αὐτοὶ θεωρεῖτε. καίτοι πῶς οὐκ ἄτοπον τούτους μὲν αὐτοὺς πονηροτάτους τῶν πολιτῶν νομίζειν, τοὺς δ’ ὑπὸ τούτων ἐπαινουμένους χρηστοὺς ἡγεῖσθαι;", "st": "51.21"}, {"sp": "N", "t": "καὶ γάρ τοι πάντα δι’ αὑτῶν ποιοῦνται, καὶ μόνον οὐχ ὑπὸ κήρυκος πωλοῦσι τὰ κοινά, καὶ στεφανοῦν, ὃν ἂν αὐτοῖς δοκῇ, καὶ μὴ στεφανοῦν κελεύουσι, κυριωτέρους αὑτοὺς τῶν ὑμετέρων δογμάτων καθιστάντες. ἐγὼ δ’ ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, παραινῶ μὴ ποιεῖν τὴν τῶν ἀναλίσκειν ἐθελόντων φιλοτιμίαν ἐπὶ τῇ τῶν λεγόντων πλεονεξίᾳ. εἰ δὲ μή, διδάξετε πάντας τὰ μὲν ὑφ’ ὑμῶν προσταττόμεν’ ὡς εὐτελέστατα διοικεῖν, τοὺς δ’ ὑπὲρ τούτων ἀναιδῶς εἰς ὑμᾶς ψευδομένους ὡς πλείστου μισθοῦσθαι.", "st": "51.22"}, {"sp": "HDR", "t": "Πρὸς Κάλλιππον", "st": "52"}, {"sp": "N", "t": "οὐκ ἔστιν χαλεπώτερον οὐδέν, ὦ ἄνδρες δικασταί, ἢ ὅταν ἄνθρωπος δόξαν ἔχων καὶ δυνάμενος εἰπεῖν τολμᾷ ψεύδεσθαι καὶ μαρτύρων εὐπορῇ. ἀνάγκη γάρ ἐστιν τῷ φεύγοντι μηκέτι περὶ τοῦ πράγματος μόνον λέγειν, ἀλλὰ καὶ περὶ αὐτοῦ τοῦ λέγοντος, ὡς οὐκ εἰκὸς αὐτῷ διὰ τὴν δόξαν πιστεύειν.", "st": "52.1"}, {"sp": "N", "t": "εἰ γὰρ ἔθος καταστήσετε τοῖς δυναμένοις εἰπεῖν καὶ δόξαν ἔχουσι μᾶλλον πιστεύειν ἢ τοῖς ἀδυνατωτέροις, ἐφ’ ὑμῖν αὐτοῖς ἔσεσθε τὸ ἔθος τοῦτο κατεσκευακότες. δέομαι οὖν ὑμῶν, εἴπερ τι καὶ ἄλλο πώποτε πρᾶγμα αὐτὸ καθ’ αὑτὸ ἐδικάσατε, μηδὲ μεθ’ ἑτέρων τὴν γνώμην γενόμενοι, μήτε μετὰ τῶν διωκόντων μήτε μετὰ τῶν φευγόντων, ἀλλὰ τὸ δίκαιον σκεψάμενοι, οὕτω καὶ νῦν διαγνῶναι. ἐξ ἀρχῆς δ’ ὑμῖν διηγήσομαι.", "st": "52.2"}, {"sp": "N", "t": "Λύκων γὰρ ὁ Ἡρακλεώτης, ὦ ἄνδρες δικασταί, οὗτος ὃν καὶ αὐτὸς λέγει, τῇ τραπέζῃ τῇ τοῦ πατρὸς ἐχρῆτο, ὥσπερ καὶ οἱ ἄλλοι ἔμποροι, ξένος μὲν ὢν Ἀριστόνῳ τῷ Δεκελεῖ καὶ Ἀρχεβιάδῃ τῷ Λαμπτρεῖ, ἄνθρωπος δέ τις σώφρων. οὗτος ἐπειδὴ ἐκπλεῖν ἔμελλεν εἰς τὴν Λιβύην, διαλογισάμενος πρὸς τὸν πατέρα τὸν ἐμὸν ἐναντίον Ἀρχεβιάδου καὶ Φρασίου προσέταξεν τὸ ἀργύριον ὃ κατέλειπεν (ἦν δὲ τοῦτο ἑκκαίδεκα μναῖ καὶ τετταράκοντα δραχμαί, ὡς ἐγὼ ὑμῖν πάνυ ἀκριβῶς ἐπιδείξω) Κηφισιάδῃ ἀποδοῦναι, λέγων ὅτι κοινωνὸς εἴη αὑτοῦ ὁ Κηφισιάδης οὗτος, οἰκήτωρ μὲν ὢν ἐν Σκίρῳ, ἐν δὲ τῷ παρόντι ἐφ’ ἑτέρᾳ ἀποδημῶν ἐμπορίᾳ.", "st": "52.3"}, {"sp": "N", "t": "δεῖξαι δ’ αὐτὸν τῷ πατρὶ τῷ ἐμῷ καὶ συστῆσαι τῷ Ἀρχεβιάδῃ καὶ τῷ Φρασίᾳ προσέταξεν, ἐπειδὴ ἥκοι ἐκ τῆς ἀποδημίας. εἰώθασι δὲ πάντες οἱ τραπεζῖται, ὅταν τις ἀργύριον τιθεὶς ἰδιώτης ἀποδοῦναί τῳ προστάττῃ, πρῶτον τοῦ θέντος τοὔνομα γράφειν καὶ τὸ κεφάλαιον τοῦ ἀργυρίου, ἔπειτα παραγράφειν “τῷ δεῖνι ἀποδοῦναι δεῖ”, καὶ ἐὰν μὲν γιγνώσκωσι τὴν ὄψιν τοῦ ἀνθρώπου ᾧ ἂν δέῃ ἀποδοῦναι, τοσοῦτο μόνον ποιεῖν, γράψαι ᾧ δεῖ ἀποδοῦναι, ἐὰν δὲ μὴ γιγνώσκωσι, καὶ τούτου τοὔνομα προσπαραγράφειν ὃς ἂν μέλλῃ συστήσειν καὶ δείξειν τὸν ἄνθρωπον, ὃν ἂν δέῃ κομίσασθαι τὸ ἀργύριον.", "st": "52.4"}, {"sp": "N", "t": "τύχης δὲ συμβάσης τοιαύτης τῷ Λύκωνι τούτῳ ὥστε εὐθὺς ἐκπλέοντα αὐτὸν περὶ τὸν Ἀργολικὸν κόλπον ὑπὸ λῃστρίδων νεῶν τά τε χρήματα καταχθῆναι εἰς Ἄργος καὶ αὐτὸν τοξευθέντα ἀποθανεῖν, ἔρχεται ἐπὶ τὴν τράπεζαν Κάλλιππος οὑτοσὶ εὐθὺς ἐρωτῶν, Λύκωνα Ἡρακλεώτην εἰ γιγνώσκοιεν. ἀποκριναμένου δὲ Φορμίωνος τουτουὶ ὅτι γιγνώσκοιεν, “ἆρα καὶ ἐχρῆτο ὑμῖν”; ἔφη ὁ Φορμίων· “ἀλλὰ πρὸς τί ἐρωτᾷς”; “πρὸς τί”; ἔφη· “ἐγώ σοι ἐρῶ. ἐκεῖνος μὲν τετελεύτηκεν, ἐγὼ δὲ προξενῶν τυγχάνω τῶν Ἡρακλεωτῶν. ἀξιῶ δή σε δεῖξαί μοι τὰ γράμματα, ἵν’ εἰδῶ εἴ τι καταλέλοιπεν ἀργύριον· ἐξ ἀνάγκης γάρ μοί ἐστιν ἁπάντων Ἡρακλεωτῶν ἐπιμελεῖσθαι.”", "st": "52.5"}, {"sp": "N", "t": "ἀκούσας δ’ αὐτοῦ ὁ Φορμίων, ὦ ἄνδρες δικασταί, ἔδειξεν εὐθέως παραχρῆμα. δείξαντος δὲ αὐτοῦ τὸ γραμματεῖον, ἀναγνοὺς αὐτὸς καὶ ἄλλος οὐδείς, καὶ ἰδὼν γεγραμμένον ἐν αὐτῷ “Λύκων Ἡρακλεώτης χιλίας ἑξακοσίας τετταράκοντα· Κηφισιάδῃ ἀποδοῦναι δεῖ· Ἀρχεβιάδης Λαμπτρεὺς δείξει τὸν Κηφισιάδην”, ᾤχετο ἀπιὼν σιωπῇ, καὶ πλέον ἢ πέντε μηνῶν οὐδένα λόγον ἐποιήσατο.", "st": "52.6"}, {"sp": "N", "t": "ἐπιδημήσαντος δὲ τοῦ Κηφισιάδου μετὰ ταῦτα καὶ προσελθόντος πρὸς τὴν τράπεζαν καὶ ἀπαιτοῦντος τὰ χρήματα, παρόντος δέ, ὦ ἄνδρες δικασταί, Ἀρχεβιάδου καὶ τοῦ Φρασίου, οὓς ὁ Λύκων τῷ πατρὶ συνέστησεν καὶ ἐκέλευσε τὸν Κηφισιάδην δεῖξαι ὃς εἴη, ἐπειδὴ ἔλθοι, παρόντων ⟨δὲ⟩ καὶ ἄλλων, ἐξαριθμήσας αὐτῷ τὰς ἑκκαίδεκα μνᾶς καὶ τετταράκοντα δραχμὰς ἀπέδωκε Φορμίων οὑτοσί. ὡς δὲ ἀληθῆ λέγω, τούτων ἁπάντων ὑμῖν τὰς μαρτυρίας ἀναγνώσεται.", "st": "52.7"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "52.7"}, {"sp": "N", "t": "ὅτι μὲν ἀληθῆ ἅπαντα εἶπον πρὸς ὑμᾶς, ὦ ἄνδρες δικασταί, τῶν μαρτυριῶν ἀκηκόατε. προσελθὼν δὲ συχνῷ χρόνῳ ὕστερον πρὸς τὸν πατέρα Κάλλιππος οὑτοσὶ ἐν ἄστει, ἤρετο αὐτὸν εἰ ἤδη ἐπιδεδημηκὼς εἴη ὁ Κηφισιάδης, ὅτῳ γεγραμμένον εἴη ἀποδοῦναι τὸ ἀργύριον τὸ ὑπὸ τοῦ Λύκωνος τοῦ Ἡρακλεώτου καταλειφθέν. ἀποκριναμένου δὲ τοῦ πατρὸς ὅτι οἴοιτο μέν, εἰ μέντοι βούλοιτο εἰς Πειραιᾶ καταβῆναι, τὴν ἀκρίβειαν εἴσοιτο, “οἶσθά τοι” ἔφη, “ὅ τι ἔστιν, ὦ Πασίων, ὅ σε ἐρωτῶ”;", "st": "52.8"}, {"sp": "N", "t": "(καὶ μὰ τὸν Δία καὶ τὸν Ἀπόλλω καὶ τὴν Δήμητρα, οὐ ψεύσομαι πρὸς ὑμᾶς, ὦ ἄνδρες δικασταί, ἀλλ’ ἃ τοῦ πατρὸς ἤκουον, διηγήσομαι ὑμῖν.) “ἔξεστί σοι” ἔφη “ἐμέ τε εὖ ποιῆσαι καὶ αὐτὸν μηδὲν βλαβῆναι. προξενῶν μὲν γὰρ τυγχάνω τῶν Ἡρακλεωτῶν, βούλοιο δ’ ἄν, ὡς οἶμαι ἐγώ, ἐμὲ μᾶλλον τὸ ἀργύριον λαβεῖν ἢ τὸν μέτοικον ἄνθρωπον καὶ ἐν Σκίρῳ κατοικοῦντα καὶ οὐδενὸς ἄξιον. συμβέβηκεν δὲ τοιοῦτόν τι· ὁ Λύκων τυγχάνει ὢν καὶ ἄπαις καὶ κληρονόμον οὐδένα οἴκοι καταλιπών, ὡς ἐγὼ πυνθάνομαι.”", "st": "52.9"}, {"sp": "N", "t": "“πρὸς δὲ τούτῳ, ἐπειδὴ εἰς Ἄργος κατήχθη τετρωμένος, τῷ προξένῳ τῶν Ἡρακλεωτῶν τῷ Ἀργείῳ Στραμμένῳ τὰ χρήματα δέδωκεν ἃ κατήχθη μετ’ αὐτοῦ. οἷος οὖν εἰμι καὶ ἐγὼ τὰ ἐνθάδε αὐτὸς ἀξιοῦν λαμβάνειν· ἡγοῦμαι γὰρ δίκαιος εἶναι ἔχειν. σὺ οὖν, εἰ ἄρα μὴ ἀπείληφεν, λέγε ὅτι ἐγὼ ἀμφισβητῶ, ἂν ἄρα ἔλθῃ ὁ Κηφισιάδης. εἰ δ’ ἄρα ἀπείληφεν, λέγε ὅτι ἐγὼ μάρτυρας ἔχων ἠξίουν ἐμφανῆ καταστῆσαι τὰ χρήματα ἢ τὸν κεκομισμένον, καὶ εἴ τίς με βούλεται ἀφελέσθαι, πρόξενον ὄντα ἀφαιρεθῆναι.”", "st": "52.10"}, {"sp": "N", "t": "ἐπειδὴ δὲ αὐτῷ εἴρητο, “ἐγώ”, ἔφη ὁ πατήρ, “ὦ Κάλλιππε, χαρίζεσθαι μέν σοι βούλομαι (καὶ γὰρ ἂν καὶ μαινοίμην, εἰ μή), οὕτω μέντοι ὅπως αὐτός τε μὴ χείρων δόξω εἶναι καὶ ἐκ τοῦ πράγματος μηδὲν ζημιώσομαι. εἰπεῖν μὲν οὖν μοι ταῦτα πρὸς τὸν Ἀρχεβιάδην καὶ τὸν Ἀριστόνουν καὶ πρὸς αὐτὸν δὲ τὸν Κηφισιάδην οὐδὲν διαφέρει· ἐὰν μέντοι μὴ ’θέλωσι ταῦτα ποιεῖν εἰπόντος ἐμοῦ, αὐτὸς ἤδη διαλέγου αὐτοῖς.” “ἀμέλει,” ἔφη οὗτος, “ὦ Πασίων, ἐὰν βούλῃ σύ, ἀναγκάσεις αὐτοὺς ταῦτα ποιῆσαι.”", "st": "52.11"}, {"sp": "N", "t": "ἃ μὲν διελέχθη, ὦ ἄνδρες δικασταί, οὗτος μὲν τῷ πατρί, ἐκεῖνος δὲ τῷ Ἀρχεβιάδῃ καὶ τῷ Κηφισιάδῃ τούτου δεηθέντος καὶ τούτῳ χαριζόμενος, ταῦτ’ ἔστιν, ἐξ ὧν κατὰ μικρὸν ἡ δίκη αὕτη πέπλασται· ὧν ἐγὼ ἤθελον τούτῳ ταύτην ἥτις εἴη μεγίστη πίστις δοῦναι, ἦ μὴν ἐγὼ τοῦ πατρὸς ἀκούειν.", "st": "52.12"}, {"sp": "N", "t": "οὗτος δὲ ὁ ἀξιῶν ὑφ’ ὑμῶν πιστεύεσθαι ὡς ἀληθῆ λέγων, τρία ἔτη διαλιπὼν ἐπειδὴ τὸ πρῶτον διαλεχθέντος τοῦ πατρὸς τῷ Ἀρχεβιάδῃ καὶ τοῖς ἄλλοις τοῖς Κηφισιάδου ἐπιτηδείοις οὐκ ἔφασαν Καλλίππῳ προσέχειν τὸν νοῦν οὐδὲ οἷς λέγει,", "st": "52.13"}, {"sp": "N", "t": "ἐπειδὴ ᾔσθετο ἀδυνάτως ἤδη ἔχοντα τὸν πατέρα καὶ μόγις εἰς ἄστυ ἀναβαίνοντα καὶ τὸν ὀφθαλμὸν αὐτὸν προδιδόντα, λαγχάνει αὐτῷ δίκην, οὐ μὰ Δί’ οὐχ ὥσπερ νῦν ἀργυρίου, ἀλλὰ βλάβης, ἐγκαλέσας βλάπτειν ἑαυτὸν ἀποδιδόντα Κηφισιάδῃ τὸ ἀργύριον, ὃ κατέλιπε Λύκων ὁ Ἡρακλεώτης παρ’ αὐτῷ, ἄνευ αὑτοῦ ὁμολογήσαντα μὴ ἀποδώσειν. λαχὼν δὲ παρὰ μὲν τοῦ διαιτητοῦ ἀνείλετο τὸ γραμματεῖον, προὐκαλέσατο δ’ αὐτὸν ἐπιτρέψαι Λυσιθείδῃ, αὑτοῦ μὲν καὶ Ἰσοκράτους καὶ Ἀφαρέως ἑταίρῳ, γνωρίμῳ δὲ τοῦ πατρός.", "st": "52.14"}, {"sp": "N", "t": "ἐπιτρέψαντος δὲ τοῦ πατρός, ὃν μὲν χρόνον ἔζη ὁ πατήρ, ὅμως καίπερ οἰκείως ἔχων τούτοις ὁ Λυσιθείδης οὐκ ἐτόλμα οὐδὲν εἰς ἡμᾶς ἐξαμαρτάνειν. καίτοι οὕτω τινὲς ἀναίσχυντοι τῶν οἰκείων τῶν τουτουί, ὥστε ἐτόλμησαν μαρτυρῆσαι ὡς ὁ μὲν Κάλλιππος ὅρκον τῷ πατρὶ δοίη, ὁ δὲ πατὴρ οὐκ ἐθέλοι ὀμόσαι παρὰ τῷ Λυσιθείδῃ, καὶ οἴονται ὑμᾶς πείσειν ὡς ὁ Λυσιθείδης, οἰκεῖος μὲν ὢν τῷ Καλλίππῳ διαιτῶν δὲ τὴν δίαιταν, ἀπέσχετ’ ἂν μὴ οὐκ εὐθὺς τοῦ πατρὸς καταδιαιτῆσαι, αὐτοῦ γε ἑαυτῷ μὴ ’θέλοντος δικαστοῦ γενέσθαι τοῦ πατρός.", "st": "52.15"}, {"sp": "N", "t": "ὡς δὲ ἐγὼ μὲν ἀληθῆ λέγω, οὗτοι δὲ ψεύδονται, πρῶτον μὲν αὐτὸ ὑμῖν τοῦτο γενέσθω τεκμήριον, ὅτι κατεγνώκει ἂν αὐτοῦ ὁ Λυσιθείδης, καὶ ὅτι ἐγὼ ἐξούλης ἂν ἔφευγον νῦν, ἀλλ’ οὐκ ἀργυρίου δίκην· πρὸς δὲ τούτῳ ἐγὼ ὑμῖν τοὺς παρόντας ἑκάστοτε τῷ πατρὶ ἐν ταῖς συνόδοις ταῖς πρὸς τοῦτον, αἳ παρὰ τῷ Λυσιθείδῃ ἐγίγνοντο, μάρτυρας παρέξομαι.", "st": "52.16"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "52.16"}, {"sp": "N", "t": "ὅτι μὲν οὐ προκαλεσάμενος εἰς ὅρκον τὸν πατέρα τότε, νυνὶ ἐκείνου τετελευτηκότος καταψεύδεται, καὶ κατ’ ἐμοῦ ῥᾳδίως τὰ ψευδῆ μαρτυροῦντας τοὺς οἰκείους τοὺς ἑαυτοῦ παρέχεται, ἔκ τε τῶν τεκμηρίων καὶ ἐκ τῆς μαρτυρίας ταύτης ῥᾴδιον ὑμῖν εἰδέναι. ὅτι δὲ ἐγὼ ὑπὲρ τοῦ πατρὸς ἠθέλησα αὐτῷ πίστιν δοῦναι ἥνπερ ὁ νόμος κελεύει, ἐάν τις τεθνεῶτι ἐπικαλῶν δικάζηται τῷ κληρονόμῳ,", "st": "52.17"}, {"sp": "N", "t": "μὴ δοκεῖν μοι μήτε ὁμολογῆσαι τὸν πατέρα τούτῳ ἀποδώσειν τὸ ἀργύριον ὃ κατέλιπε Λύκων, μήτε συσταθῆναι αὐτὸν τῷ πατρὶ ὑπὸ τοῦ Λύκωνος, καὶ Φορμίων, ἦ μὴν διαλογίσασθαί τε ἐναντίον Ἀρχεβιάδου τῷ Λύκωνι αὐτὸς καὶ προσταχθῆναι αὑτῷ Κηφισιάδῃ ἀποδοῦναι τὸ ἀργύριον, τὸν δὲ Κηφισιάδην δεῖξαι αὑτῷ τὸν Ἀρχεβιάδην,", "st": "52.18"}, {"sp": "N", "t": "καὶ ὅτε Κάλλιππος προσῆλθεν τὸ πρῶτον πρὸς τὴν τράπεζαν, λέγων ὅτι τετελευτηκὼς εἴη ὁ Λύκων καὶ αὐτὸς ἀξιοίη τὰ γράμματα ἰδεῖν, εἴ τι καταλελοιπὼς εἴη ὁ ξένος ἀργύριον, ἦ μὴν δείξαντος ἑαυτοῦ εὐθὺς αὐτῷ τὰ γράμματα, ἰδόντα αὐτὸν τῷ Κηφισιάδῃ γεγραμμένον ἀποδοῦναι, σιωπῇ οἴχεσθαι ἀπιόντα, οὐδὲν οὔτε ἀμφισβητήσαντα οὔτ’ ἀπειπόνθ’ αὑτῷ περὶ τοῦ ἀργυρίου, τούτων ὑμῖν τάς τε μαρτυρίας ἀμφοτέρας καὶ τὸν νόμον ἀναγνώσεται.", "st": "52.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ. ΝΟΜΟΣ.", "st": "52.19"}, {"sp": "N", "t": "φέρε δὴ ὑμῖν, ὦ ἄνδρες δικασταί, ὡς οὐδ’ ἐχρῆτο Λύκων τῷ Καλλίππῳ ἐπιδείξω· οἶμαι γάρ τί μοι καὶ τοῦτο εἶναι πρὸς τὴν ἀλαζονείαν τὴν τουτουὶ τοῦ φάσκοντος αὑτῷ δωρεὰν δοθῆναι τὸ ἀργύριον τοῦτο παρὰ τοῦ Λύκωνος. ἐκεῖνος γὰρ τετταράκοντα μνᾶς ἔκδοσιν ἐκδοὺς εἰς Ἄκην Μεγακλείδῃ τῷ Ἐλευσινίῳ καὶ Θρασύλλῳ τῷ ἀδελφῷ αὐτοῦ, μεταδόξαν αὐτῷ μὴ ἐκεῖσε πλεῖν μηδὲ κινδυνεύειν, ἐγκαλέσας τι τῷ Μεγακλείδῃ περὶ τῶν τόκων ὡς ἐξηπατημένος διεφέρετο καὶ ἐδικάζετο, βουλόμενος τὴν ἔκδοσιν κομίσασθαι.", "st": "52.20"}, {"sp": "N", "t": "συχνῆς δὲ πάνυ πραγματείας περὶ τοσαῦτα χρήματα γενομένης, τὸν μὲν Κάλλιππον ὁ Λύκων οὐδαμοῖ πώποτε παρεκάλεσεν, τὸν δὲ Ἀρχεβιάδην καὶ τοὺς τοῦ Ἀρχεβιάδου φίλους· καὶ ὁ διαλλάξας αὐτοὺς Ἀρχεβιάδης ἦν. ὡς δὲ ἀληθῆ λέγω, τούτων ὑμῖν αὐτὸν τὸν Μεγακλείδην μάρτυρα παρέξομαι.", "st": "52.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "52.21"}, {"sp": "N", "t": "οὑτωσὶ μὲν οἰκείως φαίνεται χρώμενος, ὦ ἄνδρες δικασταί, ὁ Λύκων τῷ Καλλίππῳ, ὥστε μήτε παρακαλεῖν αὐτὸν ἐπὶ τὰ αὑτοῦ πράγματα μήτε κατάγεσθαι ὡς τοῦτον μηδεπώποτε· καὶ αὐτό γε τοῦτο μόνον οὐ τετολμήκασιν οἱ οἰκεῖοι ⟨οἱ⟩ τούτου μαρτυρῆσαι, ὡς κατήγετο παρὰ τούτῳ ἐκεῖνος, εὖ εἰδότες ὅτι διὰ βασάνου ἐκ τῶν οἰκετῶν ὁ ἔλεγχος ἤδη ἔσοιτο, εἴ τι τοιοῦτο ψεύσοιντο.", "st": "52.22"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν καὶ τεκμήριόν τι εἰπεῖν τηλικοῦτον, ᾧ δῆλον ὑμῖν ἔσται, ὡς ἐγὼ οἴομαι, ὅτι πάντα πρὸς ὑμᾶς ἔψευσται. τῷ γὰρ Λύκωνι, ὦ ἄνδρες δικασταί, εἴπερ ἠσπάζετο μὲν τουτονὶ καὶ οἰκείως εἶχεν, ὥσπερ οὗτός φησιν, ἐβούλετο δὲ δωρεὰν δοῦναι αὐτῷ,", "st": "52.23"}, {"sp": "N", "t": "εἴ τι πάθοι, τὸ ἀργύριον, πότερον κάλλιον ἦν ἄντικρυς παρὰ τῷ Καλλίππῳ καταλιπεῖν τὸ ἀργύριον, ὃ ἔμελλε σωθεὶς μὲν ὀρθῶς καὶ δικαίως ἀπολήψεσθαι παρὰ φίλου γε ὄντος αὐτῷ καὶ προξένου, εἰ δέ τι πάθοι, ἄντικρυς ἔσεσθαι δεδωκώς, ὥσπερ καὶ ἐβούλετο, ἢ ἐπὶ τῇ τραπέζῃ καταλιπεῖν; ἐγὼ μὲν γὰρ οἶμαι ἐκεῖνο καὶ δικαιότερον καὶ μεγαλοπρεπέστερον εἶναι. οὐ τοίνυν φαίνεται τούτων οὐδὲν ποιήσας, ὥστε καὶ ταῦτα ὑμῖν τεκμήρια ἔστω, ἀλλὰ τῷ Κηφισιάδῃ καὶ γράψας καὶ προστάξας ἀποδοῦναι.", "st": "52.24"}, {"sp": "N", "t": "ἔτι τοίνυν καὶ τοδὶ σκέψασθε, ὦ ἄνδρες δικασταί, ὅτι Κάλλιππος μὲν ἦν πολίτης ὑμέτερος καὶ οὐκ ἀδύνατος οὐδέτερα ποιῆσαι, οὔτε κακῶς οὔτε εὖ, ὁ δὲ Κηφισιάδης καὶ μέτοικος καὶ οὐδὲν δυνάμενος, ὥστε μὴ προσθέσθαι ἂν παρὰ τὸ δίκαιον τῷ Κηφισιάδῃ μᾶλλον τὸν πατέρα ἢ τούτῳ τὰ δίκαια ποιῆσαι.", "st": "52.25"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία, ἴσως ἂν εἴποι, κερδαίνων τι ἰδίᾳ ὁ πατὴρ ἀπὸ τοῦ ἀργυρίου ἐκείνῳ μᾶλλον προσετίθετο τὴν γνώμην ἢ τούτῳ. εἶτα πρῶτον μὲν τὸν δυνησόμενον διπλάσιον τοῦ λήμματος κακὸν ποιῆσαι ἠδίκει, ἔπειτα ἐνταῦθα μὲν αἰσχροκερδὴς ἦν, εἰς δὲ τὰς εἰσφορὰς καὶ λῃτουργίας καὶ δωρεὰς τῇ πόλει οὔ;", "st": "52.26"}, {"sp": "N", "t": "καὶ τῶν μὲν ξένων οὐδένα ἠδίκει, Κάλλιππον δέ; καὶ οὗτος, ὡς χρηστῷ μὲν αὐτῷ ὄντι καὶ οὐδὲν ἂν ψευσαμένῳ ὅρκον ἐδίδου, ὥς φησιν, ὡς περὶ πονηροῦ δὲ καὶ ἀπαλείφοντος ἀπὸ τῶν παρακαταθηκῶν νυνὶ διαλέγεται; κἀκεῖνος οὔτ’ ὀμόσαι ’θέλων, ὡς οὗτός φησιν, οὔτ’ ἀποδιδοὺς οὐκ εὐθὺς ἂν ὠφλήκει; τῷ ταῦτα πιστά, ὦ ἄνδρες δικασταί;", "st": "52.27"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οὐδενὶ οἴομαι. καὶ ὁ Ἀρχεβιάδης εἰς τοῦτο φαυλότητος ἥκει, ὥστε τοῦ Καλλίππου δημότου ὄντος αὐτῷ καὶ πολιτευομένου καὶ οὐκ ἰδιώτου ὄντος καταμαρτυρεῖ, καὶ φησὶν ἡμᾶς μὲν ἀληθῆ λέγειν, τοῦτον δὲ ψεύδεσθαι, καὶ ταῦτα εἰδὼς ὅτι, ἂν οὗτος βούληται ἐπισκήψασθαι αὐτῷ τῶν ψευδομαρτυρίων καὶ ἄλλο μηδὲν ποιῆσαι ἢ ἐξορκῶσαι, ἀνάγκη αὐτῷ ἔσται πίστιν ἐπιθεῖναι ἣν ἂν κελεύῃ οὗτος.", "st": "52.28"}, {"sp": "N", "t": "ἔπειτα ἵνα ὁ Κηφισιάδης ἔχῃ τὸ ἀργύριον, ἄνθρωπος μέτοικος, ἢ Φορμίων, ὅν φησιν ἀπαληλιφέναι τι οὗτος τοῦ ἀργυρίου, πεισθήσεσθε ὑμεῖς ὡς ἐπιορκήσειεν ⟨ἂν⟩ ὁ Ἀρχεβιάδης; οὐκ ἔκ γε τῶν εἰκότων, ὦ ἄνδρες δικασταί. οὐ γὰρ ἄξιον οὔτε Ἀρχεβιάδου κακίαν οὐδεμίαν καταγνῶναι οὔτε τοῦ πατρὸς τοῦ ἡμετέρου· πολὺ γὰρ αὐτὸν φιλότιμον ἴστε μᾶλλον ὄντα ἢ κακόν τι ἢ αἰσχρὸν ἐπιτηδεύοντα, καὶ πρὸς Κάλλιππον οὐχ οὕτως ἔχοντα ὥστε καταφρονήσαντα τούτου ἀδικῆσαι [ἄν] τι αὐτόν.", "st": "52.29"}, {"sp": "N", "t": "οὐ γὰρ οὕτω μοι δοκεῖ δύνασθαι ὥστ’ εὐκαταφρόνητος εἶναι, ὃς οὕτως ἐρρωμένος ἐστίν, ὥστε πέρυσί μοι λαχὼν τὴν δίκην ταυτηνὶ καὶ προκαλεσάμενος τῷ Λυσιθείδῃ ἐπιτρέψαι, ἐγὼ μὲν καίπερ καταπεφρονημένος ὑπ’ αὐτοῦ τοῦτό γε ὀρθῶς ἐβουλευσάμην (κατὰ τοὺς νόμους γὰρ ἐπέτρεψα καὶ ἀπήνεγκα πρὸς τὴν ἀρχήν), οὗτος δὲ τὸν κατὰ τοὺς νόμους ἀπενηνεγμένον διαιτητὴν ἔπεισεν ἀνώμοτον διαιτῆσαι, ἐμοῦ διαμαρτυρομένου κατὰ τοὺς νόμους ὀμόσαντα διαιτᾶν, ἵνα αὐτῷ ᾖ πρὸς ὑμᾶς λέγειν ὅτι καὶ Λυσιθείδης, ἀνὴρ καλὸς κἀγαθός, ἔγνω περὶ αὐτῶν.", "st": "52.30"}, {"sp": "N", "t": "Λυσιθείδης γάρ, ὦ ἄνδρες δικασταί, ἕως μὲν ὁ πατὴρ ἔζη, καὶ ἄνευ ὅρκου καὶ μεθ’ ὅρκου ἴσως ἂν οὐκ ἠδίκησεν ἐκεῖνον· ἔμελε γὰρ αὐτῷ ἐκείνου. ἐμοῦ δὲ ἄνευ μὲν ὅρκου οὐδὲν αὐτῷ ἔμελεν, μεθ’ ὅρκου δὲ ἴσως ἂν οὐκ ἠδίκησεν διὰ τὸ αὑτοῦ ἴδιον· διόπερ ἀνώμοτος ἀπεφήνατο. ὡς δὲ ἀληθῆ λέγω, καὶ τούτων ὑμῖν τοὺς παραγενομένους μάρτυρας παρέξομαι.", "st": "52.31"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "52.31"}, {"sp": "N", "t": "ὅ τι μὲν καὶ παρὰ τοὺς νόμους καὶ παρὰ τὸ δίκαιον δύναται διαπράττεσθαι Κάλλιππος, ὦ ἄνδρες δικασταί, τῆς μαρτυρίας ἀκηκόατε. δέομαι δὲ ὑμῶν αὐτός τε ὑπὲρ ἐμαυτοῦ καὶ ὑπὲρ τοῦ πατρός, ἀναμνησθέντας ὅτι πάντων μὲν ὑμῖν καὶ μάρτυρας καὶ τεκμήρια καὶ νόμους καὶ πίστεις παρεσχόμην ὧν εἴρηκα, τούτῳ δὲ ἐπιδείκνυμι ὅτι ἐξόν, εἴπερ τι αὐτῷ προσῆκεν τοῦ ἀργυρίου, ἐπὶ τὸν Κηφισιάδην βαδίζειν τὸν ὁμολογοῦντα κεκομίσθαι καὶ ἔχειν τὸ ἀργύριον,", "st": "52.32"}, {"sp": "N", "t": "καὶ ταῦτα μηδὲν ἧττον τὰ πιστὰ παρ’ ἡμῶν λαβόντα, οὐκ ἔρχεται, εἰδὼς ὅτι οὐκ ἔστιν παρ’ ἡμῖν τὸ ἀργύριον, δέομαι ὑμῶν ἀποψηφίσασθαί μου. καὶ ταῦτα ποιοῦντες πρῶτον μὲν τὰ δίκαια καὶ κατὰ τοὺς νόμους ἔσεσθε ἐψηφισμένοι, ἔπειτα ἄξια μὲν αὐτῶν ὑμῶν, ἄξια δὲ τοῦ πατρὸς τοῦ ἐμοῦ· ὡς ἐγὼ ὑμᾶς ἂν δεξαίμην ἅπαντα τὰ ἐμαυτοῦ λαβεῖν μᾶλλον ἢ ἀδίκως τι συκοφαντούμενος ἀποτεῖσαι.", "st": "52.33"}, {"sp": "HDR", "t": "Πρὸς Νικόστρατον περὶ ἀνδραπόδων ἀπογραφῆς Ἀρεθουσίου", "st": "53"}, {"sp": "N", "t": "ὅτι μὲν οὐ συκοφαντῶν, ἀλλ’ ἀδικούμενος καὶ ὑβριζόμενος ὑπὸ τούτων καὶ οἰόμενος δεῖν τιμωρεῖσθαι τὴν ἀπογραφὴν ἐποιησάμην, μέγιστον ὑμῖν ἔστω τεκμήριον, ὦ ἄνδρες δικασταί, τό τε μέγεθος τῆς ἀπογραφῆς, καὶ ὅτι αὐτὸς ἐγὼ ἀπέγραψα. οὐ γὰρ δήπου συκοφαντεῖν γε βουλόμενος ἀπέγραψα μὲν ἂν πένθ’ ἡμιμναίων ἄξια ἀνδράποδα, ὡς αὐτὸς ὁ ἀμφισβητῶν τετίμηται αὐτά, ἐκινδύνευον δ’ ἂν περί τε χιλίων δραχμῶν καὶ τοῦ μηδέποτε μηδένα αὖθις ὑπὲρ ἐμαυτοῦ γράψασθαι·", "st": "53.1"}, {"sp": "N", "t": "οὐδ’ αὖ οὕτως ἄπορος ἦν οὐδ’ ἄφιλος ὥστε οὐκ ἂν ἐξευρεῖν τὸν ἀπογράψοντα· ἀλλὰ τῶν ἐν ἀνθρώποις ἁπάντων ἡγησάμενος δεινότατον εἶναι ἀδικεῖσθαι μὲν αὐτός, ἕτερον δ’ ὑπὲρ ἐμοῦ τοῦ ἀδικουμένου τοὔνομα παρέχειν, καὶ εἶναι ἄν τι τούτοις τοῦτο τεκμήριον, ὁπότε ἐγὼ λέγοιμι τὴν ἔχθραν πρὸς ὑμᾶς, ὡς ψεύδομαι (οὐ γὰρ ἄν ποτε ἕτερον ἀπογράψαι, εἴπερ ἐγὼ αὐτὸς ἠδικούμην), διὰ μὲν ταῦτα ἀπέγραψα. ἀπογράψας δὲ ἐὰν ἀποδείξω τὰ ἀνδράποδα Ἀρεθουσίου ὄντα, οὗπερ ἐγέγραπτο εἶναι, τὰ μὲν τρία μέρη, ἃ ἐκ τῶν νόμων τῷ ἰδιώτῃ τῷ ἀπογράψαντι γίγνεται, τῇ πόλει ἀφίημι, αὐτῷ δ’ ἐμοὶ τετιμωρῆσθαι ἀρκεῖ μόνον.", "st": "53.2"}, {"sp": "N", "t": "εἰ μὲν οὖν μοι ἦν ἱκανὸν τὸ ὕδωρ διηγήσασθαι πρὸς ὑμᾶς τὰ ἐξ ἀρχῆς, ὅσ’ ἀγαθὰ πεπονθότες ὑπ’ ἐμοῦ οἷά με εἰργασμένοι εἰσίν, εὖ οἶδ’ ὅτι ὑμεῖς τ’ ἄν μοι ἔτι μᾶλλον συγγνώμην εἴχετε τοῦ ὀργίζεσθαι αὐτοῖς, τούτους τ’ ἀνοσιωτάτους ἀνθρώπων ἡγήσασθε εἶναι· νῦν δ’ οὐδὲ διπλάσιόν μοι τούτου ὕδωρ ἱκανὸν ἂν γένοιτο. τὰ μὲν οὖν μέγιστα καὶ περιφανῆ τῶν ἀδικημάτων, καὶ ὁπόθεν ἡ ἀπογραφὴ αὕτη γέγονεν, ἐρῶ πρὸς ὑμᾶς, τὰ δὲ πολλὰ ἐάσω.", "st": "53.3"}, {"sp": "N", "t": "Νικόστρατος γὰρ οὑτοσί, ὦ ἄνδρες δικασταί, γείτων μοι ὢν ἐν ἀγρῷ καὶ ἡλικιώτης, γνωρίμως μέν μοι εἶχεν καὶ πάλαι, ἐπειδὴ δὲ ἐτελεύτησεν ὁ πατὴρ καὶ ἐγὼ ἐν ἀγρῷ κατῴκουν, οὗπερ καὶ νῦν οἰκῶ, καὶ μᾶλλον ἀλλήλοις ἤδη ἐχρώμεθα διὰ τὸ γείτονές τε εἶναι καὶ ἡλικιῶται. χρόνου δὲ προβαίνοντος καὶ πάνυ οἰκείως διεκείμεθα, καὶ ἐγώ τε οὕτως οἰκείως διεκείμην πρὸς τοῦτον, ὥστ’ οὐδενὸς πώποτε ὧν ἐδεήθη οὗτος ἐμοῦ ἀπέτυχεν, οὗτός τε αὖ ἐμοὶ οὐκ ἄχρηστος ἦν πρὸς τὸ ἐπιμεληθῆναι καὶ διοικῆσαι, καὶ ὁπότε ἐγὼ ἀποδημοίην ἢ δημοσίᾳ τριηραρχῶν ἢ ἰδίᾳ κατ’ ἄλλο τι, κύριον τῶν ἐν ἀγρῷ τοῦτον ἁπάντων κατέλειπον.", "st": "53.4"}, {"sp": "N", "t": "συμβαίνει δή μοι τριηραρχία περὶ Πελοπόννησον, ἐκεῖθεν δὲ εἰς Σικελίαν ἔδει τοὺς πρέσβεις ἄγειν, οὓς ὁ δῆμος ἐχειροτόνησεν. ἡ οὖν ἀναγωγὴ διὰ ταχέων ἐγίγνετό μοι. ἐπιστέλλω δὴ αὐτῷ ὅτι αὐτὸς μὲν ἀνῆγμαι καὶ οὐχ οἷός τε ἦν οἴκαδε ἀφικέσθαι, ἵνα μὴ κατακωλύοιμι τοὺς πρέσβεις· τούτῳ δὲ προσέταξα ἐπιμελεῖσθαί τε τῶν οἴκοι καὶ διοικεῖν, ὥσπερ καὶ ἐν τῷ ἔμπροσθεν χρόνῳ.", "st": "53.5"}, {"sp": "N", "t": "ἐν δὲ τῇ ἐμῇ ἀποδημίᾳ ἀποδιδράσκουσιν αὐτὸν οἰκέται τρεῖς ἐξ ἀγροῦ παρὰ τούτου, οἱ μὲν δύο ὧν ἐγὼ ἔδωκα αὐτῷ, ὁ δὲ εἷς ὧν αὐτὸς ἐκτήσατο. διώκων οὖν ἁλίσκεται ὑπὸ τριήρους καὶ κατήχθη εἰς Αἴγιναν, καὶ ἐκεῖ ἐπράθη. ἐπειδὴ δὲ κατέπλευσα ἐγὼ τριηραρχῶν, προσέρχεταί μοι Δείνων ὁ ἀδελφὸς ὁ τούτου, λέγων τήν τε τούτου συμφοράν, αὐτός τε ὅτι δι’ ἀπορίαν ἐφοδίων οὐ πεπορευμένος εἴη ἐπὶ τοῦτον πέμποντος τούτου αὐτῷ ἐπιστολάς, καὶ ἅμα λέγων πρὸς ἐμὲ ὡς ἀκούοι αὐτὸν δεινῶς διακεῖσθαι.", "st": "53.6"}, {"sp": "N", "t": "ἀκούσας δ’ ἐγὼ ταῦτα καὶ συναχθεσθεὶς ἐπὶ τῇ ἀτυχίᾳ τῇ τούτου, ἀποστέλλω τὸν Δείνωνα τὸν ἀδελφὸν αὐτοῦ εὐθὺς ἐπὶ τοῦτον, δοὺς ἐφόδιον αὐτῷ τριακοσίας δραχμάς. ἀφικόμενος δ’ οὗτος καὶ ἐλθὼν ὡς ἐμὲ πρῶτον μὲν ἠσπάζετο καὶ ἐπῄνει ὅτι παρέσχον τὰ ἐφόδια τῷ ἀδελφῷ αὐτοῦ, καὶ ὠδύρετο τὴν αὑτοῦ συμφοράν, καὶ κατηγορῶν ἅμα τῶν ἑαυτοῦ οἰκείων ἐδεῖτό μου βοηθῆσαι αὑτῷ, ὥσπερ καὶ ἐν τῷ ἔμπροσθεν χρόνῳ ἦν περὶ αὐτὸν ἀληθινὸς φίλος· καὶ κλάων ἅμα, καὶ λέγων ὅτι ἓξ καὶ εἴκοσι μνῶν λελυμένος εἴη, εἰσενεγκεῖν αὑτῷ τι ἐκέλευέ με εἰς τὰ λύτρα.", "st": "53.7"}, {"sp": "N", "t": "ταῦτα δὲ ἐγὼ ἀκούων καὶ ἐλεήσας τοῦτον, καὶ ἅμα ὁρῶν κακῶς διακείμενον καὶ δεικνύοντα ἕλκη ἐν ταῖς κνήμαις ὑπὸ δεσμῶν, ὧν ἔτι τὰς οὐλὰς ἔχει, καὶ ἐὰν κελεύσητε αὐτὸν δεῖξαι, οὐ μὴ ’θελήσῃ, ἀπεκρινάμην αὐτῷ ὅτι καὶ ἐν τῷ ἔμπροσθεν χρόνῳ εἴην αὐτῷ φίλος ἀληθινός, καὶ νῦν ἐν τῇ συμφορᾷ βοηθήσοιμι αὐτῷ, καὶ τάς τε τριακοσίας, ἃς τῷ ἀδελφῷ αὐτοῦ ἔδωκα ἐφόδιον ὅτε ἐπορεύετο ἐπὶ τοῦτον, ἀφιείην αὐτῷ, χιλίας τε δραχμὰς ἔρανον αὐτῷ εἰς τὰ λύτρα εἰσοίσοιμι.", "st": "53.8"}, {"sp": "N", "t": "καὶ τοῦτο οὐ λόγῳ μὲν ὑπεσχόμην, ἔργῳ δὲ οὐκ ἐποίησα, ἀλλ’ ἐπειδὴ οὐκ ηὐπόρουν ἀργυρίου διὰ τὸ διαφόρως ἔχειν τῷ Φορμίωνι καὶ ἀποστερεῖσθαι ὑπ’ αὐτοῦ τὴν οὐσίαν ἥν μοι ὁ πατὴρ κατέλιπεν, κομίσας ὡς Θεοκλέα τὸν τότε τραπεζιτεύοντα ἐκπώματα καὶ στέφανον χρυσοῦν, ἃ παρ’ ἐμοὶ ἐκ τῶν πατρῴων ὄντα ἐτύγχανεν, ἐκέλευσα δοῦναι τούτῳ χιλίας δραχμάς, καὶ τοῦτο ἔδωκα δωρεὰν αὐτῷ τὸ ἀργύριον, καὶ ὁμολογῶ δεδωκέναι.", "st": "53.9"}, {"sp": "N", "t": "ἡμέραις δὲ οὐ πολλαῖς ὕστερον προσελθών μοι κλάων ἔλεγεν, ὅτι οἱ ξένοι ἀπαιτοῖεν αὑτόν, οἱ δανείσαντες τὰ λύτρα, τὸ λοιπὸν ἀργύριον, καὶ ἐν ταῖς συγγραφαῖς εἴη τριάκονθ’ ἡμερῶν αὐτὸν ἀποδοῦναι ἢ διπλάσιον ὀφείλειν, καὶ ὅτι τὸ χωρίον τὸ ἐν γειτόνων μοι τοῦτο οὐδεὶς ἐθέλοι οὔτε πρίασθαι οὔτε θέσθαι· ὁ γὰρ ἀδελφὸς ὁ Ἀρεθούσιος, οὗ τἀνδράποδ’ ἐστὶ ταῦτα ἃ νῦν ἀπογέγραπται, οὐδένα ἐῴη οὔτε ὠνεῖσθαι οὔτε τίθεσθαι, ὡς ἐνοφειλομένου αὑτῷ ἀργυρίου.", "st": "53.10"}, {"sp": "N", "t": "“σὺ οὖν μοι,” ἔφη, “πόρισον τὸ ἐλλεῖπον τοῦ ἀργυρίου, πρὶν τὰς τριάκονθ’ ἡμέρας παρελθεῖν, ἵνα μὴ ὅ τε ἀποδέδωκα,” ἔφη, “τὰς χιλίας δραχμάς, ἀπόληται, καὶ αὐτὸς ἀγώγιμος γένωμαι. συλλέξας δ’,” ἔφη, “τὸν ἔρανον, ἐπειδὰν τοὺς ξένους ἀπαλλάξω, σοὶ ἀποδώσω ὃ ἄν μοι χρήσῃς. οἶσθα δ’,” ἔφη, “ὅτι καὶ οἱ νόμοι κελεύουσιν τοῦ λυσαμένου ἐκ τῶν πολεμίων εἶναι τὸν λυθέντα, ἐὰν μὴ ἀποδιδῷ τὰ λύτρα.”", "st": "53.11"}, {"sp": "N", "t": "ἀκούων δὲ αὐτοῦ ταῦτα καὶ δοκῶν οὐ ψεύδεσθαι, ἀπεκρινάμην αὐτῷ ἅπερ ἂν νέος τε ἄνθρωπος καὶ οἰκείως χρώμενος, οὐκ ἂν νομίσας ἀδικηθῆναι, ὅτι “ὦ Νικόστρατε, καὶ ἐν τῷ πρὸ τοῦ σοι χρόνῳ φίλος ἦν ἀληθινός, καὶ νῦν ἐν ταῖς συμφοραῖς σου, καθ’ ὅσον ἐγὼ ἐδυνάμην, βεβοήθηκα. ἐπειδὴ δὲ ἐν τῷ παρόντι οὐ δύνασαι πορίσαι ἅπαντα τὰ χρήματα, ἀργύριον μὲν ἐμοὶ οὐ πάρεστιν, οὐδ’ ἔχω οὐδ’ αὐτός, τῶν δὲ κτημάτων σοι τῶν ἐμῶν κίχρημι ὅ τι βούλει, θέντα τοῦ ἐπιλοίπου ἀργυρίου ὅσου ἐνδεῖ σοι, ἐνιαυτὸν ἀτόκῳ χρῆσθαι τῷ ἀργυρίῳ καὶ ἀποδοῦναι τοῖς ξένοις. συλλέξας δὲ ἔρανον, ὥσπερ αὐτὸς φής, λῦσαί μοι.”", "st": "53.12"}, {"sp": "N", "t": "ἀκούσας δ’ οὗτος ταῦτα καὶ ἐπαινέσας με, ἐκέλευσε τὴν ταχίστην πρᾶξαι, πρὶν ἐξήκειν τὰς ἡμέρας ἐν αἷς ἔφη δεῖν τὰ λύτρα καταθεῖναι. τίθημι οὖν τὴν συνοικίαν ἑκκαίδεκα μνῶν Ἀρκέσαντι Παμβωτάδῃ, ὃν αὐτὸς οὗτος προὐξένησεν, ἐπὶ ὀκτὼ ὀβολοῖς τὴν μνᾶν δανείσαντι τοῦ μηνὸς ἑκάστου. λαβὼν δὲ τὸ ἀργύριον οὐχ ὅπως χάριν τινά μοι ἀποδίδωσιν ὧν εὖ ἔπαθεν, ἀλλ’ εὐθέως ἐπεβούλευέ μοι, ἵνα ἀποστερήσειε τὸ ἀργύριον καὶ εἰς ἔχθραν κατασταίη, καὶ ἀπορούμενος ἐγὼ τοῖς πράγμασιν νέος ὢν ὅ τι χρησαίμην καὶ ἄπειρος πραγμάτων, ὅπως μὴ εἰσπράττοιμι αὐτὸν τὸ ἀργύριον οὗ ἡ συνοικία ἐτέθη, ἀλλ’ ἀφείην αὐτῷ.", "st": "53.13"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐπιβουλεύει μοι μετὰ τῶν ἀντιδίκων, καὶ πίστιν αὐτοῖς δίδωσιν· ἔπειτ’ ἀγώνων μοι συνεστηκότων πρὸς αὐτούς, τούς τε λόγους ἐκφέρει μου εἰδώς, καὶ ἐγγράφει τῷ δημοσίῳ ἀπρόσκλητον ἐξ ἐμφανῶν καταστάσεως ἐπιβολὴν ἑξακοσίας καὶ δέκα δραχμάς, διὰ Λυκίδου τοῦ μυλωθροῦ ποιησάμενος τὴν δίκην. κλητῆρα δὲ κατ’ ἐμοῦ τόν τε ἀδελφὸν τὸν αὑτοῦ τὸν Ἀρεθούσιον τοῦτον ἐπιγράφεται, οὗπέρ ἐστιν τὰ ἀνδράποδα ταῦτα, καὶ ἄλλον τινά· καὶ παρεσκευάζοντο, εἰ ἀνακρινοίμην κατὰ τῶν οἰκείων τῶν ἀδικούντων με τὰς δίκας ἃς εἰλήχειν αὐτοῖς, ἐνδεικνύναι με ὡς ὀφείλοντα τῷ δημοσίῳ καὶ ἐμβάλλειν εἰς τὸ δεσμωτήριον.", "st": "53.14"}, {"sp": "N", "t": "ἔτι δὲ πρὸς τούτοις ὁ [Ἀρεθούσιος] ἀπρόσκλητόν μου ⟨ἑξακοσίων καὶ⟩ δέκα δραχμῶν δίκην καταδικασάμενος ⟨καὶ ψευδεῖς⟩ κλητῆρας ἐπιγραψάμενος, [καὶ] εἰσελθὼν εἰς τὴν οἰκίαν βίᾳ τὰ σκεύη πάντα ἐξεφόρησεν, πλέον ἢ εἴκοσι μνῶν ἄξια, καὶ οὐδ’ ὁτιοῦν κατέλιπεν. ὅτε δὲ τιμωρεῖσθαι ᾤμην δεῖν, καὶ ἐκτείσας τῷ δημοσίῳ τὸ ὄφλημα, ἐπειδὴ ἐπυθόμην τὴν ἐπιβουλήν, ἐβάδιζον ἐπὶ τὸν κλητῆρα τὸν ὁμολογοῦντα κεκλητευκέναι, τὸν Ἀρεθούσιον, τῆς ψευδοκλητείας κατὰ τὸν νόμον, ἐλθὼν εἰς τὸ χωρίον τῆς νυκτός, ὅσα ἐνῆν φυτὰ ἀκροδρύων γενναῖα ἐμβεβλημένα καὶ τὰς ἀναδενδράδας ἐξέκοψε, καὶ φυτευτήρια ἐλαῶν περιστοίχων κατέκλασεν, οὕτως δεινῶς ὡς οὐδ’ ἂν οἱ πολέμιοι διαθεῖεν.", "st": "53.15"}, {"sp": "N", "t": "πρὸς δὲ τούτοις μεθ’ ἡμέραν παιδάριον ἀστὸν εἰσπέμψαντες διὰ τὸ γείτονες εἶναι καὶ ὅμορον τὸ χωρίον, ἐκέλευον τὴν ῥοδωνιὰν βλαστάνουσαν ἐκτίλλειν, ἵνα, εἰ καταλαβὼν αὐτὸν ἐγὼ δήσαιμι ἢ κατάξαιμι ὡς δοῦλον ὄντα, γραφήν με γράψαιντο ὕβρεως. ὡς δὲ τούτου διήμαρτον, καὶ ἐγὼ μάρτυρας μὲν ὧν ἔπασχον ἐποιούμην, αὐτὸς δὲ οὐδὲν ἐξημάρτανον εἰς αὐτούς, ἐνταῦθα ἤδη μοι ἐπιβουλεύουσι τὴν μεγίστην ἐπιβουλήν·", "st": "53.16"}, {"sp": "N", "t": "ἀνακεκριμένου γὰρ ἤδη μου κατ’ αὐτοῦ τὴν τῆς ψευδοκλητείας γραφὴν καὶ μέλλοντος εἰσιέναι εἰς τὸ δικαστήριον, τηρήσας με ἀνιόντα ἐκ Πειραιῶς ὀψὲ περὶ τὰς λιθοτομίας παίει τε πὺξ καὶ ἁρπάζει μέσον καὶ ἐώθει με εἰς τὰς λιθοτομίας, εἰ μή τινες προσιόντες, βοῶντός μου ἀκούσαντες, παρεγένοντο καὶ ἐβοήθησαν. ἡμέραις δὲ οὐ πολλαῖς ὕστερον εἰσελθὼν εἰς τὸ δικαστήριον πρὸς ἡμέραν διαμεμετρημένην, καὶ ἐξελέγξας αὐτὸν τὰ ψευδῆ κεκλητευκότα καὶ τὰ ἄλλα ὅσα εἴρηκα ἠδικηκότα, εἷλον.", "st": "53.17"}, {"sp": "N", "t": "καὶ ἐν τῇ τιμήσει βουλομένων τῶν δικαστῶν θανάτου τιμῆσαι αὐτῷ, ἐδεήθην ἐγὼ τῶν δικαστῶν μηδὲν δι’ ἐμοῦ τοιοῦτον πρᾶξαι, ἀλλὰ συνεχώρησα ὅσουπερ αὐτοὶ ἐτιμῶντο, ταλάντου, οὐχ ἵνα μὴ ἀποθάνῃ ὁ Ἀρεθούσιος (ἄξια γὰρ αὐτῷ θανάτου εἴργαστο εἰς ἐμέ), ἀλλ’ ἵνα ἐγὼ Πασίωνος ὢν καὶ κατὰ ψήφισμα πολίτης μηδένα Ἀθηναίων ἀπεκτονὼς εἴην. ὡς δ’ ἀληθῆ εἴρηκα πρὸς ὑμᾶς, τούτων ὑμῖν πάντων τοὺς μάρτυρας παρέξομαι.", "st": "53.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.18"}, {"sp": "N", "t": "ἃ μὲν τοίνυν ἀδικούμενος, ὦ ἄνδρες δικασταί, ὑπ’ αὐτῶν τὴν ἀπογραφὴν ἐποιησάμην, δεδήλωκα ὑμῖν· ὡς δ’ ἔστιν Ἀρεθουσίου τὰ ἀνδράποδα ταῦτα καὶ ὄντα ἐν τῇ οὐσίᾳ τῇ ἐκείνου ἀπέγραψα, ἐπιδείξω ὑμῖν. τὸν μὲν γὰρ Κέρδωνα ἐκ μικροῦ παιδαρίου ἐξεθρέψατο· καὶ ὡς ἦν Ἀρεθουσίου, τούτων ὑμῖν τοὺς εἰδότας μάρτυρας παρέξομαι.", "st": "53.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.19"}, {"sp": "N", "t": "παρ’ οἷς τοίνυν ἠργάσατο πώποτε, ὡς τοὺς μισθοὺς Ἀρεθούσιος ἐκομίζετο ὑπὲρ αὐτοῦ, καὶ δίκας ἐλάμβανε καὶ ἐδίδου, ὁπότε κακόν τι ἐργάσαιτο, ὡς δεσπότης ὤν, τούτων ὑμῖν τοὺς εἰδότας μάρτυρας παρέξομαι.", "st": "53.20"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.20"}, {"sp": "N", "t": "τὸν δὲ Μάνην, δανείσας ἀργύριον Ἀρχεπόλιδι τῷ Πειραιεῖ, ἐπειδὴ οὐχ οἷός τ’ ἦν αὐτῷ ἀποδοῦναι ὁ Ἀρχέπολις οὔτε τὸν τόκον οὔτε τὸ ἀρχαῖον ἅπαν, ἐναπετίμησεν αὐτῷ. καὶ ὅτι ἀληθῆ λέγω, τούτων ὑμῖν τοὺς μάρτυρας παρέξομαι.", "st": "53.20"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.20"}, {"sp": "N", "t": "ἔτι τοίνυν καὶ ἐκ τῶνδε γνώσεσθε, ὦ ἄνδρες δικασταί, ὅτι εἰσὶν Ἀρεθουσίου οἱ ἄνθρωποι. ὁπότε γὰρ οἱ ἄνθρωποι οὗτοι ἢ ὀπώραν πρίαιντο ἢ θέρος μισθοῖντο ἐκθερίσαι ἢ ἄλλο τι τῶν περὶ γεωργίαν ἔργων ἀναιροῖντο, Ἀρεθούσιος ἦν ὁ ὠνούμενος καὶ μισθούμενος ὑπὲρ αὐτῶν. ὡς δ’ ἀληθῆ λέγω, καὶ τούτων ὑμῖν τοὺς μάρτυρας παρέξομαι.", "st": "53.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.21"}, {"sp": "N", "t": "ὅσας μὲν τοίνυν μαρτυρίας παρασχέσθαι εἶχον ὑμῖν, ὡς ἔστιν Ἀρεθουσίου τὰ ἀνδράποδα, δεδήλωκα ὑμῖν. βούλομαι δὲ καὶ περὶ τῆς προκλήσεως εἰπεῖν, ἣν οὗτοί με προὐκαλέσαντο καὶ ἐγὼ τούτους. οὗτοι μὲν γάρ με προὐκαλέσαντο, ὅτε ἡ πρώτη ἀνάκρισις ἦν, φάσκοντες ἕτοιμοι εἶναι παραδιδόναι ἐμοὶ αὐτῷ τὰ ἀνδράποδα βασανίσαι, βουλόμενοι μαρτυρίαν τινὰ αὑτοῖς ταύτην γενέσθαι.", "st": "53.22"}, {"sp": "N", "t": "ἐγὼ δὲ ἀπεκρινάμην αὐτοῖς ἐναντίον μαρτύρων, ὅτι ἕτοιμός εἰμι ἰέναι εἰς τὴν βουλὴν μετ’ αὐτῶν καὶ παραλαμβάνειν μετ’ ἐκείνης ἢ μετὰ τῶν ἕνδεκα, λέγων ὅτι, εἰ μὲν ἰδίαν δίκην ἐδικαζόμην αὐτοῖς, εἰ ἐμοὶ ἐξεδίδοσαν, παρελάμβανον ἄν, νῦν δὲ τῆς πόλεως εἴη τὰ ἀνδράποδα καὶ ἡ ἀπογραφή· δεῖν οὖν δημοσίᾳ βασανίζεσθαι.", "st": "53.23"}, {"sp": "N", "t": "ἡγούμην γὰρ οὐ προσήκειν ἐμοὶ ἰδιώτῃ ὄντι τοὺς δημοσίους βασανίζειν· οὔτε γὰρ τῆς βασάνου κύριος ἐγιγνόμην, οὔτε καλῶς ἔχειν τὰ λεγόμενα ὑπὸ τῶν ἀνθρώπων ἐμὲ κρίνειν, ἡγούμην τε δεῖν τὴν ἀρχὴν ἢ τοὺς ᾑρημένους ὑπὸ τῆς βουλῆς γράφεσθαι, καὶ κατασημηναμένους τὰς βασάνους, ὅ τι εἴποιεν οἱ ἄνθρωποι, παρέχειν εἰς τὸ δικαστήριον, ἵν’ ἀκούσαντες ἐκ τούτων ἐψηφίσασθε ὁποῖόν τι ὑμῖν ἐδόκει.", "st": "53.24"}, {"sp": "N", "t": "ἰδίᾳ μὲν γὰρ βασανιζομένων τῶν ἀνθρώπων ὑπ’ ἐμοῦ ἀντελέγετ’ ἂν ἅπαντα ὑπὸ τούτων, εἰ δὲ δημοσίᾳ, ἡμεῖς μὲν ἂν ἐσιωπῶμεν, οἱ δ’ ἄρχοντες ἢ οἱ ᾑρημένοι ὑπὸ τῆς βουλῆς ἐβασάνιζον ἂν μέχρι οὗ αὐτοῖς ἐδόκει. ταῦτα δ’ ἐμοῦ ἐθέλοντος, οὐκ ἂν ἔφασαν τῇ ἀρχῇ παραδοῦναι, οὐδ’ εἰς τὴν βουλὴν ἤθελον ἀκολουθεῖν. ὡς οὖν ἀληθῆ λέγω, κάλει μοι τούτων τοὺς μάρτυρας.", "st": "53.25"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "53.25"}, {"sp": "N", "t": "κατὰ πολλὰ μὲν οὖν ἔμοιγε δοκοῦσιν εἶναι ἀναίσχυντοι ἀμφισβητοῦντες τῶν ὑμετέρων, οὐχ ἥκιστα δὲ ὑμῖν αὐτοὺς ἐπιδείξω ἐκ τῶν νόμων τῶν ὑμετέρων. οὗτοι γάρ, ὅτε οἱ δικασταὶ ἐβούλοντο θανάτου τιμῆσαι τῷ Ἀρεθουσίῳ, ἐδέοντο τῶν δικαστῶν χρημάτων τιμῆσαι καὶ ἐμοῦ συγχωρῆσαι, καὶ ὡμολόγησαν αὐτοὶ συνεκτείσειν.", "st": "53.26"}, {"sp": "N", "t": "τοσούτου δὴ δέουσιν ἐκτίνειν καθ’ ἃ ἠγγυήσαντο, ὥστε καὶ τῶν ὑμετέρων ἀμφισβητοῦσι. καίτοι οἵ γε νόμοι κελεύουσι τὴν οὐσίαν εἶναι δημοσίαν, ὃς ἂν ἐγγυησάμενός τι τῶν τῆς πόλεως μὴ ἀποδιδῷ τὴν ἐγγύην· ὥστε καὶ εἰ τούτων ἦν τὰ ἀνδράποδα, προσῆκεν αὐτὰ δημόσια εἶναι, εἴπερ τι τῶν νόμων ὄφελος.", "st": "53.27"}, {"sp": "N", "t": "καὶ πρὶν μὲν ὀφείλειν τῷ δημοσίῳ, ὁ Ἀρεθούσιος ὡμολογεῖτο τῶν ἀδελφῶν εὐπορώτατος εἶναι· ἐπειδὴ δὲ οἱ νόμοι κελεύουσιν τἀκείνου ὑμέτερα εἶναι, τηνικαῦτα πένης ὢν φαίνεται ὁ Ἀρεθούσιος, καὶ τῶν μὲν ἡ μήτηρ ἀμφισβητεῖ, τῶν δὲ οἱ ἀδελφοί. χρῆν δ’ αὐτούς, εἴπερ ἐβούλοντο δικαίως προσφέρεσθαι πρὸς ὑμᾶς, ἀποδείξαντας ἅπασαν τὴν οὐσίαν τὴν ἐκείνου, τὰ τούτων αὐτῶν εἴ τις ἀπέγραφεν, ἀμφισβητεῖν.", "st": "53.28"}, {"sp": "N", "t": "ἐὰν οὖν ἐνθυμηθῆτε, ὅτι οὐδέποτε ἔσται ἀπορία τῶν ἀμφισβητησόντων ὑμῖν περὶ τῶν ὑμετέρων (ἢ γὰρ ὀρφανοὺς ἢ ἐπικλήρους κατασκευάσαντες ἀξιώσουσιν ἐλεεῖσθαι ὑφ’ ὑμῶν, ἢ γῆρας καὶ ἀπορίας καὶ τροφὰς μητρὶ λέγοντες, καὶ ὀδυρόμενοι δι’ ὧν μάλιστα ἐλπίζουσιν ἐξαπατήσειν ὑμᾶς, πειράσονται ἀποστερῆσαι τὴν πόλιν τοῦ ὀφλήματος), ἐὰν οὖν ταῦτα παριδόντες πάντα καταψηφίσησθε, ὀρθῶς βουλεύσεσθε.", "st": "53.29"}, {"sp": "HDR", "t": "Κατὰ Κόνωνος αἰκείας", "st": "54"}, {"sp": "N", "t": "ὑβρισθείς, ὦ ἄνδρες δικασταί, καὶ παθὼν ὑπὸ Κόνωνος τουτουὶ τοιαῦτα, ὥστε πολὺν χρόνον πάνυ μήτε τοὺς οἰκείους μήτε τῶν ἰατρῶν μηδένα προσδοκᾶν περιφεύξεσθαί με, ὑγιάνας καὶ σωθεὶς ἀπροσδοκήτως ἔλαχον αὐτῷ τὴν δίκην τῆς αἰκείας ταυτηνί. πάντων δὲ τῶν φίλων καὶ τῶν οἰκείων, οἷς συνεβουλευόμην, ἔνοχον μὲν φασκόντων αὐτὸν ἐκ τῶν πεπραγμένων εἶναι καὶ τῇ τῶν λωποδυτῶν ἀπαγωγῇ καὶ ταῖς τῆς ὕβρεως γραφαῖς, συμβουλευόντων δέ μοι καὶ παραινούντων μὴ μείζω πράγματ’ ἢ δυνήσομαι φέρειν ἐπάγεσθαι, μηδ’ ὑπὲρ τὴν ἡλικίαν ⟨περὶ⟩ ὧν ἐπεπόνθειν ἐγκαλοῦντα φαίνεσθαι, οὕτως ἐποίησα καὶ δι’ ἐκείνους ἰδίαν ἔλαχον δίκην, ἥδιστ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, θανάτου κρίνας τουτονί.", "st": "54.1"}, {"sp": "N", "t": "καὶ τούτου συγγνώμην ἕξετε, εὖ οἶδ’ ὅτι, πάντες, ἐπειδὰν ἃ πέπονθ’ ἀκούσητε· δεινῆς γὰρ οὔσης τῆς τότε συμβάσης ὕβρεως οὐκ ἐλάττων ἡ μετὰ ταῦτ’ ἀσέλγει’ ἐστὶ τουτουί. ἀξιῶ δὴ καὶ δέομαι πάντων ὁμοίως ὑμῶν πρῶτον μὲν εὐνοϊκῶς ἀκοῦσαί μου περὶ ὧν πέπονθα λέγοντος, εἶτα, ἐὰν ἠδικῆσθαι καὶ παρανενομῆσθαι δοκῶ, βοηθῆσαί μοι τὰ δίκαια. ἐξ ἀρχῆς δ’ ὡς ἕκαστα πέπρακται διηγήσομαι πρὸς ὑμᾶς, ὡς ἂν οἷός τ’ ὦ διὰ βραχυτάτων.", "st": "54.2"}, {"sp": "N", "t": "ἐξῆλθον ἔτος τουτὶ τρίτον εἰς Πάνακτον φρουρᾶς ἡμῖν προγραφείσης. ἐσκήνωσαν οὖν οἱ υἱεῖς οἱ Κόνωνος τουτουὶ ἐγγὺς ἡμῶν, ὡς οὐκ ἂν ἐβουλόμην· ἡ γὰρ ἐξ ἀρχῆς ἔχθρα καὶ τὰ προσκρούματ’ ἐκεῖθεν ἡμῖν συνέβη· ἐξ ὧν δέ, ἀκούσεσθε. ἔπινον ἑκάστοθ’ οὗτοι τὴν ἡμέραν, ἐπειδὴ τάχιστ’ ἀριστήσαιεν, ὅλην, καὶ τοῦθ’, ἕως περ ἦμεν ἐν τῇ φρουρᾷ, διετέλουν ποιοῦντες. ἡμεῖς δ’ ὥσπερ ἐνθάδ’ εἰώθειμεν, οὕτω διήγομεν καὶ ἔξω.", "st": "54.3"}, {"sp": "N", "t": "ἣν οὖν δειπνοποιεῖσθαι τοῖς ἄλλοις ὥραν συμβαίνοι, ταύτην ἂν ἤδη ἐπαρῴνουν οὗτοι, τὰ μὲν πόλλ’ εἰς τοὺς παῖδας ἡμῶν τοὺς ἀκολούθους, τελευτῶντες δὲ καὶ εἰς ἡμᾶς αὐτούς. φήσαντες γὰρ καπνίζειν αὑτοὺς ὀψοποιουμένους τοὺς παῖδας ἢ κακῶς λέγειν, ὅ τι τύχοιεν, ἔτυπτον καὶ τὰς ἀμίδας κατεσκεδάννυον καὶ προσεούρουν, καὶ ἀσελγείας καὶ ὕβρεως οὐδ’ ὁτιοῦν ἀπέλειπον. ὁρῶντες δ’ ἡμεῖς ταῦτα καὶ λυπούμενοι τὸ μὲν πρῶτον ἀπεπεμψάμεθα, ὡς δ’ ἐχλεύαζον ἡμᾶς καὶ οὐκ ἐπαύοντο, τῷ στρατηγῷ τὸ πρᾶγμ’ εἴπομεν κοινῇ πάντες οἱ σύσσιτοι προσελθόντες, οὐκ ἐγὼ τῶν ἄλλων ἔξω.", "st": "54.4"}, {"sp": "N", "t": "λοιδορηθέντος δ’ αὐτοῖς ἐκείνου καὶ κακίσαντος αὐτοὺς οὐ μόνον περὶ ὧν εἰς ἡμᾶς ἠσέλγαινον, ἀλλὰ καὶ περὶ ὧν ὅλως ἐποίουν ἐν τῷ στρατοπέδῳ, τοσούτου ἐδέησαν παύσασθαι ἢ αἰσχυνθῆναι, ὥστ’ ἐπειδὴ θᾶττον συνεσκότασεν, εὐθὺς ὡς ἡμᾶς εἰσεπήδησαν ταύτῃ τῇ ἑσπέρᾳ, καὶ τὸ μὲν πρῶτον κακῶς ἔλεγον, τελευτῶντες δὲ καὶ πληγὰς ἐνέτειναν ἐμοί, καὶ τοσαύτην κραυγὴν καὶ θόρυβον περὶ τὴν σκηνὴν ἐποίησαν ὥστε καὶ τὸν στρατηγὸν καὶ τοὺς ταξιάρχους ἐλθεῖν καὶ τῶν ἄλλων στρατιωτῶν τινάς, οἵπερ ἐκώλυσαν μηδὲν ἡμᾶς ἀνήκεστον παθεῖν μηδ’ αὐτοὺς ποιῆσαι παροινουμένους ὑπὸ τουτωνί.", "st": "54.5"}, {"sp": "N", "t": "τοῦ δὲ πράγματος εἰς τοῦτο προελθόντος, ὡς δεῦρ’ ἐπανήλθομεν, ἦν ἡμῖν, οἷον εἰκός, ἐκ τούτων ὀργὴ καὶ ἔχθρα πρὸς ἀλλήλους. μὰ τοὺς θεοὺς οὐ μὴν ἔγωγ’ ᾠόμην δεῖν οὔτε δίκην λαχεῖν αὐτοῖς οὔτε λόγον ποιεῖσθαι τῶν συμβάντων οὐδένα, ἀλλ’ ἐκεῖν’ ἁπλῶς ἐγνώκειν τὸ λοιπὸν εὐλαβεῖσθαι καὶ φυλάττεσθαι μὴ πλησιάζειν τοῖς τοιούτοις. πρῶτον μὲν οὖν τούτων ὧν εἴρηκα βούλομαι τὰς μαρτυρίας παρασχόμενος, μετὰ ταῦθ’ οἷ’ ὑπ’ αὐτοῦ τούτου πέπονθ’ ἐπιδεῖξαι, ἵν’ εἰδῆθ’ ὅτι ᾧ προσῆκεν τοῖς τὸ πρῶτον ἁμαρτηθεῖσιν ἐπιτιμᾶν, οὗτος αὐτὸς πρότερος πολλῷ δεινότερ’ εἴργασται.", "st": "54.6"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "54.6"}, {"sp": "N", "t": "ὧν μὲν τοίνυν οὐδέν’ ᾤμην δεῖν λόγον ποιεῖσθαι, ταῦτ’ ἐστίν. χρόνῳ δ’ ὕστερον οὐ πολλῷ περιπατοῦντος, ὥσπερ εἰώθειν, ἑσπέρας ἐν ἀγορᾷ μου μετὰ Φανοστράτου τοῦ Κηφισιέως, τῶν ἡλικιωτῶν τινός, παρέρχεται Κτησίας ὁ υἱὸς ὁ τούτου, μεθύων, κατὰ τὸ Λεωκόριον, ἐγγὺς τῶν Πυθοδώρου. κατιδὼν δ’ ἡμᾶς καὶ κραυγάσας, καὶ διαλεχθείς τι πρὸς αὑτὸν οὕτως ὡς ἂν μεθύων, ὥστε μὴ μαθεῖν ὅ τι λέγοι, παρῆλθε πρὸς Μελίτην ἄνω. ἔπινον δ’ ἄρ’ ἐνταῦθα (ταῦτα γὰρ ὕστερον ἐπυθόμεθα) παρὰ Παμφίλῳ τῷ γναφεῖ Κόνων οὑτοσί, Θεότιμός τις, Ἀρχεβιάδης, Σπίνθαρος ὁ Εὐβούλου, Θεογένης ὁ Ἀνδρομένους, πολλοί τινες, οὓς ἐξαναστήσας ὁ Κτησίας ἐπορεύετ’ εἰς τὴν ἀγοράν.", "st": "54.7"}, {"sp": "N", "t": "καὶ ἡμῖν συμβαίνει ἀναστρέφουσιν ἀπὸ τοῦ Φερρεφαττίου καὶ περιπατοῦσιν πάλιν κατ’ αὐτό πως τὸ Λεωκόριον εἶναι, καὶ τούτοις περιτυγχάνομεν. ὡς δ’ ἀνεμείχθημεν, εἷς μὲν αὐτῶν, ἀγνώς τις, Φανοστράτῳ προσπίπτει καὶ κατεῖχεν ἐκεῖνον, Κόνων δ’ οὑτοσὶ καὶ ὁ υἱὸς αὐτοῦ καὶ ὁ Ἀνδρομένους υἱὸς ἐμοὶ προσπεσόντες τὸ μὲν πρῶτον ἐξέδυσαν, εἶθ’ ὑποσκελίσαντες καὶ ῥάξαντες εἰς τὸν βόρβορον οὕτω διέθηκαν ἐναλλόμενοι καὶ ὑβρίζοντες, ὥστε τὸ μὲν χεῖλος διακόψαι, τοὺς δ’ ὀφθαλμοὺς συγκλεῖσαι· οὕτω δὲ κακῶς ἔχοντα κατέλιπον, ὥστε μήτ’ ἀναστῆναι μήτε φθέγξασθαι δύνασθαι. κείμενος δ’ αὐτῶν ἤκουον πολλὰ καὶ δεινὰ λεγόντων.", "st": "54.8"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλα καὶ βλασφημίαν ἔχει τινὰ καὶ ὀνομάζειν ὀκνήσαιμ’ ἂν ἐν ὑμῖν ἔνια, ὃ δὲ τῆς ὕβρεώς ἐστι τῆς τούτου σημεῖον καὶ τεκμήριον τοῦ πᾶν τὸ πρᾶγμ’ ὑπὸ τούτου γεγενῆσθαι, τοῦθ’ ὑμῖν ἐρῶ· ᾖδε γὰρ τοὺς ἀλεκτρυόνας μιμούμενος τοὺς νενικηκότας, οἱ δὲ κροτεῖν τοῖς ἀγκῶσιν αὐτὸν ἠξίουν ἀντὶ πτερύγων τὰς πλευράς. καὶ μετὰ ταῦτ’ ἐγὼ μὲν ἀπεκομίσθην ὑπὸ τῶν παρατυχόντων γυμνός, οὗτοι δ’ ᾤχοντο θοἰμάτιον λαβόντες μου. ὡς δ’ ἐπὶ τὴν θύραν ἦλθον, κραυγὴ καὶ βοὴ τῆς μητρὸς καὶ τῶν θεραπαινίδων ἦν, καὶ μόγις ποτ’ εἰς βαλανεῖον ἐνεγκόντες με καὶ περιπλύναντες ἔδειξαν τοῖς ἰατροῖς. ὡς οὖν ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν τοὺς μάρτυρας παρέξομαι.", "st": "54.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "54.9"}, {"sp": "N", "t": "συνέβη τοίνυν, ὦ ἄνδρες δικασταί, καὶ Εὐξίθεον τουτονὶ τὸν Χολλῄδην, ὄνθ’ ἡμῖν συγγενῆ, καὶ Μειδίαν μετὰ τούτου ἀπὸ δείπνου ποθὲν ἀπιόντας περιτυχεῖν πλησίον ὄντι μοι τῆς οἰκίας ἤδη, καὶ εἴς τε τὸ βαλανεῖον φερομένῳ παρακολουθῆσαι, καὶ ἰατρὸν ἄγουσιν παραγενέσθαι. οὕτω δ’ εἶχον ἀσθενῶς ὥστε, ἵνα μὴ μακρὰν φεροίμην οἴκαδ’ ἐκ τοῦ βαλανείου, ἐδόκει τοῖς παροῦσιν ὡς τὸν Μειδίαν ἐκείνην τὴν ἑσπέραν κομίσαι, καὶ ἐποίησαν οὕτω. λάβ’ οὖν καὶ τὰς τούτων μαρτυρίας, ἵν’ εἰδῆθ’ ὅτι πολλοὶ συνίσασιν ὡς ὑπὸ τούτων ὑβρίσθην.", "st": "54.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "54.10"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὴν τοῦ ἰατροῦ μαρτυρίαν.", "st": "54.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "54.10"}, {"sp": "N", "t": "τότε μὲν τοίνυν παραχρῆμ’ ὑπὸ τῶν πληγῶν ἃς ἔλαβον καὶ τῆς ὕβρεως οὕτω διετέθην, ὡς ἀκούετε καὶ μεμαρτύρηται παρὰ πάντων ὑμῖν τῶν εὐθὺς ἰδόντων. μετὰ δὲ ταῦτα τῶν μὲν οἰδημάτων τῶν ἐν τῷ προσώπῳ καὶ τῶν ἑλκῶν οὐδὲν ἔφη φοβεῖσθαι λίαν ὁ ἰατρός, πυρετοὶ δὲ παρηκολούθουν μοι συνεχεῖς καὶ ἀλγήματα, ὅλου μὲν τοῦ σώματος πάνυ σφοδρὰ καὶ δεινά, μάλιστα δὲ τῶν πλευρῶν καὶ τοῦ ἤτρου, καὶ τῶν σιτίων ἀπεκεκλείμην.", "st": "54.11"}, {"sp": "N", "t": "καὶ ὡς μὲν ὁ ἰατρὸς ἔφη, εἰ μὴ κάθαρσις αἵματος αὐτομάτη μοι πάνυ πολλὴ συνέβη περιωδύνῳ ὄντι καὶ ἀπορουμένῳ ἤδη, κἂν ἔμπυος γενόμενος διεφθάρην· νῦν δὲ τοῦτ’ ἔσῳσεν τὸ αἷμ’ ἀποχωρῆσαν. ὡς οὖν καὶ ταῦτ’ ἀληθῆ λέγω, καὶ παρηκολούθησέ μοι τοιαύτη νόσος ἐξ ἧς εἰς τοὔσχατον ἦλθον, ἐξ ὧν ὑπὸ τούτων ἔλαβον πληγῶν, λέγε τὴν τοῦ ἰατροῦ μαρτυρίαν καὶ τὴν τῶν ἐπισκοπούντων.", "st": "54.12"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "54.12"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐ μετρίας τινὰς καὶ φαύλας λαβὼν πληγάς, ἀλλ’ εἰς πᾶν ἐλθὼν διὰ τὴν ὕβριν καὶ τὴν ἀσέλγειαν τὴν τούτων πολὺ τῆς προσηκούσης ἐλάττω δίκην εἴληχα, πολλαχόθεν νομίζω δῆλον ὑμῖν γεγενῆσθαι. οἴομαι δ’ ὑμῶν ἐνίους θαυμάζειν, τί ποτ’ ἐστὶν ἃ πρὸς ταῦτα τολμήσει Κόνων λέγειν. βούλομαι δὴ προειπεῖν ὑμῖν ἁγὼ πέπυσμαι λέγειν αὐτὸν παρεσκευάσθαι, ἀπὸ τῆς ὕβρεως καὶ τῶν πεπραγμένων τὸ πρᾶγμ’ ἄγοντ’ εἰς γέλωτα καὶ σκώμματ’ ἐμβαλεῖν πειράσεσθαι,", "st": "54.13"}, {"sp": "N", "t": "καὶ ἐρεῖν ὡς εἰσὶν ἐν τῇ πόλει πολλοί, καλῶν κἀγαθῶν ἀνδρῶν υἱεῖς, οἳ παίζοντες οἷ’ ἄνθρωποι νέοι σφίσιν αὐτοῖς ἐπωνυμίας πεποίηνται, καὶ καλοῦσι τοὺς μὲν ἰθυφάλλους, τοὺς δ’ αὐτοληκύθους, ἐρῶσι δ’ ἐκ τούτων ἑταιρῶν τινές, καὶ δὴ καὶ τὸν υἱὸν τὸν ἑαυτοῦ εἶναι τούτων ἕνα, καὶ πολλάκις περὶ ἑταίρας καὶ εἰληφέναι καὶ δεδωκέναι πληγάς, καὶ ταῦτ’ εἶναι νέων ἀνθρώπων. ἡμᾶς δὲ πάντας τοὺς ἀδελφοὺς παροίνους μέν τινας καὶ ὑβριστὰς κατασκευάσει, ἀγνώμονας δὲ καὶ πικρούς.", "st": "54.14"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, χαλεπῶς ἐφ’ οἷς πέπονθα ἐνηνοχώς, οὐχ ἧττον τοῦτ’ ἀγανακτήσαιμ’ ἂν καὶ ὑβρίσθαι νομίσαιμι, εἰ οἷόν τ’ εἰπεῖν, εἰ ταῦτ’ ἀληθῆ δόξει Κόνων οὑτοσὶ λέγειν περὶ ἡμῶν, καὶ τοσαύτη τις ἄγνοια παρ’ ὑμῖν ἐστιν, ὥσθ’, ὁποῖος ἄν τις ἕκαστος εἶναι φῇ ἢ ὁ πλησίον αὐτὸν αἰτιάσηται, τοιοῦτος νομισθήσεται, τοῦ δὲ καθ’ ἡμέραν βίου καὶ τῶν ἐπιτηδευμάτων μηδ’ ὁτιοῦν ἔσται τοῖς μετρίοις ὄφελος.", "st": "54.15"}, {"sp": "N", "t": "ἡμεῖς γὰρ οὔτε παροινοῦντες οὔθ’ ὑβρίζοντες ὑπ’ οὐδενὸς ἀνθρώπων ἑωράμεθα, οὐδ’ ἄγνωμον οὐδὲν ἡγούμεθα ποιεῖν, εἰ περὶ ὧν ἠδικήμεθ’ ἀξιοῦμεν κατὰ τοὺς νόμους δίκην λαβεῖν. ἰθυφάλλοις δὲ καὶ αὐτοληκύθοις συγχωροῦμεν εἶναι τοῖς υἱέσι τοῖς τούτου, καὶ ἔγωγ’ εὔχομαι τοῖς θεοῖς εἰς Κόνωνα καὶ τοὺς υἱεῖς τοὺς τούτου καὶ ταῦτα καὶ τὰ τοιαῦθ’ ἅπαντα τρέπεσθαι.", "st": "54.16"}, {"sp": "N", "t": "οὗτοι γάρ εἰσιν οἱ τελοῦντες ἀλλήλους τῷ ἰθυφάλλῳ, καὶ τοιαῦτα ποιοῦντες ἃ πολλὴν αἰσχύνην ἔχει καὶ λέγειν, μή τί γε δὴ ποιεῖν ἀνθρώπους μετρίους. ἀλλὰ τί ταῦτ’ ἐμοί; θαυμάζω γὰρ ἔγωγε, εἴ τίς ἐστιν πρόφασις παρ’ ὑμῖν ἢ σκῆψις ηὑρημένη δι’ ἥν, ἂν ὑβρίζων τις ἐξελέγχηται καὶ τύπτων, δίκην οὐ δώσει. οἱ μὲν γὰρ νόμοι πολὺ τἀναντία καὶ τὰς ἀναγκαίας προφάσεις, ὅπως μὴ μείζους γίγνωνται, προείδοντο, οἷον (ἀνάγκη γάρ μοι ταῦτα καὶ ζητεῖν καὶ πυνθάνεσθαι διὰ τοῦτον γέγονεν) εἰσὶ κακηγορίας δίκαι·", "st": "54.17"}, {"sp": "N", "t": "φασὶ τοίνυν ταύτας διὰ τοῦτο γίγνεσθαι, ἵνα μὴ λοιδορούμενοι τύπτειν ἀλλήλους προάγωνται. πάλιν αἰκείας εἰσί· καὶ ταύτας ἀκούω διὰ τοῦτ’ εἶναι τὰς δίκας, ἵνα μηδείς, ὅταν ἥττων ᾖ, λίθῳ μηδὲ τῶν τοιούτων ἀμύνηται μηδενί, ἀλλὰ τὴν ἐκ τοῦ νόμου δίκην ἀναμένῃ. τραύματος πάλιν εἰσὶν γραφαὶ τοῦ μὴ τιτρωσκομένων τινῶν φόνους γίγνεσθαι.", "st": "54.18"}, {"sp": "N", "t": "τὸ φαυλότατον, οἶμαι, τὸ τῆς λοιδορίας, πρὸ τοῦ τελευταίου καὶ δεινοτάτου προεώραται, τοῦ μὴ φόνον γίγνεσθαι, μηδὲ κατὰ μικρὸν ὑπάγεσθαι ἐκ μὲν λοιδορίας εἰς πληγάς, ἐκ δὲ πληγῶν εἰς τραύματα, ἐκ δὲ τραυμάτων εἰς θάνατον, ἀλλ’ ἐν τοῖς νόμοις εἶναι τούτων ἑκάστου τὴν δίκην, μὴ τῇ τοῦ προστυχόντος ὀργῇ μηδὲ βουλήσει ταῦτα κρίνεσθαι.", "st": "54.19"}, {"sp": "N", "t": "εἶτ’ ἐν μὲν τοῖς νόμοις οὕτως· ἂν δ’ εἴπῃ Κόνων “ἰθύφαλλοί τινές ἐσμεν ἡμεῖς συνειλεγμένοι, καὶ ἐρῶντες οὓς ἂν ἡμῖν δόξῃ παίομεν καὶ ἄγχομεν”, εἶτα γελάσαντες ὑμεῖς ἀφήσετε; οὐκ οἴομαί γε. οὐ γὰρ ἂν γέλως ὑμῶν ἔλαβεν οὐδένα, εἰ παρὼν ἐτύγχανεν ἡνίχ’ εἱλκόμην καὶ ἐξεδυόμην καὶ ὑβριζόμην, καὶ ὑγιὴς ἐξελθὼν φοράδην ἦλθον οἴκαδε, ἐξεπεπηδήκει δὲ μετὰ ταῦθ’ ἡ μήτηρ, καὶ κραυγὴ καὶ βοὴ τῶν γυναικῶν τοσαύτη παρ’ ἡμῖν ἦν ὡσπερανεὶ τεθνεῶτός τινος, ὥστε τῶν γειτόνων τινὰς πέμψαι πρὸς ἡμᾶς ἐρησομένους ὅ τι ἐστὶν τὸ συμβεβηκός.", "st": "54.20"}, {"sp": "N", "t": "ὅλως δ’, ὦ ἄνδρες δικασταί, δίκαιον μὲν οὐδενὶ δήπου σκῆψιν οὐδεμίαν τοιαύτην οὐδ’ ἄδειαν ὑπάρχειν παρ’ ὑμῖν, δι’ ἣν ὑβρίζειν ἐξέσται· εἰ δ’ ἄρ’ ἐστίν τῳ, τοῖς δι’ ἡλικίαν τούτων τι πράττουσιν, τούτοις ἀποκεῖσθαι προσήκει τὰς τοιαύτας καταφυγάς, κἀκείνοις οὐκ εἰς τὸ μὴ δοῦναι δίκην, ἀλλ’ εἰς τὸ τῆς προσηκούσης ἐλάττω.", "st": "54.21"}, {"sp": "N", "t": "ὅστις δ’ ἐτῶν μέν ἐστιν πλειόνων ἢ πεντήκοντα, παρὼν δὲ νεωτέροις ἀνθρώποις καὶ τούτοις υἱέσιν, οὐχ ὅπως ἀπέτρεψεν ἢ διεκώλυσεν, ἀλλ’ αὐτὸς ἡγεμὼν καὶ πρῶτος καὶ πάντων βδελυρώτατος γεγένηται, τίν’ ἂν οὗτος ἀξίαν τῶν πεπραγμένων ὑπόσχοι δίκην; ἐγὼ μὲν γὰρ οὐδ’ ἀποθανόντ’ οἴομαι. καὶ γὰρ εἰ μηδὲν αὐτὸς εἴργαστο τῶν πεπραγμένων, ἀλλ’ εἰ παρεστηκότος τούτου Κτησίας ὁ υἱὸς ὁ τούτου ταὔθ’ ἅπερ νυνὶ πεποιηκὼς ἐφαίνετο, τοῦτον ἐμισεῖτ’ ἂν δικαίως.", "st": "54.22"}, {"sp": "N", "t": "εἰ γὰρ οὕτω τοὺς αὑτοῦ προῆκται παῖδας ὥστ’ ἐναντίον ἐξαμαρτάνοντας ἑαυτοῦ, καὶ ταῦτ’ ἐφ’ ὧν ἐνίοις θάνατος ἡ ζημία κεῖται, μήτε φοβεῖσθαι μήτ’ αἰσχύνεσθαι, τί τοῦτον οὐκ ἂν εἰκότως παθεῖν οἴεσθε; ἐγὼ μὲν γὰρ ἡγοῦμαι ταῦτ’ εἶναι σημεῖα τοῦ μηδὲ τοῦτον τὸν ἑαυτοῦ πατέρ’ αἰσχύνεσθαι· εἰ γὰρ ἐκεῖνον αὐτὸς ἐτίμα καὶ ἐδεδίει, κἂν τούτους αὑτὸν ἠξίου.", "st": "54.23"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τοὺς νόμους, τόν τε τῆς ὕβρεως καὶ τὸν περὶ τῶν λωποδυτῶν· καὶ γὰρ τούτοις ἀμφοτέροις ἐνόχους τούτους ὄψεσθε. λέγε.", "st": "54.24"}, {"sp": "N", "t": "ΝΟΜΟΙ.", "st": "54.24"}, {"sp": "N", "t": "τούτοις τοῖς νόμοις ἀμφοτέροις ἐκ τῶν πεπραγμένων ἔνοχος Κόνων ἐστὶν οὑτοσί· καὶ γὰρ ὕβριζεν καὶ ἐλωποδύτει. εἰ δὲ μὴ κατὰ τούτους προειλόμεθ’ ἡμεῖς δίκην λαμβάνειν, ἡμεῖς μὲν ἀπράγμονες καὶ μέτριοι φαινοίμεθ’ ἂν εἰκότως, οὗτος δ’ ὁμοίως πονηρός.", "st": "54.24"}, {"sp": "N", "t": "καὶ μὴν εἰ παθεῖν τί μοι συνέβη, φόνου καὶ τῶν δεινοτάτων ἂν ἦν ὑπόδικος. τὸν γοῦν τῆς Βραυρωνόθεν ἱερείας πατέρ’ ὁμολογουμένως οὐχ ἁψάμενον τοῦ τελευτήσαντος, ὅτι τῷ πατάξαντι τύπτειν παρεκελεύσατο, ἐξέβαλεν ἡ βουλὴ ἡ ἐξ Ἀρείου πάγου, δικαίως· εἰ γὰρ οἱ παρόντες ἀντὶ τοῦ κωλύειν τοὺς ἢ δι’ οἶνον ἢ δι’ ὀργὴν ἤ τιν’ ἄλλην αἰτίαν ἐξαμαρτάνειν ἐπιχειροῦντας αὐτοὶ παροξυνοῦσιν, οὐδεμί’ ἐστὶν ἐλπὶς σωτηρίας τῷ περιπίπτοντι τοῖς ἀσελγαίνουσιν, ἀλλ’ ἕως ἂν ἀπείπωσιν, ὑβρίζεσθαι ὑπάρξει· ὅπερ ἐμοὶ συνέβη.", "st": "54.25"}, {"sp": "N", "t": "ἃ τοίνυν, ὅθ’ ἡ δίαιτα ἐγίγνετο, ἐποίουν, βούλομαι πρὸς ὑμᾶς εἰπεῖν· καὶ γὰρ ἐκ τούτων τὴν ἀσέλγειαν θεάσεσθ’ αὐτῶν. ἐποίησαν μὲν γὰρ ἔξω μέσων νυκτῶν τὴν ὥραν, οὔτε τὰς μαρτυρίας ἀναγιγνώσκειν ἐθέλοντες οὔτ’ ἀντίγραφα διδόναι, τῶν τε παρόντων ἡμῖν καθ’ ἕν’ οὑτωσὶ πρὸς τὸν λίθον ἄγοντες καὶ ἐξορκοῦντες, καὶ γράφοντες μαρτυρίας οὐδὲν πρὸς τὸ πρᾶγμα, ἀλλ’ ἐξ ἑταίρας εἶναι παιδίον αὐτῷ καὶ τοῦτο πεπονθέναι τὰ καὶ τά, ἃ μὰ τοὺς θεούς, ἄνδρες δικασταί, οὐδεὶς ὅστις οὐκ ἐπετίμα τῶν παρόντων καὶ ἐμίσει, τελευτῶντες δὲ καὶ αὐτοὶ οὗτοι ἑαυτούς.", "st": "54.26"}, {"sp": "N", "t": "ἐπειδὴ δ’ οὖν ποτ’ ἀπεῖπον καὶ ἐνεπλήσθησαν ταῦτα ποιοῦντες, προκαλοῦνται ἐπὶ διακρούσει καὶ τῷ μὴ σημανθῆναι τοὺς ἐχίνους ἐθέλειν ἐκδοῦναι περὶ τῶν πληγῶν παῖδας, ὀνόματα γράψαντες. καὶ νῦν οἶμαι περὶ τοῦτ’ ἔσεσθαι τοὺς πολλοὺς τῶν λόγων αὐτοῖς. ἐγὼ δ’ οἶμαι δεῖν πάντας ὑμᾶς ἐκεῖνο σκοπεῖν, ὅτι οὗτοι, εἰ τοῦ γενέσθαι τὴν βάσανον ἕνεκα προὐκαλοῦντο καὶ ἐπίστευον τῷ δικαίῳ τούτῳ, οὐκ ἂν ἤδη τῆς διαίτης ἀποφαινομένης, νυκτός, οὐδεμιᾶς ὑπολοίπου σκήψεως οὔσης, προὐκαλοῦντο,", "st": "54.27"}, {"sp": "N", "t": "ἀλλὰ πρῶτον μὲν πρὸ τοῦ τὴν δίκην ληχθῆναι, ἡνίκ’ ἀσθενῶν ἐγὼ κατεκείμην, καὶ οὐκ εἰδὼς εἰ περιφεύξομαι, πρὸς ἅπαντας τοὺς εἰσιόντας τοῦτον ἀπέφαινον τὸν πρῶτον πατάξαντα καὶ τὰ πλεῖσθ’ ὧν ὑβρίσμην διαπεπραγμένον, τότ’ ἂν εὐθέως ἧκεν ἔχων μάρτυρας πολλοὺς ἐπὶ τὴν οἰκίαν, τότ’ ἂν τοὺς οἰκέτας παρεδίδου καὶ τῶν ἐξ Ἀρείου πάγου τινὰς παρεκάλει· εἰ γὰρ ἀπέθανον, παρ’ ἐκείνοις ἂν ἦν ἡ δίκη.", "st": "54.28"}, {"sp": "N", "t": "εἰ δ’ ἄρ’ ἠγνόησε ταῦτα, καὶ τοῦτο τὸ δίκαιον ἔχων, ὡς νῦν φήσει, οὐ παρεσκευάσατ’ ὑπὲρ τηλικούτου κινδύνου, ἐπειδή γ’ ἀνεστηκὼς ἤδη προσεκαλεσάμην αὐτόν, ἐν τῇ πρώτῃ συνόδῳ πρὸς τῷ διαιτητῇ παραδιδοὺς ἐφαίνετ’ ἄν· ὧν οὐδὲν πέπρακται τούτῳ. ὅτι δ’ ἀληθῆ λέγω καὶ διακρούσεως ἕνεχ’ ἡ πρόκλησις ἦν, λέγε ταύτην τὴν μαρτυρίαν· ἔσται γὰρ ἐκ ταύτης φανερόν.", "st": "54.29"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "54.29"}, {"sp": "N", "t": "περὶ μὲν τοίνυν τῆς βασάνου ταῦτα μέμνησθε, τὴν ὥραν ἡνίκα προὐκαλεῖτο, ὧν ἕνεκ’ ἐκκρούων ταῦτ’ ἐποίει, τοὺς χρόνους τοὺς πρώτους, ἐν οἷς οὐδαμοῦ τοῦτο βουληθεὶς τὸ δίκαιον αὑτῷ γενέσθαι φαίνεται, οὐδὲ προκαλεσάμενος, οὐδ’ ἀξιώσας. ἐπειδὴ τοίνυν ταὐτὰ πάντ’ ἠλέγχεθ’ ἅπερ καὶ νῦν, πρὸς τῷ διαιτητῇ, καὶ φανερῶς ἐδείκνυτο πᾶσιν ὢν ἔνοχος τοῖς ἐγκεκλημένοις,", "st": "54.30"}, {"sp": "N", "t": "ἐμβάλλεται μαρτυρίαν ψευδῆ καὶ ἐπιγράφεται μάρτυρας ἀνθρώπους οὓς οὐδ’ ὑμᾶς ἀγνοήσειν οἴομαι, ἐὰν ἀκούσητε, “Διότιμος Διοτίμου Ἰκαριεύς, Ἀρχεβιάδης Δημοτέλους Ἁλαιεύς, Χαιρήτιος Χαιριμένους Πιθεὺς μαρτυροῦσιν ἀπιέναι ἀπὸ δείπνου μετὰ Κόνωνος, καὶ προσελθεῖν ἐν ἀγορᾷ μαχομένοις Ἀρίστωνι καὶ τῷ υἱεῖ τῷ Κόνωνος,”", "st": "54.31"}, {"sp": "N", "t": "“καὶ μὴ πατάξαι Κόνωνα Ἀρίστωνα”, ὡς ὑμᾶς εὐθέως πιστεύσοντας, τὸ δ’ ἀληθὲς οὐ λογιουμένους, ὅτι πρῶτον μὲν οὐδέποτ’ ἂν οὔθ’ ὁ Λυσίστρατος οὔθ’ ὁ Πασέας οὔθ’ ὁ Νικήρατος οὔθ’ ὁ Διόδωρος, οἳ διαρρήδην μεμαρτυρήκασιν ὁρᾶν ὑπὸ Κόνωνος τυπτόμενον ἐμὲ καὶ θοἰμάτιον ἐκδυόμενον καὶ τἄλλ’ ὅσ’ ἔπασχον ὑβριζόμενον, ἀγνῶτες ὄντες κἀπὸ ταὐτομάτου παραγενόμενοι τῷ πράγματι τὰ ψευδῆ μαρτυρεῖν ἠθέλησαν, εἰ μὴ ταῦθ’ ἑώρων πεπονθότα· ἔπειτ’ αὐτὸς ἐγὼ οὐδέποτ’ ἄν, μὴ παθὼν ὑπὸ τούτου ταῦτα, ἀφεὶς τοὺς καὶ παρ’ αὐτῶν τούτων ὁμολογουμένους τύπτειν ἐμὲ πρὸς τὸν οὐδ’ ἁψάμενον πρῶτον εἰσιέναι προειλόμην.", "st": "54.32"}, {"sp": "N", "t": "τί γὰρ ἄν; ἀλλ’ ὑφ’ οὗ γε πρώτου ἐπλήγην καὶ μάλισθ’ ὑβρίσθην, τούτῳ καὶ δικάζομαι καὶ μισῶ καὶ ἐπεξέρχομαι. καὶ τὰ μὲν παρ’ ἐμοῦ πάνθ’ οὕτως ἐστὶν ἀληθῆ καὶ φαίνεται· τούτῳ δὲ μὴ παρασχομένῳ τούτους μάρτυρας ἦν δήπου λόγος οὐδείς, ἀλλ’ ἑαλωκέναι παραχρῆμ’ ὑπῆρχε σιωπῇ. συμπόται δ’ ὄντες τούτου καὶ πολλῶν τοιούτων ἔργων κοινωνοὶ εἰκότως τὰ ψευδῆ μεμαρτυρήκασιν. εἰ δ’ ἔσται τὸ πρᾶγμα τοιοῦτον, ἐὰν ἅπαξ ἀπαναισχυντήσωσίν τινες καὶ τὰ ψευδῆ φανερῶς τολμήσωσι μαρτυρεῖν, οὐδὲν δὲ τῆς ἀληθείας ὄφελος, πάνδεινον ἔσται πρᾶγμα.", "st": "54.33"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ οὐκ εἰσὶ τοιοῦτοι. ἀλλ’ ἴσασιν ὑμῶν, ὡς ἐγὼ νομίζω, πολλοὶ καὶ τὸν Διότιμον καὶ τὸν Ἀρχεβιάδην καὶ τὸν Χαιρήτιον τὸν ἐπιπόλιον τουτονί, οἳ μεθ’ ἡμέραν μὲν ἐσκυθρωπάκασιν καὶ λακωνίζειν φασὶ καὶ τρίβωνας ἔχουσιν καὶ ἁπλᾶς ὑποδέδενται, ἐπειδὰν δὲ συλλεγῶσιν καὶ μετ’ ἀλλήλων γένωνται, κακῶν καὶ αἰσχρῶν οὐδὲν ἐλλείπουσι.", "st": "54.34"}, {"sp": "N", "t": "καὶ ταῦτα τὰ λαμπρὰ καὶ νεανικά ἐστιν αὐτῶν “οὐ γὰρ ἡμεῖς μαρτυρήσομεν ἀλλήλοις; οὐ γὰρ ταῦθ’ ἑταίρων ἐστὶ καὶ φίλων; τί δὲ καὶ δεινόν ἐστιν ὧν παρέξεται κατὰ σοῦ; τυπτόμενόν φασί τινες ὁρᾶν; ἡμεῖς δὲ μηδ’ ἧφθαι τὸ παράπαν μαρτυρήσομεν. ἐκδεδύσθαι θοἰμάτιον; τοῦτ’ ἐκείνους προτέρους πεποιηκέναι ἡμεῖς μαρτυρήσομεν. τὸ χεῖλος ἐρράφθαι; τὴν κεφαλὴν δέ γ’ ἡμεῖς ἢ ἕτερόν τι κατεαγέναι φήσομεν.”", "st": "54.35"}, {"sp": "N", "t": "ἀλλὰ καὶ μάρτυρας ἰατροὺς παρέχομαι. τοῦτ’ οὐκ ἔστιν, ὦ ἄνδρες δικασταί, παρὰ τούτοις· ὅσα γὰρ μὴ δι’ αὑτῶν, οὐδενὸς μάρτυρος καθ’ ἡμῶν εὐπορήσουσιν. ἡ δ’ ἀπ’ αὐτῶν ἑτοιμότης οὐδ’ ἂν εἰπεῖν μὰ τοὺς θεοὺς δυναίμην ὅση καὶ οἵα πρὸς τὸ ποιεῖν ὁτιοῦν ὑπάρχει. ἵνα δ’ εἰδῆθ’ οἷα καὶ διαπραττόμενοι περιέρχονται, λέγ’ αὐτοῖς ταυτασὶ τὰς μαρτυρίας, σὺ δ’ ἐπίλαβε τὸ ὕδωρ.", "st": "54.36"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "54.36"}, {"sp": "N", "t": "τοίχους τοίνυν διορύττοντες καὶ παίοντες τοὺς ἀπαντῶντας, ἆρ’ ἂν ὑμῖν ὀκνῆσαι δοκοῦσιν ἐν γραμματειδίῳ τὰ ψευδῆ μαρτυρεῖν ἀλλήλοις οἱ κεκοινωνηκότες τοσαύτης καὶ τοιαύτης φιλαπεχθημοσύνης καὶ πονηρίας καὶ ἀναιδείας καὶ ὕβρεως; πάντα γὰρ ταῦτ’ ἔμοιγ’ ἐν τοῖς ὑπὸ τούτων πραττομένοις ἐνεῖναι δοκεῖ. καίτοι καὶ τούτων ἕτερ’ ἐστὶν πεπραγμένα τούτοις δεινότερα, ἀλλ’ ἡμεῖς οὐχ οἷοί τε γενοίμεθ’ ἂν πάντας ἐξευρεῖν τοὺς ἠδικημένους.", "st": "54.37"}, {"sp": "N", "t": "ὃ τοίνυν πάντων ἀναιδέστατον μέλλειν αὐτὸν ἀκούω ποιεῖν, βέλτιον νομίζω προειπεῖν ὑμῖν εἶναι. φασὶ γὰρ παραστησάμενον τοὺς παῖδας αὐτὸν κατὰ τούτων ὀμεῖσθαι, καὶ ἀράς τινας δεινὰς καὶ χαλεπὰς ἐπαράσεσθαι καὶ τοιαύτας οἵας ἀκηκοώς γέ τις θαυμάσας ἀπήγγελλεν ἡμῖν. ἔστι δ’, ὦ ἄνδρες δικασταί, ἀνυπόστατα μὲν τὰ τοιαῦτα τολμήματα· οἱ γὰρ οἶμαι βέλτιστοι καὶ ἥκιστ’ ἂν αὐτοί τι ψευσάμενοι μάλισθ’ ὑπὸ τῶν τοιούτων ἐξαπατῶνται· οὐ μὴν ἀλλὰ δεῖ πρὸς τὸν βίον καὶ τὸν τρόπον ἀποβλέποντας πιστεύειν.", "st": "54.38"}, {"sp": "N", "t": "τὴν δὲ τούτου πρὸς τὰ τοιαῦτ’ ὀλιγωρίαν ἐγὼ πρὸς ὑμᾶς ἐρῶ· πέπυσμαι γὰρ ἐξ ἀνάγκης. ἀκούω γάρ, ὦ ἄνδρες δικασταί, Βάκχιόν τέ τινα, ὃς παρ’ ὑμῖν ἀπέθανε, καὶ Ἀριστοκράτην τὸν τοὺς ὀφθαλμοὺς διεφθαρμένον καὶ τοιούτους ἑτέρους καὶ Κόνωνα τουτονὶ ἑταίρους εἶναι μειράκι’ ὄντας καὶ Τριβαλλοὺς ἐπωνυμίαν ἔχειν· τούτους τά θ’ Ἑκαταῖα [κατεσθίειν,] καὶ τοὺς ὄρχεις τοὺς ἐκ τῶν χοίρων, οἷς καθαίρουσιν ὅταν εἰσιέναι μέλλωσιν, συλλέγοντας ἑκάστοτε συνδειπνεῖν ἀλλήλοις, καὶ ῥᾷον ὀμνύναι καὶ ἐπιορκεῖν ἢ ὁτιοῦν.", "st": "54.39"}, {"sp": "N", "t": "οὐ δὴ Κόνων ὁ τοιοῦτος πιστός ἐστιν ὀμνύων, οὐδὲ πολλοῦ δεῖ, ἀλλ’ ὁ μηδ’ εὔορκον ⟨ἑκὼν⟩ μηδὲν ἂν ὀμόσας, κατὰ δὲ δὴ παίδων ὧν μὴ νομίζετε μηδ’ ἂν μελλήσας, ἀλλὰ κἂν ὁτιοῦν παθὼν πρότερον, εἰ δ’ ἄρ’ ἀναγκαῖον, ὀμνύων ὡς νόμιμον, ⟨κατ’ ἐξωλείας αὑτοῦ καὶ γένους καὶ οἰκίας⟩, ἀξιοπιστότερος τοῦ κατὰ τῶν παίδων ὀμνύοντος καὶ διὰ τοῦ πυρός. ἐγὼ τοίνυν ὁ δικαιότερόν σου πιστευθεὶς ἂν κατὰ πάντ’, ὦ Κόνων, ἠθέλησ’ ὀμόσαι ταυτί, οὐχ ὑπὲρ τοῦ μὴ δοῦναι δίκην ὧν ἠδίκηκα, καὶ ὁτιοῦν ποιῶν, ὥσπερ σύ, ἀλλ’ ὑπὲρ τῆς ἀληθείας καὶ ὑπὲρ τοῦ μὴ προσυβρισθῆναι, ὡς οὐ κατεπιορκησόμενος τὸ πρᾶγμα. λέγε τὴν πρόκλησιν.", "st": "54.40"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "54.40"}, {"sp": "N", "t": "ταῦτ’ ἐγὼ καὶ τότ’ ἠθέλησ’ ὀμόσαι, καὶ νῦν ὀμνύω τοὺς θεοὺς καὶ τὰς θεὰς ἅπαντας καὶ πάσας ὑμῶν ἕνεκ’, ὦ ἄνδρες δικασταί, καὶ τῶν περιεστηκότων, ἦ μὴν παθὼν ὑπὸ Κόνωνος ταῦθ’ ὧν δικάζομαι, καὶ λαβὼν πληγάς, καὶ τὸ χεῖλος διακοπεὶς οὕτως ὥστε καὶ ῥαφῆναι, καὶ ὑβρισθεὶς τὴν δίκην διώκειν. καὶ εἰ μὲν εὐορκῶ, πολλά μοι ἀγαθὰ γένοιτο καὶ μηδέποτ’ αὖθις τοιοῦτο μηδὲν πάθοιμι, εἰ δ’ ἐπιορκῶ, ἐξώλης ἀπολοίμην αὐτὸς καὶ εἴ τί μοι ἔστιν ἢ μέλλει ἔσεσθαι.", "st": "54.41"}, {"sp": "N", "t": "ἀλλ’ οὐκ ἐπιορκῶ, οὐδ’ ἂν Κόνων διαρραγῇ. ἀξιῶ τοίνυν ὑμᾶς, ὦ ἄνδρες δικασταί, πάνθ’ ὅσ’ ἐστὶν δίκαι’ ἐπιδείξαντος ἐμοῦ καὶ πίστιν προσθέντος ὑμῖν, ὥσπερ ἂν αὐτὸς ἕκαστος παθὼν τὸν πεποιηκότ’ ἐμίσει, οὕτως ὑπὲρ ἐμοῦ πρὸς Κόνωνα τουτονὶ τὴν ὀργὴν ἔχειν, καὶ μὴ νομίζειν ἴδιον τῶν τοιούτων μηδὲν ὃ κἂν ἄλλῳ τυχὸν συμβαίη, ἀλλ’ ἐφ’ ὅτου ποτ’ ἂν συμβῇ, βοηθεῖν καὶ τὰ δίκαι’ ἀποδιδόναι, καὶ μισεῖν τοὺς πρὸ μὲν τῶν ἁμαρτημάτων θρασεῖς καὶ προπετεῖς, ἐν δὲ τῷ δίκην ὑπέχειν ἀναισχύντους καὶ πονηροὺς καὶ μήτε δόξης μήτ’ ἔθους μήτ’ ἄλλου μηδενὸς φροντίζοντας πρὸς τὸ μὴ δοῦναι δίκην.", "st": "54.42"}, {"sp": "N", "t": "ἀλλὰ δεήσεται Κόνων καὶ κλαήσει. σκοπεῖτε δὴ πότερός ἐστιν ἐλεινότερος, ὁ πεπονθὼς οἷ’ ἐγὼ πέπονθ’ ὑπὸ τούτου, εἰ προσυβρισθεὶς ἄπειμι καὶ δίκης μὴ τυχών, ἢ Κόνων, εἰ δώσει δίκην; πότερον δ’ ὑμῶν ἑκάστῳ συμφέρει ἐξεῖναι τύπτειν καὶ ὑβρίζειν ἢ μή; ἐγὼ μὲν οἴομαι μή. οὐκοῦν, ἂν μὲν ἀφιῆτε, ἔσονται πολλοί, ἐὰν δὲ κολάζητε, ἐλάττους.", "st": "54.43"}, {"sp": "N", "t": "πόλλ’ ἂν εἰπεῖν ἔχοιμ’, ὦ ἄνδρες δικασταί, καὶ ὡς ἡμεῖς χρήσιμοι, καὶ αὐτοὶ καὶ ὁ πατήρ, ἕως ἔζη, καὶ τριηραρχοῦντες καὶ στρατευόμενοι καὶ τὸ προσταττόμενον ποιοῦντες, καὶ ὡς οὐδὲν οὔθ’ οὗτος οὔτε τῶν τούτου οὐδείς· ἀλλ’ οὔτε τὸ ὕδωρ ἱκανὸν οὔτε νῦν περὶ τούτων ὁ λόγος ἐστίν. εἰ γὰρ δὴ ὁμολογουμένως ἔτι τούτων καὶ ἀχρηστοτέροις καὶ πονηροτέροις ἡμῖν εἶναι συνέβαινεν, οὐ τυπτητέοι, οὐδ’ ὑβριστέοι δήπου ἐσμέν.", "st": "54.44"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· οἶμαι γὰρ ὑμᾶς οὐδὲν ἀγνοεῖν τῶν εἰρημένων.", "st": "54.44"}, {"sp": "HDR", "t": "Πρὸς Καλλικλέα περὶ χωρίου βλάβης", "st": "55"}, {"sp": "N", "t": "οὐκ ἦν ἄρ’, ὦ ἄνδρες Ἀθηναῖοι, χαλεπώτερον οὐδὲν ἢ γείτονος πονηροῦ καὶ πλεονέκτου τυχεῖν, ὅπερ ἐμοὶ νυνὶ συμβέβηκεν. ἐπιθυμήσας γὰρ τῶν χωρίων μου Καλλικλῆς οὕτω διατέθηκέν με συκοφαντῶν, ὥστε πρῶτον μὲν τὸν ἀνεψιὸν τὸν ἑαυτοῦ κατεσκεύασεν ἀμφισβητεῖν μοι τῶν χωρίων,", "st": "55.1"}, {"sp": "N", "t": "ἐξελεγχθεὶς δὲ φανερῶς καὶ περιγενομένου μου τῆς τούτων σκευωρίας πάλιν δύο δίκας ἐρήμους μου κατεδιῃτήσατο, τὴν μὲν αὐτὸς χιλίων δραχμῶν, τὴν δὲ τὸν ἀδελφὸν τουτονὶ πείσας Καλλικράτην. δέομαι δὴ πάντων ὑμῶν ἀκοῦσαί μου καὶ προσέχειν τὸν νοῦν, οὐχ ὡς αὐτὸς δυνησόμενος εἰπεῖν, ἀλλ’ ἵν’ ὑμεῖς ἐξ αὐτῶν τῶν πραγμάτων καταμάθητε, ὅτι φανερῶς συκοφαντοῦμαι.", "st": "55.2"}, {"sp": "N", "t": "ἓν μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, πρὸς ἅπαντας τοὺς τούτων λόγους ὑπάρχει μοι δίκαιον. τὸ γὰρ χωρίον τοῦτο περιῳκοδόμησεν ὁ πατὴρ μικροῦ δεῖν πρὶν ἐμὲ γενέσθαι, ζῶντος μὲν ἔτι Καλλιππίδου τοῦ τούτων πατρὸς καὶ γειτνιῶντος, ὃς ἀκριβέστερον ᾔδει δήπου τούτων, ὄντος δὲ Καλλικλέους ἀνδρὸς ἤδη καὶ ἐπιδημοῦντος Ἀθήνησιν.", "st": "55.3"}, {"sp": "N", "t": "ἐν δὲ τούτοις τοῖς ἔτεσιν ἅπασιν οὔτ’ ἐγκαλῶν οὐδεὶς πώποτ’ ἦλθεν οὔτε μεμφόμενος (καίτοι δῆλον ὅτι καὶ τόθ’ ὕδατα πολλάκις ἐγένετο), οὐδ’ ἐκώλυσεν ἐξ ἀρχῆς, εἴπερ ἠδίκει τινὰ περιοικοδομῶν ὁ πατὴρ τὸ ἡμέτερον χωρίον, ἀλλ’ οὐδ’ ἀπηγόρευσεν οὐδὲ διεμαρτύρατο, πλέον μὲν ἢ πεντεκαίδεκ’ ἔτη τοῦ πατρὸς ἐπιβιόντος, οὐκ ἐλάττω δὲ τοῦ τούτων πατρὸς Καλλιππίδου.", "st": "55.4"}, {"sp": "N", "t": "καίτοι, ὦ Καλλίκλεις, ἐξῆν δήπου τόθ’ ὑμῖν, ὁρῶσιν ἀποικοδομουμένην τὴν χαράδραν, ἐλθοῦσιν εὐθὺς ἀγανακτεῖν καὶ λέγειν πρὸς τὸν πατέρα “Τεισία, τί ταῦτα ποιεῖς; ἀποικοδομεῖς τὴν χαράδραν; εἶτ’ ἐμπεσεῖται τὸ ὕδωρ εἰς τὸ χωρίον τὸ ἡμέτερον”, ἵν’ εἰ μὲν ἐβούλετο παύσασθαι, μηδὲν ἡμῖν ἦν δυσχερὲς πρὸς ἀλλήλους, εἰ δ’ ὠλιγώρησεν καὶ συνέβη τι τοιοῦτον, μάρτυσιν εἶχες τοῖς τότε παραγενομένοις χρῆσθαι.", "st": "55.5"}, {"sp": "N", "t": "καὶ νὴ Δι’ ἐπιδεῖξαί γέ σ’ ἔδει πᾶσιν ἀνθρώποις χαράδραν οὖσαν, ἵνα μὴ λόγῳ μόνον, ὥσπερ νῦν, ἀλλ’ ἔργῳ τὸν πατέρ’ ἀδικοῦντ’ ἀπέφαινες. τούτων τοίνυν οὐδὲν πώποτ’ οὐδεὶς ποιεῖν ἠξίωσεν. οὐ γὰρ ἂν οὔτ’ ἐρήμην, ὥσπερ ἐμοῦ νῦν, κατεδιῃτήσασθε, οὔτε πλέον ἂν ἦν ὑμῖν συκοφαντοῦσιν οὐδέν,", "st": "55.6"}, {"sp": "N", "t": "ἀλλ’ [εἰ ἠνέγκατε τότε μάρτυρα καὶ ἐπεμαρτύρασθε, νῦν] ἀπέφαινεν ἂν ἐκεῖνος εἰδὼς ἀκριβῶς ὅπως εἶχεν ἕκαστα τούτων, καὶ τοὺς ῥᾳδίως τούτους μαρτυροῦντας ἐξήλεγχεν. ἀνθρώπου δ’ οἶμαι τηλικούτου καὶ ἀπείρου [τῶν] πραγμάτων ἅπαντες καταπεφρονήκατέ μου. ἀλλ’ ἐγὼ πρὸς ἅπαντας τούτους, ὦ ἄνδρες Ἀθηναῖοι, τὰς αὐτῶν πράξεις ἰσχυροτάτας μαρτυρίας παρέχομαι. διὰ τί γὰρ οὐδεὶς οὔτ’ ἐπεμαρτύρατ’ οὔτ’ ἐνεκάλεσεν, ἀλλ’ οὐδ’ ἐμέμψατο πώποτε, ἀλλ’ ἐξήρκει ταῦτ’ αὐτοῖς ἠδικημένοις περιορᾶν;", "st": "55.7"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἱκανὰ μὲν ἡγοῦμαι καὶ ταῦτ’ εἶναι πρὸς τὴν τούτων ἀναίδειαν· ἵνα δ’ εἰδῆτ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ περὶ τῶν ἄλλων, ὡς οὔθ’ ὁ πατὴρ οὐδὲν ἠδίκει περιοικοδομῶν τὸ χωρίον οὗτοί τε κατεψευσμένοι πάντ’ εἰσὶν ἡμῶν, ἔτι σαφέστερον ὑμᾶς πειράσομαι διδάσκειν. τὸ μὲν γὰρ χωρίον ὁμολογεῖται καὶ παρ’ αὐτῶν τούτων ἡμέτερον ἴδιον εἶναι·", "st": "55.8"}, {"sp": "N", "t": "τούτου δ’ ὑπάρχοντος, ὦ ἄνδρες Ἀθηναῖοι, μάλιστα μὲν ᾔδειτ’ ἂν ἰδόντες τὸ χωρίον ὅτι συκοφαντοῦμαι. διὸ καὶ τοῖς εἰδόσιν ἐπιτρέπειν ἐβουλόμην ἐγώ, τοῖς ἴσοις. ἀλλ’ οὐχ οὗτοι, καθάπερ νυνὶ λέγειν ἐπιχειροῦσιν· δῆλον δ’ ὑμῖν καὶ τοῦτ’ αὐτίκ’ ἔσται πᾶσιν. ἀλλὰ προσέχετ’, ὦ ἄνδρες Ἀθηναῖοι, πρὸς Διὸς καὶ θεῶν τὸν νοῦν.", "st": "55.9"}, {"sp": "N", "t": "τοῦ γὰρ χωρίου τοῦ τ’ ἐμοῦ καὶ τοῦ τούτων τὸ μέσον ὁδός ἐστιν, ὄρους δὲ περιέχοντος κύκλῳ τοῖς χωρίοις τὸ καταρρέον ὕδωρ τῇ μὲν εἰς τὴν ὁδόν, τῇ δ’ εἰς τὰ χωρία συμβαίνει φέρεσθαι. καὶ δὴ καὶ τούτου τὸ εἰσπῖπτον εἰς τὴν ὁδόν, ᾗ μὲν ἂν εὐοδῇ, φέρεται κάτω κατὰ τὴν ὁδόν, ᾗ δ’ ἂν ἐνστῇ τι, τηνικαῦτα τοῦτ’ εἰς τὰ χωρί’ ὑπεραίρειν ἀναγκαῖον ἤδη.", "st": "55.10"}, {"sp": "N", "t": "καὶ δὴ κατὰ τοῦτο τὸ χωρίον, ὦ ἄνδρες δικασταί, γενομένης ἐπομβρίας συνέβη τὸ ὕδωρ ἐμβαλεῖν· ἀμεληθὲν δ’ οὔπω τοῦ πατρὸς ἔχοντος αὐτό, ἀλλ’ ἀνθρώπου δυσχεραίνοντος ὅλως τοῖς τόποις καὶ μᾶλλον ἀστικοῦ, δὶς καὶ τρὶς ἐμβαλὸν τὸ ὕδωρ τά τε χωρί’ ἐλυμήνατο καὶ μᾶλλον ὡδοποίει. διὸ δὴ ταῦθ’ ὁ πατὴρ ὁρῶν, ὡς ἐγὼ τῶν εἰδότων ἀκούω, καὶ τῶν γειτόνων ἐπινεμόντων ἅμα καὶ βαδιζόντων διὰ τοῦ χωρίου, τὴν αἱμασιὰν περιῳκοδόμησεν ταύτην.", "st": "55.11"}, {"sp": "N", "t": "καὶ ὡς ταῦτ’ ἀληθῆ λέγω, παρέξομαι μὲν καὶ μάρτυρας ὑμῖν τοὺς εἰδότας, πολὺ δ’, ὦ ἄνδρες Ἀθηναῖοι, τῶν μαρτύρων ἰσχυρότερα τεκμήρια. Καλλικλῆς μὲν γάρ φησιν τὴν χαράδραν ἀποικοδομήσαντα βλάπτειν ἔμ’ αὑτόν· ἐγὼ δ’ ἀποδείξω χωρίον ὂν τοῦτο, ἀλλ’ οὐ χαράδραν.", "st": "55.12"}, {"sp": "N", "t": "εἰ μὲν οὖν μὴ συνεχωρεῖθ’ ἡμέτερον ἴδιον εἶναι, τάχ’ ἂν τοῦτ’ ἠδικοῦμεν, εἴ τι τῶν δημοσίων ᾠκοδομοῦμεν· νυνὶ δ’ οὔτε τοῦτ’ ἀμφισβητοῦσιν, ἔστιν τ’ ἐν τῷ χωρίῳ δένδρα πεφυτευμένα, ἄμπελοι καὶ συκαῖ. καίτοι τίς ἂν ἐν χαράδρᾳ ταῦτα φυτεύειν ἀξιώσειεν; οὐδείς γε. τίς δὲ πάλιν τοὺς αὑτοῦ προγόνους θάπτειν;", "st": "55.13"}, {"sp": "N", "t": "οὐδὲ τοῦτ’ οἶμαι. ταῦτα τοίνυν ἀμφότερ’, ὦ ἄνδρες δικασταί, συμβέβηκεν· καὶ γὰρ τὰ δένδρα πεφύτευται πρότερον ἢ τὸν πατέρα περιοικοδομῆσαι τὴν αἱμασιάν, καὶ τὰ μνήματα παλαιὰ καὶ πρὶν ἡμᾶς κτήσασθαι τὸ χωρίον γεγενημέν’ ἐστίν. καίτοι τούτων ὑπαρχόντων τίς ἂν ἔτι λόγος ἰσχυρότερος, ὦ ἄνδρες Ἀθηναῖοι, γένοιτο; τὰ γὰρ ἔργα φανερῶς ἐξελέγχει. καί μοι λαβὲ πάσας νυνὶ τὰς μαρτυρίας, καὶ λέγε.", "st": "55.14"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "55.14"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες Ἀθηναῖοι, τῶν μαρτυριῶν. ἆρ’ ὑμῖν δοκοῦσι διαρρήδην μαρτυρεῖν, καὶ χωρίον εἶναι δένδρων μεστὸν καὶ μνήματ’ ἔχειν τινὰ καὶ τἄλλ’ ἅπερ καὶ τοῖς ἄλλοις χωρίοις συμβέβηκεν, καὶ πάλιν ὅτι περιῳκοδομήθη τὸ χωρίον ζῶντος μὲν ἔτι τοῦ τούτων πατρός, οὐκ ἀμφισβητούντων δ’ οὔτε τούτων οὔτ’ ἄλλου τῶν γειτόνων οὐδενός;", "st": "55.15"}, {"sp": "N", "t": "ἄξιον δ’, ὦ ἄνδρες δικασταί, καὶ περὶ τῶν ἄλλων ὧν εἴρηκε Καλλικλῆς ἀκοῦσαι. καὶ σκέψασθε πρῶτον μέν, εἴ τις ὑμῶν ἑόρακεν ἢ ἀκήκοεν πώποτε παρ’ ὁδὸν χαράδραν οὖσαν. οἶμαι γὰρ ἐν πάσῃ τῇ χώρᾳ μηδεμίαν εἶναι· τοῦ γὰρ ἕνεκ’ ⟨ἄν⟩, ὃ διὰ τῆς ὁδοῦ τῆς δημοσίας ἔμελλεν βαδιεῖσθαι φερόμενον, τούτῳ διὰ τῶν ἰδίων χωρίων χαράδραν ἐποίησέν τις;", "st": "55.16"}, {"sp": "N", "t": "ἔπειτα τίς ἂν ὑμῶν εἴτ’ ἐν ἀγρῷ νὴ Δί’ εἴτ’ ἐν ἄστει τὸ διὰ τῆς ὁδοῦ ῥέον ὕδωρ εἰς τὸ χωρίον ἢ τὴν οἰκίαν δέξαιτ’ ἂν [αὑτοῦ]; ἀλλ’ οὐκ αὐτὸ τοὐναντίον, κἂν βιάσηταί ποτε, ἀποφράττειν ἅπαντες καὶ παροικοδομεῖν εἰώθαμεν; οὗτος τοίνυν ἀξιοῖ μ’ ἐκ τῆς ὁδοῦ τὸ ὕδωρ εἰσδεξάμενον εἰς τὸ ἐμαυτοῦ χωρίον, ὅταν τὸ τούτου παραλλάξῃ χωρίον, πάλιν εἰς τὴν ὁδὸν ἐξαγαγεῖν. οὐκοῦν πάλιν ὁ μετὰ τοῦτόν μοι γεωργῶν τῶν γειτόνων ἐγκαλεῖ· τὸ γὰρ ὑπὲρ τούτου δίκαιον δῆλον ὅτι κἀκείνοις ὑπάρξει πᾶσι λέγειν.", "st": "55.17"}, {"sp": "N", "t": "ἀλλὰ μὴν εἴ γ’ εἰς τὴν ὁδὸν ὀκνήσω τὸ ὕδωρ ἐξάγειν, ἦ που σφόδρα θαρρῶν εἰς τὸ τοῦ πλησίον χωρίον ἀφιείην ἄν. ὅπου γὰρ δίκας ἀτιμήτους φεύγω διότι τὸ ἐκ τῆς ὁδοῦ ῥέον ὕδωρ εἰς τὸ τούτου χωρίον διέπεσεν, τί πείσομαι πρὸς Διὸς ὑπὸ τῶν ἐκ τοῦ χωρίου τοὐμοῦ τοῦ ὕδατος εἰσπεσόντος βλαπτομένων; ὅπου δὲ μήτ’ εἰς τὴν ὁδὸν μήτ’ εἰς τὰ χωρί’ ἀφιέναι μοι τὸ ὕδωρ ἐξέσται δεξαμένῳ, τί λοιπόν, ὦ ἄνδρες δικασταί, πρὸς θεῶν; οὐ γὰρ ἐκπιεῖν γε δήπου με Καλλικλῆς αὐτὸ προσαναγκάσει.", "st": "55.18"}, {"sp": "N", "t": "ταῦτα τοίνυν ἐγὼ πάσχων ὑπὸ τούτων καὶ πόλλ’ ἕτερα καὶ δεινά, μὴ ὅτι δίκην λαβών, ἀλλὰ μὴ προσοφλὼν ἀγαπήσαιμ’ ἄν. εἰ μὲν γὰρ ἦν, ὦ ἄνδρες δικασταί, χαράδρα πάλιν ὑποδεχομένη, τάχ’ ἂν ἠδίκουν ἐγὼ μὴ δεχόμενος, ὥσπερ ἀν’ ἕτερ’ ἄττα τῶν χωρίων εἰσὶν ὁμολογούμεναι χαράδραι· καὶ ταύταις δέχονται μὲν οἱ πρῶτοι, καθάπερ τοὺς ἐκ τῶν οἰκιῶν χειμάρρους, παρὰ τούτων δ’ ἕτεροι παραλαμβάνουσιν ὡσαύτως· ταύτῃ δ’ οὔτε παραδίδωσιν οὐδεὶς οὔτε παρ’ ἐμοῦ παραλαμβάνει.", "st": "55.19"}, {"sp": "N", "t": "πῶς ἂν οὖν εἴη τοῦτο χαράδρα; τὸ δ’ εἰσπεσὸν ὕδωρ ἔβλαψεν οἶμαι πολλάκις ἤδη πολλοὺς μὴ φυλαξαμένους, ἔβλαψε δὲ καὶ νῦν τουτονί. ὃ καὶ πάντων ἐστὶν δεινότατον, εἰ Καλλικλῆς μὲν εἰς τὸ χωρίον εἰσπεσόντος τοῦ ὕδατος ἁμαξιαίους λίθους προσκομίσας ἀποικοδομεῖ, τοῦ δὲ πατρός, ὅτι τοῦτο παθόντος τοῦ χωρίου περιῳκοδόμησεν, ὡς ἀδικοῦντος ἐμοὶ βλάβης εἴληχε δίκην. καίτοι εἰ ὅσοι κακῶς πεπόνθασιν ὑπὸ τῶν ὑδάτων τῶν ταύτῃ ῥεόντων ἐμοὶ λήξονται δίκας, οὐδὲ πολλαπλάσια γενόμενα τὰ ὄντ’ ἐξαρκέσειεν ἄν μοι.", "st": "55.20"}, {"sp": "N", "t": "τοσοῦτον τοίνυν διαφέρουσιν οὗτοι τῶν ἄλλων, ὥστε πεπονθότες μὲν οὐδέν, ὡς αὐτίχ’ ὑμῖν ἐγὼ σαφῶς ἐπιδείξω, πολλῶν δὲ πολλὰ καὶ μεγάλα βεβλαμμένων, μόνοι δικάζεσθαι τετολμήκασιν οὗτοί μοι. καίτοι πᾶσι μᾶλλον ἐνεχώρει τοῦτο πράττειν. οὗτοι μὲν γάρ, εἰ καί τι πεπόνθασιν, αὐτοὶ δι’ αὑτοὺς βεβλαμμένοι συκοφαντοῦσιν· ἐκεῖνοι δέ, εἰ καὶ μηδὲν ἄλλο, τοιαύτην γ’ οὐδεμίαν αἰτίαν ἔχουσιν. ἀλλ’ ἵνα μὴ πάνθ’ ἅμα συνταράξας λέγω, λαβέ μοι τὰς τῶν γειτόνων μαρτυρίας.", "st": "55.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "55.21"}, {"sp": "N", "t": "οὔκουν δεινόν, ὦ ἄνδρες δικασταί, τούτους μὲν μηδὲν ἐγκαλεῖν μοι τοσαῦτα βεβλαμμένους, μηδ’ ἄλλον μηδένα τῶν ἠτυχηκότων, ἀλλὰ τὴν τύχην στέργειν, τουτονὶ δὲ συκοφαντεῖν; ὃν ὅτι μὲν αὐτὸς ἐξημάρτηκεν πρῶτον μὲν τὴν ὁδὸν στενοτέραν ποιήσας, ἐξαγαγὼν ἔξω τὴν αἱμασιάν, ἵνα τὰ δένδρα τῆς ὁδοῦ ποιήσειεν εἴσω, ἔπειτα δὲ τὸν χλῆδον ἐκβαλὼν εἰς τὴν ὁδόν, ἐξ ὧν ὑψηλοτέραν τὴν αὐτὴν καὶ στενοτέραν πεποιῆσθαι συμβέβηκεν, ἐκ τῶν μαρτυριῶν αὐτίκ’ εἴσεσθε σαφέστερον,", "st": "55.22"}, {"sp": "N", "t": "ὅτι δ’ οὐδὲν ἀπολωλεκὼς οὐδὲ καταβεβλαμμένος ἄξιον λόγου τηλικαύτην μοι δίκην εἴληχεν, τοῦθ’ ὑμᾶς ἤδη πειράσομαι διδάσκειν. τῆς γὰρ μητρὸς τῆς ἐμῆς χρωμένης τῇ τούτων μητρὶ πρὶν τούτους ἐπιχειρῆσαι με συκοφαντεῖν, καὶ πρὸς ἀλλήλας ἀφικνουμένων, οἷον εἰκὸς ἅμα μὲν ἀμφοτέρων οἰκουσῶν ἐν ἀγρῷ καὶ γειτνιωσῶν,", "st": "55.23"}, {"sp": "N", "t": "ἅμα δὲ τῶν ἀνδρῶν χρωμένων ἀλλήλοις ἕως ἔζων, ἐλθούσης δὲ τῆς ἐμῆς μητρὸς ὡς τὴν τούτων καὶ ἀποδυραμένης ἐκείνης τὰ συμβάντα καὶ δεικνυούσης, οὕτως ἐπυθόμεθα πάνθ’ ἡμεῖς, ὦ ἄνδρες δικασταί· καὶ λέγω μὲν ἅπερ ἤκουσα τῆς μητρός, οὕτω μοι πόλλ’ ἀγαθὰ γένοιτο, εἰ δὲ ψεύδομαι, τἀναντία τούτων· ἦ μὴν ὁρᾶν καὶ τῆς τούτων μητρὸς ἀκούειν ἔφη, κριθῶν μὲν βρεχθῆναι, καὶ ξηραινομένους ἰδεῖν αὑτήν, μηδὲ τρεῖς μεδίμνους, ἀλεύρων δ’ ὡς ἡμιμέδιμνον· ἐλαίου δ’ ἀποκλιθῆναι μὲν κεράμιον φάσκειν, οὐ μέντοι παθεῖν γ’ οὐδέν.", "st": "55.24"}, {"sp": "N", "t": "τοσαῦτ’, ὦ ἄνδρες δικασταί, τὰ συμβάντ’ ἦν τούτοις, ἀνθ’ ὧν ἐγὼ χιλίων δραχμῶν δίκην ἀτίμητον φεύγω. οὐ γὰρ δὴ τειχίον γ’ εἰ παλαιὸν ἐπῳκοδόμησεν, ἐμοὶ καὶ τοῦτο λογιστέον ἐστίν, ὃ μήτ’ ἔπεσεν μήτ’ ἄλλο δεινὸν μηδὲν ἔπαθεν. ὥστ’ εἰ συνεχώρουν αὐτοῖς ἁπάντων αἴτιος εἶναι τῶν συμβεβηκότων, τά γε βρεχθέντα ταῦτ’ ἦν.", "st": "55.25"}, {"sp": "N", "t": "ὁπότε δὲ μήτ’ ἐξ ἀρχῆς ὁ πατὴρ ἠδίκει τὸ χωρίον περιοικοδομῶν, μήθ’ οὗτοι πώποτ’ ἐνεκάλεσαν τοσούτου χρόνου διελθόντος, οἵ τ’ ἄλλοι πολλὰ καὶ δεινὰ πεπονθότες μηδὲν μᾶλλον ἐγκαλοῦσιν ἐμοί, πάντες θ’ ὑμεῖς τὸ ἐκ τῶν οἰκιῶν καὶ τὸ ἐκ τῶν χωρίων ὕδωρ εἰς τὴν ὁδὸν ἐξάγειν εἰώθατε, ἀλλ’ οὐ μὰ Δί’ εἴσω τὸ ἐκ τῆς ὁδοῦ δέχεσθαι, τί δεῖ πλείω λέγειν; οὐδὲ γὰρ ἐκ τούτων ἄδηλον ὅτι φανερῶς συκοφαντοῦμαι, οὔτ’ ἀδικῶν οὐδὲν οὔτε βεβλαμμένων ἅ φασιν.", "st": "55.26"}, {"sp": "N", "t": "ἵνα δ’ εἰδῆθ’ ὅτι καὶ τὸν χλῆδον εἰς τὴν ὁδὸν ἐκβεβλήκασιν, καὶ τὴν αἱμασιὰν προαγαγόντες στενοτέραν τὴν ὁδὸν πεποιήκασιν, ἔτι δ’ ὡς ὅρκον ἐδίδουν ἐγὼ τῇ τούτων μητρί, καὶ τὴν ἐμαυτοῦ τὸν αὐτὸν ὀμόσαι προὐκαλούμην, λαβέ μοι τάς τε μαρτυρίας καὶ τὴν πρόκλησιν.", "st": "55.27"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ. ΠΡΟΚΛΗΣΙΣ.", "st": "55.27"}, {"sp": "N", "t": "εἶτα τούτων ἀναισχυντότεροι γένοιντ’ ἂν ἄνθρωποι ἢ περιφανέστερον συκοφαντοῦντες, οἵτινες αὐτοὶ τὴν αἱμασιὰν προαγαγόντες καὶ τὴν ὁδὸν ἀνακεχωκότες ἑτέροις βλάβης δικάζονται, καὶ ταῦτα χιλίων δραχμῶν ἀτίμητον, οἵ γ’ οὐδὲ πεντήκοντα δραχμῶν τὸ παράπαν ἅπαντ’ ἀπολωλέκασιν; καίτοι σκοπεῖτ’, ὦ ἄνδρες δικασταί, πόσους ὑπὸ τῶν ὑδάτων ἐν τοῖς ἀγροῖς βεβλάφθαι συμβέβηκεν, τὰ μὲν Ἐλευσῖνι, τὰ δ’ ἐν τοῖς ἄλλοις τόποις. ἀλλ’ οὐ δήπου τούτων, ὦ γῆ καὶ θεοί, παρὰ τῶν γειτόνων ἕκαστος ἀξιώσει τὰς βλάβας κομίζεσθαι.", "st": "55.28"}, {"sp": "N", "t": "καὶ ἐγὼ μέν, ὃν προσῆκεν ἀγανακτεῖν τῆς ὁδοῦ στενοτέρας καὶ μετεωροτέρας γεγενημένης, ἡσυχίαν ἔχω· τούτοις δὲ τοσοῦτον περίεστιν ὡς ἔοικεν, ὥστε τοὺς ἠδικημένους πρὸς συκοφαντοῦσιν. καίτοι, ὦ Καλλίκλεις, εἰ καὶ ὑμῖν περιοικοδομεῖν ἔξεστιν τὸ ὑμέτερον αὐτῶν χωρίον, καὶ ἡμῖν δήπου τὸ ἡμέτερον ἐξῆν. εἰ δ’ ὁ πατὴρ ὁ ἐμὸς ἠδίκει περιοικοδομῶν ὑμᾶς, καὶ νῦν ὑμεῖς ἔμ’ ἀδικεῖτε περιοικοδομοῦντες οὕτως·", "st": "55.29"}, {"sp": "N", "t": "δῆλον γὰρ ὅτι μεγάλοις λίθοις ἀποικοδομηθέντος πάλιν τὸ ὕδωρ εἰς τὸ ἐμὸν ἥξει χωρίον, εἶθ’ ὅταν τύχῃ καταβαλεῖ τὴν αἱμασιὰν ἀπροσδοκήτως. ἀλλ’ οὐδὲν μᾶλλον ἐγκαλῶ τούτοις ἐγὼ διὰ τοῦτο, ἀλλὰ στέργω τὴν τύχην καὶ τἀμαυτοῦ φυλάττειν πειράσομαι. καὶ γὰρ τοῦτον φράττοντα μὲν τὰ ἑαυτοῦ σωφρονεῖν ἡγοῦμαι, δικαζόμενον δέ μοι πονηρότατόν τ’ εἶναι καὶ διεφθαρμένον ὑπὸ νόσου νομίζω.", "st": "55.30"}, {"sp": "N", "t": "μὴ θαυμάζετε δ’, ὦ ἄνδρες δικασταί, τὴν τούτου προθυμίαν, μηδ’ εἰ τὰ ψευδῆ κατηγορεῖν νῦν τετόλμηκεν. καὶ γὰρ τὸ πρότερον πείσας τὸν ἀνεψιὸν ἀμφισβητεῖν μοι τοῦ χωρίου, συνθήκας οὐ γενομένας ἀπήνεγκεν, καὶ νῦν αὐτὸς ἐρήμην μου καταδεδιῄτηται τοιαύτην ἑτέραν δίκην, Κάλλαρον ἐπιγραψάμενος τῶν ἐμῶν δούλων. πρὸς γὰρ τοῖς ἄλλοις κακοῖς καὶ τοῦθ’ ηὕρηνται σόφισμα· Καλλάρῳ τὴν αὐτὴν δίκην δικάζονται.", "st": "55.31"}, {"sp": "N", "t": "καίτοι τίς ἂν οἰκέτης τὸ τοῦ δεσπότου χωρίον περιοικοδομήσειεν μὴ προστάξαντος τοῦ δεσπότου; Καλλάρῳ δ’ ἕτερον ἐγκαλεῖν οὐδὲν ἔχοντες, ὑπὲρ ὧν ὁ πατὴρ πλέον ἢ πεντεκαίδεκ’ ἔτη φράξας ἐπεβίω δικάζονται. κἂν μὲν ἐγὼ τῶν χωρίων ἀποστῶ τούτοις ἀποδόμενος ἢ πρὸς ἕτερα χωρία ἀλλαξάμενος, οὐδὲν ἀδικεῖ Κάλλαρος· ἂν δ’ ἐγὼ μὴ βούλωμαι τἀμαυτοῦ τούτοις προέσθαι, πάντα τὰ δεινόταθ’ ὑπὸ Καλλάρου πάσχουσιν οὗτοι, καὶ ζητοῦσιν καὶ διαιτητὴν ὅστις αὐτοῖς τὰ χωρία προσκαταγνώσεται, καὶ διαλύσεις τοιαύτας ἐξ ὧν τὰ χωρί’ ἕξουσιν.", "st": "55.32"}, {"sp": "N", "t": "εἰ μὲν οὖν, ὦ ἄνδρες δικασταί, τοὺς ἐπιβουλεύοντας καὶ συκοφαντοῦντας δεῖ πλέον ἔχειν, οὐδὲν ἂν ὄφελος εἴη τῶν εἰρημένων· εἰ δ’ ὑμεῖς τοὺς μὲν τοιούτους μισεῖτε, τὰ δὲ δίκαια ψηφίζεσθε, μήτ’ ἀπολωλεκότος Καλλικλέους μηδὲν μήτ’ ἠδικημένου μήθ’ ὑπὸ Καλλάρου μήθ’ ὑπὸ τοῦ πατρός, οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν.", "st": "55.33"}, {"sp": "N", "t": "ἵνα δ’ εἰδῆθ’ ὅτι καὶ πρότερον ἐπιβουλεύων μου τοῖς χωρίοις τὸν ἀνεψιὸν κατεσκεύασεν, καὶ νῦν τὴν ἑτέραν αὐτὸς κατεδιῃτήσατο Καλλάρου ταύτην τὴν δίκην, ἐπηρεάζων ἐμοὶ διότι τὸν ἄνθρωπον περὶ πολλοῦ ποιοῦμαι, καὶ ⟨Καλλικράτης⟩ Καλλάρῳ πάλιν εἴληχεν ἑτέραν, ἁπάντων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "55.34"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "55.34"}, {"sp": "N", "t": "μὴ οὖν πρὸς Διὸς καὶ θεῶν, ὦ ἄνδρες δικασταί, προῆσθέ με τούτοις μηδὲν ἀδικοῦντα. οὐ γὰρ τῆς ζημίας τοσοῦτόν τί μοι μέλει, χαλεπὸν ὂν πᾶσι τοῖς μικρὰν οὐσίαν ἔχουσιν· ἀλλ’ ἐκβάλλουσιν ὅλως ἐκ τοῦ δήμου μ’ ἐλαύνοντες καὶ συκοφαντοῦντες. ὅτι δ’ οὐκ ἀδικοῦμεν οὐδέν, ἕτοιμοι μὲν ἦμεν ἐπιτρέπειν τοῖς εἰδόσιν, ⟨τοῖς⟩ ἴσοις καὶ κοινοῖς, ἕτοιμοι δ’ ὀμνύναι τὸν νόμιμον ὅρκον· ταῦτα γὰρ ᾠόμεθ’ ἰσχυρότατ’ ⟨ἂν⟩ παρασχέσθαι τοῖς αὐτοῖς ὑμῖν ὀμωμοκόσιν. καί μοι λαβὲ τήν τε πρόκλησιν καὶ τὰς ὑπολοίπους ἔτι μαρτυρίας.", "st": "55.35"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "55.35"}, {"sp": "HDR", "t": "Κατὰ Διονυσοδώρου βλάβης", "st": "56"}, {"sp": "N", "t": "κοινωνός εἰμι τοῦ δανείσματος τούτου, ἄνδρες δικασταί. συμβαίνει δ’ ἡμῖν τοῖς τὴν κατὰ θάλατταν ἐργασίαν προῃρημένοις καὶ τὰ ἡμέτερ’ αὐτῶν ἐγχειρίζουσιν ἑτέροις ἐκεῖνο μὲν σαφῶς εἰδέναι, ὅτι ὁ δανειζόμενος ἐν παντὶ προέχει ἡμῶν. λαβὼν γὰρ ἀργύριον φανερὸν καὶ ὁμολογούμενον, ἐν γραμματειδίῳ δυοῖν χαλκοῖν ἐωνημένῳ καὶ βυβλιδίῳ μικρῷ πάνυ τὴν ὁμολογίαν καταλέλοιπε τοῦ ποιήσειν τὰ δίκαια. ἡμεῖς δ’ οὐ φαμὲν δώσειν, ἀλλ’ εὐθὺς τῷ δανειζομένῳ δίδομεν τὸ ἀργύριον.", "st": "56.1"}, {"sp": "N", "t": "τῷ οὖν ποτὲ πιστεύοντες καὶ τί λαβόντες τὸ βέβαιον, προϊέμεθα; ὑμῖν, ὦ ἄνδρες δικασταί, καὶ τοῖς νόμοις τοῖς ὑμετέροις, οἳ κελεύουσιν, ὅσα ἄν τις ἑκὼν ἕτερος ἑτέρῳ ὁμολογήσῃ, κύρια εἶναι. ἀλλά μοι δοκεῖ οὔτε τῶν νόμων οὔτε συγγραφῆς οὐδεμιᾶς ὄφελος εἶναι οὐδέν, ἂν ὁ λαμβάνων τὰ χρήματα μὴ πάνυ δίκαιος ᾖ τὸν τρόπον, καὶ δυοῖν θάτερον, ἢ ὑμᾶς δεδιὼς ἢ τὸν συμβαλόντα αἰσχυνόμενος.", "st": "56.2"}, {"sp": "N", "t": "ὧν οὐδέτερον πρόσεστι Διονυσοδώρῳ τουτῳί, ἀλλ’ εἰς τοσοῦτον ἥκει τόλμης, ὥστε δανεισάμενος παρ’ ἡμῶν ἐπὶ τῇ νηὶ τρισχιλίας δραχμὰς ἐφ’ ᾧ τε τὴν ναῦν καταπλεῖν Ἀθήναζε, καὶ δέον ἡμᾶς ἐν τῇ πέρυσιν ὥρᾳ κεκομίσθαι τὰ χρήματα, τὴν μὲν ναῦν εἰς Ῥόδον κατεκόμισε καὶ τὸν γόμον ἐκεῖσε ἐξελόμενος ἀπέδοτο παρὰ τὴν συγγραφὴν καὶ τοὺς νόμους τοὺς ὑμετέρους, ἐκ δὲ τῆς Ῥόδου πάλιν ἀπέστειλε τὴν ναῦν εἰς Αἴγυπτον κἀκεῖθεν εἰς Ῥόδον, ἡμῖν δὲ τοῖς Ἀθήνησι δανείσασιν οὐδέπω καὶ νῦν οὔτε τὰ χρήματα ἀποδίδωσιν οὔτε τὸ ἐνέχυρον καθίστησιν εἰς τὸ ἐμφανές,", "st": "56.3"}, {"sp": "N", "t": "ἀλλὰ δεύτερον ἔτος τουτὶ καρπούμενος τὰ ἡμέτερα, καὶ ἔχων τό τε δάνειον καὶ τὴν ἐργασίαν καὶ τὴν ναῦν τὴν ὑποκειμένην ἡμῖν, οὐδὲν ἧττον εἰσελήλυθεν πρὸς ὑμᾶς, δῆλον ὡς ζημιώσων ἡμᾶς τῇ ἐπωβελίᾳ καὶ καταθησόμενος εἰς τὸ οἴκημα πρὸς τῷ ἀποστερεῖν τὰ χρήματα. ὑμῶν οὖν, ὦ ἄνδρες Ἀθηναῖοι, ὁμοίως ἁπάντων δεόμεθα καὶ ἱκετεύομεν βοηθῆσαι ἡμῖν, ἂν δοκῶμεν ἀδικεῖσθαι. τὴν δὲ ἀρχὴν τοῦ συμβολαίου διεξελθεῖν ὑμῖν πρῶτον βούλομαι· οὕτως γὰρ καὶ ὑμεῖς ῥᾷστα παρακολουθήσετε.", "st": "56.4"}, {"sp": "N", "t": "Διονυσόδωρος γὰρ οὑτοσί, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὁ κοινωνὸς αὐτοῦ Παρμενίσκος προσελθόντες ἡμῖν πέρυσιν τοῦ μεταγειτνιῶνος μηνὸς ἔλεγον ὅτι βούλονται δανείσασθαι ἐπὶ τῇ νηί, ἐφ’ ᾧ τε πλεῦσαι εἰς Αἴγυπτον καὶ ἐξ Αἰγύπτου εἰς Ῥόδον ἢ εἰς Ἀθήνας, διομολογησάμενοι τοὺς τόκους ⟨τοὺς⟩ εἰς ἑκάτερον τῶν ἐμπορίων τούτων.", "st": "56.5"}, {"sp": "N", "t": "ἀποκριναμένων δ’ ἡμῶν, ὦ ἄνδρες δικασταί, ὅτι οὐκ ἂν δανείσαιμεν εἰς ἕτερον ἐμπόριον οὐδὲν ἀλλ’ ἢ εἰς Ἀθήνας, οὕτω προσομολογοῦσι πλεύσεσθαι δεῦρο, καὶ ἐπὶ ταύταις ταῖς ὁμολογίαις δανείζονται παρ’ ἡμῶν ἐπὶ τῇ νηὶ τρισχιλίας δραχμὰς ἀμφοτερόπλουν, καὶ συγγραφὴν ἐγράψαντο ὑπὲρ τούτων. ἐν μὲν οὖν ταῖς συνθήκαις δανειστὴς ἐγράφη Πάμφιλος οὑτοσί· ἐγὼ δ’ ἔξωθεν μετεῖχον αὐτῷ τοῦ δανείσματος. καὶ πρῶτον ὑμῖν ἀναγνώσεται αὐτὴν τὴν συγγραφήν.", "st": "56.6"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ.", "st": "56.6"}, {"sp": "N", "t": "κατὰ ταύτην τὴν συγγραφήν, ὦ ἄνδρες δικασταί, λαβόντες παρ’ ἡμῶν τὰ χρήματα Διονυσόδωρός τε οὑτοσὶ καὶ ὁ κοινωνὸς αὐτοῦ Παρμενίσκος ἀπέστελλον τὴν ναῦν εἰς τὴν Αἴγυπτον ἐνθένδε. καὶ ὁ μὲν Παρμενίσκος ἐπέπλει ἐπὶ τῆς νεώς, οὑτοσὶ δὲ αὐτοῦ κατέμενεν. ἦσαν γάρ, ὦ ἄνδρες δικασταί, ἵνα μηδὲ τοῦτο ἀγνοῆτε, ὑπηρέται καὶ συνεργοὶ πάντες οὗτοι Κλεομένους τοῦ ἐν τῇ Αἰγύπτῳ ἄρξαντος, ὃς ἐξ οὗ τὴν ἀρχὴν παρέλαβεν οὐκ ὀλίγα κακὰ ἠργάσατο τὴν πόλιν τὴν ὑμετέραν, μᾶλλον δὲ καὶ τοὺς ἄλλους Ἕλληνας, παλιγκαπηλεύων καὶ συνιστὰς τὰς τιμὰς τοῦ σίτου καὶ αὐτὸς καὶ οὗτοι μετ’ αὐτοῦ.", "st": "56.7"}, {"sp": "N", "t": "οἱ μὲν γὰρ αὐτῶν ἀπέστελλον ἐκ τῆς Αἰγύπτου τὰ χρήματα, οἱ δ’ ἐπέπλεον ταῖς ἐμπορίαις, οἱ δ’ ἐνθάδε μένοντες διετίθεντο τὰ ἀποστελλόμενα· εἶτα πρὸς τὰς καθεστηκυίας τιμὰς ἔπεμπον γράμματα οἱ ἐπιδημοῦντες τοῖς ἀποδημοῦσιν, ἵνα ἐὰν μὲν παρ’ ὑμῖν τίμιος ᾖ ὁ σῖτος, δεῦρο αὐτὸν κομίσωσιν, ἐὰν δ’ εὐωνότερος γένηται, εἰς ἄλλο τι καταπλεύσωσιν ἐμπόριον. ὅθεν περ οὐχ ἥκιστα, ὦ ἄνδρες δικασταί, συνετιμήθη τὰ περὶ τὸν σῖτον ἐκ τῶν τοιούτων ἐπιστολῶν καὶ συνεργιῶν.", "st": "56.8"}, {"sp": "N", "t": "ὅτε μὲν οὖν ἐνθένδε ἀπέστελλον οὗτοι τὴν ναῦν, ἐπιεικῶς ἔντιμον κατέλιπον τὸν σῖτον· διὸ καὶ ὑπέμειναν ἐν τῇ συγγραφῇ γράψασθαι εἰς Ἀθήνας πλεῖν, εἰς δ’ ἄλλο μηδὲν ἐμπόριον. μετὰ δὲ ταῦτα, ὦ ἄνδρες δικασταί, ἐπειδὴ ὁ Σικελικὸς κατάπλους ἐγένετο καὶ αἱ τιμαὶ τοῦ σίτου ἐπ’ ἔλαττον ἐβάδιζον καὶ ἡ ναῦς ἡ τούτων ἀνῆκτο εἰς Αἴγυπτον, εὐθέως οὗτος ἀποστέλλει τινὰ εἰς τὴν Ῥόδον ἀπαγγελοῦντα τῷ Παρμενίσκῳ τῷ κοινωνῷ τὰ ἐνθένδε καθεστηκότα, ἀκριβῶς εἰδὼς ὅτι ἀναγκαῖον εἴη τῇ νηὶ προσσχεῖν εἰς Ῥόδον.", "st": "56.9"}, {"sp": "N", "t": "πέρας δ’ οὖν, λαβὼν γὰρ ὁ Παρμενίσκος ὁ τουτουὶ κοινωνὸς τὰ γράμματα τὰ παρὰ τούτου ἀποσταλέντα, καὶ πυθόμενος τὰς τιμὰς τὰς ἐνθάδε [τοῦ σίτου] καθεστηκυίας, ἐξαιρεῖται τὸν σῖτον ἐν τῇ Ῥόδῳ κἀκεῖ ἀποδίδοται, καταφρονήσαντες μὲν τῆς συγγραφῆς, ὦ ἄνδρες δικασταί, καὶ τῶν ἐπιτιμίων, ἃ συνεγράψαντο αὐτοὶ οὗτοι καθ’ αὑτῶν, ἐάν τι παραβαίνωσιν, καταφρονήσαντες δὲ τῶν νόμων τῶν ὑμετέρων, οἳ κελεύουσι τοὺς ναυκλήρους καὶ τοὺς ἐπιβάτας πλεῖν εἰς ὅ τι ἂν συνθῶνται ἐμπόριον, εἰ δὲ μή, ταῖς μεγίσταις ζημίαις εἶναι ἐνόχους.", "st": "56.10"}, {"sp": "N", "t": "καὶ ἡμεῖς ἐπειδὴ τάχιστα ἐπυθόμεθα τὸ γεγονός, ἐκπεπληγμένοι τῷ πράγματι προσῇμεν τούτῳ τῷ ἀρχιτέκτονι τῆς ὅλης ἐπιβουλῆς, ἀγανακτοῦντες, οἷον εἰκός, καὶ ἐγκαλοῦντες ὅτι διαρρήδην ἡμῶν διορισαμένων ἐν ταῖς συνθήκαις ὅπως ἡ ναῦς μηδαμόσε καταπλεύσεται ἀλλ’ ἢ εἰς Ἀθήνας, καὶ ἐπὶ ταύταις ταῖς ὁμολογίαις δανεισάντων τὸ ἀργύριον, ἡμᾶς μὲν ἐν ὑποψίᾳ καταλέλοιπεν τοῖς βουλομένοις αἰτιᾶσθαι καὶ λέγειν, ὡς ἄρα καὶ ἡμεῖς κεκοινωνήκαμεν τῆς σιτηγίας τῆς εἰς τὴν Ῥόδον, αὐτοὶ δὲ οὐδὲν μᾶλλον τὴν ναῦν ἥκουσι κατακομίζοντες εἰς τὸ ὑμέτερον ἐμπόριον εἰς ὃ συνεγράψαντο.", "st": "56.11"}, {"sp": "N", "t": "ἐπειδὴ δὲ οὐδὲν ἐπεραίνομεν ὑπὲρ τῆς συγγραφῆς καὶ τῶν δικαίων διαλεγόμενοι, ἀλλὰ τό γε δάνειον καὶ τοὺς τόκους ἠξιοῦμεν ἀπολαβεῖν τοὺς ἐξ ἀρχῆς ὁμολογηθέντας. οὗτος δὲ οὕτως ὑβριστικῶς ἐχρήσατο ἡμῖν, ὥστε τοὺς μὲν τόκους τοὺς ἐν τῇ συγγραφῇ γεγραμμένους οὐκ ἔφη δώσειν· “εἰ δὲ βούλεσθε,” ἔφη, “κομίζεσθαι τὸ πρὸς μέρος τοῦ πλοῦ τοῦ πεπλευσμένου, δώσω ὑμῖν” φησὶν “τοὺς εἰς Ῥόδον τόκους· πλείους δ’ οὐκ ἂν δοίην”, αὐτὸς ἑαυτῷ νομοθετῶν καὶ οὐχὶ τοῖς ἐκ τῆς συγγραφῆς δικαίοις πειθόμενος.", "st": "56.12"}, {"sp": "N", "t": "ὡς δ’ ἡμεῖς οὐκ ἂν ἔφαμεν συγχωρῆσαι οὐδὲν τούτων, λογιζόμενοι ὅτι, ὁπότε τοῦτο πράξομεν, ὁμολογοῦμεν καὶ αὐτοὶ εἰς Ῥόδον σεσιτηγηκέναι, ἔτι μᾶλλον ἐπέτεινεν οὗτος καὶ μάρτυρας πολλοὺς παραλαβὼν προσῄει, φάσκων ἕτοιμος εἶναι ἀποδιδόναι τὸ δάνειον καὶ τοὺς τόκους τοὺς εἰς Ῥόδον, οὐδὲν μᾶλλον, ὦ ἄνδρες δικασταί, ἀποδοῦναι διανοούμενος, ἀλλ’ ἡμᾶς ὑπολαμβάνων οὐκ ἂν ἐθελῆσαι λαβεῖν τὸ ἀργύριον διὰ τὰς ὑπούσας αἰτίας. ἐδήλωσε δὲ αὐτὸ τὸ ἔργον.", "st": "56.13"}, {"sp": "N", "t": "ἐπειδὴ γάρ, ὦ ἄνδρες Ἀθηναῖοι, τῶν ὑμετέρων πολιτῶν τινὲς παραγενόμενοι ἀπὸ ταὐτομάτου συνεβούλευον ἡμῖν τὸ μὲν διδόμενον λαμβάνειν, περὶ δὲ τῶν ἀντιλεγομένων κρίνεσθαι, τοὺς δὲ εἰς Ῥόδον τόκους μὴ καθομολογεῖν τέως ἂν κριθῶμεν, ἡμεῖς μὲν ταῦτα συνεχωροῦμεν, οὐκ ἀγνοοῦντες, ὦ ἄνδρες δικασταί, τὸ ἐκ τῆς συγγραφῆς δίκαιον, ἀλλ’ ἡγούμενοι δεῖν ἐλαττοῦσθαί τι καὶ συγχωρεῖν ὥστε μὴ δοκεῖν φιλόδικοι εἶναι, οὗτος δ’ ὡς ἑώρα ἡμᾶς ὁμόσε πορευομένους, “ἀναιρεῖσθε” φησὶ “τοίνυν τὴν συγγραφήν.”", "st": "56.14"}, {"sp": "N", "t": "“ἡμεῖς ἀναιρώμεθα; οὐδέν γε μᾶλλον ἢ ὁτιοῦν· ἀλλὰ κατὰ μὲν τἀργύριον ὃ ἂν ἀποδῷς, ὁμολογήσομεν ἐναντίον τοῦ τραπεζίτου ἄκυρον ποιεῖν τὴν συγγραφήν, τὸ μέντοι σύνολον οὐκ ἂν ἀνελοίμεθα, ἕως ἂν περὶ τῶν ἀντιλεγομένων κριθῶμεν. τί γὰρ ἔχοντες δίκαιον ἢ τί τὸ ἰσχυρὸν ἀντιδικήσομεν, ἐάν τε πρὸς διαιτητὴν ἐάν τε εἰς δικαστήριον δέῃ βαδίζειν, ἀνελόμενοι τὴν συγγραφήν, ἐν ᾗ τὴν ὑπὲρ τῶν δικαίων βοήθειαν ἔχομεν”;", "st": "56.15"}, {"sp": "N", "t": "ταῦτα δὲ ἡμῶν λεγόντων, ὦ ἄνδρες δικασταί, καὶ ἀξιούντων Διονυσόδωρον τουτονὶ τὴν μὲν συγγραφὴν μὴ κινεῖν μηδὲ ἄκυρον ποιεῖν τὴν ὁμολογουμένην καὶ ὑπ’ αὐτῶν τούτων κυρίαν εἶναι, τῶν δὲ χρημάτων ὅσα μὲν αὐτὸς ὁμολογεῖ, ἀποδοῦναι ἡμῖν, περὶ δὲ τῶν ἀντιλεγομένων [ὡς] ἑτοίμων ὄντων κριθῆναι, εἴτε βούλοιντο ἐφ’ ἑνὸς εἴτε κἀν πλείοσι τῶν ἐκ τοῦ ἐμπορίου, οὐκ ἔφη προσέχειν Διονυσόδωρος τούτων οὐδενί, ἀλλ’ ὅτι τὴν συγγραφὴν ὅλως οὐκ ἀνῃρούμεθα ἀπολαμβάνοντες ἃ οὗτος ἐπέταττεν, ἔχει δεύτερον ἔτος τὰ ἡμέτερα καὶ χρῆται τοῖς χρήμασιν·", "st": "56.16"}, {"sp": "N", "t": "καὶ ὃ πάντων ἐστὶ δεινότατον, ὦ ἄνδρες δικασταί, ὅτι αὐτὸς μὲν οὗτος παρ’ ἑτέρων εἰσπράττει ναυτικοὺς τόκους ἀπὸ τῶν ἡμετέρων χρημάτων, οὐκ Ἀθήνησι δανείσας οὐδ’ εἰς Ἀθήνας, ἀλλ’ εἰς Ῥόδον καὶ Αἴγυπτον, ἡμῖν δὲ τοῖς δανείσασιν εἰς τὸ ὑμέτερον ἐμπόριον οὐκ οἴεται δεῖν τῶν δικαίων οὐδὲν ποιεῖν. ὅτι δ’ ἀληθῆ λέγω, ἀναγνώσεται ὑμῖν τὴν πρόκλησιν ἣν ὑπὲρ τούτων προὐκαλεσάμεθ’ αὐτόν.", "st": "56.17"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "56.17"}, {"sp": "N", "t": "ταῦτα τοίνυν, ὦ ἄνδρες δικασταί, προκαλεσαμένων ἡμῶν Διονυσόδωρον τουτονὶ πολλάκις, καὶ ἐπὶ πολλὰς ἡμέρας ἐκτιθέντων τὴν πρόκλησιν, εὐήθεις ἔφη παντελῶς ἡμᾶς εἶναι, εἰ ὑπολαμβάνομεν αὐτὸν οὕτως ἀλογίστως ἔχειν ὥστ’ ἐπὶ διαιτητὴν βαδίζειν, προδήλου ὄντος ὅτι καταγνώσεται αὐτοῦ ἀποτεῖσαι τὰ χρήματα, ἐξὸν αὐτῷ ἐπὶ τὸ δικαστήριον ἥκειν φέροντα τὸ ἀργύριον, εἶτ’ ἐὰν μὲν δύνηται ὑμᾶς παρακρούσασθαι, ἀπιέναι τἀλλότρια ἔχοντα, εἰ δὲ μή, τηνικαῦτα καταθεῖναι τὰ χρήματα, ὡς ⟨ἂν⟩ ἄνθρωπος οὐ τῷ δικαίῳ πιστεύων, ἀλλὰ διάπειραν ὑμῶν λαμβάνειν βουλόμενος.", "st": "56.18"}, {"sp": "N", "t": "τὰ μὲν τοίνυν πεπραγμένα Διονυσοδώρῳ ἀκηκόατε, ὦ ἄνδρες δικασταί· οἴομαι δ’ ὑμᾶς θαυμάζειν ἀκούοντας πάλαι τὴν τόλμαν αὐτοῦ, καὶ τῷ ποτε πιστεύων εἰσελήλυθεν δευρί. πῶς γὰρ οὐ τολμηρόν, εἴ τις ἄνθρωπος δανεισάμενος χρήματα ἐκ τοῦ ἐμπορίου τοῦ Ἀθηναίων,", "st": "56.19"}, {"sp": "N", "t": "καὶ συγγραφὴν διαρρήδην γραψάμενος ἐφ’ ᾧ τε καταπλεῖν τὴν ναῦν εἰς τὸ ὑμέτερον ἐμπόριον, εἰ δὲ μή, ἀποτίνειν διπλάσια τὰ χρήματα, μήτε τὴν ναῦν κατακεκόμικεν εἰς τὸν Πειραιᾶ μήτε τὰ χρήματα ἀποδίδωσι τοῖς δανείσασιν, τόν τε σῖτον ἐξελόμενος ἐν Ῥόδῳ ἀπέδοτο, καὶ ταῦτα διαπεπραγμένος μηδὲν ἧττον τολμᾷ βλέπειν εἰς τὰ ὑμέτερα πρόσωπα;", "st": "56.20"}, {"sp": "N", "t": "ἃ δὴ λέγει πρὸς ταῦτα ἀκούσατε. φησὶ γὰρ τὴν ναῦν πλέουσαν ἐξ Αἰγύπτου ῥαγῆναι, καὶ διὰ ταῦτα ἀναγκασθῆναι καὶ προσσχεῖν εἰς τὴν Ῥόδον κἀκεῖ ἐξελέσθαι τὸν σῖτον. καὶ τούτου τεκμήριον λέγει, ὡς ἄρα ἐκ τῆς Ῥόδου μισθώσαιτο πλοῖα καὶ δεῦρο ἀποστείλειε τῶν χρημάτων ἔνια. ἓν μὲν τοῦτό ἐστιν αὐτῷ μέρος τῆς ἀπολογίας, δεύτερον δ’ ἐκεῖνο·", "st": "56.21"}, {"sp": "N", "t": "φησὶ γὰρ ἑτέρους τινὰς δανειστὰς συγκεχωρηκέναι αὑτῷ τοὺς τόκους τοὺς εἰς Ῥόδον· δεινὸν οὖν, εἰ ἡμεῖς μὴ συγχωρήσομεν ταὐτὰ ἐκείνοις. τρίτον πρὸς τούτοις τὴν συγγραφὴν κελεύειν φησὶν αὑτὸν σωθείσης τῆς νεὼς ἀποδοῦναι τὰ χρήματα, τὴν δὲ ναῦν οὐ σεσῷσθαι εἰς τὸν Πειραιᾶ. πρὸς ἕκαστον δὴ τούτων, ὦ ἄνδρες δικασταί, ἀκούσατε ἃ λέγομεν δίκαια.", "st": "56.22"}, {"sp": "N", "t": "πρῶτον μὲν τὸ ῥαγῆναι τὴν ναῦν ὅταν λέγῃ, οἶμαι πᾶσιν ὑμῖν φανερὸν εἶναι ὅτι ψεύδεται. εἰ γὰρ τοῦτο συνέβη παθεῖν τῇ νηί, οὔτ’ ἂν εἰς τὴν Ῥόδον ἐσώθη οὔτ’ ἂν ὕστερον πλόϊμος ἦν. νῦν δὲ φαίνεται εἰς τὴν Ῥόδον σωθεῖσα καὶ πάλιν ἐκεῖθεν ἀποσταλεῖσα εἰς Αἴγυπτον καὶ ἔτι καὶ νῦν πλέουσα πανταχόσε, πλὴν οὐκ εἰς Ἀθήνας. καίτοι πῶς οὐκ ἄτοπον, ὅταν μὲν εἰς τὸ Ἀθηναίων ἐμπόριον δεήσῃ κατάγειν τὴν ναῦν, ῥαγῆναι φάσκειν, ὅταν δὲ εἰς τὴν Ῥόδον τὸν σῖτον ἐξελέσθαι, τηνικαῦτα δὲ πλόϊμον οὖσαν φαίνεσθαι τὴν αὐτὴν ναῦν;", "st": "56.23"}, {"sp": "N", "t": "διὰ τί οὖν, φησίν, ἐμισθωσάμην ἕτερα πλοῖα καὶ μετεξειλόμην τὸν γόμον καὶ δεῦρ’ ἀπέστειλα; ὅτι, ὦ ἄνδρες Ἀθηναῖοι, οὐ τῶν ἁπάντων ἀγωγίμων οὔθ’ οὗτος ἦν κύριος οὔθ’ ὁ κοινωνὸς αὐτοῦ, ἀλλ’ οἱ ἐπιβάται τὰ ἑαυτῶν χρήματα ἀπέστελλον οἶμαι δεῦρο ἐν ἑτέροις πλοίοις ἐξ ἀνάγκης, ἐπειδὴ προκατέλυσαν οὗτοι τὸν πλοῦν· ὧν μέντοι αὐτοὶ ἦσαν κύριοι, οὐδὲ ταῦτα ἀπέστελλον πάντα δεῦρο, ἀλλ’ ἐκλεγόμενοι τίνων αἱ τιμαὶ ἐπετέταντο.", "st": "56.24"}, {"sp": "N", "t": "ἐπεὶ τί δήποτε μισθούμενοι ἕτερα πλοῖα, ὥς φατε, οὐχ ἅπαντα τὸν γόμον τῆς νεὼς μετενέθεσθε, ἀλλὰ τὸν σῖτον αὐτοῦ ἐν τῇ Ῥόδῳ κατελίπετε; ὅτι, ὦ ἄνδρες δικασταί, τοῦτον μὲν συνέφερεν αὐτοῖς ἐκεῖσε πωλεῖν (τὰς γὰρ τιμὰς τὰς ἐνθάδε ἀνεικέναι ἤκουον)· τὰ δ’ ἄλλ’ ἀγώγιμα ὡς ὑμᾶς ἀπέστελλον, ἀφ’ ὧν κερδανεῖν ἤλπιζον. ὥστε τὴν μίσθωσιν τῶν πλοίων ὅταν λέγῃς, οὐ τοῦ ῥαγῆναι τὴν ναῦν τεκμήριον λέγεις, ἀλλὰ τοῦ συμφέροντος ὑμῖν.", "st": "56.25"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων ἱκανά μοι τὰ εἰρημένα· περὶ δὲ τῶν δανειστῶν, οὕς φασι συγκεχωρηκέναι λαβεῖν παρ’ αὑτῶν τοὺς εἰς Ῥόδον τόκους, ἔστι μὲν οὐδὲν πρὸς ἡμᾶς τοῦτο. εἰ γάρ τις ὑμῖν ἀφῆκέν τι τῶν αὑτοῦ, οὐδὲν ἀδικεῖται οὔθ’ ὁ δοὺς οὔθ’ ὁ πείσας· ἀλλ’ ἡμεῖς οὔτ’ ἀφείκαμέν σοι οὐδὲν οὔτε συγκεχωρήκαμεν τῷ πλῷ τῷ εἰς Ῥόδον, οὐδ’ ἐστὶν ἡμῖν οὐδὲν κυριώτερον τῆς συγγραφῆς.", "st": "56.26"}, {"sp": "N", "t": "αὕτη δὲ τί λέγει καὶ ποῖ προστάττει τὸν πλοῦν ποιεῖσθαι; Ἀθήνηθεν εἰς Αἴγυπτον καὶ ἐξ Αἰγύπτου εἰς Ἀθήνας· εἰ δὲ μή, ἀποτίνειν κελεύει διπλάσια τὰ χρήματα. ταῦτα εἰ μὲν πεποίηκας, οὐδὲν ἀδικεῖς, εἰ δὲ μὴ πεποίηκας μηδὲ κατακεκόμικας τὴν ναῦν Ἀθήναζε, προσήκει σε ζημιοῦσθαι τῷ ἐπιτιμίῳ τῷ ἐκ τῆς συγγραφῆς· τοῦτο γὰρ τὸ δίκαιον οὐκ ἄλλος οὐδείς, ἀλλ’ αὐτὸς σὺ σαυτῷ ὥρισας. δεῖξον οὖν τοῖς δικασταῖς δυοῖν θάτερον, ἢ τὴν συγγραφήν, ὡς οὐκ ἔστιν ἡμῖν κυρία, ἢ ὡς οὐ δίκαιος εἶ πάντα κατὰ ταύτην πράττειν.", "st": "56.27"}, {"sp": "N", "t": "εἰ δέ τινες ἀφείκασίν τί σοι καὶ συγκεχωρήκασιν τοὺς εἰς Ῥόδον τόκους ὁτῳδήποτε τρόπῳ πεισθέντες, διὰ ταῦτα οὐδὲν ἀδικεῖς ἡμᾶς, οὓς παρασυγγεγράφηκας εἰς Ῥόδον καταγαγὼν τὴν ναῦν; οὐκ οἴομαί γε· οὐ γὰρ τὰ ὑφ’ ἑτέρων συγκεχωρημένα δικάζουσιν οὗτοι νῦν, ἀλλὰ τὰ ὑπ’ αὐτοῦ σοῦ πρὸς ἡμᾶς συγγεγραμμένα. ἐπεὶ ὅτι γε καὶ τὸ περὶ τὴν ἄφεσιν τῶν τόκων, εἰ ἄρα γέγονεν ὡς οὗτοι λέγουσιν, μετὰ τοῦ συμφέροντος τοῦ τῶν δανειστῶν γέγονε, πᾶσιν ὑμῖν φανερόν ἐστιν.", "st": "56.28"}, {"sp": "N", "t": "οἱ γὰρ ἐκ τῆς Αἰγύπτου δανείσαντες τούτοις ἑτερόπλουν τἀργύριον εἰς Ἀθήνας, ὡς ἀφίκοντο εἰς τὴν Ῥόδον καὶ τὴν ναῦν ἐκεῖσε οὗτοι κατεκόμισαν, οὐδὲν οἶμαι διέφερεν αὐτοῖς ἀφεμένοις τῶν τόκων καὶ κομισαμένοις τὸ δάνειον ἐν τῇ Ῥόδῳ πάλιν ἐνεργὸν ποιεῖν εἰς τὴν Αἴγυπτον, ἀλλ’ ἐλυσιτέλει πολλῷ μᾶλλον τοῦτ’ ἢ δεῦρ’ ἐπαναπλεῖν.", "st": "56.29"}, {"sp": "N", "t": "ἐκεῖσε μέν γε ἀεὶ ὡραῖος ὁ πλοῦς, καὶ δὶς ἢ τρὶς ὑπῆρχεν αὐτοῖς ἐργάσασθαι τῷ αὐτῷ ἀργυρίῳ· ἐνταῦθα δ’ ἐπιδημήσαντας παραχειμάζειν ἔδει καὶ περιμένειν τὴν ὡραίαν. ὥστ’ ἐκεῖνοι μὲν οἱ δανεισταὶ προσκεκερδήκασιν καὶ οὐκ ἀφείκασι τούτοις οὐδέν· ἡμῖν δ’ οὐχ ὅπως περὶ τοῦ τόκου ὁ λόγος ἐστίν, ἀλλ’ οὐδὲ τἀρχαῖα ἀπολαβεῖν δυνάμεθα.", "st": "56.30"}, {"sp": "N", "t": "μὴ οὖν ἀποδέχεσθε τούτου φενακίζοντος ὑμᾶς καὶ τὰ πρὸς τοὺς ἄλλους δανειστὰς πεπραγμένα παραβάλλοντος, ἀλλ’ ἐπὶ τὴν συγγραφὴν ἀνάγετ’ αὐτὸν καὶ τὰ ἐκ τῆς συγγραφῆς δίκαια. ἔστι γὰρ ἐμοί τε λοιπὸν διδάξαι ὑμᾶς τοῦτο, καὶ οὗτος ἰσχυρίζεται τῷ αὐτῷ τούτῳ, φάσκων τὴν συγγραφὴν κελεύειν σωθείσης τῆς νεὼς ἀποδιδόναι τὸ δάνειον.", "st": "56.31"}, {"sp": "N", "t": "καὶ ἡμεῖς ταῦτα οὕτω φαμὲν δεῖν ἔχειν. ἡδέως δ’ ἂν πυθοίμην αὐτοῦ σοῦ, πότερον ὡς ὑπὲρ διεφθαρμένης τῆς νεὼς διαλέγει, ἢ ὡς ὑπὲρ σεσῳσμένης. εἰ μὲν γὰρ διέφθαρται ἡ ναῦς καὶ ἀπόλωλεν, τί περὶ τῶν τόκων διαφέρει καὶ ἀξιοῖς ἡμᾶς κομίζεσθαι τοὺς εἰς Ῥόδον τόκους; οὔτε γὰρ τοὺς τόκους οὔτε τἀρχαῖα προσήκει ἡμᾶς ἀπολαβεῖν. εἰ δ’ ἐστὶν ἡ ναῦς σῶς καὶ μὴ διέφθαρται, διὰ τί ἡμῖν οὐκ ἀποδίδως τὰ χρήματα ἃ συνεγράψω;", "st": "56.32"}, {"sp": "N", "t": "πόθεν οὖν ἀκριβέστατα ἂν μάθοιτε, ἄνδρες Ἀθηναῖοι, ὅτι σέσῳσται ἡ ναῦς; μάλιστα μὲν ἐξ αὐτοῦ τοῦ εἶναι τὴν ναῦν ἐν πλῷ, οὐχ ἧττον δὲ καὶ ἐξ ὧν αὐτοὶ οὗτοι λέγουσιν. ἀξιοῦσιν γὰρ ἡμᾶς τά τε ἀρχαῖα ἀπολαβεῖν καὶ μέρος τι τῶν τόκων, ὡς σεσῳσμένης μὲν τῆς νεώς, οὐ πεπλευκυίας δὲ πάντα τὸν πλοῦν.", "st": "56.33"}, {"sp": "N", "t": "σκοπεῖτε δέ, ὦ ἄνδρες Ἀθηναῖοι, πότερον ἡμεῖς τοῖς ἐκ τῆς συγγραφῆς δικαίοις χρώμεθα ἢ οὗτοι, οἳ οὔτε εἰς τὸ συγκείμενον ἐμπόριον πεπλεύκασιν, ἀλλ’ εἰς Ῥόδον καὶ Αἴγυπτον, σωθείσης τε τῆς νεὼς καὶ οὐ διεφθαρμένης ἄφεσιν οἴονται δεῖν εὑρίσκεσθαι τῶν τόκων παρασυγγεγραφηκότες, καὶ αὐτοὶ μὲν πολλὰ χρήματα εἰργασμένοι παρὰ τὴν σιτηγίαν τὴν εἰς Ῥόδον, τὰ δ’ ἡμέτερα χρήματα ἔχοντες καὶ καρπούμενοι δεύτερον ἔτος τουτί.", "st": "56.34"}, {"sp": "N", "t": "καινότατον δ’ ἐστὶ πάντων τὸ γιγνόμενον· τὸ μὲν γὰρ δάνειον τὸ ἀρχαῖον ἀποδιδόασιν ἡμῖν ὡς σεσῳσμένης τῆς νεώς, τοὺς τόκους δ’ ἀποστερῆσαι οἴονται δεῖν ὡς διεφθαρμένης. καίτοι ἡ συγγραφὴ οὐχ ἕτερα μὲν λέγει περὶ τῶν τόκων, ἕτερα δὲ περὶ τοῦ ἀρχαίου δανείσματος;", "st": "56.35"}, {"sp": "N", "t": "ἀλλὰ τὰ δίκαια ταὐτὰ περὶ ἀμφοῖν ἐστιν καὶ ἡ πρᾶξις ἡ αὐτή. ἀνάγνωθι δέ μοι πάλιν τὴν συγγραφήν.", "st": "56.36"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ", "st": "56.36"}, {"sp": "N", "t": "… Ἀθήνηθεν εἰς Αἴγυπτον καὶ ἐξ Αἰγύπτου Ἀθήναζε.", "st": "56.36"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες Ἀθηναῖοι· “Ἀθήνηθεν,” φησίν, “εἰς Αἴγυπτον καὶ ἐξ Αἰγύπτου Ἀθήναζε.” λέγε τὰ λοιπά.", "st": "56.36"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ", "st": "56.36"}, {"sp": "N", "t": "σωθείσης δὲ τῆς νεὼς εἰς Πειραιᾶ …", "st": "56.36"}, {"sp": "N", "t": "ἄνδρες Ἀθηναῖοι, πάνυ ἁπλοῦν ἐστιν διαγνῶναι ὑμῖν ὑπὲρ ταύτης τῆς δίκης, καὶ οὐδὲν δεῖ λόγων πολλῶν. ἡ ναῦς ὅτι μὲν σέσῳσται καὶ ἔστιν σῶς, καὶ παρ’ αὐτῶν τούτων ὁμολογεῖται (οὐ γὰρ ἂν ἀπεδίδοσαν τό τε ἀρχαῖον δάνειον καὶ τῶν τόκων μέρος τι), οὐ κατακεκόμισται δ’ εἰς τὸν Πειραιᾶ. διὰ τοῦτο ἡμεῖς μὲν οἱ δανείσαντες ἀδικεῖσθαί φαμεν, καὶ ὑπὲρ τούτου δικαζόμεθα, ὅτι οὐ κατέπλευσεν εἰς τὸ συγκείμενον ἐμπόριον.", "st": "56.37"}, {"sp": "N", "t": "Διονυσόδωρος δὲ οὔ φησιν ἀδικεῖν δι’ αὐτὸ τοῦτο· οὐ γὰρ δεῖν αὑτὸν ἀποδοῦναι πάντας τοὺς τόκους, ἐπειδὴ ἡ ναῦς οὐ κατέπλευσεν εἰς τὸν Πειραιᾶ. ἡ δὲ συγγραφὴ τί λέγει; οὐ μὰ Δί’ οὐ ταῦτα ἃ σὺ λέγεις, ὦ Διονυσόδωρε· ἀλλ’ ἐὰν μὴ ἀποδῷς τὸ δάνειον καὶ τοὺς τόκους ἢ μὴ παράσχῃς τὰ ὑποκείμενα ἐμφανῆ καὶ ἀνέπαφα, ἢ ἄλλο τι παρὰ τὴν συγγραφὴν ποιήσῃς, ἀποτίνειν κελεύει σε διπλάσια τὰ χρήματα. καί μοι λέγε αὐτὸ τοῦτο τῆς συγγραφῆς.", "st": "56.38"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ.", "st": "56.38"}, {"sp": "N", "t": "ἐὰν δὲ … μὴ παράσχωσι τὰ ὑποκείμενα ἐμφανῆ καὶ ἀνέπαφα, ἢ ποιήσωσίν τι παρὰ τὴν συγγραφήν, ἀποδιδότωσαν διπλάσια τὰ χρήματα.", "st": "56.38"}, {"sp": "N", "t": "ἔστιν οὖν ὅποι παρέσχηκας ἐμφανῆ τὴν ναῦν, ἀφ’ οὗ τὰ χρήματα ἔλαβες παρ’ ἡμῶν, ὁμολογῶν σῶν εἶναι αὐτός; ἢ καταπέπλευκας ἐξ ἐκείνου τοῦ χρόνου εἰς τὸ Ἀθηναίων ἐμπόριον, τῆς συγγραφῆς διαρρήδην λεγούσης εἰς τὸν Πειραιᾶ κατάγειν τὴν ναῦν καὶ ἐμφανῆ παρέχειν τοῖς δανείσασιν;", "st": "56.39"}, {"sp": "N", "t": "καὶ γὰρ τοῦτο, ἄνδρες Ἀθηναῖοι. θεάσασθε τὴν ὑπερβολήν. ἐρράγη ἡ ναῦς, ὥς φησιν οὗτος, καὶ διὰ τοῦτ’ εἰς Ῥόδον κατήγαγεν αὐτήν. οὐκοῦν τὸ μετὰ τοῦτο ἐπεσκευάσθη καὶ πλόϊμος ἐγένετο. διὰ τί οὖν, ὦ βέλτιστε, εἰς μὲν τὴν Αἴγυπτον καὶ τἄλλα ἐμπόρια ἀπέστελλες αὐτήν, Ἀθήναζε δὲ οὐκ ἀπέσταλκας οὐδέπω καὶ νῦν πρὸς ἡμᾶς τοὺς δανείσαντας, οἷς ἡ συγγραφὴ κελεύει σε ἐμφανῆ καὶ ἀνέπαφον τὴν ναῦν παρέχειν, καὶ ταῦτ’ ἀξιούντων ἡμῶν καὶ προκαλεσαμένων σε πολλάκις;", "st": "56.40"}, {"sp": "N", "t": "ἀλλ’ οὕτως ἀνδρεῖος εἶ, μᾶλλον δὲ ἀναίσχυντος, ὥστ’ ἐκ τῆς συγγραφῆς ὀφείλων ἡμῖν διπλάσια τὰ χρήματα, οὐκ οἴει δεῖν οὐδὲ τοὺς τόκους τοὺς γιγνομένους ἀποδοῦναι, ἀλλὰ τοὺς εἰς Ῥόδον προστάττεις ἀπολαβεῖν, ὥσπερ τὸ σὸν πρόσταγμα τῆς συγγραφῆς δέον κυριώτερον γενέσθαι, καὶ τολμᾷς λέγειν ὡς οὐκ ἐσώθη ἡ ναῦς εἰς τὸν Πειραιᾶ· ἐφ’ ᾧ δικαίως ἂν ἀποθάνοις ὑπὸ τῶν δικαστῶν.", "st": "56.41"}, {"sp": "N", "t": "διὰ τίνα γὰρ μᾶλλον, ὦ ἄνδρες δικασταί, οὐ σέσῳσται ἡ ναῦς εἰς τὸν Πειραιᾶ; πότερον δι’ ἡμᾶς τοὺς διαρρήδην δανείσαντας εἰς Αἴγυπτον καὶ εἰς Ἀθήνας, ἢ διὰ τοῦτον καὶ τὸν κοινωνὸν αὐτοῦ, οἳ ἐπὶ ταύταις ταῖς ὁμολογίαις δανεισάμενοι, ἐφ’ ᾧ τε καταπλεῖν Ἀθήναζε, εἰς Ῥόδον κατήγαγον τὴν ναῦν; ὅτι δὲ ἑκόντες καὶ οὐκ ἐξ ἀνάγκης ταῦτ’ ἔπραξαν, ἐκ πολλῶν δῆλον.", "st": "56.42"}, {"sp": "N", "t": "εἰ γὰρ ὡς ἀληθῶς ἀκούσιον τὸ συμβὰν ἐγένετο καὶ ἡ ναῦς ἐρράγη, τὸ μετὰ τοῦτ’ ἐπειδὴ ἐπεσκεύασαν τὴν ναῦν, οὐκ ἂν εἰς ἕτερα δήπου ἐμπόρια ἐμίσθωσαν αὐτήν, ἀλλ’ ὡς ὑμᾶς ἀπέστελλον, ἐπανορθούμενοι τὸ ἀκούσιον σύμπτωμα. νῦν δ’ οὐχ ὅπως ἐπηνωρθώσαντο, ἀλλὰ πρὸς τοῖς ἐξ ἀρχῆς ἀδικήμασι πολλῷ μείζω προσεξημαρτήκασιν, καὶ ὥσπερ ἐπὶ καταγέλωτι ἀντιδικοῦντες εἰσεληλύθασιν, ὡς ἐπ’ αὐτοῖς ἐσόμενον, ἐὰν καταψηφίσησθε αὐτῶν, τὰ ἀρχαῖα μόνον ἀποδοῦναι καὶ τοὺς τόκους.", "st": "56.43"}, {"sp": "N", "t": "ὑμεῖς οὖν, ὦ ἄνδρες Ἀθηναῖοι, μὴ ἐπιτρέπετε τούτοις οὕτως ἔχουσιν, μηδ’ ἐπὶ δυοῖν ἀγκύραιν ὁρμεῖν αὐτοὺς ἐᾶτε, ὡς, ἐὰν μὲν κατορθώσωσι, τἀλλότρια ἕξοντας, ἐὰν δὲ μὴ δύνωνται ἐξαπατῆσαι ὑμᾶς, αὐτὰ τὰ ὀφειλόμενα ἀποδώσοντας· ἀλλὰ τοῖς ἐπιτιμίοις ζημιοῦτε τοῖς ἐκ τῆς συγγραφῆς. καὶ γὰρ ἂν δεινὸν εἴη, αὐτοὺς μὲν τούτους διπλασίαν καθ’ αὑτῶν τὴν ζημίαν γράψασθαι, ἐάν τι παραβαίνωσι τῶν ἐν τῇ συγγραφῇ, ὑμᾶς δ’ ἠπιωτέρως ἔχειν πρὸς αὐτούς, καὶ ταῦτα οὐχ ἧττον ἡμῶν συνηδικημένους.", "st": "56.44"}, {"sp": "N", "t": "τὰ μὲν οὖν περὶ τοῦ πράγματος δίκαια βραχέα ἐστὶ καὶ εὐμνημόνευτα. ἐδανείσαμεν Διονυσοδώρῳ τουτῳὶ καὶ τῷ κοινωνῷ αὐτοῦ τρισχιλίας δραχμὰς Ἀθήνηθεν εἰς Αἴγυπτον καὶ ἐξ Αἰγύπτου Ἀθήναζε· οὐκ ἀπειλήφαμεν τὰ χρήματα οὐδὲ τοὺς τόκους, ἀλλ’ ἔχουσι τὰ ἡμέτερα καὶ χρῶνται δεύτερον ἔτος· οὐ κατακεκομίκασιν τὴν ναῦν εἰς τὸ ὑμέτερον ἐμπόριον οὐδέπω καὶ νῦν, οὐδ’ ἡμῖν παρεσχήκασιν ἐμφανῆ· ἡ δὲ συγγραφὴ κελεύει, ἐὰν μὴ παρέχωσιν ἐμφανῆ τὴν ναῦν, ἀποτίνειν αὐτοὺς διπλάσια τὰ χρήματα, τὴν δὲ πρᾶξιν εἶναι καὶ ἐξ ἑνὸς καὶ ἐξ ἀμφοῖν.", "st": "56.45"}, {"sp": "N", "t": "ταῦτ’ ἔχοντες τὰ δίκαια εἰσεληλύθαμεν πρὸς ὑμᾶς, ἀξιοῦντες τὰ ἡμέτερα αὐτῶν ἀπολαβεῖν δι’ ὑμῶν, ἐπειδὴ παρ’ αὐτῶν τούτων οὐ δυνάμεθα. ὁ μὲν παρ’ ἡμῶν λόγος οὗτός ἐστιν. οὗτοι δὲ δανείσασθαι μὲν ὁμολογοῦσιν καὶ μὴ ἀποδεδωκέναι, διαφέρονται δὲ ὡς οὐ δεῖ τελεῖν αὐτοὺς τοὺς τόκους τοὺς ἐν τῇ συγγραφῇ, ἀλλὰ τοὺς εἰς Ῥόδον, οὓς οὔτε συνεγράψαντο οὔτε ἔπεισαν ἡμᾶς. εἰ μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι,", "st": "56.46"}, {"sp": "N", "t": "ἐν τῷ Ῥοδίων δικαστηρίῳ ἐκρινόμεθα, ἴσως ἂν οὗτοι ἐπλεονέκτουν ἡμῶν, σεσιτηγηκότες πρὸς αὐτοὺς καὶ καταπεπλευκότες τῇ νηὶ εἰς τὸ ἐκείνων ἐμπόριον· νῦν δὲ εἰς Ἀθηναίους εἰσεληλυθότες καὶ συγγραψάμενοι εἰς τὸ ὑμέτερον ἐμπόριον, οὐκ ἀξιοῦμεν ἐλαττωθῆναι ὑπὸ τῶν καὶ ἡμᾶς καὶ ὑμᾶς ἠδικηκότων.", "st": "56.47"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, ἄνδρες Ἀθηναῖοι, μὴ ἀγνοεῖτε, ὅτι νυνὶ μίαν δίκην δικάζοντες νομοθετεῖτε ὑπὲρ ὅλου τοῦ ἐμπορίου, καὶ παρεστᾶσι πολλοὶ τῶν κατὰ θάλατταν ἐργάζεσθαι προαιρουμένων ὑμᾶς θεωροῦντες, πῶς τὸ πρᾶγμα τουτὶ κρίνετε. εἰ μὲν γὰρ ὑμεῖς τὰς συγγραφὰς καὶ τὰς ὁμολογίας τὰς πρὸς ἀλλήλους γιγνομένας ἰσχυρὰς οἴεσθε δεῖν εἶναι καὶ τοῖς παραβαίνουσιν αὐτὰς μηδεμίαν συγγνώμην ἕξετε, ἑτοιμότερον προήσονται τὰ ἑαυτῶν οἱ ἐπὶ τοῦ δανείζειν ὄντες, ἐκ δὲ τούτων αὐξηθήσεται ὑμῖν τὸ ἐμπόριον.", "st": "56.48"}, {"sp": "N", "t": "εἰ μέντοι ἐξέσται τοῖς ναυκλήροις, συγγραφὴν γραψαμένοις ἐφ’ ᾧ τε καταπλεῖν εἰς Ἀθήνας, ἔπειτα κατάγειν τὴν ναῦν εἰς ἕτερα ἐμπόρια, φάσκοντας ῥαγῆναι καὶ τοιαύτας προφάσεις ποριζομένους οἵαισπερ καὶ Διονυσόδωρος οὑτοσὶ χρῆται, καὶ τοὺς τόκους μερίζειν πρὸς τὸν πλοῦν ὃν ἂν φήσωσιν πεπλευκέναι, καὶ μὴ πρὸς τὴν συγγραφήν, οὐδὲν κωλύσει ἅπαντα τὰ συμβόλαια διαλύεσθαι.", "st": "56.49"}, {"sp": "N", "t": "τίς γὰρ ἐθελήσει τὰ ἑαυτοῦ προέσθαι, ὅταν ὁρᾷ τὰς μὲν συγγραφὰς ἀκύρους, ἰσχύοντας δὲ τοὺς τοιούτους λόγους, καὶ τὰς αἰτίας τῶν ἠδικηκότων ἔμπροσθεν οὔσας τοῦ δικαίου; μηδαμῶς, ὦ ἄνδρες δικασταί· οὔτε γὰρ τῷ πλήθει τῷ ὑμετέρῳ συμφέρει τοῦτο οὔτε τοῖς ἐργάζεσθαι προῃρημένοις, οἵπερ χρησιμώτατοί εἰσιν καὶ κοινῇ πᾶσιν ὑμῖν καὶ ἰδίᾳ τῷ ἐντυγχάνοντι. διόπερ δεῖ ὑμᾶς αὐτῶν ἐπιμέλειαν ποιεῖσθαι.", "st": "56.50"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ὅσαπερ οἷός τ’ ἦν, εἴρηκα· ἀξιῶ δὲ καὶ τῶν φίλων μοί τινα συνειπεῖν. δεῦρο Δημόσθενες.", "st": "56.50"}, {"sp": "HDR", "t": "Ἔφεσις πρὸς Εὐβουλίδην", "st": "57"}, {"sp": "N", "t": "πολλὰ καὶ ψευδῆ κατηγορηκότος ἡμῶν Εὐβουλίδου, καὶ βλασφημίας οὔτε προσηκούσας οὔτε δικαίας πεποιημένου, πειράσομαι τἀληθῆ καὶ τὰ δίκαια λέγων, ὦ ἄνδρες δικασταί, δεῖξαι καὶ μετὸν τῆς πόλεως ἡμῖν καὶ πεπονθότ’ ἐμαυτὸν οὐχὶ προσήκονθ’ ὑπὸ τούτου. δέομαι δ’ ἁπάντων ὑμῶν, ὦ ἄνδρες δικασταί, καὶ ἱκετεύω καὶ ἀντιβολῶ, λογισαμένους τό τε μέγεθος τοῦ παρόντος ἀγῶνος καὶ τὴν αἰσχύνην μεθ’ ἧς ὑπάρχει τοῖς ἁλισκομένοις ἀπολωλέναι, ἀκοῦσαι καὶ ἐμοῦ σιωπῇ, μάλιστα μέν, εἰ δυνατόν, μετὰ πλείονος εὐνοίας ἢ τούτου (τοῖς γὰρ ἐν κινδύνῳ καθεστηκόσιν εἰκὸς εὐνοϊκωτέρους ὑπάρχειν), εἰ δὲ μή, μετά γε τῆς ἴσης. συμβαίνει δέ μοι τὸ μὲν καθ’ ἡμᾶς,", "st": "57.1"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, καὶ τὸ προσήκειν μοι τῆς πόλεως, θαρρεῖν καὶ πολλὰς ἔχειν ἐλπίδας καλῶς ἀγωνιεῖσθαι, τὸν καιρὸν δὲ καὶ τὸ παρωξύνθαι τὴν πόλιν πρὸς τὰς ἀποψηφίσεις φοβεῖσθαι· πολλῶν γὰρ ἐξεληλαμένων δικαίως ἐκ πάντων τῶν δήμων, συγκεκοινωνήκαμεν τῆς δόξης ταύτης οἱ κατεστασιασμένοι, καὶ πρὸς τὴν κατ’ ἐκείνων αἰτίαν, οὐ πρὸς τὸ καθ’ αὑτὸν ἕκαστος ἀγωνιζόμεθα, ὥστ’ ἐξ ἀνάγκης μέγαν ἡμῖν εἶναι τὸν φόβον.", "st": "57.2"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ τούτων οὕτως ἐχόντων, ἃ νομίζω περὶ τούτων αὐτῶν πρῶτον εἶναι δίκαια, ἐρῶ πρὸς ὑμᾶς. ἐγὼ γὰρ οἴομαι δεῖν ὑμᾶς τοῖς μὲν ἐξελεγχομένοις ξένοις οὖσιν χαλεπαίνειν, εἰ μήτε πείσαντες μήτε δεηθέντες ὑμῶν λάθρᾳ καὶ βίᾳ τῶν ὑμετέρων ἱερῶν καὶ κοινῶν μετεῖχον, τοῖς δ’ ἠτυχηκόσι καὶ δεικνύουσι πολίτας ὄντας αὑτοὺς βοηθεῖν καὶ σῴζειν, ἐνθυμουμένους ὅτι πάντων οἰκτρότατον πάθος ἡμῖν ἂν συμβαίη τοῖς ἠδικημένοις, εἰ τῶν λαμβανόντων δίκην ὄντες ἂν δικαίως μεθ’ ὑμῶν, ἐν τοῖς διδοῦσι γενοίμεθα καὶ συναδικηθείημεν διὰ τὴν τοῦ πράγματος ὀργήν.", "st": "57.3"}, {"sp": "N", "t": "ᾤμην μὲν οὖν ἔγωγ’, ὦ ἄνδρες δικασταί, προσήκειν Εὐβουλίδῃ, καὶ πᾶσιν δ’ ὅσοι νῦν ἐπὶ ταῖς ἀποψηφίσεσιν κατηγοροῦσιν, ὅσ’ ἴσασιν ἀκριβῶς λέγειν καὶ μηδεμίαν προσάγειν ἀκοὴν πρὸς τὸν τοιοῦτον ἀγῶνα. οὕτω γὰρ τοῦτ’ ἄδικον καὶ σφόδρα πάλαι κέκριται, ὥστ’ οὐδὲ μαρτυρεῖν ἀκοὴν ἐῶσιν οἱ νόμοι, οὐδ’ ἐπὶ τοῖς πάνυ φαύλοις ἐγκλήμασιν, εἰκότως· ὅπου γὰρ εἰδέναι τινὲς ἤδη φήσαντες ψευδεῖς ἐφάνησαν, πῶς ἅ γε μηδ’ αὐτὸς οἶδεν ὁ λέγων, προσήκει πιστεύεσθαι;", "st": "57.4"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅπου γε μηδ’ ὑπεύθυνον καθιστάνθ’ ἑαυτὸν ἔξεστιν, δι’ ὧν ἂν ἀκοῦσαι τις φῇ, βλάπτειν μηδένα, πῶς ἀνυπευθύνῳ γε λέγοντι προσήκει πιστεύειν ὑμᾶς; ἐπειδὴ τοίνυν οὗτος εἰδὼς τοὺς νόμους καὶ μᾶλλον ἢ προσῆκεν, ἀδίκως καὶ πλεονεκτικῶς τὴν κατηγορίαν πεποίηται, ἀναγκαῖον ἐμοὶ περὶ ὧν ἐν τοῖς δημόταις ὑβρίσθην πρῶτον εἰπεῖν.", "st": "57.5"}, {"sp": "N", "t": "ἀξιῶ δ’, ὦ ἄνδρες Ἀθηναῖοι, μηδέπω τὴν τῶν δημοτῶν ἀποψήφισιν ποιεῖσθαι τεκμήριον ὑμᾶς, ὡς ἄρ’ οὐχὶ προσήκει μοι τῆς πόλεως. εἰ γὰρ πάντ’ ἐνομίζετε τὰ δίκαια δυνήσεσθαι τοὺς δημότας διακρῖναι, οὐκ ἂν ἐδώκατε τὴν εἰς ὑμᾶς ἔφεσιν· νῦν δὲ καὶ διὰ φιλονικίαν καὶ διὰ φθόνον καὶ δι’ ἔχθραν καὶ δι’ ἄλλας προφάσεις ἔσεσθαί τι τοιοῦτον ἡγούμενοι, τὴν εἰς ὑμᾶς τοῖς ἀδικηθεῖσιν ἐποιήσατε καταφυγήν, δι’ ἣν καλῶς ποιοῦντες, ὦ ἄνδρες Ἀθηναῖοι, τοὺς ἠδικημένους ἅπαντας σεσῴκατε.", "st": "57.6"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὃν τρόπον ἐν τοῖς δημόταις συνέβη τὴν διαψήφισιν γενέσθαι, φράσω πρὸς ὑμᾶς· τὸ γὰρ εἰς αὐτὸ τὸ πρᾶγμα πάντα λέγειν τοῦτ’ ἐγὼ ὑπολαμβάνω, ὅσα τις παρὰ τὸ ψήφισμα πέπονθεν ἀδίκως καταστασιασθείς, ἐπιδεῖξαι.", "st": "57.7"}, {"sp": "N", "t": "Εὐβουλίδης γὰρ οὑτοσί, ὦ ἄνδρες Ἀθηναῖοι, ὡς ὑμῶν ἴσασι πολλοί, γραψάμενος ἀσεβείας τὴν ἀδελφὴν τὴν Λακεδαιμονίου τὸ πέμπτον μέρος τῶν ψήφων οὐ μετέλαβεν. ὅτι δὴ ἐν ἐκείνῳ τῷ ἀγῶνι τὰ δίκαια, τούτῳ δὲ τἀναντί’ ἐμαρτύρησα, διὰ ταύτην τὴν ἔχθραν ἐπιτίθεταί μοι. καὶ βουλεύων, ὦ ἄνδρες δικασταί, καὶ κύριος ὢν τοῦ θ’ ὅρκου καὶ τῶν γραμμάτων ἐξ ὧν ἀνεκάλει τοὺς δημότας, τί ποιεῖ;", "st": "57.8"}, {"sp": "N", "t": "πρῶτον μέν, ἐπειδὴ συνελέγησαν οἱ δημόται, κατέτριψεν τὴν ἡμέραν δημηγορῶν καὶ ψηφίσματα γράφων. τοῦτο δ’ ἦν οὐκ ἀπὸ τοῦ αὐτομάτου, ἀλλ’ ἐπιβουλεύων ἐμοί, ὅπως ὡς ὀψιαίταθ’ ἡ διαψήφισις ἡ περὶ ἐμοῦ γένοιτο· καὶ διεπράξατο τοῦτο. καὶ τῶν μὲν δημοτῶν οἱ ὀμόσαντες ἐγενόμεθα τρεῖς καὶ ἑβδομήκοντα, ἠρξάμεθα δὲ τοῦ διαψηφίζεσθαι δείλης ὀψίας, ὥστε συνέβη, ἡνίκα τοὐμὸν ὄνομ’ ἐκαλεῖτο, σκότος εἶναι ἤδη·", "st": "57.9"}, {"sp": "N", "t": "καὶ γὰρ ἦν περὶ ἑξηκοστόν, καὶ ἐκλήθην ὕστατος ἁπάντων τῶν ἐν ἐκείνῃ τῇ ἡμέρᾳ κληθέντων, ἡνίχ’ οἱ μὲν πρεσβύτεροι τῶν δημοτῶν ἀπεληλύθεσαν εἰς τοὺς ἀγρούς· τοῦ γὰρ δήμου ἡμῖν, ὦ ἄνδρες δικασταί, πέντε καὶ τριάκοντα στάδια τοῦ ἄστεως ἀπέχοντος καὶ τῶν πλείστων ἐκεῖ οἰκούντων, ἀπεληλύθεσαν οἱ πολλοί· οἱ δὲ κατάλοιποι ἦσαν οὐ πλείους ἢ τριάκοντα. ἐν δὲ τούτοις ἦσαν ἅπαντες οἱ τούτῳ παρεσκευασμένοι.", "st": "57.10"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἐκλήθη τοὐμὸν ὄνομα, ἀναπηδήσας οὗτος ἐβλασφήμει κατ’ ἐμοῦ ταχὺ καὶ πολλὰ καὶ μεγάλῃ τῇ φωνῇ, ὥσπερ καὶ νῦν, μάρτυρα μὲν ὧν κατηγόρησεν οὐδένα παρασχόμενος οὔτε τῶν δημοτῶν οὔτε τῶν ἄλλων πολιτῶν, παρεκελεύετο δὲ τοῖς δημόταις ἀποψηφίζεσθαι.", "st": "57.11"}, {"sp": "N", "t": "ἀξιοῦντος δέ μου ἀναβαλέσθαι εἰς τὴν ὑστεραίαν διά τε τὴν ὥραν καὶ τὸ μηδένα μοι παρεῖναι τό τε πρᾶγμ’ ἄφνω προσπεπτωκέναι, ἵνα τούτῳ τ’ ἐξουσία γένοιθ’ ὁπόσα βούλοιτο κατηγορῆσαι καὶ μάρτυρας εἴ τινας ἔχοι παρασχέσθαι, ἐμοί τ’ ἐκγένοιτ’ ἀπολογήσασθαι ἐν ἅπασι τοῖς δημόταις καὶ τοὺς οἰκείους μάρτυρας παρασχέσθαι· καὶ ὅ τι γνοίησαν περὶ ἐμοῦ, τούτοις ἤθελον ἐμμένειν·", "st": "57.12"}, {"sp": "N", "t": "οὗτος ὧν μὲν ἐγὼ προὐκαλούμην οὐδὲν ἐφρόντισεν, τὴν δὲ ψῆφον εὐθὺς ἐδίδου τοῖς παροῦσι τῶν δημοτῶν, οὔτ’ ἀπολογίαν οὐδεμίαν ἐμοὶ δοὺς οὔτ’ ἔλεγχον οὐδέν’ ἀκριβῆ ποιήσας. οἱ δὲ τούτῳ συνεστῶτες ἀναπηδήσαντες ἐψηφίζοντο. καὶ ἦν μὲν σκότος, οἱ δὲ λαμβάνοντες δύο καὶ τρεῖς ψήφους ἕκαστος παρὰ τούτου ἐνέβαλλον εἰς τὸν καδίσκον. σημεῖον δέ· οἱ μὲν γὰρ ψηφισάμενοι οὐ πλείους ἢ τριάκοντ’ ἦσαν, αἱ δὲ ψῆφοι ἠριθμήθησαν πλείους ἢ ἑξήκοντα, ὥστε πάντας ἡμᾶς ἐκπλαγῆναι.", "st": "57.13"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς ἀληθῆ λέγω, καὶ ὅτι οὔτ’ ἐδόθη ἡ ψῆφος ἐν ἅπασιν πλείους τ’ ἐγένοντο τῶν ψηφισαμένων, μάρτυρας ὑμῖν παρέξομαι. συμβαίνει δέ μοι περὶ τούτων τῶν μὲν φίλων ἢ τῶν ἄλλων Ἀθηναίων μηδένα μάρτυρα παρεῖναι διά τε τὴν ὥραν καὶ διὰ τὸ μηδένα παρακαλέσαι, αὐτοῖς δὲ τοῖς ἠδικηκόσιν με χρῆσθαι μάρτυσιν. ἃ οὖν οὐ δυνήσονται ἔξαρνοι γενέσθαι, ταῦτα γέγραφ’ αὐτοῖς. λέγε.", "st": "57.14"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "57.14"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες δικασταί, συνέβαινεν τοῖς Ἁλιμουσίοις περὶ ἁπάντων τῶν δημοτῶν διαψηφίσασθαι ἐν ἐκείνῃ τῇ ἡμέρᾳ, εἰκὸς ἦν καὶ εἰς ὀψὲ ψηφίζεσθαι, ἵν’ ἀπηλλαγμένοι ἦσαν ποιήσαντες τὰ ὑμῖν ἐψηφισμένα. εἰ δὲ πλείους ἢ εἴκοσιν ὑπόλοιποι ἦσαν τῶν δημοτῶν, περὶ ὧν ἔδει τῇ ὑστεραίᾳ διαψηφίσασθαι, καὶ ὁμοίως ἦν ἀνάγκη συλλέγεσθαι τοὺς δημότας, τί ποτ’ ἦν τὸ δυσχερὲς Εὐβουλίδῃ ἀναβαλέσθαι εἰς τὴν ὑστεραίαν καὶ περὶ ἐμοῦ πρώτου τὴν ψῆφον διδόναι τοῖς δημόταις;", "st": "57.15"}, {"sp": "N", "t": "διότι, ὦ ἄνδρες δικασταί, οὐκ ἠγνόει Εὐβουλίδης ὅτι, εἰ λόγος ἀποδοθήσοιτο καὶ παραγένοιντό μοι πάντες οἱ δημόται καὶ ἡ ψῆφος δικαίως δοθείη, οὐδαμοῦ γενήσονται οἱ μετὰ τούτου συνεστηκότες. ὅθεν δ’ οὗτοι συνέστησαν, ταῦτα, ἐπειδὰν περὶ τοῦ γένους εἴπω, τότε, ἂν βούλησθ’ ἀκούειν, ἐρῶ.", "st": "57.16"}, {"sp": "N", "t": "νῦν δὲ τί δίκαιον νομίζω καὶ τί παρεσκεύασμαι ποιεῖν, ἄνδρες δικασταί; δεῖξαι πρὸς ὑμᾶς ἐμαυτὸν Ἀθηναῖον ὄντα καὶ τὰ πρὸς πατρὸς καὶ τὰ πρὸς μητρός, καὶ μάρτυρας τούτων, οὓς ὑμεῖς ἀληθεῖς φήσετ’ εἶναι, παρασχέσθαι, τὰς δὲ λοιδορίας καὶ τὰς αἰτίας ἀνελεῖν· ὑμᾶς δ’ ἀκούσαντας τούτων, ἐὰν μὲν ὑμῖν πολίτης ὢν κατεστασιάσθαι δοκῶ, σῴζειν, εἰ δὲ μή, πράττειν ὁποῖον ἄν τι ὑμῖν εὐσεβὲς εἶναι δοκῇ. ἄρξομαι δ’ ἐντεῦθεν.", "st": "57.17"}, {"sp": "N", "t": "διαβεβλήκασι γάρ μου τὸν πατέρα, ὡς ἐξένιζεν· καὶ ὅτι μὲν ἁλοὺς ὑπὸ τῶν πολεμίων ὑπὸ τὸν Δεκελεικὸν πόλεμον καὶ πραθεὶς εἰς Λευκάδα, Κλεάνδρῳ περιτυχὼν τῷ ὑποκριτῇ πρὸς τοὺς οἰκείους ἐσώθη δεῦρο πολλοστῷ χρόνῳ, παραλελοίπασιν, ὥσπερ δὲ δέον ἡμᾶς δι’ ἐκείνας τὰς ἀτυχίας ἀπολέσθαι, τὸ ξενίζειν αὐτοῦ κατηγορήκασιν.", "st": "57.18"}, {"sp": "N", "t": "ἐγὼ δ’ ἐξ αὐτῶν τούτων μάλιστ’ οἶμαι ὑμῖν ἐμαυτὸν Ἀθηναῖον ὄντ’ ἐπιδείξειν. καὶ πρῶτον μὲν ὡς ἑάλω καὶ ἐσώθη, μάρτυρας ὑμῖν παρέξομαι, ἔπειθ’ ὅτι ἀφικόμενος τῆς οὐσίας παρὰ τῶν θείων τὸ μέρος μετέλαβεν, εἶθ’ ὅτι οὔτ’ ἐν τοῖς δημόταις οὔτ’ ἐν τοῖς φράτερσιν οὔτ’ ἄλλοθι οὐδαμοῦ τὸν ξενίζοντ’ οὐδεὶς πώποτ’ ᾐτιάσαθ’ ὡς εἴη ξένος. καί μοι λαβὲ τὰς μαρτυρίας.", "st": "57.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "57.19"}, {"sp": "N", "t": "περὶ μὲν τῆς ἁλώσεως καὶ τῆς σωτηρίας, ἣν συνέβη γενέσθαι τῷ πατρὶ δεῦρο, ἀκηκόατε. ὡς δ’ ὑμέτερος ἦν πολίτης, ὦ ἄνδρες δικασταί (τὸ γὰρ ὂν καὶ ἀληθὲς οὕτως ὑπάρχει), μάρτυρας καλῶ τοὺς ζῶντας ὑμῖν τῶν συγγενῶν τῶν πρὸς πατρός. κάλει δή μοι πρῶτον μὲν Θουκριτίδην καὶ Χαρισιάδην· ὁ γὰρ τούτων πατὴρ Χαρίσιος ἀδελφὸς ἦν τοῦ πάππου τοῦ ἐμοῦ Θουκριτίδου καὶ Λυσαρέτης τῆς ἐμῆς τήθης (ἀδελφὴν γὰρ ὁ πάππος οὑμὸς ἔγημεν οὐχ ὁμομητρίαν), θεῖος δὲ τοῦ πατρὸς τοῦ ἐμοῦ·", "st": "57.20"}, {"sp": "N", "t": "ἔπειτα Νικιάδην· καὶ γὰρ ὁ τούτου πατὴρ Λυσανίας ἀδελφὸς ἦν τοῦ Θουκριτίδου καὶ τῆς Λυσαρέτης, θεῖος δὲ τοῦ πατρὸς τοῦ ἐμοῦ· ἔπειτα Νικόστρατον· καὶ γὰρ ὁ τούτου πατὴρ Νικιάδης ἀδελφιδοῦς ἦν τῷ πάππῳ τῷ ἐμῷ καὶ τῇ τήθῃ, ἀνεψιὸς δὲ τῷ πατρί. καί μοι κάλει τούτους πάντας. σὺ δ’ ἐπίλαβε τὸ ὕδωρ.", "st": "57.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.21"}, {"sp": "N", "t": "τῶν μὲν τοίνυν πρὸς ἀνδρῶν τῷ πατρὶ συγγενῶν ἀκηκόατ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ μαρτυρούντων καὶ διομνυμένων ⟨Ἀθηναῖον⟩ εἶναι καὶ συγγενῆ τὸν ἐμὸν πατέρ’ αὑτοῖς· ὧν οὐδεὶς δήπου, παραστησάμενος τοὺς συνεισομένους αὑτῷ τὰ ψευδῆ μαρτυροῦντι, κατ’ ἐξωλείας ἐπιορκεῖ. λαβὲ δὴ καὶ τὰς τῶν πρὸς γυναικῶν τῷ πατρὶ συγγενῶν μαρτυρίας.", "st": "57.22"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "57.22"}, {"sp": "N", "t": "οἱ μὲν τοίνυν ζῶντες οὗτοι τῶν συγγενῶν τοῦ πατρὸς καὶ πρὸς ἀνδρῶν καὶ πρὸς γυναικῶν μεμαρτυρήκασιν, ὡς ἦν ἀμφοτέρωθεν Ἀθηναῖος καὶ μετῆν τῆς πόλεως αὐτῷ δικαίως. κάλει δή μοι καὶ τοὺς φράτερας, ἔπειτα τοὺς γεννήτας.", "st": "57.23"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.23"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὰς τῶν δημοτῶν μαρτυρίας, καὶ τὰς τῶν συγγενῶν περὶ τῶν φρατέρων, ὡς εἵλοντό με φρατρίαρχον.", "st": "57.23"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "57.23"}, {"sp": "N", "t": "τὰ μὲν τοίνυν ὑπὸ τῶν συγγενῶν καὶ φρατέρων καὶ δημοτῶν καὶ γεννητῶν, ὧν προσήκει, μαρτυρούμεν’ ἀκηκόατε. ἐξ ὧν ἔστιν ὑμῖν εἰδέναι, πότερόν ποτ’ ἀστὸς ἢ ξένος ἦν ᾧ ταῦθ’ ὑπῆρχεν. καὶ γὰρ εἰ μὲν εἰς ἕν’ ἢ δύ’ ἀνθρώπους κατεφεύγομεν, εἴχομεν ἄν τιν’ ὑποψίαν παρεσκευάσθαι τούτους· εἰ δ’ ἐν ἅπασιν, ὅσοισπερ ἕκαστος ὑμῶν, ἐξητασμένος φαίνεται καὶ ζῶν ὁ πατὴρ καὶ νῦν ἐγώ, λέγω φράτερσι, συγγενέσι, δημόταις, γεννήταις, πῶς ἔνεστιν ἢ πῶς δυνατὸν τούτους ἅπαντας μὴ μετ’ ἀληθείας ὑπάρχοντας κατεσκευάσθαι;", "st": "57.24"}, {"sp": "N", "t": "εἰ μὲν τοίνυν εὔπορος ὢν ὁ πατὴρ χρήματα δοὺς τούτοις ἐφαίνετο πείσας συγγενεῖς αὐτοὺς ἑαυτοῦ φάσκειν εἶναι, λόγον εἶχεν ἂν ὑποψίαν τιν’ ἔχειν ὡς οὐκ ἦν ἀστός· εἰ δὲ πένης ὢν ἅμα συγγενεῖς τε παρέσχετο τοὺς αὐτοὺς καὶ μεταδιδόντας τῶν ὄντων ἐπεδείκνυε, πῶς οὐκ εὔδηλον ὅτι τῇ ἀληθείᾳ προσῆκε τούτοις; οὐ γὰρ ἂν δήπου, εἴ γε μηδενὶ ἦν οἰκεῖος, χρήματ’ αὐτῷ προστιθέντες οὗτοι τοῦ γένους μετεδίδοσαν. ἀλλ’ ἦν, ὡς τό τ’ ἔργον ἐδήλωσεν καὶ ὑμῖν μεμαρτύρηται. ἔτι τοίνυν ἀρχὰς ἔλαχεν καὶ ἦρξεν δοκιμασθείς. καί μοι λαβὲ τὴν μαρτυρίαν.", "st": "57.25"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "57.25"}, {"sp": "N", "t": "οἴεταί τις οὖν ὑμῶν ἐᾶσαί ποτ’ ἂν τοὺς δημότας ἐκεῖνον τὸν ξένον καὶ μὴ πολίτην ἄρχειν παρ’ αὑτοῖς, ἀλλ’ οὐκ ἂν κατηγορεῖν; οὐ τοίνυν κατηγόρησεν οὐδὲ εἷς, οὐδ’ ᾐτιάσατο. ἀλλὰ μὴν καὶ διαψηφίσεις ἐξ ἀνάγκης ἐγένοντο τοῖς δημόταις ὀμόσασιν καθ’ ἱερῶν, ὅτ’ ἀπώλετ’ αὐτοῖς τὸ ληξιαρχικὸν γραμματεῖον δημαρχοῦντος Ἀντιφίλου τοῦ πατρὸς τοῦ Εὐβουλίδου, καί τινας ἀπήλασαν αὑτῶν· περὶ ἐκείνου δ’ οὐδεὶς οὔτ’ εἶπεν οὔτ’ ᾐτιάσατο τοιοῦτον οὐδέν.", "st": "57.26"}, {"sp": "N", "t": "καίτοι πᾶσίν ἐστιν ἀνθρώποις τέλος τοῦ βίου θάνατος, καὶ περὶ ὧν μὲν ἄν τις ζῶν αἰτίαν σχῇ, δίκαιον τοὺς παῖδας τὴν ἀειλογίαν παρέχειν· περὶ ὧν δ’ ἂν μηδεὶς αὐτὸν ζῶντα καταιτιάσηται, πῶς οὐ δεινὸν εἰ τοὺς παῖδας ὁ βουλόμενος κρινεῖ; εἰ μὲν τοίνυν περὶ τούτων μηδεὶς λόγος ἐξητάσθη, δῶμεν τοῦτο λεληθέναι· εἰ δ’ ἐδόθη καὶ διεψηφίσαντο καὶ μηδὲν ᾐτιάσατο πώποτε μηδείς, πῶς οὐ δικαίως ἂν ἐγὼ κατ’ ἐκεῖνον Ἀθηναῖος εἴην, τὸν τελευτήσαντα πρὶν ἀμφισβητηθῆναι τοῦ γένους αὐτῷ; ὡς δὴ ταῦτ’ ἀληθῆ λέγω, καλῶ καὶ τούτων μάρτυρας.", "st": "57.27"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.27"}, {"sp": "N", "t": "ἔτι τοίνυν παίδων αὐτῷ τεττάρων γενομένων ὁμομητρίων ἐμοὶ καὶ τελευτησάντων, ἔθαψε τούτους εἰς τὰ πατρῷα μνήματα, ὧν ὅσοιπέρ εἰσιν τοῦ γένους κοινωνοῦσιν· καὶ τούτων οὐδεὶς οὐκ ἀπεῖπεν πώποτε, οὐκ ἐκώλυσεν, οὐ δίκην ἔλαχεν. καίτοι τίς ἔστιν ὅστις ἂν εἰς τὰ πατρῷα μνήματα τοὺς μηδὲν ἐν γένει τιθέναι ἐάσαι; ὡς τοίνυν καὶ ταῦτ’ ἀληθῆ λέγω, λαβὲ τὴν μαρτυρίαν.", "st": "57.28"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "57.28"}, {"sp": "N", "t": "περὶ μὲν τοίνυν τοῦ πατρός, ὡς Ἀθηναῖος ἦν, ταῦτ’ ἔχω λέγειν, καὶ μάρτυρας παρέσχημαι τοὺς ὑπ’ αὐτῶν τούτων ἐψηφισμένους εἶναι πολίτας, μαρτυροῦντας ἐκεῖνον ἑαυτοῖς ἀνεψιὸν εἶναι. φαίνεται δὲ βιοὺς ἔτη τόσα καὶ τόσ’ ἐνθάδε, καὶ οὐδαμοῦ πώποθ’ ὡς ξένος ἐξετασθείς, ἀλλὰ πρὸς τούτους ὄντας συγγενεῖς καταφεύγων, οὗτοι δὲ καὶ προσδεχόμενοι καὶ τῆς οὐσίας μεταδιδόντες ὡς αὑτῶν ἑνί.", "st": "57.29"}, {"sp": "N", "t": "τοῖς χρόνοις τοίνυν οὕτω φαίνεται γεγονὼς ὥστε, εἰ καὶ κατὰ θάτερ’ ἀστὸς ἦν, εἶναι πολίτην προσήκειν αὐτόν· γέγονε γὰρ πρὸ Εὐκλείδου. περὶ δὲ τῆς μητρὸς (καὶ γὰρ ταύτην διαβεβλήκασί μου) λέξω, καὶ μάρτυρας ὧν ἂν λέγω, καλῶ. καίτοι, ὦ ἄνδρες Ἀθηναῖοι, οὐ μόνον παρὰ τὸ ψήφισμα τὰ περὶ τὴν ἀγορὰν διέβαλλεν ἡμᾶς Εὐβουλίδης, ἀλλὰ καὶ παρὰ τοὺς νόμους, οἳ κελεύουσιν ἔνοχον εἶναι τῇ κακηγορίᾳ τὸν τὴν ἐργασίαν τὴν ἐν τῇ ἀγορᾷ ἢ τῶν πολιτῶν ἢ τῶν πολιτίδων ὀνειδίζοντά τινι.", "st": "57.30"}, {"sp": "N", "t": "ἡμεῖς δ’ ὁμολογοῦμεν καὶ ταινίας πωλεῖν καὶ ζῆν οὐχ ὅντινα τρόπον βουλόμεθα. καὶ εἴ σοί ἐστιν τοῦτο σημεῖον, ὦ Εὐβουλίδη, τοῦ μὴ Ἀθηναίους εἶναι [ἡμᾶς], ἐγώ σοι τούτου ὅλως τοὐναντίον ἐπιδείξω, ὅτι οὐκ ἔξεστιν ξένῳ ἐν τῇ ἀγορᾷ ἐργάζεσθαι. καί μοι λαβὼν ἀνάγνωθι πρῶτον τὸν Σόλωνος νόμον.", "st": "57.31"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "57.31"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὸν Ἀριστοφῶντος· οὕτω γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον ἔδοξεν ἐκεῖνος καλῶς καὶ δημοτικῶς νομοθετῆσαι, ὥστ’ ἐψηφίσασθε πάλιν ἀνανεώσασθαι.", "st": "57.32"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "57.32"}, {"sp": "N", "t": "προσήκει τοίνυν ὑμῖν βοηθοῦσι τοῖς νόμοις μὴ τοὺς ἐργαζομένους ξένους νομίζειν, ἀλλὰ τοὺς συκοφαντοῦντας πονηρούς. ἐπεί, ὦ Εὐβουλίδη, ἔστι καὶ ἕτερος περὶ τῆς ἀργίας νόμος, ᾧ αὐτὸς ἔνοχος ὢν ἡμᾶς τοὺς ἐργαζομένους διαβάλλεις.", "st": "57.32"}, {"sp": "N", "t": "ἀλλὰ γὰρ τοσαύτη τις ἀτυχία ἐστὶν περὶ ἡμᾶς νῦν, ὥστε τούτῳ μὲν ἔξεστιν ἔξω τοῦ πράγματος βλασφημεῖν καὶ πάντα ποιεῖν, ὅπως μηδενὸς τῶν δικαίων ἐγὼ τύχω· ἐμοὶ δ’ ἐπιτιμήσετ’ ἴσως, ἐὰν λέγω ὃν τρόπον οὗτος ἐργάζεται περιιὼν ἐν τῇ πόλει, καὶ εἰκότως· ἃ γὰρ ὑμεῖς ἴστε, τί δεῖ λέγειν; σκοπεῖτε δή· νομίζω γὰρ ἔγωγε τὸ ἐν τῇ ἀγορᾷ ἡμᾶς ἐργάζεσθαι μέγιστον εἶναι σημεῖον τοῦ ψευδεῖς ἡμῖν αἰτίας τοῦτον ἐπιφέρειν. ἣν γάρ φησιν ταινιόπωλιν εἶναι καὶ φανερὰν πᾶσιν,", "st": "57.33"}, {"sp": "N", "t": "προσῆκεν δήπουθεν εἰδότας αὐτὴν πολλοὺς ἥτις ἐστὶ μαρτυρεῖν, καὶ μὴ μόνον ἀκοήν, ἀλλ’ εἰ μὲν ξένη ἦν, τὰ τέλη ἐξετάσαντας τὰ ἐν τῇ ἀγορᾷ, εἰ ξενικὰ ἐτέλει, καὶ ποδαπὴ ἦν ἐπιδεικνύντας· εἰ δὲ δούλη, μάλιστα μὲν τὸν πριάμενον, εἰ δὲ μή, τὸν ἀποδόμενον ἥκειν καταμαρτυροῦντα, εἰ δὲ μή, τῶν ἄλλων τινά, ἢ ὡς ἐδούλευσεν ἢ ὡς ἀφείθη ἐλευθέρα. νῦν δὲ τούτων μὲν ἀπέδειξεν οὐδέν, λελοιδόρηκεν δέ, ὡς ἐμοὶ δοκεῖ, οὐδὲν ὅ τι οὔ. τοῦτο γάρ ἐστιν ὁ συκοφάντης, αἰτιᾶσθαι μὲν πάντα, ἐξελέγξαι δὲ μηδέν.", "st": "57.34"}, {"sp": "N", "t": "ἐπεὶ κἀκεῖνο περὶ τῆς μητρὸς εἴρηκεν, ὅτι ἐτίτθευσεν. ἡμεῖς δέ, ὅθ’ ἡ πόλις ἠτύχει καὶ πάντες κακῶς ἔπραττον, οὐκ ἀρνούμεθα τοῦτο γενέσθαι· ὃν δὲ τρόπον καὶ ὧν ἕνεκ’ ἐτίτθευσεν, ἐγὼ σαφῶς ὑμῖν ἐπιδείξω. μηδεὶς δ’ ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, δυσχερῶς ὑπολάβῃ· καὶ γὰρ νῦν ἀστὰς γυναῖκας πολλὰς εὑρήσετε τιτθευούσας, ἃς ὑμῖν καὶ κατ’ ὄνομα, ἐὰν βούλησθε, ἐροῦμεν. εἰ δέ γε πλούσιοι ἦμεν, οὔτ’ ἂν τὰς ταινίας ἐπωλοῦμεν οὔτ’ ἂν ὅλως ἦμεν ἄποροι. ἀλλὰ τί ταῦτα κοινωνεῖ τῷ γένει;", "st": "57.35"}, {"sp": "N", "t": "ἐγὼ μὲν οὐδὲν οἶμαι. μηδαμῶς, ὦ ἄνδρες δικασταί, τοὺς πένητας ἀτιμάζετε (ἱκανὸν γὰρ αὐτοῖς τὸ πένεσθαι κακόν), μηδέ γε τοὺς ἐργάζεσθαι καὶ ζῆν ἐκ τοῦ δικαίου προαιρουμένους· ἀλλ’ ἀκούσαντες, ἐὰν ὑμῖν ἐπιδεικνύω τῆς μητρὸς τοὺς οἰκείους οἵους προσήκει εἶναι ἀνθρώποις ἐλευθέροις, ἃ καταιτιᾶται περὶ αὐτῆς, ταύτας τὰς διαβολὰς ἐξομνυμένους, καὶ μαρτυροῦντας αὐτὴν ἀστὴν οὖσαν εἰδέναι, οὓς ὑμεῖς φήσετε πιστοὺς εἶναι, δικαίαν ἡμῖν θέσθε τὴν ψῆφον.", "st": "57.36"}, {"sp": "N", "t": "ἐμοὶ γὰρ ἦν πάππος, ὦ ἄνδρες Ἀθηναῖοι, τῆς μητρὸς πατήρ, Δαμόστρατος Μελιτεύς. τούτῳ γίγνονται τέτταρες παῖδες, ἐκ μὲν ἧς τὸ πρῶτον ἔσχεν γυναικὸς θυγάτηρ καὶ υἱὸς ᾧ ὄνομ’ Ἀμυθέων, ἐκ δὲ τῆς ὕστερον, Χαιρεστράτης, ἡ μήτηρ ἡ ἐμὴ καὶ Τιμοκράτης. τούτοις δὲ γίγνονται παῖδες, τῷ μὲν Ἀμυθέωνι Δαμόστρατος, τοῦ πάππου τοὔνομ’ ἔχων, καὶ Καλλίστρατος καὶ Δεξίθεος. καὶ ὁ μὲν Ἀμυθέων ὁ τῆς μητρὸς ἀδελφὸς τῶν ἐν Σικελίᾳ στρατευσαμένων καὶ τελευτησάντων ἐστίν, καὶ τέθαπται ἐν τοῖς δημοσίοις μνήμασιν· καὶ ταῦτα μαρτυρήσεται.", "st": "57.37"}, {"sp": "N", "t": "τῇ δ’ ἀδελφῇ αὐτοῦ συνοικησάσῃ Διοδώρῳ Ἁλαιεῖ υἱὸς γίγνεται Κτησίβιος. καὶ οὗτος μὲν ἐτελεύτησεν ἐν Ἀβύδῳ μετὰ Θρασυβούλου στρατευόμενος, ζῇ δὲ τούτων ὁ Δαμόστρατος ὁ τοῦ Ἀμυθέωνος, τῆς μητρὸς ἀδελφιδοῦς τῆς ἐμῆς. τῆς δὲ Χαιρεστράτης τῆς ἐμῆς τήθης τὴν ἀδελφὴν λαμβάνει Ἀπολλόδωρος Πλωθεύς· τούτων γίγνεται Ὀλύμπιχος, τοῦ δ’ Ὀλυμπίχου Ἀπολλόδωρος, καὶ οὗτος ζῇ. καί μοι κάλει αὐτούς.", "st": "57.38"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.38"}, {"sp": "N", "t": "τούτων μὲν τοίνυν ἀκηκόατε μαρτυρούντων καὶ διομνυμένων· τὸν δὲ [καὶ ὁμομήτριον] καὶ κατ’ ἀμφότερ’ ἡμῖν συγγενῆ καλῶ, καὶ τοὺς υἱεῖς αὐτοῦ. τῷ γὰρ Τιμοκράτει τῷ τῆς μητρὸς ἀδελφῷ τῆς ἐμῆς τῷ ὁμοπατρίῳ καὶ ὁμομητρίῳ γίγνεται Εὐξίθεος, τοῦ δ’ Εὐξιθέου τρεῖς υἱεῖς· οὗτοι πάντες ζῶσιν. καί μοι κάλει τοὺς ἐπιδημοῦντας αὐτῶν.", "st": "57.39"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.39"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τὰς τῶν φρατέρων τῶν συγγενῶν τῶν τῆς μητρὸς καὶ δημοτῶν μαρτυρίας, καὶ ὧν τὰ μνήματα ταὐτά.", "st": "57.40"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "57.40"}, {"sp": "N", "t": "τὰ μὲν τοίνυν τοῦ γένους τοῦ τῆς μητρὸς οὕτως ὑμῖν ἐπιδεικνύω, καὶ πρὸς ἀνδρῶν καὶ πρὸς γυναικῶν ἀστήν. τῇ δὲ μητρὶ τῇ ἐμῇ γίγνεται, ὦ ἄνδρες δικασταί, τὸ μὲν πρῶτον ἐκ Πρωτομάχου, ᾧ αὐτὴν ὁ Τιμοκράτης ὁμομήτριος καὶ ὁμοπάτριος ὢν ἀδελφὸς ἔδωκεν, θυγάτηρ, εἶτ’ ἐκ τοῦ πατρὸς τοῦ ἐμοῦ ἐγώ. ὃν δὲ τρόπον τῷ πατρὶ τῷ ἐμῷ συνῴκησεν, ταῦθ’ ὑμᾶς ἀκοῦσαι δεῖ· καὶ γὰρ ἃ περὶ τὸν Κλεινίαν αἰτιᾶται καὶ τὸ τιτθεῦσαι τὴν μητέρα καὶ ταῦτα πάντ’ ἐγὼ σαφῶς ὑμῖν διηγήσομαι.", "st": "57.40"}, {"sp": "N", "t": "ὁ Πρωτόμαχος πένης ἦν· ἐπικλήρου δὲ κληρονομήσας εὐπόρου, τὴν μητέρα βουληθεὶς ἐκδοῦναι πείθει λαβεῖν αὐτὴν Θούκριτον τὸν πατέρα τὸν ἐμόν, ὄνθ’ ἑαυτοῦ γνώριμον, καὶ ἐγγυᾶται ὁ πατὴρ τὴν μητέρα τὴν ἐμὴν παρὰ τοῦ ἀδελφοῦ αὐτῆς Τιμοκράτους Μελιτέως, παρόντων τῶν τε θείων ἀμφοτέρων τῶν ἑαυτοῦ καὶ ἄλλων μαρτύρων· καὶ τούτων ὅσοι ζῶσι, μαρτυρήσουσιν ὑμῖν.", "st": "57.41"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα χρόνῳ ὕστερον παιδίων αὐτῇ δυοῖν ἤδη γεγενημένων, καὶ τοῦ μὲν πατρὸς στρατευομένου καὶ ἀποδημοῦντος μετὰ Θρασυβούλου, αὐτὴ δ’ οὖσ’ ἐν ἀπορίαις ἠναγκάσθη τὸν Κλεινίαν τὸν τοῦ Κλειδίκου τιτθεῦσαι, τῷ μὲν εἰς ἔμ’ ἥκοντι κινδύνῳ νῦν μὰ τὸν Δι’ οὐχὶ συμφέρον πρᾶγμα ποιήσασα (ἀπὸ γὰρ ταύτης τῆς τιτθείας ἅπασ’ ἡ περὶ ἡμᾶς γέγονεν βλασφημία), τῇ μέντοι ὑπαρχούσῃ πενίᾳ ἴσως καὶ ἀναγκαῖα καὶ ἁρμόττοντα ποιοῦσα.", "st": "57.42"}, {"sp": "N", "t": "φαίνεται τοίνυν οὐχ ὁ ἐμὸς πατὴρ πρῶτος, ὦ ἄνδρες Ἀθηναῖοι, λαβὼν τὴν ἐμὴν μητέρα, ἀλλ’ ὁ Πρωτόμαχος, καὶ παῖδας ποιησάμενος καὶ θυγατέρ’ ἐκδούς· ὃς καὶ τετελευτηκὼς ὅμως μαρτυρεῖ τοῖς ἔργοις ἀστήν τ’ αὐτὴν καὶ πολῖτιν εἶναι. ὡς οὖν ταῦτ’ ἀληθῆ λέγω, κάλει μοι πρῶτον μὲν τοὺς τοῦ Πρωτομάχου υἱεῖς, ἔπειτα τοὺς ἐγγυωμένῳ παρόντας τῷ πατρὶ καὶ τῶν φρατέρων τοὺς οἰκείους, οἷς τὴν γαμηλίαν εἰσήνεγκεν ὑπὲρ τῆς μητρὸς ὁ πατήρ, εἶτ’ Εὔνικον Χολαργέα τὸν τὴν ἀδελφὴν λαβόντα τὴν ἐμὴν παρὰ τοῦ Πρωτομάχου, εἶτα τὸν υἱὸν τῆς ἀδελφῆς. κάλει τούτους.", "st": "57.43"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.43"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἂν οἰκτρότατ’, ὦ ἄνδρες Ἀθηναῖοι, πάντων ἐγὼ πεπονθὼς εἴην, εἰ τῶν συγγενῶν ὄντων τοσούτων τουτωνὶ καὶ μαρτυρούντων καὶ διομνυμένων ἐμοὶ προσήκειν, μηδεὶς μηδενὶ τούτων ἀμφισβητῶν ὡς οὐκ εἰσὶ πολῖται, ἐμὲ ψηφίσαισθ’ εἶναι ξένον; λαβὲ δή μοι καὶ τὴν τοῦ Κλεινίου καὶ τὴν τῶν συγγενῶν αὐτοῦ μαρτυρίαν· οἳ ἴσασιν δήπου τίς οὖσά ποθ’ ἡ ἐμὴ μήτηρ ἐτίτθευσεν αὐτόν. οὐ γὰρ ἃ τήμερον ἡμεῖς φαμέν, εὔορκον αὐτοῖς μαρτυρεῖν, ἀλλ’ ἃ πάντα τὸν χρόνον ᾔδεσαν τὴν ἡμετέραν μὲν μητέρα, τιτθὴν δὲ τούτου νομιζομένην.", "st": "57.44"}, {"sp": "N", "t": "καὶ γὰρ εἰ ταπεινὸν ἡ τιτθή, τὴν ἀλήθειαν οὐ φεύγω· οὐ γὰρ εἰ πένητες ἦμεν, ἠδικήκαμεν, ἀλλ’ εἰ μὴ πολῖται· οὐδὲ περὶ τύχης οὐδὲ περὶ χρημάτων ἡμῖν ἐστὶν ὁ παρὼν ἀγών, ἀλλ’ ὑπὲρ γένους. πολλὰ δουλικὰ καὶ ταπεινὰ πράγματα τοὺς ἐλευθέρους ἡ πενία βιάζεται ποιεῖν, ἐφ’ οἷς ἐλεοῖντ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, δικαιότερον ἢ προσαπολλύοιντο. ὡς γὰρ ἐγὼ ἀκούω, πολλαὶ καὶ τιτθαὶ καὶ ἔριθοι καὶ τρυγήτριαι γεγόνασιν ὑπὸ τῶν τῆς πόλεως κατ’ ἐκείνους τοὺς χρόνους συμφορῶν ἀσταὶ γυναῖκες, πολλαὶ δ’ ἐκ πενήτων πλούσιαι νῦν. ἀλλ’ αὐτίχ’ ὑπὲρ τούτων. νῦν δὲ τοὺς μάρτυρας κάλει.", "st": "57.45"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.45"}, {"sp": "N", "t": "οὐκοῦν ὅτι μὲν καὶ τὰ πρὸς μητρός εἰμ’ ἀστὸς καὶ τὰ πρὸς πατρός, τὰ μὲν ἐξ ὧν ἄρτι μεμαρτύρηται μεμαθήκατε πάντες, τὰ δ’ ἐξ ὧν πρότερον περὶ τοῦ πατρός. λοιπὸν δέ μοι περὶ ἐμαυτοῦ πρὸς ὑμᾶς εἰπεῖν, τὸ μὲν ἁπλούστατον οἶμαι καὶ δικαιότατον, ἐξ ἀμφοτέρων ἀστῶν ὄντα με, κεκληρονομηκότα καὶ τῆς οὐσίας καὶ τοῦ γένους, εἶναι πολίτην· οὐ μὴν ἀλλὰ καὶ τὰ προσήκοντα πάντ’ ἐπιδείξω μάρτυρας παρεχόμενος, ὡς εἰσήχθην εἰς τοὺς φράτερας, ὡς ἐνεγράφην εἰς τοὺς δημότας, ὡς ὑπ’ αὐτῶν τούτων προὐκρίθην ἐν τοῖς εὐγενεστάτοις κληροῦσθαι τῆς ἱερωσύνης τῷ Ἡρακλεῖ, ὡς ἦρχον ἀρχὰς δοκιμασθείς. καί μοι κάλει αὐτούς.", "st": "57.46"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "57.46"}, {"sp": "N", "t": "οὔκουν δεινόν, ὦ ἄνδρες δικασταί, εἰ μὲν ἔλαχον ἱερεύς, ὥσπερ προὐκρίθην, δεῖν ἄν με καὶ αὐτὸν θύειν ὑπὲρ τούτων καὶ τοῦτον μετ’ ἐμοῦ συνθύειν, νῦν δὲ τοὺς αὐτοὺς τούτους ἐμὲ μεθ’ αὑτῶν μηδὲ συνθύειν ἐᾶν; φαίνομαι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τὸν μὲν ἄλλον χρόνον ἅπαντα παρὰ πᾶσιν τοῖς νῦν κατηγοροῦσι πολίτης ὡμολογημένος·", "st": "57.47"}, {"sp": "N", "t": "οὐ γὰρ ἂν δήπου τόν γε ξένον καὶ μέτοικον, ὡς νῦν φησιν Εὐβουλίδης, οὔτ’ ἀρχὰς ἄρχειν οὔθ’ ἱερωσύνην κληροῦσθαι μεθ’ ἑαυτοῦ προκριθέντ’ εἴασεν· καὶ γὰρ οὗτος ἦν τῶν κληρουμένων καὶ προκριθέντων. οὐδέ γ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, παλαιὸς ὢν ἐχθρὸς ἐμοὶ τοῦτον τὸν καιρὸν περιέμενεν, ὃν οὐδεὶς ᾔδει γενησόμενον, εἴπερ τι συνῄδει τοιοῦτον.", "st": "57.48"}, {"sp": "N", "t": "ἀλλ’ οὐ συνῄδει· διόπερ τὸν μὲν ἄλλον ἅπαντα χρόνον δημοτευόμενος μετ’ ἐμοῦ καὶ κληρούμενος οὐδὲν ἑώρα τούτων, ἐπειδὴ δ’ ἡ πόλις πᾶσα τοῖς ἀσελγῶς εἰσπεπηδηκόσιν εἰς τοὺς δήμους ὀργιζομένη παρώξυντο, τηνικαῦτα μοι ἐπεβούλευσεν. ἦν δ’ ἐκεῖνος μὲν ὁ καιρὸς τοῦ συνειδότος αὑτῷ τἀληθῆ λέγειν, ὁ δὲ νυνὶ παρὼν ἐχθροῦ καὶ συκοφαντεῖν βουλομένου.", "st": "57.49"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί (καί μοι πρὸς Διὸς καὶ θεῶν μηδεὶς θορυβήσῃ, μηδ’ ἐφ’ ᾧ μέλλω λέγειν ἀχθεσθῇ), ἐμαυτὸν Ἀθηναῖον ὑπείληφ’ ὥσπερ ὑμῶν ἕκαστος ἑαυτόν, μητέρ’ ἐξ ἀρχῆς νομίζων ἥνπερ εἰς ὑμᾶς ἀποφαίνω, καὶ οὐχ ἑτέρας μὲν ὢν ταύτης δὲ προσποιούμενος· πατέρα πάλιν, ὦ ἄνδρες Ἀθηναῖοι, τὸν αὐτὸν τρόπον.", "st": "57.50"}, {"sp": "N", "t": "καίτοι εἰ τοῖς ἐξελεγχομένοις ὧν μέν εἰσιν ἀποκρυπτομένοις, ὧν δ’ οὐκ εἰσὶν προσποιουμένοις, δίκαιον ὑπάρχειν παρ’ ὑμῖν τοῦτο σημεῖον ὡς εἰσὶ ξένοι, ἐμοὶ δήπου τοὐναντίον ὡς εἰμὶ πολίτης. οὐ γὰρ ἂν ξένην καὶ ξένον τοὺς ἐμαυτοῦ γονέας ἐπιγραψάμενος μετέχειν ἠξίουν τῆς πόλεως· ἀλλ’ εἴ τι τοιοῦτον συνῄδειν, ἐζήτησ’ ἂν ὧν φήσω γονέων εἶναι. ἀλλ’ οὐ συνῄδειν, διόπερ μένων ἐπὶ τοῖς οὖσιν δικαίως γονεῦσιν ἐμαυτῷ τῆς πόλεως μετέχειν ἀξιῶ.", "st": "57.51"}, {"sp": "N", "t": "ἔτι τοίνυν ὀρφανὸς κατελείφθην, καὶ φασίν μ’ εὔπορον εἶναι καὶ τῶν μαρτύρων ἐνίους ὠφελουμένους μοι μαρτυρεῖν συγγενεῖς εἶναι. καὶ ἅμα μὲν κατ’ ἐμοῦ λέγουσιν τὰς ἐκ τῆς πενίας ἀδοξίας καὶ περὶ τὸ γένος διαβάλλουσιν, ἅμα δὲ δι’ εὐπορίαν φασὶ πάντα μ’ ὠνεῖσθαι.", "st": "57.52"}, {"sp": "N", "t": "ὥστε πότερα χρὴ αὐτοῖς πιστεύειν; ἐξῆν δὲ δήπου τούτοις, εἰ νόθος ἢ ξένος ἦν ἐγώ, κληρονόμοις εἶναι τῶν ἐμῶν πάντων. εἶθ’ οὗτοι μικρὰ λαμβάνειν καὶ κινδυνεύειν ἐν ψευδομαρτυρίοις καὶ ἐπιορκεῖν μᾶλλον αἱροῦνται ἢ πάντ’ ἔχειν, καὶ ταῦτ’ ἀσφαλῶς, καὶ μηδεμιᾶς ἐξωλείας ὑπόχους ἑαυτοὺς ποιεῖν; οὐκ ἔστι ταῦτα, ἀλλ’ οἶμαι συγγενεῖς ὄντες τὰ δίκαια ποιοῦσι, βοηθοῦντες αὑτῶν ἑνί.", "st": "57.53"}, {"sp": "N", "t": "καὶ ταῦτ’ οὐχὶ νῦν πεπεισμένοι ποιοῦσιν, ἀλλὰ παιδίον ὄντα μ’ εὐθέως ἦγον εἰς τοὺς φράτερας, εἰς Ἀπόλλωνος πατρῴου [ἦγον], εἰς τἄλλ’ ἱερά. καίτοι οὐ δήπου παῖς ὢν ἐγὼ ταῦτ’ ἔπειθον αὐτοὺς ἀργύριον διδούς. ἀλλὰ μὴν ὁ πατὴρ αὐτὸς ζῶν ὀμόσας τὸν νόμιμον τοῖς φράτερσιν ὅρκον εἰσήγαγέν με, ἀστὸν ἐξ ἀστῆς ἐγγυητῆς αὑτῷ γεγενημένον εἰδώς, καὶ ταῦτα μεμαρτύρηται.", "st": "57.54"}, {"sp": "N", "t": "εἶτ’ ἐγὼ ξένος; ποῦ μετοίκιον καταθείς; ἢ τίς τῶν ἐμῶν πώποτε; ποῦ πρὸς ἄλλους δημότας ἐλθών, καὶ οὐ δυνηθεὶς ἐκείνους πεῖσαι δεῦρ’ ἐμαυτὸν ἐνέγραψα; ποῦ τί ποιήσας ὧν ὅσοι μὴ καθαρῶς ἦσαν πολῖται πεποιηκότες φαίνονται; οὐδαμοῦ, ἀλλ’ ἁπλῶς, ἐν οἷς ὁ πάππος ὁ τοῦ πατρός, ὁ ἐμός, ⟨ὁ⟩ πατήρ, ἐνταῦθα καὶ αὐτὸς φαίνομαι δημοτευόμενος. καὶ νῦν πῶς ἄν τις ὑμῖν σαφέστερον ἐπιδείξειεν μετὸν τῆς πόλεως αὑτῷ;", "st": "57.55"}, {"sp": "N", "t": "ἐνθυμείσθω γὰρ ἕκαστος ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, τοὺς ἑαυτῷ προσήκοντας τίν’ ἄλλον ἂν δύναιτ’ ἐπιδεῖξαι τρόπον ἢ τὸν αὐτὸν ἐμοί, μαρτυροῦντας, ὀμνύοντας, πάλαι τοὺς αὐτοὺς ἀπὸ τῆς ἀρχῆς ὄντας;", "st": "57.56"}, {"sp": "N", "t": "διὰ ταῦτα τοίνυν ἐγὼ πιστεύων ἐμαυτῷ κατέφυγον εἰς ὑμᾶς. ὁρῶ γάρ, ὦ ἄνδρες Ἀθηναῖοι, οὐ μόνον τῶν ἀποψηφισαμένων Ἁλιμουσίων ἐμοῦ κυριώτερ’ ὄντα τὰ δικαστήρια, ἀλλὰ καὶ τῆς βουλῆς καὶ τοῦ δήμου, δικαίως· κατὰ γὰρ πάνθ’ αἱ παρ’ ὑμῖν εἰσι κρίσεις δικαιόταται.", "st": "57.56"}, {"sp": "N", "t": "ἐνθυμεῖσθε τοίνυν κἀκεῖνο, ὅσοι τῶν μεγάλων δήμων ἐστέ, ὡς οὐδέν’ ἀπεστερεῖτ’ οὔτε κατηγορίας οὔτ’ ἀπολογίας. καὶ πόλλ’ ἀγαθὰ γένοιτο πᾶσιν ὑμῖν τοῖς δικαίως τούτῳ τῷ πράγματι χρησαμένοις, ὅτι καὶ τῶν ἀναβαλέσθαι δεομένων οὐκ ἀφῄρησθε τὸ παρασκευάσασθαι· ᾧ καὶ τοὺς συκοφαντοῦντας καὶ δι’ ἔχθραν ἐπιβουλεύοντας ἐξηλέγχετε.", "st": "57.57"}, {"sp": "N", "t": "καὶ ὑμᾶς μὲν ἄξιον ἐπαινεῖν, ὦ ἄνδρες Ἀθηναῖοι, τοὺς δὲ καλῷ καὶ δικαίῳ πράγματι μὴ καλῶς χρησαμένους ψέγειν. ἐν οὐδενὶ τοίνυν εὑρήσετε τῶν δήμων δεινότερα γεγενημένα τῶν παρ’ ἡμῖν. οὗτοι γὰρ ἀδελφῶν ὁμομητρίων καὶ ὁμοπατρίων τῶν μέν εἰσιν ἀπεψηφισμένοι, τῶν δ’ οὔ, καὶ πρεσβυτέρων ἀνθρώπων ἀπόρων, ὧν τοὺς υἱεῖς ἐγκαταλελοίπασιν· καὶ τούτων ἂν βούλησθε, μάρτυρας παρέξομαι.", "st": "57.58"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον οἱ συνεστηκότες πεποιήκασιν (καί μοι πρὸς Διὸς καὶ θεῶν μηδεὶς ὑπολάβῃ δυσκόλως, ἐὰν τοὺς ἠδικηκότας ἐμαυτὸν πονηροὺς ὄντας ἐπιδεικνύω· νομίζω γὰρ ὑμῖν τὴν τούτων πονηρίαν δεικνὺς εἰς αὐτὸ τὸ πρᾶγμα λέγειν τὸ γενόμενόν μοι)· οὗτοι γάρ, ὦ ἄνδρες Ἀθηναῖοι, βουλομένους τινὰς ἀνθρώπους ξένους πολίτας γενέσθαι, Ἀναξιμένην καὶ Νικόστρατον, κοινῇ διανειμάμενοι πέντε δραχμὰς ἕκαστος προσεδέξαντο. καὶ ταῦτ’ οὐκ ἂν ἐξομόσαιτ’ Εὐβουλίδης οὐδ’ οἱ μετ’ αὐτοῦ μὴ οὐκ εἰδέναι. καὶ νῦν τούτων οὐκ ἀπεψηφίσαντο. τί οὖν οὐκ ἂν οἴεσθε τούτους ἰδίᾳ ποιῆσαι, οἳ κοινῇ ταῦτ’ ἐτόλμων;", "st": "57.59"}, {"sp": "N", "t": "πολλούς, ὦ ἄνδρες δικασταί, οἱ μετ’ Εὐβουλίδου συνεστῶτες καὶ ἀπολωλέκασιν καὶ σεσῴκασιν ἕνεκ’ ἀργυρίου. ἐπεὶ καὶ τὸ πρότερον (ἐρῶ δ’ εἰς αὐτὸ τὸ πρᾶγμ’, ὦ ἄνδρες Ἀθηναῖοι) δημαρχῶν ὁ Εὐβουλίδου πατήρ, ὥσπερ εἶπον, Ἀντίφιλος, τεχνάζει βουλόμενος παρά τινων λαβεῖν ἀργύριον, καὶ ἔφη τὸ κοινὸν γραμματεῖον ἀπολωλέναι, ὥστ’ ἔπεισε διαψηφίσασθαι τοὺς Ἁλιμουσίους περὶ αὑτῶν, καὶ κατηγορῶν δέκα τῶν δημοτῶν ἐξέβαλεν, οὓς ἅπαντας πλὴν ἑνὸς κατεδέξατο τὸ δικαστήριον. καὶ ταῦτα πάντες ἴσασιν οἱ πρεσβύτεροι.", "st": "57.60"}, {"sp": "N", "t": "πολλοῦ γ’ ἔδεόν τινας ἐγκαταλιπεῖν τῶν μὴ Ἀθηναίων, ὅπου καὶ τοὺς ὄντας πολίτας συνιστάμενοι ἐξέβαλον, οὓς τὸ δικαστήριον κατεδέξατο. καὶ ὢν ἐχθρὸς τῷ ἐμῷ πατρὶ τότ’ οὐ μόνον οὐ κατηγόρησεν, ἀλλ’ οὐδὲ τὴν ψῆφον ἤνεγκεν ὡς οὐκ ἦν Ἀθηναῖος. τῷ τοῦτο δῆλον; ὅτι ἁπάσαις ἔδοξεν δημότης εἶναι. καὶ τί δεῖ περὶ τῶν πατέρων λέγειν; ἀλλ’ Εὐβουλίδης αὐτὸς οὑτοσί, ἡνίκ’ ἐνεγράφην ἐγὼ καὶ ὀμόσαντες οἱ δημόται δικαίως πάντες περὶ ἐμοῦ τὴν ψῆφον ἔφερον, οὔτε κατηγόρησεν οὔτ’ ἐναντίαν τὴν ψῆφον ἤνεγκεν· καὶ γὰρ ἐνταῦθα πάλιν ἐμὲ πάντες ἐψηφίσαντο δημότην. καὶ εἴ φασίν με τοῦτο ψεύδεσθαι, ἐπὶ τοῦ ἐμοῦ ὕδατος ὅστις βούλεται τούτων τἀναντία μαρτυρησάτω.", "st": "57.61"}, {"sp": "N", "t": "εἰ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο δοκοῦσιν οὗτοι λέγειν μάλιστ’ ἰσχυρόν, ὡς ἀπεψηφίσαντό μου νῦν οἱ δημόται, ἐγὼ τετράκις ἐπιδεικνύω πρότερον, ὅθ’ ὁσίως ἄνευ συστάσεως ἐψηφίσαντο, καὶ ἐμὲ καὶ τὸν πατέρα δημότας αὑτῶν εἶναι ψηφισαμένους, πρῶτον μέν γε τοῦ πατρὸς δοκιμασθέντος, εἶτ’ ἐμοῦ, εἶτ’ ἐν τῇ προτέρᾳ διαψηφίσει, ὅτ’ ἠφάνισαν οὗτοι τὸ γραμματεῖον· τὸ δὲ τελευταῖον προκρίναντες ἐμὲ ἐψηφίσαντ’ ἐν τοῖς εὐγενεστάτοις κληροῦσθαι τῆς ἱερωσύνης τῷ Ἡρακλεῖ. καὶ ταῦτα πάντα μεμαρτύρηται.", "st": "57.62"}, {"sp": "N", "t": "εἰ δὲ δεῖ τὴν δημαρχίαν λέγειν, δι’ ἣν ὠργίζοντό μοί τινες, ἐν ᾗ διάφορος ἐγενόμην εἰσπράττων ὀφείλοντας πολλοὺς αὐτῶν μισθώσεις τεμενῶν καὶ ἕτερ’ ἃ τῶν κοινῶν διηρπάκεσαν, ἐγὼ μὲν ἂν βουλοίμην ὑμᾶς ἀκούειν, ἀλλ’ ἴσως ἔξω τοῦ πράγματος ὑπολήψεσθε ταῦτ’ εἶναι. ἐπεὶ καὶ τοῦτ’ ἔχω δεικνύναι τεκμήριον ὡς συνέστησαν· ἔκ τε γὰρ τοῦ ὅρκου ἐξήλειψαν τὸ ψηφιεῖσθαι γνώμῃ τῇ δικαιοτάτῃ καὶ οὔτε χάριτος ἕνεκ’ οὔτ’ ἔχθρας·", "st": "57.63"}, {"sp": "N", "t": "καὶ γὰρ τοῦτο φανερὸν ἐγένετο καὶ ὅτι ἱεροσυλήσαντες τὰ ὅπλα (εἰρήσεται γάρ), ἃ ἐγὼ ἀνέθηκα τῇ Ἀθηνᾷ, καὶ τὸ ψήφισμ’ ἐκκολάψαντες ὃ ἐμοὶ ἐψηφίσανθ’ οἱ δημόται, συνώμνυον οὗτοι ἐπ’ ἐμὲ οἱ ὑπ’ ἐμοῦ τὰ κοινὰ εἰσπραχθέντες. καὶ εἰς τοσοῦτ’ ἀναιδείας ἐληλύθασιν, ὥστ’ ἔλεγον περιιόντες ἐμὲ τῆς ἀπολογίας ἕνεκα ταῦτα ποιῆσαι. καὶ τίς ὑμῶν ἂν καταγνοίη μου τοσαύτην μανίαν, ὦ ἄνδρες δικασταί, ὥστε τηλικούτων ἕνεκα πρὸς τὸ πρᾶγμα τεκμηρίων ἄξια θανάτου διαπράξασθαι, καὶ ἃ ἐμοὶ φιλοτιμίαν ἔφερεν, ταῦτ’ ἀφανίζειν;", "st": "57.64"}, {"sp": "N", "t": "τὸ δὲ πάντων δεινότατον οὐ δήπου γε φήσαιεν ἂν ἐμὲ κατασκευάσαι. οὐ γὰρ ἔφθη μοι συμβᾶσ’ ἡ ἀτυχία καὶ εὐθύς, ὥσπερ φυγάδος ἤδη μου ὄντος καὶ ἀπολωλότος, τούτων τινὲς ἐπὶ τὸ οἰκίδιον ἐλθόντες ⟨τὸ⟩ ἐν ἀγρῷ νύκτωρ ἐπεχείρησαν διαφορῆσαι τὰ ἔνδοθεν· οὕτω σφόδρ’ ὑμῶν καὶ τῶν νόμων κατεφρόνησαν. καὶ ταῦτα τοὺς εἰδότας, ἐὰν βούλησθε, καλοῦμεν.", "st": "57.65"}, {"sp": "N", "t": "πολλὰ δ’ ἔχων καὶ ἄλλ’ ἐπιδεῖξαι, ἃ τούτοις ἐστὶν διαπεπραγμένα καὶ ἅ εἰσιν ἐψευσμένοι, ἡδέως μὲν ἂν ὑμῖν λέγοιμι, ἐπειδὴ δ’ ἔξω τοῦ πράγματος νομίζετ’ εἶναι, ἐάσω. ἀναμνήσθητε δ’ ἐκείνων καὶ θεάσασθε, ὡς πολλὰ καὶ δίκαι’ ἔχων πρὸς ὑμᾶς ἥκω. ὥσπερ γὰρ τοὺς θεσμοθέτας ἀνακρίνετε, ἐγὼ τὸν αὐτὸν τρόπον ἐμαυτὸν ὑμῖν ἀνακρινῶ.", "st": "57.66"}, {"sp": "N", "t": "“ὦ ἄνθρωπε, τίς ἦν σοι πατήρ;” ἐμοί; Θούκριτος. “οἰκεῖοί τινες εἶναι μαρτυροῦσιν αὐτῷ;” πάνυ γε, πρῶτον μέν γε τέτταρες ἀνεψιοί, εἶτ’ ἀνεψιαδοῦς, εἶθ’ οἱ τὰς ἀνεψιὰς λαβόντες αὐτῷ, εἶτα φράτερες, εἶτ’ Ἀπόλλωνος πατρῴου καὶ Διὸς ἑρκείου γεννῆται, εἶθ’ οἷς ἠρία ταὐτά, εἶθ’ οἱ δημόται πολλάκις αὐτὸν δεδοκιμάσθαι καὶ ἀρχὰς ἄρξαι, καὶ αὐτοὶ διεψηφισμένοι φαίνονται. τὰ μὲν τοίνυν περὶ τοῦ πατρὸς πῶς ἂν ὑμῖν δικαιότερον ἢ καθαρώτερον ἐπιδείξαιμι; καλῶ δ’ ὑμῖν τοὺς οἰκείους, εἰ βούλεσθε. τὰ δὲ περὶ τῆς μητρὸς ἀκούσατε.", "st": "57.67"}, {"sp": "N", "t": "ἐμοὶ γάρ ἐστιν μήτηρ Νικαρέτη Δαμοστράτου θυγάτηρ Μελιτέως. ταύτης τίνες οἰκεῖοι μαρτυροῦσιν; πρῶτον μὲν ἀδελφιδοῦς, εἶτα τοῦ ἑτέρου ἀδελφιδοῦ δύ’ υἱοί, εἶτ’ ἀνεψιαδοῦς, εἶθ’ οἱ Πρωτομάχου υἱεῖς τοῦ λαβόντος τὴν ἐμὴν μητέρα πρότερον, εἶθ’ ὁ τὴν ἀδελφὴν τὴν ἐμὴν τὴν ἐκ τοῦ Πρωτομάχου γήμας Εὔνικος Χολαργεύς, εἶθ’ υἱὸς τῆς ἀδελφῆς.", "st": "57.68"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ φράτερες τῶν οἰκείων αὐτῆς καὶ δημόται ταῦτα μεμαρτυρήκασι. τίνος οὖν ἂν προσδέοισθε; καὶ γὰρ ὅτι κατὰ τοὺς νόμους ὁ πατὴρ ἔγημεν καὶ γαμηλίαν τοῖς φράτερσιν εἰσήνεγκεν μεμαρτύρηται. πρὸς δὲ τούτοις καὶ ἐμαυτὸν ἐπέδειξα πάντων μετειληφόθ’ ὅσων προσήκει τοὺς ἐλευθέρους. ὥστε πανταχῇ δικαίως καὶ προσηκόντως ἡμῖν ἂν προσθέμενοι τὴν ψῆφον εὐορκοίητε.", "st": "57.69"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες δικασταί, τοὺς ἐννέα ἄρχοντας ἀνακρίνετε, εἰ γονέας εὖ ποιοῦσιν. ἐγὼ δὲ τοῦ μὲν πατρὸς ὀρφανὸς κατελείφθην, τὴν δὲ μητέρ’ ἱκετεύω ὑμᾶς καὶ ἀντιβολῶ διὰ τοῦτον τὸν ἀγῶν’ ἀπόδοτέ μοι θάψαι εἰς τὰ πατρῷα μνήματα καὶ μή με κωλύσητε, μηδ’ ἄπολιν ποιήσητε, μηδὲ τῶν οἰκείων ἀποστερήσητε τοσούτων ὄντων τὸ πλῆθος, καὶ ὅλως ἀπολέσητε. πρότερον γὰρ ἢ προλιπεῖν τούτους, εἰ μὴ δυνατὸν ὑπ’ αὐτῶν εἴη σωθῆναι, ἀποκτείναιμ’ ἂν ἐμαυτόν, ὥστ’ ἐν τῇ πατρίδι γ’ ὑπὸ τούτων ταφῆναι.", "st": "57.70"}, {"sp": "HDR", "t": "Ἔνδειξις κατὰ Θεοκρίνου", "st": "58"}, {"sp": "N", "t": "τοῦ πατρὸς ἡμῶν, ὦ ἄνδρες δικασταί, διὰ τουτονὶ Θεοκρίνην ἀτυχήσαντος πρὸς τὴν πόλιν καὶ ὀφλόντος δέκα τάλαντα, καὶ τούτου διπλοῦ γεγενημένου ὥστε μηδ’ ἐλπίδα ἡμῖν εἶναι σωτηρίας μηδεμίαν, ἡγησάμην δεῖν ἐπὶ τῷ τιμωρεῖσθαι μεθ’ ὑμῶν τοῦτον μήτε ἡλικίαν μήτε ἄλλο μηδὲν ὑπολογισάμενος δοῦναι τὴν ἔνδειξιν ταύτην.", "st": "58.1"}, {"sp": "N", "t": "καὶ γὰρ ὁ πατήρ, ὦ ἄνδρες δικασταί, ᾧπερ πάντα πειθόμενος πεποίηκα, πρὸς ἅπαντας ὠδύρετο τοὺς γνωρίμους, εἰ παραλιπὼν ἐγὼ τὸν καιρὸν ἐν ᾧ διὰ τὸ τὸν πατέρα ζῆν ἔξεστί μοι τοῦτον ἀμύνασθαι, τὴν ἀπειρίαν καὶ τὴν ἡλικίαν προφασιζόμενος αὐτὸν μὲν περιόψομαι πάντων ἀπεστερημένον, Θεοκρίνην δὲ παρὰ τοὺς νόμους γραφὰς γραφόμενον καὶ συκοφαντοῦντα πολλοὺς τῶν πολιτῶν, οὐκ ἐξὸν αὐτῷ.", "st": "58.2"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν ἁπάντων, ὦ ἄνδρες Ἀθηναῖοι, καὶ ἱκετεύω μετ’ εὐνοίας ἀκοῦσαί μου, πρῶτον μὲν ὅτι τῷ πατρὶ βοηθῶν καὶ πειθόμενος ἀγωνίζομαι, ἔπειθ’ ὅτι καὶ νέος ὢν καὶ ἄπειρος, ὥστ’ ἀγαπητὸν εἶναί μοι, ἐὰν ὑπαρξάσης τῆς παρ’ ὑμῶν εὐνοίας δυνηθῶ δηλῶσαι τὰ πεπραγμένα τούτῳ·", "st": "58.3"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, ὅτι, ὦ ἄνδρες δικασταί, προδέδομαι (τὰ γὰρ ἀληθῆ πρὸς ὑμᾶς εἰρήσεται) ὑπ’ ἀνθρώπων, οἳ πιστευθέντες ὑφ’ ἡμῶν διὰ τὴν πρὸς τοῦτον ἔχθραν, καὶ πυθόμενοι τὰ πράγματα καὶ φήσαντες ἐμοὶ συναγωνιεῖσθαι, ἐγκαταλελοίπασι νυνί με καὶ διαλέλυνται πρὸς τοῦτον ἐν τοῖς ἐμοῖς πράγμασιν, ὥστε μοι μηδὲ τὸν συνεροῦντ’ εἶναι, ἐὰν μή τις ἄρα τῶν οἰκείων βοηθήσῃ.", "st": "58.4"}, {"sp": "N", "t": "πολλαῖς μὲν οὖν ἐνδείξεσιν ἦν ἔνοχος οὑτοσί, καὶ ἅπαντας τοὺς περὶ ταῦτα νόμους ἐφαίνετο παραβεβηκώς· καινότατον δὲ τῶν ἔργων τῶν τούτου τὴν περὶ τὸ πλοῖον φάσιν ηὑρίσκομεν γεγονυῖαν, διόπερ ταῦτα γράψας εἰς τὴν ἔνδειξιν ἔδωκεν ὁ πατήρ μοι. πρῶτον μὲν οὖν τὸν νόμον ὑμῖν ἀναγνώσεται τὸν περὶ τῶν φαινόντων καὶ οὐκ ἐπεξιόντων, ἀλλὰ διαλυομένων παρὰ τοὺς νόμους (ἐντεῦθεν γὰρ οἶμαι προσήκειν μοι τὴν ἀρχὴν ποιήσασθαι τοῦ λόγου), εἶτα τὴν φάσιν αὐτὴν ἣν οὗτος ἐποιήσατο κατὰ τοῦ Μίκωνος. λέγε.", "st": "58.5"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.5"}, {"sp": "N", "t": "ὁ νόμος οὑτοσί, ὦ ἄνδρες δικασταί, τοῖς προαιρουμένοις ἢ γράφεσθαι γραφὰς ἢ φαίνειν ἢ ἄλλο τι ποιεῖν τῶν ἐν τῷ νόμῳ τούτῳ γεγραμμένων προλέγει διαρρήδην, ἐφ’ οἷς ἕκαστόν ἐστιν τούτων ποιητέον. ἔστι δὲ ταῦτα, ὥσπερ ἠκούσατε ἐξ αὐτοῦ τοῦ νόμου, ἐὰν ἐπεξιών τις μὴ μεταλάβῃ τὸ πέμπτον μέρος τῶν ψήφων, χιλίας ἀποτίνειν, κἂν μὴ ἐπεξίῃ ⟨γ’⟩, ὦ Θεοκρίνη, χιλίας ἑτέρας, ἵνα μήτε συκοφαντῇ μηδείς, μήτε ἄδειαν ἔχων ἐργολαβῇ καὶ καθυφιῇ τὰ τῆς πόλεως. φημὶ δὴ κατὰ ταύτην τὴν ἔνδειξιν ἔνοχον εἶναι Θεοκρίνην τῷ φήναντα Μίκωνα Χολλῄδην μὴ ἐπεξελθεῖν, ἀλλ’ ἀργύριον λαβόντα ἀποδόσθαι τὸ πρᾶγμα.", "st": "58.6"}, {"sp": "N", "t": "καὶ τοῦτο ἀποδείξω σαφῶς, ὡς ἐγὼ νομίζω. καίτοι Θεοκρίνης γε, ὦ ἄνδρες δικασταί, καὶ οἱ μετὰ τούτου οὐδὲν ὅ τι οὐ πεποιήκασι προσιόντες τοῖς μάρτυσι καὶ τὰ μὲν ἀπειλοῦντες αὐτοῖς, τὰ δὲ πείθοντες μὴ μαρτυρεῖν. ἀλλ’ ὅμως ἐὰν ὑμεῖς βούλησθε τὰ δίκαια βοηθεῖν μοι, καὶ κελεύητε αὐτούς, μᾶλλον δὲ ἀναγκάζοντος ἐμοῦ συναναγκάζητε, ἤτοι μαρτυρεῖν ἢ ἐξόμνυσθαι, καὶ μὴ ἐᾶτε λόγους λέγειν, εὑρεθήσεται τἀληθές. λέγε οὖν πρῶτον μὲν τὴν φάσιν, εἶτα τὰς μαρτυρίας.", "st": "58.7"}, {"sp": "N", "t": "ΦΑΣΙΣ.", "st": "58.7"}, {"sp": "N", "t": "ταύτην τὴν φάσιν, ὦ ἄνδρες δικασταί, ἔδωκεν μὲν οὑτοσὶ προσκαλεσάμενος τὸν Μίκωνα, ἔλαβεν δὲ ὁ γραμματεὺς ὁ τῶν τοῦ ἐμπορίου ἐπιμελητῶν, Εὐθύφημος. ἐξέκειτο δὲ πολὺν χρόνον ἔμπροσθεν τοῦ συνεδρίου ἡ φάσις, ἕως λαβὼν ἀργύριον οὗτος εἴασε διαγραφῆναι καλούντων αὐτὸν εἰς τὴν ἀνάκρισιν τῶν ἀρχόντων. ὅτι δὲ ταῦτ’ ἀληθῆ λέγω, πρῶτον μὲν κάλει ὃς ἐγραμμάτευε τῇ ἀρχῇ, Εὐθύφημον.", "st": "58.8"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "58.8"}, {"sp": "N", "t": "λέγε δὴ καὶ τὴν τῶν ἰδόντων ἐκκειμένην τὴν φάσιν μαρτυρίαν. λέγε.", "st": "58.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "58.9"}, {"sp": "N", "t": "κάλει δὲ καὶ τοὺς τοῦ ἐμπορίου ἐπιμελητάς, καὶ αὐτὸν τὸν Μίκων’ οὗ ἔφηνε τὸ πλοῖον· καὶ τὰς μαρτυρίας ἀναγίγνωσκε.", "st": "58.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "58.9"}, {"sp": "N", "t": "ὡς μὲν τοίνυν, ὦ ἄνδρες δικασταί, ἔφηνε Θεοκρίνης τὸ τοῦ Μίκωνος πλοῖον, καὶ ὡς ἐξέκειτο πολὺν χρόνον ἡ φάσις, καὶ ὡς εἰς τὴν ἀνάκρισιν καλούμενος οὐχ ὑπήκουσεν οὐδ’ ἐπεξῆλθεν, ἀκηκόατε μαρτυρούντων [τούτων] οὓς εἰδέναι μάλιστα προσήκει. ὅτι δ’ οὐ ταῖς χιλίαις μόνον ἔνοχός ἐστιν, ἀλλὰ καὶ ἀπαγωγῇ καὶ τοῖς ἄλλοις ὅσα κελεύει πάσχειν ὁ νόμος οὑτοσὶ τὸν συκοφαντοῦντα τοὺς ἐμπόρους καὶ τοὺς ναυκλήρους, ῥᾳδίως ἐξ αὐτοῦ τοῦ νόμου γνώσεσθε.", "st": "58.10"}, {"sp": "N", "t": "βουλόμενος γὰρ ὁ τὸν νόμον τιθεὶς μήτε τοὺς ἀδικοῦντας τῶν ἐμπόρων ἀθῴους εἶναι, μήτε τοὺς ἄλλους πράγματ’ ἔχειν, ἁπλῶς ἀπεῖπε τοῖς τοιούτοις τῶν ἀνθρώπων μὴ φαίνειν, εἰ μὴ πιστεύει τις αὑτῷ δείξειν ἐν ὑμῖν γεγενημένα περὶ ὧν ποιεῖται τὴν φάσιν· ἐὰν δέ τις παρὰ ταῦτα ποιῇ τῶν συκοφαντούντων, ἔνδειξιν αὐτῶν εἶναι καὶ ἀπαγωγήν. μᾶλλον δὲ λέγε τὸν νόμον αὐτόν· πολὺ γὰρ ἐμοῦ σαφέστερον διδάξει.", "st": "58.11"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.11"}, {"sp": "N", "t": "ἀκούετε τοῦ νόμου ἃ κελεύει πάσχειν, ὦ ἄνδρες δικασταί, τὸν συκοφάντην. οὐκοῦν εἰ μέν τι πεποιηκότα τούτων ὧν ἔγραψεν ἐν τῇ φάσει Θεοκρίνης πεποιηκέναι τὸν Μίκωνα, καθυφεῖκε τὸ πρᾶγμα καὶ διαλέλυται πρὸς τὸν ἄνθρωπον, ἀδικεῖ πάντας ὑμᾶς καὶ δικαίως ὀφείλει τὰς χιλίας. εἰ δὲ πλεύσαντα αὐτὸν δικαίως οἷ προσῆκεν (ἔστω γὰρ ὁπότερον οὗτος βούλεται) φαίνει καὶ προσκαλεῖται, συκοφαντεῖ τοὺς ναυκλήρους, καὶ τὸν νόμον οὐ μόνον τὸν πρότερον, ἀλλὰ καὶ τὸν ἀρτίως ἀναγνωσθέντα παραβέβηκεν, καὶ καταμεμαρτύρηκεν αὑτοῦ μηδὲν ὑγιὲς μήτε λέγειν μήτε πράττειν.", "st": "58.12"}, {"sp": "N", "t": "τίς γὰρ ἂν παρεὶς τὸ δικαίως πράττοντα λαβεῖν τὸ μέρος τῶν χρημάτων κατὰ τὸν νόμον, διαλυσάμενος ἐβουλήθη μικρὰ κερδᾶναι καὶ τούτοις ἔνοχον αὑτὸν καταστῆσαι τοῖς νόμοις, ἐξόν, ὅπερ ἀρτίως εἶπον, τὰ ἡμίσεα τῶν φανθέντων λαβεῖν; οὐδ’ ἂν εἷς, ὦ ἄνδρες δικασταί, μὴ οὐ συνειδὼς ἑαυτῷ συκοφαντοῦντι.", "st": "58.13"}, {"sp": "N", "t": "δύο μὲν τοίνυν οὗτοι νόμοι εἰσὶν οὓς παραβέβηκεν ὁ τοὺς ἄλλους παρανόμων γραφόμενος· ἕτερον δὲ τρίτον, ὃς ὁμοίως κελεύει κατά τε τῶν ὀφειλόντων τῷ δημοσίῳ τὰς ἐνδείξεις τὸν βουλόμενον ποιεῖσθαι τῶν πολιτῶν, καὶ ἐάν τις ὀφείλῃ τῇ Ἀθηνᾷ ἢ τῶν ἄλλων θεῶν ἢ τῶν ἐπωνύμων τῳ. ὃ φανήσεται οὗτος, ὀφείλων καὶ οὐκ ἐκτετεικὼς ἑπτακοσίας δραχμάς, ἃς ὦφλεν ἐν ταῖς εὐθύναις τῷ ἐπωνύμῳ τῆς αὑτοῦ φυλῆς. καί μοι λέγε τοῦτ’ αὐτὸ τοῦ νόμου.", "st": "58.14"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.14"}, {"sp": "N", "t": "ἐπίσχες. ἀκούεις, οὑτοσί, τί λέγει; “ἢ τῶν ἐπωνύμων τῳ”. λέγε δὴ τὴν τῶν φυλετῶν μαρτυρίαν.", "st": "58.15"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "58.15"}, {"sp": "N", "t": "ταχύ γ’ ἂν οὗτος, ὦ ἄνδρες δικασταί, ἀνθρώπων ὀλίγων φροντίσειεν ἢ τῶν τὸν πλεῖστον τοῦ χρόνου πλεόντων, ὥσπερ ὁ Μίκων, ὅστις τοὺς φυλέτας παρόντας οὔτ’ ἔδεισεν οὔτ’ ᾐσχύνθη, τοῦτο μὲν οὕτως αὐτῶν τὰ κοινὰ διοικήσας ὥστ’ ἐκείνους κλοπὴν αὐτοῦ καταγνῶναι, τοῦτο δὲ ὀφλὼν καὶ τοὺς νόμους ἀκριβῶς εἰδὼς ὅτι κωλύουσιν αὐτὸν γράφεσθαι γραφὰς ἕως ἂν ἐκτείσῃ, βιαζόμενος καὶ νομίζων δεῖν τοὺς μὲν ἄλλους τοὺς ὀφείλοντας μηδενὸς μετέχειν τῶν κοινῶν, αὑτὸν δὲ κρείττω τῶν νόμων εἶναι.", "st": "58.15"}, {"sp": "N", "t": "φήσει τοίνυν τὸν πάππον, οὐχ αὑτὸν εἶναι τὸν ἐν τῷ γραμματείῳ γεγραμμένον, καὶ περὶ τούτου πολλοὺς ἐρεῖ λόγους, ὡς ἐκεῖνός ἐστιν. ἐγὼ δὲ τὸ μὲν ἀκριβές, ὁπότερός ἐστιν, οὐκ ἔχω λέγειν· εἰ δ’ οὖν ἐστιν ὡς οὗτος ἐρεῖ, πολὺ δικαιότερον εἶναι νομίζω καταψηφίσασθαι ὑμᾶς αὐτοῦ, εἰ ταῦθ’ οὕτως ἐστίν.", "st": "58.16"}, {"sp": "N", "t": "εἰ γὰρ ὀφείλοντος αὐτῷ τοῦ πάππου πάλαι, καὶ τοῦ νόμου κελεύοντος κληρονομεῖν τοῦτον τῶν ἐκείνου, προσῆκον αὐτῷ μηδὲ πάλαι γράφεσθαι ἐγράφετο, καὶ διὰ τοῦτο οἰήσεται δεῖν ἀποφεύγειν ὅτι πονηρὸς ἐκ τριγονίας ἐστίν, οὐ δίκαια ἐρεῖ, ὦ ἄνδρες δικασταί. ὡς οὖν καὶ παρ’ αὐτοῦ Θεοκρίνου ὁμολογεῖται τοῦτ’ εἶναι τὸ ὄφλημα καὶ κατετάξατο τοῖς φυλέταις ὑπὲρ αὑτοῦ καὶ τοῦ ἀδελφοῦ, καὶ τοῖς βουλομένοις εὐορκεῖν οὐ καλῶς ἔχει ταύτην ἀπογιγνώσκειν τὴν ἔνδειξιν, λαβέ μοι τὸ ψήφισμα ὃ εἶπεν ἐν τοῖς φυλέταις Σκιρωνίδης.", "st": "58.17"}, {"sp": "N", "t": "προσελθὼν δὲ οὑτοσὶ Θεοκρίνης ὡμολόγησεν ὀφείλειν καὶ ἐκτείσειν ἐναντίον τῶν φυλετῶν, ἐπειδὴ προσιόντας ἡμᾶς ᾔσθετο καὶ βουλομένους ἀντίγραφα τῶν ἐν τῷ γραμματείῳ γεγραμμένων λαβεῖν.", "st": "58.18"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "58.18"}, {"sp": "N", "t": "πολύ γ’ ἄν, ὦ ἄνδρες Λεωντίδαι, τοὺς ἀναγκάσαντας ἀποδοῦναι Θεοκρίνην τὰς ἑπτὰ μνᾶς ἐπῃνέσατ’ ἂν μᾶλλον ἢ τοῦτον.", "st": "58.18"}, {"sp": "N", "t": "τέταρτος τοίνυν νόμος ἐστίν (ὁμολογῶ γὰρ τῶν τούτῳ πεπραγμένων τὰ πλεῖστα ἐξητακέναι) καθ’ ὃν ὀφείλει πεντακοσίας δραχμὰς Θεοκρίνης οὑτοσί, οὐκ ἐκτετεικότος αὐτῷ τοῦ πατρὸς ἃς προσῶφλεν ἀφελόμενος τὴν Κηφισοδώρου θεράπαιναν εἰς ἐλευθερίαν, ἀλλὰ διοικησαμένου πρὸς Κτησικλέα τὸν λογογράφον, ὃς ἦν ἐπὶ τοῖς τῶν ἀντιδίκων πράγμασιν, ὥστε μήτ’ ἐκτεῖσαι μήτ’ εἰς ἀκρόπολιν ἀνενεχθῆναι.", "st": "58.19"}, {"sp": "N", "t": "ἃς οὐδὲν ἧττον οἶμαι Θεοκρίνης ὀφείλει νυνὶ κατὰ τὸν νόμον. οὐ γὰρ ἐὰν Κτησικλῆς ὁ μέτοικος συγχωρήσῃ τούτῳ, πονηρὸς πονηρῷ, μὴ παραδοθῆναι τοῖς πράκτορσιν τὸν προσοφλόντα κατὰ τὸν νόμον, διὰ τοῦτο δεῖ τὴν πόλιν ἀπεστερῆσθαι τῶν ἐκ τῶν νόμων ἐπικειμένων ζημιῶν, ἀλλὰ προσήκει τοὺς ἀντιδίκους ὑπὲρ μὲν τῶν ἰδίων, ὅπως ἂν αὑτοὺς πείθωσιν, διοικεῖσθαι πρὸς ἀλλήλους, ὑπὲρ δὲ τῶν πρὸς τὸ δημόσιον, ὅπως ἂν οἱ νόμοι κελεύωσιν.", "st": "58.20"}, {"sp": "N", "t": "καί μοι λέγε τόν τε νόμον, ὃς κελεύει τὸ ἥμισυ τοῦ τιμήματος ὀφείλειν τῷ δημοσίῳ ὃς ἂν δόξῃ μὴ δικαίως εἰς τὴν ἐλευθερίαν ἀφελέσθαι, καὶ τὴν τοῦ Κηφισοδώρου μαρτυρίαν.", "st": "58.21"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΜΑΡΤΥΡΙΑ.", "st": "58.21"}, {"sp": "N", "t": "λέγε δὴ κἀκεῖνον τὸν νόμον τὸν ἀπ’ ἐκείνης κελεύοντα τῆς ἡμέρας ὀφείλειν ἀφ’ ἧς ἂν ὄφλῃ, ἐάν τε ἐγγεγραμμένος ᾖ, ἐάν τε μή.", "st": "58.21"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.21"}, {"sp": "N", "t": "πῶς οὖν ἄλλως, ὦ ἄνδρες δικασταί, προσήκει τὸν δικαίως κατηγοροῦντα ἀποφαίνειν ὀρθῶς ἐνδεδειγμένον Θεοκρίνην τουτονί, καὶ μὴ μόνον ἔνοχον ὄντα τῇ ἐνδείξει κατὰ τὰς χιλίας ἐφ’ αἷς ἐνδέδεικται, ἀλλὰ καὶ πολλοῖς ἄλλοις ὀφλήμασιν; ἐγὼ μὲν οὐδαμῶς νομίζω. οὐ γὰρ δὴ προσδοκᾶν γε δεῖ Θεοκρίνην αὐτὸν ὁμολογήσειν ὀφείλειν ὑμῖν τῷ δημοσίῳ καὶ δικαίως ἐνδεδεῖχθαι φήσειν, ἀλλὰ τοὐναντίον πάντα λόγον μᾶλλον ἐρεῖν καὶ πάσας αἰτίας οἴσειν, ὡς καταστασιάζεται, ὡς διὰ τὰς τῶν παρανόμων γραφὰς εἰς ταῦθ’ ἥκει.", "st": "58.22"}, {"sp": "N", "t": "λοιπὸν γάρ ἐστιν τοῦτο τοῖς ἐν αὐτοῖς τοῖς πράγμασιν ἐξελεγχομένοις, αἰτίας καὶ προφάσεις εὑρίσκειν αἵτινες τοῦ παρόντος ὑμᾶς ποιήσουσι πράγματος ἐπιλαθομένους τοῖς ἔξω τῆς κατηγορίας λόγοις προσέχειν. ἐγὼ δέ, ὦ ἄνδρες δικασταί, εἰ μὲν ἑώρων ἐν τοῖς ἀνεγνωσμένοις νόμοις γεγραμμένον “ταῦτα δ’ εἶναι κύρια περὶ τῶν συκοφαντούντων, ἂν μὴ Θεοκρίνης ἐνδειχθεὶς αἰτιᾶσθαι βούληται Θουκυδίδην ἢ Δημοσθένην ἢ καὶ τῶν πολιτευομένων ἄλλον τινά”, ἡσυχίαν ἂν ἦγον. νῦν δὲ τούτων οὐδεμίαν ὁρῶ τῶν σκήψεων ὑπόλογον οὖσαν ἐν τοῖς νόμοις, οὐδὲ καινήν, ὥστε προσέχειν νῦν πρῶτον ἀκούσαντας, ἀλλὰ μυριάκις παρὰ τῶν κρινομένων εἰρημένην.", "st": "58.23"}, {"sp": "N", "t": "ἀκούω δὲ καὶ παρὰ τῶν πρεσβυτέρων, ὦ ἄνδρες δικασταί, ὡς ἄρα προσῆκόν ἐστιν ὅλως μὲν μηδενὶ μηδεμίαν συγγνώμην ὑπάρχειν παραβαίνοντι τοὺς νόμους, εἰ δ’ ἄρα δεῖ, μὴ τοῖς συνεχῶς οὖσι πονηροῖς μηδὲ τοῖς ἐπ’ ἀργυρίῳ τοὺς νόμους προϊεμένοις (οὐ γὰρ εἰκός), ἀλλ’ οἵτινες ἂν διὰ τὴν αὑτῶν ἀπραγμοσύνην ἄκοντές τι τῶν γεγραμμένων παραβῶ- σιν. ὧν οὐδεὶς ἂν δήπου Θεοκρίνην τουτονὶ φήσειεν εἶναι, ἀλλὰ τοὐναντίον οὐδενὸς τῶν ἐν τοῖς νόμοις ἄπειρον.", "st": "58.24"}, {"sp": "N", "t": "διὸ καὶ δεῖ φυλάττειν αὐτόν, μὴ πρὸς τοὺς ἐμοὺς λόγους μηδὲ τοὺς ὑπὸ τούτου ῥηθησομένους ἀποβλέποντας. οὐ γὰρ δίκαιον τοὺς ὑπὲρ τῶν νόμων καθημένους μακροῖς λόγοις καὶ κατηγορίαις προσέχειν, ἀλλ’ οἷς ἂν ἅπαντες ῥᾳδίως ἐπακολουθήσαιτε, καὶ δι’ ὧν δόξετε πᾶσι τοῖς ἐν τῇ πόλει τῶν νόμων ἀξίως ταύτην τὴν ἔνδειξιν δικάσαι, σαφῶς ἐρωτῶντας “τί λέγεις, Θεοκρίνη καὶ πάντες οἱ τῶν αὐτῶν τούτῳ μετέχοντες; ἀξιοῦθ’ ἡμᾶς, κατὰ τοὺς νόμους ὀμωμοκότας δικάσειν, παρὰ τούτους διὰ τοὺς ὑμετέρους λόγους ψηφίζεσθαι;”", "st": "58.25"}, {"sp": "N", "t": "“μεμαρτυρηκότος μὲν ἡμῖν τοῦ Μίκωνος, καθ’ οὗ δοὺς Θεοκρίνης οὑτοσὶ τὴν φάσιν οὐκ ἐπεξῆλθε, καὶ πεποιηκότος αὑτὸν τούτοις ὑπόδικον, ὁμολογοῦντος δὲ τοῦ γραμματέως λαβεῖν τὴν φάσιν παρὰ τούτου, καὶ πεποιηκυίας τῆς μαρτυρίας τῆς ὀλίγον τι πρότερον ἀναγνωσθείσης αὐτὸν ὑπόδικον; ἔτι δὲ τῶν τοῦ ἐμπορίου ἐπιμελητῶν μόλις μέν, ἀλλ’ οὖν ταὐτὰ τούτοις μεμαρτυρηκότων; πρὸς δὲ τούτοις τῶν ἰδόντων ἐκκειμένην τὴν φάσιν καὶ προσελθόντων τοῖς ἄρχουσι μαρτυρούντων, ὥσπερ ὀλίγον πρότερον ἠκούσατε;” ἀλλ’ οὐ δίκαιον, ὦ ἄνδρες δικασταί.", "st": "58.26"}, {"sp": "N", "t": "οὐ γὰρ δὴ διὰ τὸν τρόπον γε τὸν τοῦ φεύγοντος καὶ τὸν βίον ψευδεῖς ὑπολήψεσθε τὰς μαρτυρίας τὰς ἀνεγνωσμένας εἶναι. πολὺ γὰρ ἐκ τοῦ τρόπου σαφέστερον ἐπιδείκνυται Θεοκρίνης τοιοῦτος ὢν ἢ διὰ τῶν εἰρημένων. τί γὰρ οὐ πεποίηκεν οὗτος ὧν ἂν πονηρὸς καὶ συκοφάντης ἄνθρωπος ποιήσειεν; οὐ διὰ μὲν τὴν τούτου πονηρίαν ἁδελφὸς αὐτοῦ θεσμοθετῶν καὶ τούτῳ χρώμενος συμβούλῳ τοιοῦτος ἔδοξε παρ’ ὑμῖν ἄνθρωπος εἶναι, ὥστε οὐ μόνον αὐτὸς ἀπεχειροτο- νήθη τῶν ἐπιχειροτονιῶν οὐσῶν, ἀλλὰ καὶ τὴν ἀρχὴν ἅπασαν ἐποίησεν; καὶ εἰ μὴ δεομένων αὐτῶν καὶ ἱκετευόντων, καὶ λεγόντων ὡς οὐκέτι πρόσεισιν Θεοκρίνης πρὸς τὴν ἀρχήν, ἐπείσθηθ’ ὑμεῖς καὶ πάλιν ἀπέδοτε τοὺς στεφάνους αὐτοῖς, πάντων ἂν αἴσχιστα οἱ συνάρχοντες ἐπεπόνθεσαν;", "st": "58.27"}, {"sp": "N", "t": "καὶ τούτων οὐδέν με δεῖ μάρτυρας ὑμῖν παρασχέσθαι· πάντες γὰρ ἴστε τοὺς ἐπὶ Λυκίσκου ἄρχοντος θεσμοθέτας ἀποχειροτονηθέντας ἐν τῷ δήμῳ διὰ τοῦτον. ὧν ἀναμιμνῃσκομένους ὑμᾶς χρὴ τὸν αὐτὸν ὑπολαμβάνειν εἶναι τοῦτον καὶ πρότερον καὶ νῦν. οὐ πολλῷ τοίνυν χρόνῳ ὕστερον τῆς ἀποχειροτονίας, τελευτήσαντος αὐτῷ τοῦ ἀδελφοῦ βιαίῳ θανάτῳ, τοιοῦτος ἐγένετο περὶ αὐτὸν οὗτος, ὥστε ζητήσας τοὺς δράσαντας καὶ πυθόμενος οἵτινες ἦσαν, ἀργύριον λαβὼν ἀπηλλάγη.", "st": "58.28"}, {"sp": "N", "t": "καὶ τὴν μὲν ἀρχὴν ἣν ἐκεῖνος ἄρχων ἐτελεύτησεν, ἱεροποιὸς ὤν, παρὰ τοὺς νόμους ἦρχεν οὗτος, οὔτε λαχὼν οὔτ’ ἐπιλαχών· ὑπὲρ ὧν δ’ ἔπαθεν ἐκεῖνος, μέχρι τούτου σχετλιάζων περιῄει καὶ φάσκων εἰς Ἄρειον πάγον Δημοχάρην προσκαλεῖσθαι, ἕως διελύσατο πρὸς τοὺς τὴν αἰτίαν ἔχοντας. χρηστός γ’ ἐστὶ καὶ πιστὸς καὶ κρείττων χρημάτων. οὐδ’ ἂν αὐτὸς φήσειεν. οὐ γὰρ τοσούτων δεῖσθαί φασι δεῖν τὸν δικαίως καὶ μετρίως τῶν κοινῶν ἐπιμελησόμενον, ἀλλὰ πάντων τούτων εἶναι κρείττω δι’ ὧν ἀναλίσκουσιν εἰς ἑαυτοὺς ἃ λαμβάνουσιν.", "st": "58.29"}, {"sp": "N", "t": "καὶ τὰ μὲν πρὸς τὸν ἀδελφὸν αὐτῷ πεπραγμένα τοιαῦτά ἐστιν· ἃ δὲ πρὸς τὴν πόλιν προσελθὼν διῴκηται (δευτέρους γὰρ ὑμᾶς φήσει φιλεῖν μετὰ τοὺς οἰκείους) ἄξιον ἀκοῦσαι. ἄρξομαι δ’ ἀπὸ τῶν πρὸς ἡμᾶς αὐτῷ πεπραγμένων. τοῦ γὰρ πατρὸς κατηγορῶν, ὦ ἄνδρες δικασταί, ὅτε τὴν τῶν παρανόμων αὐτὸν ἐδίωκε γραφήν, ἔλεγεν ὡς ἐπιβεβουλευμένος ὁ παῖς εἴη περὶ οὗ τὸ ψήφισμα γεγραμμένον ἦν, ἐν ᾧ τὴν σίτησιν ἔγραψεν Χαριδήμῳ ὁ πατὴρ τῷ Ἰσχομάχου υἱῷ,", "st": "58.30"}, {"sp": "N", "t": "λέγων ὡς, ἐὰν ἐπανέλθῃ εἰς τὸν πατρῷον οἶκον ὁ παῖς, ἀπολωλεκὼς ἔσται τὴν οὐσίαν ἅπασαν ἣν Αἰσχύλος ὁ ποιησάμενος αὐτὸν υἱὸν ἔδωκεν αὐτῷ, ψευδόμενος· οὐδενὶ γὰρ πώποτε, ὦ ἄνδρες δικασταί, τοῦτο τῶν εἰσποιηθέντων συνέβη. καὶ τούτων πάντων αἴτιον ἔφη Πολύευκτον γεγενῆσθαι τὸν ἔχοντα τὴν μητέρα τοῦ παιδός, βουλόμενον ἔχειν αὐτὸν τὴν τοῦ παιδὸς οὐσίαν. ὀργισθέντων δὲ τῶν δικαστῶν ἐπὶ τοῖς λεγομένοις, καὶ νομισάντων αὐτὸ μὲν τὸ ψήφισμα καὶ τὴν δωρεὰν κατὰ τοὺς νόμους εἶναι, τῷ δὲ ὄντι τὸν παῖδα μέλλειν ἀποστερεῖσθαι τῶν χρημάτων, τῷ μὲν πατρὶ δέκα ταλάντων ἐτίμησαν ὡς μετὰ Πολυεύκτου ταῦτα πράττοντι, τούτῳ δ’ ἐπίστευσαν ὡς δὴ βοηθήσαντι τῷ παιδί.", "st": "58.31"}, {"sp": "N", "t": "καὶ τὰ μὲν ἐπὶ τοῦ δικαστηρίου γενόμενα τοιαῦτα καὶ παραπλήσια τούτοις ἦν· ὡς δ’ ὁ χρηστὸς οὗτος ὠργισμένους ᾔσθετο τοὺς ἀνθρώπους καὶ πεπιστευμένον αὑτὸν ὡς οὐ παντάπασιν ἀνόσιον ὄντα, προσκαλεσάμενος τὸν Πολύευκτον ἀποφέρει γραφὴν κατ’ αὐτοῦ κακώσεως πρὸς τὸν ἄρχοντα καὶ δίδωσι τὴν λῆξιν Μνησαρχίδῃ τῷ παρέδρῳ· λαβὼν δὲ διακοσίας δραχμὰς παρὰ τοῦ Πολυεύκτου, καὶ τὰ δεινὰ ταῦτ’ ἀποδόμενος μικροῦ λήμματος ἐφ’ οἷς τῷ πατρὶ ἐτιμήσατο δέκα ταλάντων, ἀπηλλάγη καὶ τὴν γραφὴν ἀνείλετο προδοὺς τὸν ὀρφανόν. καί μοι κάλει τούτων τοὺς μάρτυρας.", "st": "58.32"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "58.32"}, {"sp": "N", "t": "εἰ τοίνυν εὔπορος ἦν ὁ πατήρ, ὦ ἄνδρες δικασταί, καὶ δυνατὸς πορίσαι χιλίας δραχμάς, ὅλως ἂν ἀπηλλάγη τῆς γραφῆς τῆς τῶν παρανόμων· τοσοῦτον γὰρ αὐτὸν ᾔτει οὑτοσί. καί μοι κάλει Φιλιππίδην τὸν Παιανιέα, πρὸς ὃν ἔλεγε ταῦτα Θεοκρίνης οὑτοσί, καὶ τοὺς ἄλλους οἳ συνίσασιν τούτῳ ταῦτα λέγοντι.", "st": "58.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "58.33"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν, ὦ ἄνδρες δικασταί, Θεοκρίνης, εἴ τις αὐτῷ τὰς χιλίας δραχμὰς ἐδίδου, τὴν γραφὴν ⟨ἂν⟩ ἀνείλετο τὴν κατὰ τοῦ πατρός, ἡγοῦμαι πάντας ὑμᾶς πιστεύειν, καὶ εἰ μηδεὶς ἐμαρτύρησεν. ὅτι δὲ πολλὰς ἑτέρας προσκαλεσάμενος καὶ γραψάμενος καθυφεῖκεν, καὶ μικρὸν ἀργύριον λαμβάνων ἀπαλλάττεται, τοὺς δόντας ὑμῖν αὐτοὺς καλῶ, ἵνα μὴ πιστεύητε αὐτῷ λέγοντι ὡς αὐτὸς φυλάττει τοὺς παράνομα γράφοντας, καὶ ὡς, ὅταν αἱ τῶν παρανόμων γραφαὶ ἀναιρεθῶσιν, ὁ δῆμος καταλύεται· ταῦτα γὰρ οἱ πάντα πωλοῦντες λέγειν εἰθισμένοι εἰσίν.", "st": "58.34"}, {"sp": "N", "t": "κάλει μοι Ἀριστόμαχον Κριτοδήμου Ἀλωπεκῆθεν. οὗτος γὰρ ἔδωκεν, μᾶλλον δ’ ἐν τῇ τούτου οἰκίᾳ ἐδόθη τρί’ ἡμίμναια τούτῳ τῷ ἀδωροδοκήτῳ ὑπὲρ τοῦ ψηφίσματος ὃ Ἀντιμέδων ἔγραψε τοῖς Τενεδίοις.", "st": "58.35"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "58.35"}, {"sp": "N", "t": "λέγε δὴ καὶ τὰς τῶν ἄλλων ἐφεξῆς τὰς τοιαύτας μαρτυρίας, καὶ τὴν Ὑπερείδου καὶ Δημοσθένους. τοῦτο γάρ ἐστιν ὑπερβολή, τὸ παρ’ ὧν οὐδ’ ἂν εἷς ἀξιώσαι λαβεῖν, τοῦτον παρὰ τούτων ἥδιστα λαμβάνειν πωλοῦντα τὰς γραφάς.", "st": "58.35"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "58.35"}, {"sp": "N", "t": "οὗτος τοίνυν αὐτίκα φήσει διὰ τοῦτο τὴν ἔνδειξιν καθ’ αὑτοῦ γεγονέναι, ἵνα Δημοσθένει μὴ ἐπεξέλθῃ τὴν γραφὴν ἣν ἐγράψατ’ αὐτόν, μηδὲ Θουκυδίδῃ· δεινὸς γάρ ἐστι ψεύσασθαι καὶ μηδὲν ὑγιὲς εἰπεῖν. ἡμεῖς δέ, ὦ ἄνδρες δικασταί, καὶ τοῦτ’ ἐπεσκεψάμεθα, καὶ δείξομεν ὑμῖν οὐδὲν τὴν πόλιν βλαπτομένην, οὔτε μὰ τὸν Δία ἐὰν κύριον γένηται τὸ ψήφισμα τὸ Θουκυδίδου οὔτ’ ἂν ἄκυρον. καίτοι τάς γε τοιαύτας ἀπολογίας οὐ δίκαιόν ἐστι προσφέρειν τοῖς κατὰ τοὺς νόμους ὀμωμοκόσιν δικάσειν· ἀλλ’ ὅμως ἐξ αὐτῆς τῆς γραφῆς αὐτίκα γνώσεσθε διότι πρόφασίς ἐστιν τῆς ἐνδείξεως ἡ γραφή. λέγε τὰς γραφὰς ταύτας.", "st": "58.36"}, {"sp": "N", "t": "ΓΡΑΦΑΙ.", "st": "58.36"}, {"sp": "N", "t": "τούτων τῶν ψηφισμάτων, ὦ ἄνδρες δικασταί, ἢ μενόντων κατὰ χώραν ἢ ἁλόντων (οὐδὲν γὰρ ἔμοιγε διαφέρει) τί ἡ πόλις κερδαίνει ἢ βλάπτεται; ἐγὼ μὲν γὰρ οὐδὲν οἶμαι. τοὺς γὰρ Αἰνίους φασὶν οὐδὲ προσέχειν τῇ πόλει, τοῦτο δὲ γεγονέναι διὰ Θεοκρίνην τουτονί. συκοφαντούμενοι γὰρ ἐν ἐκείνοις τοῖς χρόνοις ὑπὸ τούτου, ἐν οἷς οἱ μὲν ἐφιλίππιζον, οἱ δ’ ἠττίκιζον αὐτῶν, καὶ πυνθανόμενοι γεγράφθαι τὸ ψήφισμα παρανόμων ὃ Χαρῖνος πρότερον ἐγράψατο, τοῦτο τὸ περὶ τῆς συντάξεως, ὃ Θουκυδίδης εἶπε, καὶ πέρας τῶν πραγμάτων οὐδὲν γιγνόμενον,", "st": "58.37"}, {"sp": "N", "t": "ἀλλὰ τὸν μὲν δῆμον συγχωροῦντα τὴν σύνταξιν διδόναι τοὺς Αἰνίους ὅσην Χάρητι τῷ στρατηγῷ συνεχώρησαν, τοῦτον δὲ τὸν μιαρὸν παραδεξάμενον Χαρίνῳ τῷ προδότῃ ταὐτὰ πράττειν, ὅπερ ἦν ἀναγκαῖον αὐτοῖς, τοῦτ’ ἔπραξαν· εἵλοντο γὰρ τῶν παρόντων κακῶν τὰ ἐλάχιστα. καίτοι τί χρὴ νομίζειν αὐτοὺς πάσχειν ὑπὸ τῶν ἐνθάδε γραφομένων, οἷς ἦν αἱρετώτερον φρουρὰν ὑποδέχεσθαι καὶ βαρβάρων ἀκούειν, ὑμῶν ἀποστάντας; ἀλλ’ οἶμαι τὴν τούτων πονηρίαν ὑμεῖς μόνοι δύνασθε φέρειν, ἄλλος δ’ οὐδεὶς τῶν Ἑλλήνων.", "st": "58.38"}, {"sp": "N", "t": "ὅτι μὲν οὖν οὔτε διὰ τὰς γραφὰς τὰς ἀνεγνωσμένας οὔτε δι’ ἄλλην αἰτίαν οὐδεμίαν ἄξιόν ἐστιν παρὰ πάντας τοὺς νόμους τοὺς περὶ τῶν ἐνδείξεων ἀφεῖναι Θεοκρίνην, σχεδὸν καὶ διὰ τῶν εἰρημένων φανερόν ἐστιν. ἐγὼ δὲ τὰς μὲν τούτων προφάσεις, ὦ ἄνδρες δικασταί, καὶ τὰς κατηγορίας καὶ τὰς προσποιήτους ταύτας ἔχθρας οὐ λανθάνειν ὑμᾶς νομίζω.", "st": "58.39"}, {"sp": "N", "t": "οὐ γὰρ ὀλιγάκις ἑοράκατ’ αὐτοὺς ἐπὶ μὲν τῶν δικαστηρίων καὶ τοῦ βήματος ἐχθροὺς εἶναι φάσκοντας ἀλλήλοις, ἰδίᾳ δὲ ταὐτὰ πράττοντας καὶ μετέχοντας τῶν λημμάτων, καὶ τοτὲ μὲν λοιδορουμένους καὶ πλύνοντας αὑτοὺς τἀπόρρητα, μικρὸν δὲ διαλιπόντας τοῖς αὐτοῖς τούτοις συνδεκαδίζοντας καὶ τῶν αὐτῶν ἱερῶν κοινωνοῦντας. καὶ τούτων οὐδὲν ἴσως θαυμάσαι ἄξιόν ἐστιν· φύσει τε γάρ εἰσι πονηροί, καὶ τὰς τοιαύτας προφάσεις ὁρῶσιν ὑμᾶς ἀποδεχομένους, ὥστε τί κωλύει ταύταις αὐτοὺς χρωμένους ἐξαπατᾶν ὑμᾶς πειρᾶσθαι;", "st": "58.40"}, {"sp": "N", "t": "ὅλως δ’ ἔγωγε οἶμαι δεῖν ὑμᾶς, ὦ ἄνδρες δικασταί, ὑπὲρ αὐτοῦ τοῦ πράγματος σκεψαμένους, εἰ μὲν δίκαια λέγω καὶ κατὰ τοὺς νόμους, βοηθεῖν μοι, μηδὲν ὑπολογισαμένους εἰ μὴ Δημοσθένης ἐστὶν ὁ κατηγορῶν, ἀλλὰ μειράκιον, μηδὲ νομίζειν κυριωτέρους δεῖν εἶναι τοὺς νόμους, ἂν εὖ τις τοῖς ὀνόμασι συμπλέξας αὐτοὺς [τούτους] ὑμῖν παράσχηται, τῶν ὅπως ἔτυχεν λεγόντων, ἀλλὰ τοὺς αὐτούς, καὶ τοσούτῳ μᾶλλον τοῖς ἀπείροις καὶ τοῖς νέοις βοηθεῖν, ὅσῳπερ ἂν ἧττον ἐξαπατήσειαν ὑμᾶς.", "st": "58.41"}, {"sp": "N", "t": "ἐπεὶ διότι τοὐναντίον ἐστίν, καὶ οὐχ οὗτος, ἀλλ’ ἐγὼ κατεστασίασμαι, καὶ φησάντων τινῶν μοι συναγωνιεῖσθαι προδέδομαι διὰ τὰς τούτων ἑταιρείας, ἐκείνως δῆλον ὑμῖν ἔσται. καλείτω ὁ κῆρυξ οὗτος τὸν Δημοσθένην· οὐκ ἀναβήσεται. τὸ δ’ αἴτιόν ἐστιν, οὐ τὸ ἐμὲ ὑπό τινων πεπεισμένον ἐνδεῖξαι τουτονί, ἀλλὰ τοῦτον καὶ τὸν ἄρτι καλούμενον διαλελύσθαι. καὶ τοῦθ’ ὅτι ἐστὶν ἀληθές, ἀναγκάσω μὲν μαρτυρεῖν καὶ Κλεινόμαχον τὸν συναγαγόντ’ αὐτοὺς καὶ Εὐβουλίδην τὸν ἐν Κυνοσάργει παραγενόμενον·", "st": "58.42"}, {"sp": "N", "t": "οὐ μὴν ἔλατ- τόν γε τούτου σημεῖον ὑμῖν, ἀλλὰ μεῖζον παρασχήσομαι διότι τοῦτ’ ἔστιν ἀληθές, ὃ πάντες ἀκούσαντες ὁμολογήσετε. Θεοκρίνης γὰρ οὑτοσὶ τοῦτον διώκων παρανόμων, τὸν μιαρόν, ὡς αὐτίκα φήσει, καὶ τῶν νῦν αὐτῷ κακῶν αἴτιον, φανερῶς ἀφῆκε τῆς γραφῆς, ἐφ’ ᾗ δέκα τάλαντα ἐπεγράψατο τίμημα. πῶς; οὐδὲν καινὸν διαπραξάμενος, ἀλλ’ ὅπερ ἕτεροί τινες τῶν ὁμοίων τούτῳ. τὸν μὲν Δημοσθένην τις ὑπωμόσατο καλουμένης τῆς γραφῆς ὡς νοσοῦντα, τὸν περιιόντα καὶ λοιδορούμενον Αἰσχίνῃ· τοῦτον δ’ οὗτος τὸν ἐχθρὸν εἴασεν, καὶ οὔτε τότε ἀνθυπωμόσατο οὔθ’ ὕστερον ἐπήγγελκεν. ἆρ’ οὐ περιφανῶς οὗτοι φενακίζουσιν ὑμᾶς τοὺς προσέχοντας τούτοις ὡς ἐχθροῖς; λέγε τὰς μαρτυρίας.", "st": "58.43"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "58.43"}, {"sp": "N", "t": "οὐκοῦν δίκαιόν ἐστιν, ὦ ἄνδρες δικασταί, μηδ’ ὑμᾶς τῶν φησόντων Θεοκρίνῃ διὰ τὴν πρὸς Δημοσθένην ἔχθραν συνερεῖν ἐθέλειν ἀκούειν, ἀλλὰ κελεύειν αὐτούς, εἴπερ ὡς ἀληθῶς ἐχθροί εἰσιν τοῦ Δημοσθένους, αὐτὸν ἐκεῖνον γράφεσθαι καὶ μὴ ἐπιτρέπειν αὐτῷ παράνομα γράφειν. εἰσὶ δὲ δεινοὶ καὶ οὗτοι, καὶ πιστεύονται μᾶλλον παρ’ ὑμῖν. ἀλλ’ οὐ ποιήσουσι τοῦτο. διὰ τί; ὅτι φασὶ πολεμεῖν ἀλλήλοις οὐ πολεμοῦντες.", "st": "58.44"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς τούτων ἔχθρας ὑμεῖς ἂν ἀκριβέστερον ἐμοὶ διεξέλθοιτε ἢ ἐγὼ ὑμῖν. ἡδέως δ’ ἂν ἠρόμην Θεοκρίνην ἐναντίον ὑμῶν, εἴ μοι ἔμελλεν ἀποκρινεῖσθαι δικαίως, τί ποτ’ ἂν ἐποίησεν, ἐπειδή φησιν ἐπὶ τῷ κωλύειν τετάχθαι τοὺς παράνομα γράφοντας, εἴ τις ἐν τῷ δήμῳ διαλεχθεὶς ἅπασι τοῖς πολίταις καὶ πείσας ἔγραψεν ἐξεῖναι τοῖς ἀτίμοις καὶ τοῖς ὀφείλουσιν τῷ δημοσίῳ γράφεσθαι, φαίνειν, ἐνδεικνύειν, ἁπλῶς ποιεῖν ὅσαπερ νῦν ὁ νόμος κωλύει πράττειν,", "st": "58.45"}, {"sp": "N", "t": "πότερον ἐγράψατο ἂν παρανόμων τὸν ταῦτ’ εἰπόντα, ἢ οὔ; εἰ μὲν γὰρ μή [φήσει ἂν γράψασθαι], πῶς χρὴ πιστεύειν αὐτῷ λέγοντι, ὡς φυλάττει τοὺς παράνομα γράφοντας; εἰ δ’ ἐγράψατ’ ἄν, πῶς οὐ δεινόν ἐστιν ἑτέρου μὲν γράψαντος κωλύειν ἂν τέλος ἔχειν τὸ ψήφισμα, ἵνα μὴ πάντες τοῦτο ποιῶσι, καὶ γραφὴν ἀπενεγκόντα παραγραψάμενον σαφῶς τοὺς νόμους κωλύειν τὸ πρᾶγμα,", "st": "58.46"}, {"sp": "N", "t": "νυνὶ δὲ αὐτὸν τοῦτον, μήτε πείσαντα τὸν δῆμον μήτε κοινὸν καταστήσαντα τὸ πρᾶγμα, γράφεσθαι τῶν νόμων αὐτῷ ἀπαγορευόντων (καὶ δεινὰ φήσει αὐτίκα δὴ μάλα πάσχειν, εἰ μὴ ταῦτ’ ἐξέσται ποιεῖν αὐτῷ, καὶ διέξεισι τὰς ἐκ τῶν νόμων ζημίας, αἷς ἔνοχος ἐὰν ἁλῷ γενήσεται) τῶν δὲ νόμων μὴ φροντίζειν, ἀλλ’ ἀξιοῦν αὑτῷ τηλικαύτην δωρεὰν δεδόσθαι παρ’ ὑμῶν, ὅσην οὐδ’ αἰτῆσαι τετόλμηκεν οὐδείς;", "st": "58.47"}, {"sp": "N", "t": "ὅτι μὲν οὖν περὶ τῆς ἐνδείξεως οὐδὲν ἕξει δίκαιον λέγειν οὔτε Θεοκρίνης οὔτε τῶν ὑπὲρ τούτου λεγόντων οὐδείς, σχεδὸν εἰδέναι πάντας ὑμᾶς νομίζω. οἶμαι δ’ αὐτοὺς ἐπιχειρήσειν λέγειν, ὡς οὐδ’ εἰσὶν ἐνδείξεις τούτων ὅσοι μὴ ἐν ἀκροπόλει ἐγγεγραμμένοι εἰσίν, οὐδ’ ἐστὶ δίκαιον τούτους ὑπολαμβάνειν ὀφείλειν ὧν οὐδεὶς παρέδωκε τοῖς πράκτορσι τὰ ὀνόματα,", "st": "58.48"}, {"sp": "N", "t": "ὥσπερ ὑμᾶς ἀγνοήσοντας τὸν νόμον, ὃς ὀφείλειν κελεύει ἀπ’ ἐκείνης τῆς ἡμέρας, ἀφ’ ἧς ἂν ὄφλῃ ἢ παραβῇ τὸν νόμον ἢ τὸ ψήφισμα, ἢ οὐ πᾶσι δῆλον ⟨ὂν⟩ ὅτι πολλαχῶς καὶ ὀφείλουσι τῷ δημοσίῳ καὶ ἐκτίνουσιν οἱ βουλόμενοι τοῖς νόμοις πείθεσθαι, καὶ τοῦτο ἐξ αὐτοῦ τοῦ νόμου δῆλον. καί μοι πάλιν λαβὲ τὸν νόμον τοῦτον.", "st": "58.49"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.49"}, {"sp": "N", "t": "ἀκούεις, ὦ μιαρὸν σὺ θηρίον, ὅ τι κελεύει; “ἀφ’ ἧς ἂν ὄφλῃ ἢ τὸν νόμον παραβῇ.”", "st": "58.49"}, {"sp": "N", "t": "ἀκούω τοίνυν αὐτοὺς κἀκεῖνον ὑμῖν μέλλειν δεικνύναι τὸν νόμον, ὃς ἀπαλείφειν κελεύει τοῖς ἐγγεγραμμένοις ἀπὸ τοῦ ὀφλήματος καθ’ ὅ τι ἂν ἐκτίνῃ, καὶ ἐρήσεσθαι πῶς ἀπὸ τοῦ μηδ’ ἐγγεγραμμένου ἀπαλείψουσιν, ὥσπερ οὐ περὶ μὲν τῶν ἐγγεγραμμένων τοῦτον κείμενον, περὶ δὲ τῶν μὴ ἐγγεγραμμένων ὀφειλόντων δ’ ἐκεῖνον, ὃς κελεύει ἀπ’ ἐκείνης ὀφείλειν τῆς ἡμέρας, ἀφ’ ἧς ἂν ὄφλῃ ἢ παραβῇ τὸν νόμον ἢ τὸ ψήφισμα.", "st": "58.50"}, {"sp": "N", "t": "τί οὖν οὐκ ἀγραφίου με, φήσει, γράφει, τὸν ὀφείλοντα καὶ μὴ ἐγγεγραμμένον; ὅτι ὁ νόμος οὐ κατὰ τῶν ὀφειλόντων καὶ μὴ ἐγγραφέντων κελεύει τὰς γραφὰς τοῦ ἀγραφίου εἶναι, ἀλλ’ οἵτινες ἂν ἐγγραφέντες καὶ μὴ ἐκτείσαντες τῇ πόλει τὸ ὄφλημα ἐξαλειφθῶσι. καί μοι λαβὲ τὸν νόμον καὶ ἀνάγνωθι.", "st": "58.51"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "58.51"}, {"sp": "N", "t": "ἀκούετε τοῦ νόμου, ὦ ἄνδρες δικασταί, ὅτι διαρρήδην λέγει, ἐάν τις τῶν ὀφειλόντων τῷ δημοσίῳ μὴ ἐκτείσας τὸ ὄφλημα τῇ πόλει ἐξαλειφθῇ, εἶναι κατ’ αὐτοῦ τὰς γραφὰς πρὸς τοὺς θεσμοθέτας τοῦ ἀγραφίου, καὶ οὐ κατὰ τοῦ ὀφείλοντος καὶ μὴ ἐγγεγραμμένου, ἀλλ’ ἔνδειξιν κελεύει καὶ ἄλλας τιμωρίας κατὰ τούτων εἶναι. ἀλλὰ σὺ τί διδάσκεις με πάντας τοὺς τρόπους οἷς δεῖ με τιμωρήσασθαι τοὺς ἐχθρούς, ἀλλ’ οὐ καθ’ ὃν εἰσελήλυθα, τοῦτον ἀπολογεῖ;", "st": "58.52"}, {"sp": "N", "t": "Μοιροκλῆς τοίνυν, ὦ ἄνδρες δικασταί, ὁ τὸ ψήφισμα γράψας κατὰ τῶν τοὺς ἐμπόρους ἀδικούντων, καὶ πείσας οὐ μόνον ὑμᾶς ἀλλὰ καὶ τοὺς συμμάχους φυλακήν τινα τῶν κακουργούντων ποιήσασθαι, οὐκ αἰσχυνεῖται αὐτίκα μάλα λέγων ὑπὲρ Θεοκρίνου ἐναντία τοῖς ἑαυτοῦ ψηφίσμασιν,", "st": "58.53"}, {"sp": "N", "t": "ἀλλὰ τολμήσει πείθειν ὑμᾶς ὡς χρὴ τὸν οὕτως φανερῶς ἐξεληλεγμένον φάσεις ποιούμενον ἀδίκους κατὰ τῶν ἐμπόρων ἀφεῖναι καὶ μὴ τιμωρήσασθαι, ὥσπερ ἕνεκα τούτου γράψας καθαρὰν εἶναι τὴν θάλατταν, ἵνα σωθέντες οἱ πλέοντες ἐκ τοῦ πελάγους ἐν τῷ λιμένι χρήματα τούτοις ἀποτίνωσιν, ἢ διαφέρον τι τοῖς ἐμπόροις, ἂν μακρὸν διαφυγόντες πλοῦν Θεοκρίνῃ περιπέσωσιν.", "st": "58.54"}, {"sp": "N", "t": "ἐγὼ δ’ οἶμαι τῶν μὲν κατὰ πλοῦν γιγνομένων οὐχ ὑμᾶς, ἀλλὰ τοὺς στρατηγοὺς καὶ τοὺς ἐπὶ τοῖς μακροῖς πλοίοις αἰτίους εἶναι, τῶν δ’ ἐν τῷ Πειραιεῖ καὶ πρὸς ταῖς ἀρχαῖς ὑμᾶς, οἳ τούτων κύριοι ἁπάντων ἐστέ. διὸ καὶ μᾶλλόν ἐστι τηρητέον τοὺς ἐνθάδε παραβαίνοντας τοὺς νόμους τῶν ἔξω τοῖς ψηφίσμασιν οὐκ ἐμμενόντων, ἵνα μὴ δοκῆτε αὐτοὶ πράως ἐπὶ τοῖς γιγνομένοις φέρειν καὶ συνειδέναι τι τούτοις ὧν πράττουσιν.", "st": "58.55"}, {"sp": "N", "t": "οὐ γὰρ δήπου Μηλίους μέν, ὦ Μοιρόκλεις, κατὰ τὸ σὸν ψήφισμα δέκα τάλαντα νῦν εἰσεπράξαμεν, ὅτι τοὺς λῃστὰς ὑπεδέξαντο, τουτονὶ δ’ ἀφήσομεν, ὃς καὶ τὸ σὸν ψήφισμα καὶ τοὺς νόμους, δι’ οὓς οἰκοῦμεν τὴν πόλιν, παραβέβηκεν· καὶ τοὺς μὲν τὰς νήσους οἰκοῦντας κωλύσομεν ἀδικεῖν, ἐφ’ οὓς τριήρεις δεῖ πληρώσαντας ἀναγκάσαι τὰ δίκαια ποιεῖν, ὑμᾶς δὲ τοὺς μιαρούς, οἷς αὐτοῦ δεῖ καθημένους τουτουσὶ κατὰ τοὺς νόμους ἐπιθεῖναι δίκην, ἐάσομεν; οὔκ, ἄν γε σωφρονῆτε. λέγε τὴν στήλην.", "st": "58.56"}, {"sp": "N", "t": "ΣΤΗΛΗ.", "st": "58.56"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν νόμων καὶ τοῦ πράγματος οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· ἱκανῶς γάρ μοι δοκεῖτε μεμαθηκέναι. βούλομαι δὲ δεηθεὶς ὑμῶν τὰ δίκαι’ ὑπὲρ ἐμαυτοῦ καὶ τοῦ πατρὸς καταβαίνειν καὶ μὴ ἐνοχλεῖν ὑμῖν. ἐγὼ γάρ, ὦ ἄνδρες δικασταί, βοηθεῖν οἰόμενος δεῖν τῷ πατρὶ καὶ τοῦτο δίκαιον εἶναι νομίζων,", "st": "58.57"}, {"sp": "N", "t": "τὴν ἔνδειξιν ταύτην ἐποιησάμην, ὥσπερ ἐξ ἀρχῆς εἶπον, οὐκ ἀγνοῶν οὔτε τοὺς βλασφημεῖν βουλομένους, ὅτι λόγους εὑρήσουσι τοὺς διαβαλοῦντας τὴν ἐμὴν ἡλικίαν, οὔτε τοὺς ἐπαινεσομένους καὶ σωφρονεῖν με νομιοῦντας, εἰ τὸν ἐχθρὸν τοῦ πατρὸς τιμωρεῖσθαι προαιροῦμαι, ἀλλ’ ἡγούμενος ταῦτα μὲν οὕτως ὅπως ἂν τύχῃ παρὰ τοῖς ἀκροωμένοις συμβήσεσθαι, ἐμοὶ δὲ τὸ προσταχθὲν ὑπὸ τοῦ πατρός, ἄλλως τε καὶ δίκαιον ὄν, τοῦτ’ εἶναι ποιητέον.", "st": "58.58"}, {"sp": "N", "t": "πότε γάρ με καὶ δεῖ βοηθεῖν αὐτῷ; οὐχ ὅταν ἡ μὲν τιμωρία κατὰ τοὺς νόμους ᾖ, μετέχων δ’ αὐτὸς τυγχάνω τῆς τοῦ πατρὸς ἀτυχίας, μόνος δὲ καταλελειμμένος ὁ πατήρ; ὅπερ νῦν συμβέβηκεν. πρὸς γὰρ τοῖς ἄλλοις ἀτυχήμασι καὶ τοῦθ’ ἡμῖν, ὦ ἄνδρες δικασταί, συμβέβηκεν· παροξύνουσι μὲν ἡμᾶς ἅπαντες καὶ συνάχθεσθαί φασι τοῖς γεγενημένοις καὶ δεινὰ πεπονθέναι λέγουσι καὶ τοῦτον εἶναι ἔνοχον τῇ ἐνδείξει, συμπράττειν δ’ οὐδεὶς ἐθέλει τῶν εἰπόντων, οὐδέ φησιν ἀπεχθάνεσθαι βούλεσθαι φανερῶς· οὕτως ἔλαττον παρά τισιν τὸ δίκαιον ἰσχύει τῆς παρρησίας.", "st": "58.59"}, {"sp": "N", "t": "πολλῶν δ’ ἡμῖν, ὦ ἄνδρες δικασταί, διὰ τουτονὶ Θεοκρίνην ἀτυχημάτων ἐν οὐκ ὀλίγῳ χρόνῳ συμβεβηκότων, οὐδενὸς ἔλαττόν ἐστιν τὸ νῦν συμβαῖνον, ὅτι τὰ δεινὰ καὶ τὰ παρὰ τοὺς νόμους πεπραγμένα Θεοκρίνῃ τῷ μὲν πατρὶ τῷ πεπονθότι καὶ δυναμένῳ ἂν δηλῶσαι πρὸς ὑμᾶς ἐξ ἀνάγκης ἡσυχίαν ἑκτέον ἐστίν (οἱ γὰρ νόμοι ταῦτα κελεύουσιν), ἐμοὶ δὲ τῷ πάντων τούτων ὑστερίζοντι λεκτέον, καὶ τοῖς μὲν ἄλλοις τοῖς τηλικούτοις οἱ πατέρες βοηθοῦσιν, οὗτος δ’ ἐν ἐμοὶ νῦν ἔχει τὰς ἐλπίδας.", "st": "58.60"}, {"sp": "N", "t": "τοιοῦτον οὖν ἀγωνιζόμενοι ἀγῶνα δεόμεθ’ ὑμῶν ἐπικουρεῖν ἡμῖν, καὶ δεῖξαι πᾶσιν ὅτι, κἂν παῖς κἂν γέρων κἂν ἡντινοῦν ἡλικίαν ἔχων ἥκῃ πρὸς ὑμᾶς κατὰ τοὺς νόμους, οὗτος τεύξεται πάντων τῶν δικαίων. καλὸν γάρ, ὦ ἄνδρες δικασταί, μήτε τοὺς νόμους μήθ’ ὑμᾶς αὐτοὺς ἐπὶ τοῖς λέγουσι ποιεῖν, ἀλλ’ ἐκείνους ἐφ’ ὑμῖν, καὶ χωρὶς κρίνειν τούς τ’ εὖ καὶ σαφῶς καὶ τοὺς τὰ δίκαια λέγοντας· περὶ γὰρ τούτου τὴν ψῆφον ὀμωμόκατ’ οἴσειν.", "st": "58.61"}, {"sp": "N", "t": "οὐ γὰρ δὴ πείσει γ’ ὑμᾶς οὐδεὶς ὡς ἐπιλείψουσιν οἱ τοιοῦτοι ῥήτορες, οὐδ’ ὡς διὰ τοῦτο χεῖρον ἡ πόλις οἰκήσεται. τοὐναντίον γάρ ἐστιν, ὡς ἐγὼ τῶν πρεσβυτέρων ἀκούω· τότε γάρ φασιν ἄριστα πρᾶξαι τὴν πόλιν, ὅτε μέτριοι καὶ σώφρονες ἄνδρες ἐπολιτεύοντο. πότερον γὰρ συμβούλους εὕροι τις ἂν τούτους ἀγαθούς; ἀλλ’ οὐδὲν ἐν τῷ δήμῳ λέγουσιν, ἀλλὰ τοὺς ἐκεῖθεν γραφόμενοι χρήματα λαμβάνουσιν.", "st": "58.62"}, {"sp": "N", "t": "ὃ καὶ θαυμάσιόν ἐστιν, ὅτι ζῶντες ἐκ τοῦ συκοφαντεῖν οὔ φασι λαμβάνειν ἀπὸ τῆς πόλεως· καὶ πρὶν προσελθεῖν πρὸς ὑμᾶς οὐδὲν ἔχοντες, νῦν εὐποροῦντες οὐδὲ χάριν ὑμῖν ἔχουσιν, ἀλλὰ περιιόντες λέγουσιν ὡς ἀβέβαιός ἐστιν ὁ δῆμος, ὡς δυσχερής, ὡς ἀχάριστος, ὥσπερ ὑμᾶς διὰ τούτους εὐποροῦντας, οὐ τούτους διὰ τὸν δῆμον. ἀλλὰ γὰρ εἰκότως ταῦθ’ οὗτοι λέγουσιν, ὁρῶντες τὴν ὑμετέραν ῥᾳθυμίαν. οὐδένα γὰρ ἀξίως αὐτῶν τῆς πονηρίας τετιμώρησθε, ἀλλ’ ὑπομένετε λεγόντων αὐτῶν ὡς ἡ τοῦ δήμου σωτηρία διὰ τῶν γραφομένων καὶ συκοφαντούντων ἐστίν· ὧν γένος ἐξω- λέστερον οὐδέν ἐστιν.", "st": "58.63"}, {"sp": "N", "t": "τί γὰρ ἄν τις τούτους εὕροι χρησίμους ὄντας τῇ πόλει; τοὺς ἀδικοῦντας νὴ Δί’ οὗτοι κολάζουσιν, καὶ διὰ τούτους ἐλάττους εἰσὶν ἐκεῖνοι. οὐ δῆτα, ὦ ἄνδρες δικασταί, ἀλλὰ καὶ πλείους· εἰδότες γὰρ οἱ κακόν τι βουλόμενοι πράττειν ὅτι τούτοις ἐστὶν ἀπὸ τῶν λημμάτων τὸ μέρος δοτέον, ἐξ ἀνάγκης μείζω προαιροῦνται παρὰ τῶν ἄλλων ἁρπάζειν, ἵνα μὴ μόνον αὑτοῖς, ἀλλὰ καὶ τούτοις ἔχωσιν ἀναλίσκειν.", "st": "58.64"}, {"sp": "N", "t": "καὶ τοὺς μὲν ἄλλους ὅσοι κακουργοῦντες βλάπτουσί τι τοὺς ἐντυγχάνοντας, τοὺς μὲν τῶν οἴκοι φυλακὴν καταστήσαντας [σῴζειν ἔστι], τοὺς δ’ ἔνδον μένοντας τῆς νυκτὸς [μηδὲν παθεῖν], τοὺς δ’ ἑνί γέ τῳ τρόπῳ φυλαξαμένους ἔνεστι διώσασθαι τὴν τῶν κακόν τι ποιεῖν βουλομένων ἐπιβουλήν· τοὺς δὲ τοιουτουσὶ συκοφάντας, ποῖ χρὴ πορευθέντας ἀδείας παρὰ τούτων τυχεῖν; αἱ γὰρ τῶν ἄλλων ἀδικημάτων καταφυγαὶ τούτοις εἰσὶν ἐργασίαι, νόμοι, δικαστήρια, μάρτυρες, ἀγοραί· ἐν οἷς τὰς αὑτῶν ῥώμας ἐπιδείκνυνται, φίλους μὲν τοὺς διδόντας νομίζοντες, ἐχθροὺς δὲ τοὺς ἀπράγμονας καὶ πλουσίους.", "st": "58.65"}, {"sp": "N", "t": "ἀναμνησθέντες οὖν, ὦ ἄνδρες δικασταί, καὶ τῆς τούτων πονηρίας καὶ τῶν προγόνων τῶν ἡμετέρων, ὧν Ἐπιχάρης μὲν ὁ πάππος ὁ ἐμὸς Ὀλυμπίασι νικήσας παῖδας στάδιον ἐστεφάνωσε τὴν πόλιν, καὶ παρὰ τοῖς ὑμετέροις προγόνοις ἐπιεικῆ δόξαν ἔχων ἐτελεύτησεν· ἡμεῖς δὲ διὰ τοῦτον τὸν θεοῖς ἐχθρὸν ἀπεστερήμεθα ταύτης τῆς πόλεως,", "st": "58.66"}, {"sp": "N", "t": "ὑπὲρ ἧς Ἀριστοκράτης ὁ Σκελίου, θεῖος ὢν Ἐπιχάρους τοῦ πάππου τοῦ ἐμοῦ, οὗ ἔχει ἁδελφὸς οὑτοσὶ τοὔνομα, πολλὰ καὶ καλὰ διαπραξάμενος ἔργα πολεμούσης τῆς πόλεως Λακεδαιμονίοις, κατασκάψας τὴν Ἠετιώνειαν, εἰς ἣν Λακεδαιμονίους ἔμελλον οἱ περὶ Κριτίαν ὑποδέχεσθαι, καθεῖλε μὲν τὸ ἐπιτείχισμα, κατήγαγε δὲ τὸν δῆμον κινδυνεύων αὐτὸς οὐ τοιούτους κινδύνους, ἀλλ’ ἐν οἷς καὶ παθεῖν τι καλόν ἐστιν, ἔπαυσε δὲ τοὺς ἐπιβουλεύοντας ὑμῖν.", "st": "58.67"}, {"sp": "N", "t": "δι’ ὅν, εἰ Θεοκρίνῃ τουτῳὶ ὅμοιοι ὄντες ἐτυγχάνομεν, εἰκότως ἐσῴζετ’ ἂν ἡμᾶς, μὴ ὅτι βελτίους ὄντας τούτου καὶ δίκαια λέγοντας. οὐ γὰρ πολλάκις ὑμᾶς ταῦτα λέγοντες ἐνοχλήσομεν· οὕτως γὰρ ἡμᾶς οὗτος διατέθηκεν ὥστε, ὅπερ ἐξ ἀρχῆς εἶπον, μηδ’ ἐλπίδ’ ἡμῖν εἶναι μηδεμίαν τοῦ μετασχεῖν τῆς καὶ τοῖς ξένοις δεδομένης παρρησίας.", "st": "58.68"}, {"sp": "N", "t": "ἵν’ οὖν, εἰ καὶ μηδὲν ἄλλο, ταύτην γε ἔχωμεν παραψυχήν, τὸ καὶ τοῦτον ὁρᾶν ἡσυχίαν ἄγοντα, βοηθήσαθ’ ἡμῖν, ἐλεήσατε τοὺς ὑπὲρ τῆς πατρίδος ἡμῶν τετελευτηκότας, ἀναγκάσατ’ αὐτὸν ὑπὲρ αὐτῆς τῆς ἐνδείξεως ἀπολογεῖσθαι, καὶ τοιοῦτοι γένεσθ’ αὐτῷ δικασταὶ τῶν λεγομένων οἷος ἡμῶν οὗτος ἐγένετο κατήγορος,", "st": "58.69"}, {"sp": "N", "t": "ὃς ἐξαπατήσας τοὺς δικαστὰς οὐκ ἠθέλησε τιμήσασθαι μετρίου τινὸς τιμήματος τῷ πατρὶ τῷ ἐμῷ, πολλὰ ἐμοῦ δεηθέντος καὶ τοῦτον ἱκετεύσαντος πρὸς τῶν γονάτων, ἀλλ’ ὥσπερ τὴν πόλιν προδεδωκότι τῷ πατρὶ δέκα ταλάντων ἐτιμήσατο. δεόμεθ’ οὖν ὑμῶν, ἀντιβολοῦμεν, τὰ δίκαια ψηφίζεσθε.", "st": "58.70"}, {"sp": "N", "t": "βοήθησον ἡμῖν ὁ δεῖνα, εἴ τι ἔχεις, καὶ σύνειπε. ἀνάβηθι.", "st": "58.70"}, {"sp": "HDR", "t": "Κατὰ Νεαίρας", "st": "59"}, {"sp": "N", "t": "πολλά με τὰ παρακαλοῦντα ἦν, ὦ ἄνδρες Ἀθηναῖοι, γράψασθαι Νέαιραν τὴν γραφὴν ταυτηνὶ καὶ εἰσελθεῖν εἰς ὑμᾶς. καὶ γὰρ ἠδικήμεθα ὑπὸ Στεφάνου μεγάλα, καὶ εἰς κινδύνους τοὺς ἐσχάτους κατέστημεν ὑπ’ αὐτοῦ, ὅ τε κηδεστὴς καὶ ἐγὼ καὶ ἡ ἀδελφὴ καὶ ἡ γυνὴ ἡ ἐμή, ὥστε οὐχ ὑπάρχων ἀλλὰ τιμωρούμενος ἀγωνιοῦμαι τὸν ἀγῶνα τουτονί· τῆς γὰρ ἔχθρας πρότερος οὗτος ὑπῆρξεν, οὐδὲν ὑφ’ ἡμῶν πώποτε οὔτε λόγῳ οὔτε ἔργῳ κακὸν παθών. βούλομαι δ’ ὑμῖν προδιηγήσασθαι πρῶτον ἃ πεπόνθαμεν ὑπ’ αὐτοῦ, ἵνα μᾶλλόν μοι συγγνώμην ἔχητε ἀμυνομένῳ, καὶ ὡς εἰς ⟨τοὺς⟩ ἐσχάτους κινδύνους κατέστημεν περί τε τῆς πατρίδος καὶ περὶ ἀτιμίας.", "st": "59.1"}, {"sp": "N", "t": "ψηφισαμένου γὰρ τοῦ δήμου τοῦ Ἀθηναίων Ἀθηναῖον εἶναι Πασίωνα καὶ ἐκγόνους τοὺς ἐκείνου διὰ τὰς εὐεργεσίας τὰς εἰς τὴν πόλιν, ὁμογνώμων καὶ ὁ πατὴρ ἐγένετο ὁ ἐμὸς τῇ τοῦ δήμου δωρεᾷ, καὶ ἔδωκεν Ἀπολλοδώρῳ τῷ υἱεῖ τῷ ἐκείνου θυγατέρα μὲν αὑτοῦ, ἀδελφὴν δὲ ἐμήν, ἐξ ἧς Ἀπολλοδώρῳ οἱ παῖδές εἰσιν. ὄντος δὲ χρηστοῦ τοῦ Ἀπολλοδώρου περί τε τὴν ἀδελφὴν τὴν ἐμὴν καὶ περὶ ἡμᾶς ἅπαντας, καὶ ἡγουμένου τῇ ἀληθείᾳ οἰκείους ὄντας κοινωνεῖν πάντων τῶν ὄντων, ἔλαβον καὶ ἐγὼ γυναῖκα Ἀπολλοδώρου μὲν θυγατέρα, ἀδελφιδῆν δ’ ἐμαυτοῦ.", "st": "59.2"}, {"sp": "N", "t": "προεληλυθότος δὲ χρόνου λαγχάνει βουλεύειν Ἀπολλόδωρος· δοκιμασθεὶς δὲ καὶ ὀμόσας τὸν νόμιμον ὅρκον, συμβάντος τῇ πόλει καιροῦ τοιούτου καὶ πολέμου, ἐν ᾧ ἦν ἢ κρατήσασιν ὑμῖν μεγίστοις τῶν Ἑλλήνων εἶναι καὶ ἀναμφισβητήτως τά τε ὑμέτερα αὐτῶν κεκομίσθαι καὶ καταπεπολεμηκέναι Φίλιππον, ἢ ὑστερίσασι τῇ βοηθείᾳ καὶ προεμένοις τοὺς συμμάχους, δι’ ἀπορίαν χρημάτων καταλυθέντος τοῦ στρατοπέδου, τούτους τ’ ἀπολέσαι καὶ τοῖς ἄλλοις Ἕλλησιν ἀπίστους εἶναι δοκεῖν, καὶ κινδυνεύειν περὶ τῶν ὑπολοίπων, περί τε Λήμνου καὶ Ἴμβρου καὶ Σκύρου καὶ Χερρονήσου,", "st": "59.3"}, {"sp": "N", "t": "καὶ μελλόντων στρατεύεσθαι ὑμῶν πανδημεὶ εἴς τε Εὔβοιαν καὶ Ὄλυνθον, ἔγραψε ψήφισμα ἐν τῇ βουλῇ Ἀπολλόδωρος βουλεύων καὶ ἐξήνεγκε προβούλευμα εἰς τὸν δῆμον, λέγον διαχειροτονῆσαι τὸν δῆμον εἴτε δοκεῖ τὰ περιόντα χρήματα τῆς διοικήσεως στρατιωτικὰ εἶναι εἴτε θεωρικά, κελευόντων μὲν τῶν νόμων, ὅταν πόλεμος ᾖ, τὰ περιόντα χρήματα τῆς διοικήσεως στρατιωτικὰ εἶναι, κύριον δ’ ἡγούμενος δεῖν τὸν δῆμον εἶναι περὶ τῶν αὑτοῦ ὅ τι ἂν βούληται πρᾶξαι, ὀμωμοκὼς δὲ τὰ βέλτιστα βουλεύσειν τῷ δήμῳ τῷ Ἀθηναίων, ὡς ὑμεῖς πάντες ἐμαρτυρήσατε ἐν ἐκείνῳ τῷ καιρῷ.", "st": "59.4"}, {"sp": "N", "t": "γενομένης γὰρ τῆς διαχειροτονίας, οὐδεὶς ἀντεχειροτόνησεν ὡς οὐ δεῖ τοῖς χρήμασι τούτοις στρατιωτικοῖς χρῆσθαι, ἀλλὰ καὶ νῦν ἔτι, ἄν που λόγος γένηται, παρὰ πάντων ὁμολογεῖται ὡς τὰ βέλτιστα εἰπὼν ἄδικα πάθοι. τῷ οὖν ἐξαπατήσαντι τῷ λόγῳ τοὺς δικαστὰς δίκαιον ὀργίζεσθαι, οὐ τοῖς ἐξαπατηθεῖσιν. γραψάμενος γὰρ παρανόμων τὸ ψήφισμα Στέφανος οὑτοσὶ καὶ εἰσελθὼν εἰς τὸ δικαστήριον, ἐπὶ διαβολῇ ψευδεῖς μάρτυρας παρασχόμενος ὡς ὦφλε τῷ δημοσίῳ ἐκ πέντε καὶ εἴκοσιν ἐτῶν, καὶ ἔξω τῆς γραφῆς πολλὰ κατηγορῶν, εἷλε τὸ ψήφισμα.", "st": "59.5"}, {"sp": "N", "t": "καὶ τοῦτο μὲν εἰ αὐτῷ ἐδόκει διαπράξασθαι, οὐ χαλεπῶς φέρομεν· ἀλλ’ ἐπειδὴ περὶ τοῦ τιμήματος ἐλάμβανον τὴν ψῆφον οἱ δικασταί, δεομένων ἡμῶν συγχωρῆσαι οὐκ ἤθελεν, ἀλλὰ πεντεκαίδεκα ταλάντων ἐτιμᾶτο, ἵνα ἀτιμώσειεν αὐτὸν καὶ παῖδας τοὺς ἐκείνου, καὶ τὴν ἀδελφὴν τὴν ἐμὴν καὶ ἡμᾶς ἅπαντας εἰς τὴν ἐσχάτην ἀπορίαν καταστήσειεν καὶ ἔνδειαν ἁπάντων.", "st": "59.6"}, {"sp": "N", "t": "ἡ μὲν γὰρ οὐσία οὐδὲ τριῶν ταλάντων πάνυ τι ἦν, ὥστε δυνηθῆναι ἐκτεῖσαι τοσοῦτον ὄφλημα· μὴ ἐκτεισθέντος δὲ τοῦ ὀφλήματος ἐπὶ τῆς ἐνάτης πρυτανείας, διπλοῦν ἔμελλεν ἔσεσθαι τὸ ὄφλημα καὶ ἐγγραφήσεσθαι Ἀπολλόδωρος τριάκοντα τάλαντα ὀφείλων τῷ δημοσίῳ· ἐγγεγραμμένου δὲ τῷ δημοσίῳ, ἀπογραφήσεσθαι ἔμελλεν ἡ ὑπάρχουσα οὐσία Ἀπολλοδώρῳ δημοσία εἶναι, πραθείσης δ’ αὐτῆς εἰς τὴν ἐσχάτην ἀπορίαν καταστήσεσθαι καὶ αὐτὸς καὶ παῖδες οἱ ἐκείνου καὶ γυνὴ καὶ ἡμεῖς ἅπαντες.", "st": "59.7"}, {"sp": "N", "t": "ἔτι δὲ καὶ ἡ ἑτέρα θυγάτηρ ἀνέκδοτος ἔμελλεν ἔσεσθαι· τίς γὰρ ἄν ποτε παρ’ ὀφείλοντος τῷ δημοσίῳ καὶ ἀποροῦντος ἔλαβεν ἄπροικον; οὐκοῦν τηλικούτων κακῶν αἴτιος ἡμῖν πᾶσιν ἐγίγνετο, οὐδὲν πώποτε ὑφ’ ἡμῶν ἠδικημένος. τοῖς μὲν οὖν δικασταῖς τοῖς τότε δικάσασι πολλὴν χάριν κατά γε τοῦτο ἔχω, ὅτι οὐ περιεῖδον αὐτὸν ἀναρπασθέντα, ἀλλ’ ἐτίμησαν ταλάντου, ὥστε δυνηθῆναι ἐκτεῖσαι μόλις· τούτῳ δὲ δικαίως τὸν αὐτὸν ἔρανον ἐνεχειρήσαμεν ἀποδοῦναι.", "st": "59.8"}, {"sp": "N", "t": "καὶ γὰρ οὐ μόνον ταύτῃ ἐζήτησεν ἀνελεῖν ἡμᾶς, ἀλλὰ καὶ ἐκ τῆς πατρίδος αὐτὸν ἐβουλήθη ἐκβαλεῖν. ἐπενέγκας γὰρ αὐτῷ αἰτίαν ψευδῆ ὡς Ἀφίδναζέ ποτε ἀφικόμενος ἐπὶ δραπέτην αὑτοῦ ζητῶν πατάξειε γυναῖκα καὶ ἐκ τῆς πληγῆς τελευτήσειεν ἡ ἄνθρωπος, παρασκευασάμενος ἀνθρώπους δούλους καὶ κατασκευάσας ὡς Κυρηναῖοι εἴησαν, προεῖπεν αὐτῷ ἐπὶ Παλλαδίῳ φόνου.", "st": "59.9"}, {"sp": "N", "t": "καὶ ἔλεγεν τὴν δίκην Στέφανος οὑτοσί, διομοσάμενος ὡς ἔκτεινεν Ἀπολλόδωρος τὴν γυναῖκα αὐτοχειρίᾳ, ἐξώλειαν αὑτῷ καὶ γένει καὶ οἰκίᾳ ἐπαρασάμενος, ἃ οὔτ’ ἐγένετο οὔτ’ εἶδεν οὔτ’ ἤκουσεν οὐδενὸς πώποτε ἀνθρώπων. ἐξελεγχθεὶς δ’ ἐπιορκῶν καὶ ψευδῆ αἰτίαν ἐπιφέρων, καὶ καταφανὴς γενόμενος μεμισθωμένος ὑπὸ Κηφισοφῶντος καὶ Ἀπολλοφάνους ὥστ’ ἐξελάσαι Ἀπολλόδωρον ἢ ἀτιμῶσαι ἀργύριον εἰληφώς, ὀλίγας ψήφους μεταλαβὼν ἐκ πεντακοσίων, ἀπῆλθεν ἐπιωρκηκὼς καὶ δόξας πονηρὸς εἶναι.", "st": "59.10"}, {"sp": "N", "t": "σκοπεῖτε δὴ αὐτοί, ὦ ἄνδρες δικασταί, ἐκ τῶν εἰκότων λογιζόμενοι πρὸς ὑμᾶς αὐτούς, τί ἂν ἐχρησάμην ἐμαυτῷ καὶ τῇ γυναικὶ καὶ τῇ ἀδελφῇ, εἴ τι Ἀπολλοδώρῳ συνέβη παθεῖν ὧν Στέφανος οὑτοσὶ ἐπεβούλευσεν αὐτῷ, ἢ ἐν τῷ προτέρῳ ἢ ἐν τῷ ὑστέρῳ ἀγῶνι; ἢ ποίᾳ αἰσχύνῃ οὐκ ἂν καὶ συμφορᾷ περιπεπτωκὼς ἦν;", "st": "59.11"}, {"sp": "N", "t": "παρακαλούντων δή με ἁπάντων, ἰδίᾳ προσιόντων μοι, ἐπὶ τιμωρίαν τρέπεσθαι ὧν ἐπάθομεν ὑπ’ αὐτοῦ, καὶ ὀνειδιζόντων μοι ἀνανδρότατον ἀνθρώπων εἶναι, εἰ οὕτως οἰκείως ἔχων τὰ πρὸς τούτους μὴ λήψομαι δίκην ὑπὲρ ἀδελφῆς καὶ κηδεστοῦ καὶ ἀδελφιδῶν καὶ γυναικὸς ἐμαυτοῦ, μηδὲ τὴν περιφανῶς εἰς τοὺς θεοὺς ἀσεβοῦσαν καὶ εἰς τὴν πόλιν ὑβρίζουσαν καὶ τῶν νόμων καταφρονοῦσαν τῶν ὑμετέρων εἰσαγαγὼν εἰς ὑμᾶς καὶ ἐξελέγξας τῷ λόγῳ ὡς ἀδικεῖ, κυρίους καταστήσω ὅ τι ἂν βούλησθε χρῆσθαι αὐτῇ,", "st": "59.12"}, {"sp": "N", "t": "ὥσπερ καὶ Στέφανος οὑτοσὶ ἐμὲ ἀφῃρεῖτο τοὺς οἰκείους παρὰ τοὺς νόμους καὶ τὰ ψηφίσματα τὰ ὑμέτερα, οὕτω καὶ ἐγὼ τοῦτον ἥκω ἐπιδείξων εἰς ὑμᾶς ξένῃ μὲν γυναικὶ συνοικοῦντα παρὰ τὸν νόμον, ἀλλοτρίους δὲ παῖδας εἰσαγαγόντα εἴς τε τοὺς φράτερας καὶ εἰς τοὺς δημότας, ἐγγυῶντα δὲ τὰς τῶν ἑταιρῶν θυγατέρας ὡς αὑτοῦ οὔσας, ἠσεβηκότα δ’ εἰς τοὺς θεούς, ἄκυρον δὲ ποιοῦντα τὸν δῆμον τῶν αὑτοῦ, ἄν τινα βούληται πολίτην ποιήσασθαι· τίς γὰρ ἂν ἔτι παρὰ τοῦ δήμου ζητήσειε λαβεῖν δωρεάν, μετὰ πολλῶν ἀναλωμάτων καὶ πραγματείας πολίτης μέλλων ἔσεσθαι, ἐξὸν παρὰ Στεφάνου ἀπ’ ἐλάττονος ἀναλώματος, εἴ γε τὸ αὐτὸ τοῦτο γενήσεται αὐτῷ;", "st": "59.13"}, {"sp": "N", "t": "ἃ μὲν οὖν ἀδικηθεὶς ἐγὼ ὑπὸ Στεφάνου πρότερος ἐγραψάμην τὴν γραφὴν ταύτην, εἴρηκα πρὸς ὑμᾶς· ὡς δ’ ἐστὶν ξένη Νέαιρα αὑτηὶ καὶ συνοικεῖ Στεφάνῳ τουτῳὶ καὶ πολλὰ παρανενόμηκεν εἰς τὴν πόλιν, ταῦτ’ ἤδη δεῖ μαθεῖν ὑμᾶς. δέομαι οὖν ὑμῶν, ὦ ἄνδρες δικασταί, ἅπερ ἡγοῦμαι προσήκειν δεηθῆναι νέον τε ὄντα καὶ ἀπείρως ἔχοντα τοῦ λέγειν, συνήγορόν με κελεῦσαι καλέσαι τῷ ἀγῶνι τούτῳ Ἀπολλόδωρον.", "st": "59.14"}, {"sp": "N", "t": "καὶ γὰρ πρεσβύτερός ἐστιν ἢ ἐγώ, καὶ ἐμπειροτέρως ἔχει τῶν νόμων, καὶ μεμέληκεν αὐτῷ περὶ τούτων ἁπάντων ἀκριβῶς, καὶ ἠδίκηται ὑπὸ Στεφάνου τουτουί, ὥστε καὶ ἀνεπίφθονον αὐτῷ τιμωρεῖσθαι τὸν ὑπάρξαντα. δεῖ δ’ ὑμᾶς ἐξ αὐτῆς τῆς ἀληθείας, τὴν ἀκρίβειαν ἀκούσαντας τῆς τε κατηγορίας καὶ τῆς ἀπολογίας, οὕτως ἤδη τὴν ψῆφον φέρειν ὑπέρ τε τῶν θεῶν καὶ τῶν νόμων καὶ τοῦ δικαίου καὶ ὑμῶν αὐτῶν.", "st": "59.15"}, {"sp": "N", "t": "ΣΥΝΗΓΟΡΙΑ.", "st": "59.15"}, {"sp": "N", "t": "ἃ μὲν ἠδικημένος, ὦ ἄνδρες Ἀθηναῖοι, ὑπὸ Στεφάνου ἀναβέβηκα κατηγορήσων Νεαίρας ταυτησί, Θεόμνηστος εἴρηκεν πρὸς ὑμᾶς· ὡς δ’ ἐστὶ ξένη Νέαιρα καὶ παρὰ τοὺς νόμους συνοικεῖ Στεφάνῳ, τοῦτο ὑμῖν βούλομαι σαφῶς ἐπιδεῖξαι. πρῶτον μὲν οὖν τὸν νόμον ὑμῖν ἀναγνώσεται, καθ’ ὃν τήν τε γραφὴν ταυτηνὶ Θεόμνηστος ἐγράψατο καὶ ὁ ἀγὼν οὗτος εἰσέρχεται εἰς ὑμᾶς.", "st": "59.16"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "59.16"}, {"sp": "N", "t": "ἐὰν δὲ ξένος ἀστῇ συνοικῇ τέχνῃ ἢ μηχανῇ ᾑτινιοῦν, γραφέσθω πρὸς τοὺς θεσμοθέτας Ἀθηναίων ὁ βουλόμενος οἷς ἔξεστιν. ἐὰν δὲ ἁλῷ, πεπράσθω καὶ αὐτὸς καὶ ἡ οὐσία αὐτοῦ, καὶ τὸ τρίτον μέρος ἔστω τοῦ ἑλόντος. ἔστω δὲ καὶ ἐὰν ἡ ξένη τῷ ἀστῷ συνοικῇ κατὰ ταὐτά, καὶ ὁ συνοικῶν τῇ ξένῃ τῇ ἁλούσῃ ὀφειλέτω χιλίας δραχμάς.", "st": "59.16"}, {"sp": "N", "t": "τοῦ μὲν νόμου τοίνυν ἀκηκόατε, ὦ ἄνδρες δικασταί, ὃς οὐκ ἐᾷ τὴν ξένην τῷ ἀστῷ συνοικεῖν οὐδὲ τὴν ἀστὴν τῷ ξένῳ, οὐδὲ παιδοποιεῖσθαι, τέχνῃ οὐδὲ μηχανῇ οὐδεμιᾷ· ἐὰν δέ τις παρὰ ταῦτα ποιῇ, γραφὴν πεποίηκεν κατ’ αὐτῶν εἶναι πρὸς τοὺς θεσμοθέτας, κατά τε τοῦ ξένου καὶ τῆς ξένης, κἂν ἁλῷ, πεπρᾶσθαι κελεύει. ὡς οὖν ἐστι ξένη Νέαιρα αὑτηί, τοῦθ’ ὑμῖν βούλομαι ἐξ ἀρχῆς ἀκριβῶς ἐπιδεῖξαι.", "st": "59.17"}, {"sp": "N", "t": "ἑπτὰ γὰρ ταύτας παιδίσκας ἐκ μικρῶν παιδίων ἐκτήσατο Νικαρέτη, Χαρισίου μὲν οὖσα τοῦ Ἠλείου ἀπελευθέρα, Ἱππίου δὲ τοῦ μαγείρου τοῦ ἐκείνου γυνή, δεινὴ δὲ [καὶ δυναμένη] φύσιν μικρῶν παιδίων συνιδεῖν εὐπρεπῆ, καὶ ταῦτα ἐπισταμένη θρέψαι καὶ παιδεῦσαι ἐμπείρως, τέχνην ταύτην κατεσκευασμένη καὶ ἀπὸ τούτων τὸν βίον συνειλεγμένη.", "st": "59.18"}, {"sp": "N", "t": "προσειποῦσα δ’ αὐτὰς ὀνόματι θυγατέρας, ἵν’ ὡς μεγίστους μισθοὺς πράττοιτο τοὺς βουλομένους πλησιάζειν αὐταῖς ὡς ἐλευθέραις οὔσαις, ἐπειδὴ τὴν ἡλικίαν ἐκαρπώσατο αὐτῶν ἑκάστης, συλλήβδην καὶ τὰ σώματα ἀπέδοτο ἁπασῶν ἑπτὰ οὐσῶν, Ἄντειαν καὶ Στρατόλαν καὶ Ἀριστόκλειαν καὶ Μετάνειραν καὶ Φίλαν καὶ Ἰσθμιάδα καὶ Νέαιραν ταυτηνί.", "st": "59.19"}, {"sp": "N", "t": "ἣν μὲν οὖν ἕκαστος αὐτῶν ἐκτήσατο καὶ ὡς ἠλευθερώθησαν ἀπὸ τῶν πριαμένων αὐτὰς παρὰ τῆς Νικαρέτης, προϊόντος τοῦ λόγου, ἂν βούλησθε ἀκούειν καί μοι περιουσία ᾖ τοῦ ὕδατος, δηλώσω ὑμῖν· ὡς δὲ Νέαιρα αὑτηὶ Νικαρέτης ἦν καὶ ἠργάζετο τῷ σώματι μισθαρνοῦσα τοῖς βουλομένοις αὐτῇ πλησιάζειν, τοῦθ’ ὑμῖν βούλομαι πάλιν ἐπανελθεῖν.", "st": "59.20"}, {"sp": "N", "t": "Λυσίας γὰρ ὁ σοφιστὴς Μετανείρας ὢν ἐραστής, ἐβουλήθη πρὸς τοῖς ἄλλοις ἀναλώμασιν οἷς ἀνήλισκεν εἰς αὐτὴν καὶ μυῆσαι, ἡγούμενος τὰ μὲν ἄλλα ἀναλώματα τὴν κεκτημένην αὐτὴν λαμβάνειν, ἃ δ’ ἂν εἰς τὴν ἑορτὴν καὶ τὰ μυστήρια ὑπὲρ αὐτῆς ἀναλώσῃ, πρὸς αὐτὴν τὴν ἄνθρωπον χάριν καταθήσεσθαι. ἐδεήθη οὖν τῆς Νικαρέτης ἐλθεῖν εἰς τὰ μυστήρια ἄγουσαν τὴν Μετάνειραν, ἵνα μυηθῇ, καὶ αὐτὸς ὑπέσχετο μυήσειν.", "st": "59.21"}, {"sp": "N", "t": "ἀφικομένας δ’ αὐτὰς ὁ Λυσίας εἰς μὲν τὴν αὑτοῦ οἰκίαν οὐκ εἰσάγει, αἰσχυνόμενος τήν τε γυναῖκα ἣν εἶχε, Βραχύλλου μὲν θυγατέρα, ἀδελφιδῆν δὲ αὑτοῦ, καὶ τὴν μητέρα τὴν αὑτοῦ πρεσβυτέραν τε οὖσαν καὶ ἐν τῷ αὐτῷ διαιτωμένην· ὡς Φιλόστρατον δὲ τὸν Κολωνῆθεν, ᾔθεον ἔτι ὄντα καὶ φίλον αὐτῷ, καθίστησιν ὁ Λυσίας αὐτάς, τήν τε Μετάνειραν καὶ τὴν Νικαρέτην. συνηκολούθει δὲ καὶ Νέαιρα αὑτηί, ἐργαζομένη μὲν ἤδη τῷ σώματι, νεωτέρα δὲ οὖσα διὰ τὸ μήπω τὴν ἡλικίαν αὐτῇ παρεῖναι.", "st": "59.22"}, {"sp": "N", "t": "ὡς οὖν ἀληθῆ λέγω, ὅτι Νικαρέτης ἦν καὶ ἠκολούθει ἐκείνῃ καὶ ἐμισθάρνει τῷ βουλομένῳ ἀναλίσκειν, τούτων ὑμῖν αὐτὸν τὸν Φιλόστρατον μάρτυρα καλῶ.", "st": "59.23"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.23"}, {"sp": "N", "t": "Φιλόστρατος Διονυσίου Κολωνῆθεν μαρτυρεῖ εἰδέναι Νέαιραν Νικαρέτης οὖσαν, ἧσπερ καὶ Μετάνειρα ἐγένετο, καὶ κατάγεσθαι παρ’ αὑτῷ, ὅτε εἰς τὰ μυστήρια ἐπεδήμησαν ἐν Κορίνθῳ οἰκοῦσαι· καταστῆσαι δὲ αὐτὰς ὡς αὑτὸν Λυσίαν τὸν Κεφάλου, φίλον ὄντα ἑαυτῷ καὶ ἐπιτήδειον.", "st": "59.23"}, {"sp": "N", "t": "πάλιν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μετὰ ταῦτα Σῖμος ὁ Θετταλὸς ἔχων Νέαιραν ταυτηνὶ ἀφικνεῖται δεῦρο εἰς τὰ Παναθήναια τὰ μεγάλα. συνηκολούθει δὲ καὶ ἡ Νικαρέτη αὐτῇ, κατήγοντο δὲ παρὰ Κτησίππῳ τῷ Γλαυκωνίδου τῷ Κυδαντίδῃ, καὶ συνέπινεν καὶ συνεδείπνει ἐναντίον πολλῶν Νέαιρα αὑτηὶ ὡς ἂν ἑταίρα οὖσα. καὶ ὅτι ἀληθῆ λέγω, τούτων ὑμῖν τοὺς μάρτυρας καλῶ.", "st": "59.24"}, {"sp": "N", "t": "καί μοι κάλει Εὐφίλητον Σίμωνος Αἰξωνέα καὶ Ἀριστόμαχον Κριτοδήμου Ἀλωπεκῆθεν.", "st": "59.25"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "59.25"}, {"sp": "N", "t": "Εὐφίλητος Σίμωνος Αἰξωνεύς, Ἀριστόμαχος Κριτοδήμου Ἀλωπεκῆθεν, μαρτυροῦσιν εἰδέναι Σῖμον τὸν Θετταλὸν ἀφικόμενον Ἀθήναζε εἰς τὰ Παναθήναια τὰ μεγάλα, καὶ μετ’ αὐτοῦ Νικαρέτην καὶ Νέαιραν τὴν νυνὶ ἀγωνιζομένην· καὶ κατάγεσθαι αὐτοὺς παρὰ Κτησίππῳ τῷ Γλαυκωνίδου, καὶ συμπίνειν μετ’ αὐτῶν Νέαιραν ὡς ἑταίραν οὖσαν καὶ ἄλλων πολλῶν παρόντων καὶ συμπινόντων παρὰ Κτησίππῳ.", "st": "59.25"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν ἐν τῇ Κορίνθῳ αὐτῆς ἐπιφανῶς ἐργαζομένης καὶ οὔσης λαμπρᾶς ἄλλοι τε ἐρασταὶ γίγνονται καὶ Ξενοκλείδης ὁ ποιητὴς καὶ Ἵππαρχος ὁ ὑποκριτής, καὶ εἶχον αὐτὴν μεμισθωμένοι. καὶ ὅτι ἀληθῆ λέγω, τοῦ μὲν Ξενοκλείδου οὐκ ἂν δυναίμην ὑμῖν μαρτυρίαν παρασχέσθαι·", "st": "59.26"}, {"sp": "N", "t": "οὐ γὰρ ἐῶσιν αὐτὸν οἱ νόμοι μαρτυρεῖν· ὅτε γὰρ Λακεδαιμονίους ὑμεῖς ἐσῴζετε πεισθέντες ὑπὸ Καλλιστράτου, τότε ἀντειπὼν ἐν τῷ δήμῳ τῇ βοηθείᾳ, ἐωνημένος τὴν πεντηκοστὴν τοῦ σίτου ἐν εἰρήνῃ καὶ δέον αὐτὸν καταβάλλειν τὰς καταβολὰς εἰς τὸ βουλευτήριον κατὰ πρυτανείαν, καὶ οὔσης αὐτῷ ἀτελείας ἐκ τῶν νόμων οὐκ ἐξελθὼν ἐκείνην τὴν στρατείαν, γραφεὶς ὑπὸ Στεφάνου τουτουὶ ἀστρατείας καὶ διαβληθεὶς τῷ λόγῳ ἐν τῷ δικαστηρίῳ ἑάλω καὶ ἠτιμώθη.", "st": "59.27"}, {"sp": "N", "t": "καίτοι πῶς οὐκ οἴεσθε δεινὸν εἶναι, εἰ τοὺς μὲν φύσει πολίτας καὶ γνησίως μετέχοντας τῆς πόλεως ἀπεστέρηκε τῆς παρρησίας Στέφανος οὑτοσί, τοὺς δὲ μηδὲν προσήκοντας βιάζεται Ἀθηναίους εἶναι παρὰ πάντας τοὺς νόμους; τὸν δ’ Ἵππαρχον αὐτὸν ὑμῖν καλῶ, καὶ ἀναγκάσω μαρτυρεῖν ἢ ἐξόμνυσθαι κατὰ τὸν νόμον, ἢ κλητεύσω αὐτόν. καί μοι κάλει Ἵππαρχον.", "st": "59.28"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.28"}, {"sp": "N", "t": "Ἵππαρχος Ἀθμονεὺς μαρτυρεῖ Ξενοκλείδην καὶ αὑτὸν μισθώσασθαι Νέαιραν ἐν Κορίνθῳ τὴν νῦν ἀγωνιζομένην, ὡς ἑταίραν οὖσαν τῶν μισθαρνουσῶν, καὶ συμπίνειν ἐν Κορίνθῳ Νέαιραν μεθ’ αὑτοῦ καὶ Ξενοκλείδου τοῦ ποιητοῦ.", "st": "59.28"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν αὐτῆς γίγνονται ἐρασταὶ δύο, Τιμανορίδας τε ὁ Κορίνθιος καὶ Εὐκράτης ὁ Λευκάδιος, οἳ ἐπειδήπερ πολυτελὴς ἦν ἡ Νικαρέτη τοῖς ἐπιτάγμασιν, ἀξιοῦσα τὰ καθ’ ἡμέραν ἀναλώματα ἅπαντα τῇ οἰκίᾳ παρ’ αὐτῶν λαμβάνειν, κατατιθέασιν αὐτῆς τιμὴν τριάκοντα μνᾶς τοῦ σώματος τῇ Νικαρέτῃ, καὶ ὠνοῦνται αὐτὴν παρ’ αὐτῆς νόμῳ πόλεως καθάπαξ αὑτῶν δούλην εἶναι. καὶ εἶχον καὶ ἐχρῶντο ὅσον ἐβούλοντο αὐτῇ χρόνον.", "st": "59.29"}, {"sp": "N", "t": "μέλλοντες δὲ γαμεῖν, προαγορεύουσιν αὐτῇ, ὅτι οὐ βούλονται αὐτὴν σφῶν αὐτῶν ἑταίραν γεγενημένην ὁρᾶν ἐν Κορίνθῳ ἐργαζομένην οὐδ’ ὑπὸ πορνοβοσκῷ οὖσαν, ἀλλ’ ἡδέως ἂν αὑτοῖς εἴη ἔλαττόν τε τἀργύριον κομίσασθαι παρ’ αὐτῆς ἢ κατέθεσαν, καὶ αὐτὴν ταύτην ὁρᾶν τι ἀγαθὸν ἔχουσαν. ἀφιέναι οὖν αὐτῇ ἔφασαν εἰς ἐλευθερίαν χιλίας δραχμάς, πεντακοσίας ἑκάτερος· τὰς δ’ εἴκοσι μνᾶς ἐκέλευον αὐτὴν ἐξευροῦσαν αὑτοῖς ἀποδοῦναι. ἀκούσασα δ’ αὕτη τοὺς λόγους τούτους τοῦ τε Εὐκράτους καὶ Τιμανορίδου, μεταπέμπεται εἰς τὴν Κόρινθον ἄλλους τε τῶν ἐραστῶν τῶν γεγενημένων αὐτῇ καὶ Φρυνίωνα τὸν Παιανιέα, Δήμωνος μὲν ὄντα υἱόν, Δημοχάρους δὲ ἀδελφόν, ἀσελγῶς δὲ καὶ πολυτελῶς διάγοντα τὸν βίον, ὡς ὑμῶν οἱ πρεσβύτεροι μνημονεύουσιν.", "st": "59.30"}, {"sp": "N", "t": "ἀφικομένου δ’ ὡς αὐτὴν τοῦ Φρυνίωνος, λέγει πρὸς αὐτὸν τοὺς λόγους οὓς εἶπον πρὸς αὐτὴν ὅ τε Εὐκράτης καὶ Τιμανορίδας, καὶ δίδωσιν αὐτῷ τὸ ἀργύριον ὃ παρὰ τῶν ἄλλων ἐραστῶν ἐδασμολόγησεν ἔρανον εἰς τὴν ἐλευθερίαν συλλέγουσα, καὶ εἴ τι ἄρα αὐτὴ περιεποιήσατο, καὶ δεῖται αὐτοῦ προσθέντα τὸ ἐπίλοιπον, οὗ προσέδει εἰς τὰς εἴκοσι μνᾶς, καταθεῖναι αὑτῆς τῷ τε Εὐκράτει καὶ τῷ Τιμανορίδᾳ ὥστε ἐλευθέραν εἶναι.", "st": "59.31"}, {"sp": "N", "t": "ἅσμενος δ’ ἀκούσας ἐκεῖνος τοὺς λόγους τούτους αὐτῆς, καὶ λαβὼν τἀργύριον ὃ παρὰ τῶν ἐραστῶν τῶν ἄλλων εἰσηνέχθη αὐτῇ, καὶ προσθεὶς τὸ ἐπίλοιπον αὐτός, κατατίθησιν αὐτῆς τὰς εἴκοσι μνᾶς τῷ Εὐκράτει καὶ τῷ Τιμανορίδᾳ ἐπ’ ἐλευθερίᾳ καὶ ἐφ’ ᾧ ἐν Κορίνθῳ μὴ ἐργάζεσθαι. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν τὸν παραγενόμενον μάρτυρα καλῶ. καί μοι κάλει Φίλαγρον Μελιτέα.", "st": "59.32"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.32"}, {"sp": "N", "t": "Φίλαγρος Μελιτεὺς μαρτυρεῖ παρεῖναι ἐν Κορίνθῳ, ὅτε Φρυνίων ὁ Δημοχάρους ἀδελφὸς κατετίθει εἴκοσι μνᾶς Νεαίρας τῆς νῦν ἀγωνιζομένης Τιμανορίδᾳ τῷ Κορινθίῳ καὶ Εὐκράτει τῷ Λευκαδίῳ, καὶ καταθεὶς τὸ ἀργύριον ᾤχετο ἀπάγων Ἀθήναζε Νέαιραν.", "st": "59.32"}, {"sp": "N", "t": "ἀφικόμενος τοίνυν δεῦρο ἔχων αὐτὴν ἀσελγῶς καὶ προπετῶς ἐχρῆτο αὐτῇ, καὶ ἐπὶ τὰ δεῖπνα ἔχων αὐτὴν πανταχοῖ ἐπορεύετο ὅπου πίνοι, ἐκώμαζέ τ’ ἀεὶ μετ’ αὐτοῦ, συνῆν τ’ ἐμφανῶς ὁπότε βουληθείη πανταχοῦ, φιλοτιμίαν τὴν ἐξουσίαν πρὸς τοὺς ὁρῶντας ποιούμενος. καὶ ὡς ἄλλους τε πολλοὺς ἐπὶ κῶμον ἔχων ἦλθεν αὐτὴν καὶ ὡς Χαβρίαν τὸν Αἰξωνέα, ὅτε ἐνίκα ἐπὶ Σωκρατίδου ἄρχοντος τὰ Πύθια τῷ τεθρίππῳ ὃ ἐπρίατο παρὰ τῶν παίδων τῶν Μίτυος τοῦ Ἀργείου, καὶ ἥκων ἐκ Δελφῶν εἱστία τὰ ἐπινίκια ἐπὶ Κωλιάδι. καὶ ἐκεῖ ἄλλοι τε πολλοὶ συνεγίγνοντο αὐτῇ μεθυούσῃ καθεύδοντος τοῦ Φρυνίωνος, καὶ οἱ διάκονοι οἱ Χαβρίου τράπεζαν παραθέμενοι.", "st": "59.33"}, {"sp": "N", "t": "καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, τοὺς ὁρῶντας ὑμῖν καὶ παρόντας μάρτυρας παρέξομαι. καί μοι κάλει Χιωνίδην Ξυπεταιόνα καὶ Εὐθετίωνα Κυδαθηναιᾶ.", "st": "59.34"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.34"}, {"sp": "N", "t": "Χιωνίδης Ξυπεταιών, Εὐθετίων Κυδαθηναιεὺς μαρτυροῦσι κληθῆναι ὑπὸ Χαβρίου ἐπὶ δεῖπνον, ὅτε τὰ ἐπινίκια εἱστία Χαβρίας τῆς νίκης τοῦ ἅρματος, καὶ ἑστιᾶσθαι ἐπὶ Κωλιάδι, καὶ εἰδέναι Φρυνίωνα παρόντα ἐν τῷ δείπνῳ τούτῳ ἔχοντα Νέαιραν τὴν νυνὶ ἀγωνιζομένην, καὶ καθεύδειν σφᾶς αὐτοὺς καὶ Φρυνίωνα καὶ Νέαιραν, καὶ αἰσθάνεσθαι αὐτοὶ ἀνισταμένους τῆς νυκτὸς πρὸς Νέαιραν ἄλλους τε καὶ τῶν διακόνων τινάς, οἳ ἦσαν Χαβρίου οἰκέται.", "st": "59.34"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἀσελγῶς προὐπηλακίζετο ὑπὸ τοῦ Φρυνίωνος καὶ οὐχ ὡς ᾤετο ἠγαπᾶτο, οὐδ’ ὑπηρέτει αὐτῇ ἃ ἐβούλετο, συσκευασαμένη αὐτοῦ τὰ ἐκ τῆς οἰκίας καὶ ὅσα ἦν αὐτῇ ὑπ’ ἐκείνου περὶ τὸ σῶμα κατεσκευασμένα ἱμάτια καὶ χρυσία, καὶ θεραπαίνας δύο, Θρᾷτταν καὶ Κοκκαλίνην, ἀποδιδράσκει εἰς Μέγαρα. ἦν δὲ ὁ χρόνος οὗτος ᾧ Ἀστεῖος μὲν ἦν ἄρχων Ἀθήνησιν, ὁ καιρὸς δ’ ἐν ᾧ ἐπολεμεῖθ’ ὑμεῖς πρὸς Λακεδαιμονίους τὸν ὕστερον πόλεμον.", "st": "59.35"}, {"sp": "N", "t": "διατρίψασα δ’ ἐν τοῖς Μεγάροις δύ’ ἔτη, τόν τ’ ἐπ’ Ἀστείου ἄρχοντος καὶ Ἀλκισθένους ἐνιαυτόν, ὡς αὐτῇ ἡ ἀπὸ τοῦ σώματος ἐργασία οὐχ ἱκανὴν εὐπορίαν παρεῖχεν ὥστε διοικεῖν τὴν οἰκίαν, (πολυτελὴς δ’ ἦν, οἱ Μεγαρεῖς δ’ ἀνελεύθεροι καὶ μικρολόγοι, ξένων δὲ οὐ πάνυ ἐπιδημία ἦν αὐτόθι διὰ τὸ πόλεμον εἶναι καὶ τοὺς ⟨μὲν⟩ Μεγαρέας λακωνίζειν, τῆς δὲ θαλάττης ὑμᾶς ἄρχειν· εἰς δὲ τὴν Κόρινθον οὐκ ἐξῆν αὐτῇ ἐπανελθεῖν διὰ τὸ ἐπὶ τούτῳ ἀπηλλάχθαι ἀπὸ τοῦ Εὐκράτους καὶ τοῦ Τιμανορίδου, ὥστ’ ἐν Κορίνθῳ μὴ ἐργάζεσθαι),", "st": "59.36"}, {"sp": "N", "t": "ὡς οὖν γίγνεται ἡ εἰρήνη ἡ ἐπὶ Φρασικλείδου ἄρχοντος καὶ ἡ μάχη ἡ ἐν Λεύκτροις Θηβαίων καὶ Λακεδαιμονίων, τότε ἐπιδημήσαντα Στέφανον τουτονὶ εἰς τὰ Μέγαρα καὶ καταγόμενον ὡς αὐτὴν ἑταίραν οὖσαν καὶ πλησιάσαντα αὐτῇ, διηγησαμένη πάντα τὰ πεπραγμένα καὶ τὴν ὕβριν τοῦ Φρυνίωνος, καὶ ἐπιδοῦσα ἃ ἐξῆλθεν ἔχουσα παρ’ αὐτοῦ, ἐπιθυμοῦσα μὲν τῆς ἐνθάδε οἰκήσεως, φοβουμένη δὲ τὸν Φρυνίωνα διὰ τὸ ἠδικηκέναι μὲν αὐτή, ἐκεῖνον δὲ ὀργίλως ἔχειν αὐτῇ, σοβαρὸν δὲ καὶ ὀλίγωρον εἰδυῖα αὐτοῦ τὸν τρόπον ὄντα, προΐσταται Στέφανον τουτονὶ αὑτῆς.", "st": "59.37"}, {"sp": "N", "t": "ἐπάρας δὲ αὐτὴν οὗτος ἐν τοῖς Μεγάροις τῷ λόγῳ καὶ φυσήσας, ὡς κλαύσοιτο ὁ Φρυνίων εἰ ἅψοιτο αὐτῆς, αὐτὸς δὲ γυναῖκα αὐτὴν ἕξων, τούς τε παῖδας τοὺς ὄντας αὐτῇ τότε εἰσάξων εἰς τοὺς φράτερας ὡς αὑτοῦ ὄντας καὶ πολίτας ποιήσων, ἀδικήσει δὲ οὐδεὶς ἀνθρώπων, ἀφικνεῖται αὐτὴν ἔχων δεῦρο ἐκ τῶν Μεγάρων, καὶ παιδία μετ’ αὐτῆς τρία, Πρόξενον καὶ Ἀρίστωνα καὶ θυγατέρα, ἣν νυνὶ Φανὼ καλοῦσιν·", "st": "59.38"}, {"sp": "N", "t": "καὶ εἰσάγει αὐτὴν καὶ τὰ παιδία εἰς τὸ οἰκίδιον ὃ ἦν αὐτῷ παρὰ τὸν ψιθυριστὴν Ἑρμῆν, μεταξὺ τῆς Δωροθέου τοῦ Ἐλευσινίου οἰκίας καὶ τῆς Κλεινομάχου, ἣν νυνὶ Σπίνθαρος παρ’ αὐτοῦ ἐώνηται ἑπτὰ μνῶν. ὥστε ἡ μὲν ὑπάρχουσα Στεφάνῳ οὐσία αὕτη ἦν καὶ ἄλλο οὐδέν· δυοῖν δ’ ἕνεκα ἦλθεν ἔχων αὐτήν, ὡς ἐξ ἀτελείας τε ἕξων καλὴν ἑταίραν, καὶ τὰ ἐπιτήδεια ταύτην ἐργασομένην καὶ θρέψουσαν τὴν οἰκίαν· οὐ γὰρ ἦν αὐτῷ ἄλλη πρόσοδος, ὅ τι μὴ συκοφαντήσας τι λάβοι.", "st": "59.39"}, {"sp": "N", "t": "πυθόμενος δὲ ὁ Φρυνίων ἐπιδημοῦσαν αὐτὴν καὶ οὖσαν παρὰ τούτῳ, παραλαβὼν νεανίσκους μεθ’ ἑαυτοῦ καὶ ἐλθὼν ἐπὶ τὴν οἰκίαν τὴν τοῦ Στεφάνου ἦγεν αὐτήν. ἀφαιρουμένου δὲ τοῦ Στεφάνου κατὰ τὸν νόμον εἰς ἐλευθερίαν, κατηγγύησεν αὐτὴν πρὸς τῷ πολεμάρχῳ. καὶ ὡς ἀληθῆ λέγω, τούτων αὐτὸν μάρτυρα ὑμῖν τὸν τότε πολέμαρχον παρέξομαι. καί μοι κάλει Αἰήτην Κειριάδην.", "st": "59.40"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.40"}, {"sp": "N", "t": "Αἰήτης Κειριάδης μαρτυρεῖ πολεμαρχοῦντος αὑτοῦ κατεγγυηθῆναι Νέαιραν τὴν νυνὶ ἀγωνιζομένην ὑπὸ Φρυνίωνος τοῦ Δημοχάρους ἀδελφοῦ, καὶ ἐγγυητὰς γενέσθαι Νεαίρας Στέφανον Ἐροιάδην, Γλαυκέτην Κηφισιέα, Ἀριστοκράτην Φαληρέα.", "st": "59.40"}, {"sp": "N", "t": "διεγγυηθεῖσα δ’ ὑπὸ Στεφάνου καὶ οὖσα παρὰ τούτῳ τὴν μὲν αὐτὴν ἐργασίαν οὐδὲν ἧττον ἢ πρότερον ἠργάζετο, τοὺς δὲ μισθοὺς μείζους ἐπράττετο τοὺς βουλομένους αὐτῇ πλησιάζειν, ὡς ἐπὶ προσχήματος ἤδη τινὸς οὖσα καὶ ἀνδρὶ συνοικοῦσα. συνεσυκοφάντει δὲ καὶ οὗτος, εἴ τινα ξένον ἀγνῶτα πλούσιον λάβοι ἐραστὴν αὐτῆς, ὡς μοιχὸν ἐπ’ αὐτῇ ἔνδον ἀποκλείων καὶ ἀργύριον πραττόμενος πολύ, εἰκότως·", "st": "59.41"}, {"sp": "N", "t": "οὐσία μὲν γὰρ οὐχ ὑπῆρχεν Στεφάνῳ οὐδὲ Νεαίρᾳ, ὥστε τὰ καθ’ ἡμέραν ἀναλώματα δύνασθαι ὑποφέρειν, ἡ δὲ διοίκησις συχνή, ὁπότ’ ἔδει τοῦτόν τε καὶ αὑτὴν τρέφειν καὶ παιδάρια τρία, ἃ ἦλθεν ἔχουσα ὡς αὐτόν, καὶ θεραπαίνας δύο καὶ οἰκέτην διάκονον, ἄλλως τε καὶ μεμαθηκυῖα μὴ κακῶς ἔχειν τὰ ἐπιτήδεια ἑτέρων ἀναλισκόντων αὐτῇ τὸ πρότερον.", "st": "59.42"}, {"sp": "N", "t": "οὔτε γὰρ ἀπὸ τῆς πολιτείας προσῄει Στεφάνῳ τουτῳὶ ἄξιον λόγου· οὐ γάρ πω ἦν ῥήτωρ, ἀλλ’ ἔτι συκοφάντης τῶν παραβοώντων παρὰ τὸ βῆμα καὶ γραφομένων μισθοῦ καὶ φαινόντων καὶ ἐπιγραφομένων ταῖς ἀλλοτρίαις γνώμαις, ἕως ὑπέπεσε Καλλιστράτῳ τῷ Ἀφιδναίῳ· ἐξ ὅτου δὲ τρόπου καὶ δι’ ἣν αἰτίαν, ἐγὼ ὑμῖν καὶ περὶ τούτου διέξειμι, ἐπειδὰν περὶ ταυτησὶ Νεαίρας ἐπιδείξω ὡς ἔστι ξένη καὶ ὡς μεγάλα ὑμᾶς ἠδίκηκεν καὶ ὡς ἠσέβηκεν εἰς τοὺς θεούς,", "st": "59.43"}, {"sp": "N", "t": "ἵν’ εἰδῆτε ὅτι καὶ αὐτὸς οὗτος ἄξιός ἐστιν οὐκ ἐλάττω δοῦναι δίκην ἢ καὶ Νέαιρα αὑτηί, ἀλλὰ καὶ πολλῷ μείζω καὶ μᾶλλον, ὅσῳ Ἀθηναῖος φάσκων εἶναι οὕτω πολὺ τῶν νόμων καταπεφρόνηκεν καὶ ὑμῶν καὶ τῶν θεῶν, ὥστ’ οὐδ’ ὑπὲρ τῶν ἡμαρτημένων αὑτῷ αἰσχυνόμενος τολμᾷ ἡσυχίαν ἄγειν, ἀλλὰ συκοφαντῶν ἄλλους τε καὶ ἐμέ, τουτονὶ πεποίηκεν αὐτὸν καὶ ταύτην εἰς τηλικοῦ- τον ἀγῶνα καταστῆσαι, ὥστ’ ἐξετασθῆναι μὲν ταύτην ἥτις ἐστίν, ἐξελεγχθῆναι δὲ τὴν αὐτοῦ πονηρίαν.", "st": "59.44"}, {"sp": "N", "t": "λαχόντος τοίνυν αὐτῷ τοῦ Φρυνίωνος δίκην, ὅτι αὐτοῦ ἀφείλετο Νέαιραν ταυτηνὶ εἰς ἐλευθερίαν, καὶ ὅτι, ἃ ἐξῆλθεν ἔχουσα παρ’ αὐτοῦ αὕτη, ὑπεδέξατο, συνῆγον αὐτοὺς οἱ ἐπιτήδειοι καὶ ἔπεισαν δίαιταν ἐπιτρέψαι αὑτοῖς. καὶ ὑπὲρ μὲν τοῦ Φρυνίωνος διαιτητὴς ἐκαθέζετο Σάτυρος Ἀλωπεκῆθεν ὁ Λακεδαιμονίου ἀδελφός, ὑπὲρ δὲ Στεφάνου τουτουὶ Σαυρίας Λαμπτρεύς· κοινὸν δὲ αὑτοῖς προσαιροῦνται Διογείτονα Ἀχαρνέα.", "st": "59.45"}, {"sp": "N", "t": "συνελθόντες δ’ οὗτοι ἐν τῷ ἱερῷ, ἀκούσαντες ἀμφοτέρων καὶ αὐτῆς τῆς ἀνθρώπου τὰ πεπραγμένα, γνώμην ἀπεφήναντο, καὶ οὗτοι ἐνέμειναν αὐτῇ, τὴν μὲν ἄνθρωπον ἐλευθέραν εἶναι καὶ αὐτὴν αὑτῆς κυρίαν, ἃ δ’ ἐξῆλθεν ἔχουσα Νέαιρα παρὰ Φρυνίωνος χωρὶς ἱματίων καὶ χρυσίων καὶ θεραπαινῶν, ἃ αὐτῇ τῇ ἀνθρώπῳ ἠγοράσθη, ἀποδοῦναι Φρυνίωνι πάντα· συνεῖναι δ’ ἑκατέρῳ ἡμέραν παρ’ ἡμέραν· ἐὰν δὲ καὶ ἄλλως πως ἀλλήλους πείθωσι, ταῦτα κύρια εἶναι· τὰ δ’ ἐπιτήδεια τῇ ἀνθρώπῳ τὸν ἔχοντα ἀεὶ παρέχειν, καὶ ἐκ τοῦ λοιποῦ χρόνου φίλους εἶναι ἀλλήλοις καὶ μὴ μνησικακεῖν.", "st": "59.46"}, {"sp": "N", "t": "ἡ μὲν οὖν γνωσθεῖσα διαλλαγὴ ὑπὸ τῶν διαιτητῶν Φρυνίωνι καὶ Στεφάνῳ περὶ Νεαίρας ταυτησὶ αὕτη ἐστίν. ὅτι δ’ ἀληθῆ λέγω ταῦτα, τούτων ὑμῖν τὴν μαρτυρίαν ἀναγνώσεται. κάλει μοι Σάτυρον Ἀλωπεκῆθεν, Σαυρίαν Λαμπτρέα, Διογείτονα Ἀχαρνέα.", "st": "59.47"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.47"}, {"sp": "N", "t": "Σάτυρος Ἀλωπεκῆθεν, Σαυρίας Λαμπτρεύς, Διογείτων Ἀχαρνεὺς μαρτυροῦσι διαλλάξαι διαιτηταὶ γενόμενοι περὶ Νεαίρας τῆς νυνὶ ἀγωνιζομένης Στέφανον καὶ Φρυνίωνα· τὰς δὲ διαλλαγὰς εἶναι, καθ’ ἃς διήλλαξαν, οἵας παρέχεται Ἀπολλόδωρος.", "st": "59.47"}, {"sp": "N", "t": "ΔΙΑΛΛΑΓΑΙ.", "st": "59.47"}, {"sp": "N", "t": "κατὰ τάδε διήλλαξαν Φρυνίωνα καὶ Στέφανον, χρῆσθαι ἑκάτερον Νεαίρᾳ τὰς ἴσας ἡμέρας τοῦ μηνὸς παρ’ ἑαυτοῖς ἔχοντας, ἂν μή τι ἄλλο αὐτοὶ αὑτοῖς συγχωρήσωσιν.", "st": "59.47"}, {"sp": "N", "t": "ὡς δ’ ἀπηλλαγμένοι ἦσαν, οἱ παρόντες ἑκατέρῳ ἐπὶ τῇ διαίτῃ καὶ τοῖς πράγμασιν, οἷον οἶμαι φιλεῖ γίγνεσθαι ἑκάστοτε, ἄλλως τε καὶ περὶ ἑταίρας οὔσης αὐτοῖς τῆς διαφορᾶς, ἐπὶ δεῖπνον ᾖσαν ὡς ἑκάτερον αὐτῶν, ὁπότε καὶ Νέαιραν ἔχοιεν, καὶ αὑτηὶ συνεδείπνει καὶ συνέπινεν ὡς ἑταίρα οὖσα. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, κάλει μοι μάρτυρας τοὺς συνόντας αὐτοῖς, Εὔβουλον Προβαλίσιον, Διοπείθην Μελιτέα, Κτήσωνα ἐκ Κεραμέων.", "st": "59.48"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "59.48"}, {"sp": "N", "t": "Εὔβουλος Προβαλίσιος, Διοπείθης Μελιτεύς, Κτήσων ἐκ Κεραμέων μαρτυροῦσιν, ἐπειδὴ αἱ διαλλαγαὶ ἐγένοντο αἱ περὶ Νεαίρας Φρυνίωνι καὶ Στεφάνῳ, πολλάκις συνδειπνῆσαι αὐτοῖς καὶ συμπίνειν μετὰ Νεαίρας τῆς νυνὶ ἀγωνιζομένης, καὶ ὁπότε παρὰ Στεφάνῳ εἴη Νέαιρα καὶ ὁπότε παρὰ Φρυνίωνι.", "st": "59.48"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν ἐξ ἀρχῆς δούλη ἦν καὶ ἐπράθη δὶς καὶ ἠργάζετο τῷ σώματι ὡς ἑταίρα οὖσα, καὶ ἀπέδρα τὸν Φρυνίωνα εἰς Μέγαρα, καὶ ἥκουσα κατηγγυήθη ὡς ξένη οὖσα πρὸς τῷ πολεμάρχῳ, τῷ τε λόγῳ ἀποφαίνω ὑμῖν καὶ μεμαρτύρηται. βούλομαι δ’ ὑμῖν καὶ αὐτὸν Στέφανον τουτονὶ ἐπιδεῖξαι καταμεμαρτυρηκότ’ αὐτῆς ὡς ἔστι ξένη.", "st": "59.49"}, {"sp": "N", "t": "τὴν γὰρ θυγατέρα τὴν ταυτησὶ Νεαίρας, ἣν ἦλθεν ἔχουσα ὡς τουτονὶ παιδάριον μικρόν, ἣν τότε μὲν Στρυβήλην ἐκάλουν, νυνὶ δὲ Φανώ, ἐκδίδωσι Στέφανος οὑτοσὶ ὡς οὖσαν αὑτοῦ θυγατέρα ἀνδρὶ Ἀθηναίῳ Φράστορι Αἰγιλιεῖ, καὶ προῖκα ἐπ’ αὐτῇ δίδωσι τριάκοντα μνᾶς. ὡς δ’ ἦλθεν ὡς τὸν Φράστορα, ἄνδρα ἐργάτην καὶ ἀκριβῶς τὸν βίον συνειλεγμένον, οὐκ ἠπίστατο τοῖς τοῦ Φράστορος τρόποις ἀρέσκειν, ἀλλ’ ἐζήτει τὰ τῆς μητρὸς ἔθη καὶ τὴν παρ’ αὐτῇ ἀκολασίαν, ἐν τοιαύτῃ οἶμαι ἐξουσίᾳ τεθραμμένη.", "st": "59.50"}, {"sp": "N", "t": "ὁρῶν δὲ Φράστωρ αὐτὴν οὔτε κοσμίαν οὖσαν οὔτ’ ἐθέλουσαν αὑτοῦ ἀκροᾶσθαι, ἅμα δὲ καὶ πεπυσμένος σαφῶς ἤδη ὅτι Στεφάνου μὲν οὐκ εἴη θυγάτηρ, Νεαίρας δέ, τὸ δὲ πρῶτον ἐξηπατήθη, ὅτ’ ἠγγυᾶτο ὡς Στεφάνου θυγατέρα λαμβάνων καὶ οὐ Νεαίρας, ἀλλὰ τούτῳ ἐξ ἀστῆς αὐτὴν γυναικὸς οὖσαν πρότερον πρὶν ταύτῃ συνοικῆσαι, ὀργισθεὶς δ’ ἐπὶ τούτοις ἅπασιν, καὶ ὑβρίσθαι ἡγούμενος καὶ ἐξηπατῆσθαι, ἐκβάλλει τὴν ἄνθρωπον ὡς ἐνιαυτὸν συνοικήσας αὐτῇ, κυοῦσαν, καὶ τὴν προῖκα οὐκ ἀποδίδωσιν.", "st": "59.51"}, {"sp": "N", "t": "λαχόντος δὲ τοῦ Στεφάνου αὐτῷ δίκην σίτου εἰς Ὠιδεῖον κατὰ τὸν νόμον ὃς κελεύει, ἐὰν ἀποπέμπῃ τὴν γυναῖκα, ἀποδιδόναι τὴν προῖκα, ἐὰν δὲ μή, ἐπ’ ἐννέ’ ὀβολοῖς τοκοφορεῖν, καὶ σίτου εἰς Ὠιδεῖον εἶναι δικάσασθαι ὑπὲρ τῆς γυναικὸς τῷ κυρίῳ, γράφεται ὁ Φράστωρ Στέφανον τουτονὶ γραφὴν πρὸς τοὺς θεσμοθέτας, Ἀθηναίῳ ὄντι ξένης θυγατέρα αὐτῷ ἐγγυῆσαι ὡς αὑτῷ προσήκουσαν, κατὰ τὸν νόμον τουτονί. καί μοι ἀνάγνωθι αὐτόν.", "st": "59.52"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "59.52"}, {"sp": "N", "t": "ἐὰν δέ τις ἐκδῷ ξένην γυναῖκα ἀνδρὶ Ἀθηναίῳ ὡς ἑαυτῷ προσήκουσαν, ἄτιμος ἔστω, καὶ ἡ οὐσία αὐτοῦ δημοσία ἔστω, καὶ τοῦ ἑλόντος τὸ τρίτον μέρος. γραφέσθων δὲ πρὸς τοὺς θεσμοθέτας οἷς ἔξεστιν, καθάπερ τῆς ξενίας.", "st": "59.52"}, {"sp": "N", "t": "τὸν μὲν τοίνυν νόμον ἀνέγνω ὑμῖν, καθ’ ὃν ἐγράφη Στέφανος οὑτοσὶ ὑπὸ τοῦ Φράστορος πρὸς τοὺς θεσμοθέτας. γνοὺς δ’ ὅτι κινδυνεύσει ἐξελεγχθεὶς ξένης θυγατέρα ἠγγυηκέναι καὶ ταῖς ἐσχάταις ζημίαις περιπεσεῖν, διαλλάττεται πρὸς τὸν Φράστορα καὶ ἀφίσταται τῆς προικός, καὶ τὴν δίκην τοῦ σίτου ἀνείλετο, καὶ ὁ Φράστωρ τὴν γραφὴν παρὰ τῶν θεσμοθετῶν. καὶ ὡς ἀληθῆ λέγω, τούτων ὑμῖν μάρτυρα αὐτὸν τὸν Φράστορα καλῶ, καὶ ἀναγκάσω μαρτυρεῖν κατὰ τὸν νόμον.", "st": "59.53"}, {"sp": "N", "t": "κάλει μοι Φράστορα Αἰγιλιέα.", "st": "59.54"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.54"}, {"sp": "N", "t": "Φράστωρ Αἰγιλιεὺς μαρτυρεῖ, ἐπειδὴ ᾔσθετο Νεαίρας θυγατέρα ἐγγυήσαντα αὑτῷ Στέφανον ὡς ἑαυτοῦ οὖσαν θυγατέρα, γράψασθαι αὐτὸν γραφὴν πρὸς τοὺς θεσμοθέτας κατὰ τὸν νόμον, καὶ τὴν ἄνθρωπον ἐκβαλεῖν ἐκ τῆς ἑαυτοῦ οἰκίας καὶ οὐκέτι συνοικεῖν αὐτῇ, καὶ λαχόντος αὑτῷ Στεφάνου εἰς Ὠιδεῖον σίτου διαλύσασθαι πρὸς αὑτὸν Στέφανον, ὥστε τὴν γραφὴν ἀναιρεθῆναι παρὰ τῶν θεσμοθετῶν καὶ τὴν δίκην τοῦ σίτου ἣν ἔλαχεν ἐμοὶ Στέφανος.", "st": "59.54"}, {"sp": "N", "t": "φέρε δὴ ὑμῖν καὶ ἑτέραν μαρτυρίαν παράσχωμαι τοῦ τε Φράστορος καὶ τῶν φρατέρων αὐτοῦ καὶ γεννητῶν, ὡς ἔστι ξένη Νέαιρα αὑτηί. οὐ πολλῷ χρόνῳ γὰρ ὕστερον ἢ ἐξέπεμψεν ὁ Φράστωρ τὴν τῆς Νεαίρας θυγατέρα, ἠσθένησε καὶ πάνυ πονηρῶς διετέθη καὶ εἰς πᾶσαν ἀπορίαν κατέστη. διαφορᾶς δ’ οὔσης αὐτῷ παλαιᾶς πρὸς τοὺς οἰκείους τοὺς αὑτοῦ καὶ ὀργῆς καὶ μίσους, πρὸς δὲ καὶ ἄπαις ὤν, ψυχαγωγούμενος ἐν τῇ ἀσθενείᾳ τῇ θεραπείᾳ ⟨τῇ⟩ ὑπό τε τῆς Νεαίρας καὶ τῆς θυγατρὸς αὐτῆς", "st": "59.55"}, {"sp": "N", "t": "(ἐβάδιζον γὰρ πρὸς αὐτόν, ὡς ἠσθένει καὶ ἔρημος ἦν τοῦ θεραπεύσοντος τὸ νόσημα, τὰ πρόσφορα τῇ νόσῳ φέρουσαι καὶ ἐπισκοπούμεναι· ἴστε δήπου καὶ αὐτοὶ ὅσου ἀξία ἐστὶν γυνὴ ἐν ταῖς νόσοις, παροῦσα κάμνοντι ἀνθρώπῳ) ἐπείσθη δὴ τὸ παιδίον, ὃ ἔτεκεν ἡ θυγάτηρ ἡ Νεαίρας ταυτησὶ ὅτ’ ἐξεπέμφθη ὑπὸ τοῦ Φράστορος κυοῦσα, πυθομένου ὅτι οὐ Στεφάνου εἴη θυγάτηρ ἀλλὰ Νεαίρας, καὶ ὀργισθέντος ἐπὶ τῇ ἀπάτῃ, πάλιν λαβεῖν καὶ ποιήσασθαι υἱὸν αὑτοῦ,", "st": "59.56"}, {"sp": "N", "t": "λογισμὸν ἀνθρώπινον καὶ εἰκότα λογιζόμενος, ὅτι πονηρῶς μὲν ἔχοι καὶ οὐ πολλὴ ἐλπὶς εἴη αὐτὸν περιγενήσεσθαι, τοῦ δὲ μὴ λαβεῖν τοὺς συγγενεῖς τὰ αὑτοῦ μηδ’ ἄπαις τετελευτηκέναι ἐποιήσατο τὸν παῖδα καὶ ἀνέλαβεν ὡς αὑτόν· ἐπεὶ ὅτι γε ὑγιαίνων οὐκ ἄν ποτε ἔπραξεν, μεγάλῳ τεκμηρίῳ καὶ περιφανεῖ ἐγὼ ὑμῖν ἐπιδείξω.", "st": "59.57"}, {"sp": "N", "t": "ὡς γὰρ ἀνέστη τάχιστα ἐξ ἐκείνης τῆς ἀσθενείας ὁ Φράστωρ καὶ ἀνέλαβεν αὑτὸν καὶ ἔσχεν ἐπιεικῶς τὸ σῶμα, λαμβάνει γυναῖκα ἀστὴν κατὰ τοὺς νόμους, Σατύρου μὲν τοῦ Μελιτέως θυγατέρα γνησίαν, Διφίλου δὲ ἀδελφήν. ὥστε ὅτι μὲν οὐχ ἑκὼν ἀνεδέξατο τὸν παῖδα, ἀλλὰ βιασθεὶς ὑπὸ τῆς νόσου καὶ τῆς ἀπαιδίας καὶ τῆς ⟨ὑπ’⟩ αὐτῶν θεραπείας καὶ τῆς ἔχθρας τῆς πρὸς τοὺς οἰκείους, ἵνα μὴ κληρονόμοι γένωνται τῶν αὑτοῦ, ἄν τι πάθῃ, ταῦτ’ ἔστω ὑμῖν τεκμήρια· δηλώσει δὲ καὶ τἀκόλουθ’ αὐτῶν ἔτι μᾶλλον.", "st": "59.58"}, {"sp": "N", "t": "ὡς γὰρ εἰσῆγεν ὁ Φράστωρ εἰς τοὺς φράτερας τὸν παῖδα ἐν τῇ ἀσθενείᾳ ὢν τὸν ἐκ τῆς θυγατρὸς τῆς Νεαίρας, καὶ εἰς τοὺς Βρυτίδας ὧν καὶ αὐτός ἐστιν ὁ Φράστωρ γεννήτης, εἰδότες οἶμαι οἱ γεννῆται τὴν γυναῖκα ἥτις ἦν, ἣν ἔλαβεν ὁ Φράστωρ τὸ πρῶτον, τὴν τῆς Νεαίρας θυγατέρα, καὶ τὴν ἀπόπεμψιν τῆς ἀνθρώπου, καὶ διὰ τὴν ἀσθένειαν πεπεισμένον αὐτὸν πάλιν ἀναλαβεῖν τὸν παῖδα, ἀποψηφίζονται τοῦ παιδὸς καὶ οὐκ ἐνέγραφον αὐτὸν εἰς σφᾶς αὐτούς.", "st": "59.59"}, {"sp": "N", "t": "λαχόντος δὲ τοῦ Φράστορος αὐτοῖς δίκην, ὅτι οὐκ ἐνέγραφον αὑτοῦ υἱόν, προκαλοῦνται αὐτὸν οἱ γεννῆται πρὸς τῷ διαιτητῇ ὀμόσαι καθ’ ἱερῶν τελείων ἦ μὴν νομίζειν εἶναι αὑτοῦ υἱὸν ἐξ ἀστῆς γυναικὸς καὶ ἐγγυητῆς κατὰ τὸν νόμον. προκαλουμένων δὲ ταῦτα τῶν γεννητῶν τὸν Φράστορα πρὸς τῷ διαιτητῇ, ἔλιπεν ὁ Φράστωρ τὸν ὅρκον καὶ οὐκ ὤμοσεν.", "st": "59.60"}, {"sp": "N", "t": "καὶ ὅτι ἀληθῆ ταῦτα λέγω, τούτων ὑμῖν μάρτυρας τοὺς παρόντας Βρυτιδῶν παρέξομαι.", "st": "59.61"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "59.61"}, {"sp": "N", "t": "Τιμόστρατος Ἑκάληθεν, Ξάνθιππος Ἐροιάδης, Εὐάλκης Φαληρεύς, Ἄνυτος Λακιάδης, Εὐφράνωρ Αἰγιλιεύς, Νίκιππος Κεφαλῆθεν μαρτυροῦσιν εἶναι καὶ αὑτοὺς καὶ Φράστορα τὸν Αἰγιλιέα τῶν γεννητῶν οἳ καλοῦνται Βρυτίδαι, καὶ ἀξιοῦντος Φράστορος εἰσάγειν τὸν υἱὸν ⟨τὸν⟩ αὑτοῦ εἰς τοὺς γεννήτας, εἰδότες αὐτοὶ ὅτι Φράστορος υἱὸς εἴη ἐκ τῆς θυγατρὸς τῆς Νεαίρας, κωλύειν εἰσάγειν Φράστορα τὸν υἱόν.", "st": "59.61"}, {"sp": "N", "t": "οὐκοῦν περιφανῶς ἐπιδεικνύω ὑμῖν καὶ αὐτοὺς τοὺς οἰκειοτάτους Νεαίρας ταυτησὶ καταμεμαρτυρηκότας ὡς ἔστιν ξένη, Στέφανόν τε τουτονὶ τὸν ἔχοντα ταύτην νυνὶ καὶ συνοικοῦντ’ αὐτῇ καὶ Φράστορα τὸν λαβόντα τὴν θυγατέρα, Στέφανον μὲν οὐκ ἐθελήσαντα ἀγωνίσασθαι ὑπὲρ τῆς θυγατρὸς τῆς ταύτης, γραφέντα ὑπὸ Φράστορος πρὸς τοὺς θεσμοθέτας ὡς Ἀθηναίῳ ὄντι ξένης θυγατέρα αὐτῷ ἠγγύησεν, ἀλλ’ ἀποστάντα τῆς προικὸς καὶ οὐκ ἀπολαβόντα,", "st": "59.62"}, {"sp": "N", "t": "Φράστορα δ’ ἐκβαλόντα τε τὴν θυγατέρα τὴν Νεαίρας ταυτησὶ γήμαντα, ἐπειδὴ ἐπύθετο οὐ Στεφάνου οὖσαν, καὶ τὴν προῖκα οὐκ ἀποδόντα, ἐπειδή τε ἐπείσθη ὕστερον διὰ τὴν ἀσθένειαν τὴν αὑτοῦ καὶ τὴν ἀπαιδίαν καὶ τὴν ἔχθραν τὴν πρὸς τοὺς οἰκείους ποιήσασθαι τὸν υἱόν, καὶ ἐπειδὴ εἰσῆγεν εἰς τοὺς γεννήτας, ἀποψηφισαμένων τῶν γεννητῶν καὶ διδόντων ὅρκον αὐτῷ οὐκ ἐθελήσαντα ὀμόσαι, ἀλλὰ μᾶλλον εὐορκεῖν προελόμενον, καὶ ἑτέραν ὕστερον γήμαντα γυναῖκα ἀστὴν κατὰ τὸν νόμον· αὗται γὰρ αἱ πράξεις περιφανεῖς οὖσαι μεγάλας μαρτυρίας δεδώκασι κατ’ αὐτῶν, ὅτι ἔστι ξένη Νέαιρα αὑτηί.", "st": "59.63"}, {"sp": "N", "t": "σκέψασθε δὲ καὶ τὴν αἰσχροκερδίαν τὴν Στεφάνου τουτουὶ καὶ τὴν πονηρίαν, ἵνα καὶ ἐκ ταύτης εἰδῆτε ὅτι οὐκ ἔστιν Νέαιρα αὑτηὶ ἀστή. Ἐπαίνετον γὰρ τὸν Ἄνδριον, ἐραστὴν ὄντα Νεαίρας ταυτησὶ παλαιὸν καὶ πολλὰ ἀνηλωκότα εἰς αὐτὴν καὶ καταγόμενον παρὰ τούτοις ὁπότε ἐπιδημήσειεν Ἀθήναζε διὰ τὴν φιλίαν τὴν Νεαίρας,", "st": "59.64"}, {"sp": "N", "t": "ἐπιβουλεύσας Στέφανος οὑτοσί, μεταπεμψάμενος εἰς ἀγρὸν ὡς θύων, λαμβάνει μοιχὸν ἐπὶ τῇ θυγατρὶ τῇ Νεαίρας ταυτησί, καὶ εἰς φόβον καταστήσας πράττεται μνᾶς τριάκοντα, καὶ λαβὼν ἐγγυητὰς τούτων Ἀριστόμαχόν τε τὸν θεσμοθετήσαντα καὶ Ναυσίφιλον τὸν Ναυσινίκου τοῦ ἄρξαντος υἱόν, ἀφίησιν ὡς ἀποδώσοντα αὑτῷ τὸ ἀργύριον.", "st": "59.65"}, {"sp": "N", "t": "ἐξελθὼν δὲ ὁ Ἐπαίνετος καὶ αὐτὸς αὑτοῦ κύριος γενόμενος γράφεται πρὸς τοὺς θεσμοθέτας γραφὴν Στέφανον τουτονί, ἀδίκως εἱρχθῆναι ὑπ’ αὐτοῦ, κατὰ τὸν νόμον ὃς κελεύει, ἐάν τις ἀδίκως εἵρξῃ ὡς μοιχόν, γράψασθαι πρὸς τοὺς θεσμοθέτας ἀδίκως εἱρχθῆναι, καὶ ἐὰν μὲν ἕλῃ τὸν εἵρξαντα καὶ δόξῃ ἀδίκως ἐπιβεβουλεῦσθαι, ἀθῷον εἶναι αὐτὸν καὶ τοὺς ἐγγυητὰς ἀπηλλάχθαι τῆς ἐγγύης· ἐὰν δὲ δόξῃ μοιχὸς εἶναι, παραδοῦναι αὐτὸν κελεύει τοὺς ἐγγυητὰς τῷ ἑλόντι, ἐπὶ δὲ τοῦ δικαστηρίου ἄνευ ἐγχειριδίου χρῆσθαι ὅ τι ἂν βουληθῇ, ὡς μοιχῷ ὄντι.", "st": "59.66"}, {"sp": "N", "t": "κατὰ δὴ τοῦτον τὸν νόμον γράφεται αὐτὸν ὁ Ἐπαίνετος, καὶ ὡμολόγει μὲν χρῆσθαι τῇ ἀνθρώπῳ, οὐ μέντοι μοιχός γε εἶναι· οὔτε γὰρ Στεφάνου θυγατέρα αὐτὴν εἶναι ἀλλὰ Νεαίρας, τήν τε μητέρα αὐτῆς συνειδέναι πλησιάζουσαν αὑτῷ, ἀνηλωκέναι τε πολλὰ εἰς αὐτάς, τρέφειν τε ὁπότε ἐπιδημήσειεν, τὴν οἰκίαν ὅλην· τόν τε νόμον ἐπὶ τούτοις παρεχόμενος, ὃς οὐκ ἐᾷ ἐπὶ ταύτῃσι μοιχὸν λαβεῖν ὁπόσαι ἂν ἐπ’ ἐργαστηρίου καθῶνται ἢ πωλῶνται ἀποπεφασμένως, ἐργαστήριον φάσκων καὶ τοῦτο εἶναι, τὴν Στεφάνου οἰκίαν, καὶ τὴν ἐργασίαν ταύτην εἶναι, καὶ ἀπὸ τούτων αὐτοὺς εὐπορεῖν μάλιστα.", "st": "59.67"}, {"sp": "N", "t": "τούτους δὲ τοὺς λόγους λέγοντος τοῦ Ἐπαινέτου καὶ τὴν γραφὴν γεγραμμένου, γνοὺς Στέφανος οὑτοσὶ ὅτι ἐξελεγχθήσεται πορνοβοσκῶν καὶ συκοφαντῶν, δίαιταν ἐπιτρέπει πρὸς τὸν Ἐπαίνετον αὐτοῖς τοῖς ἐγγυηταῖς, ὥστε τῆς μὲν ἐγγύης αὐτοὺς ἀφεῖσθαι, τὴν δὲ γραφὴν ἀνελέσθαι τὸν Ἐπαίνετον.", "st": "59.68"}, {"sp": "N", "t": "πεισθέντος δὲ τοῦ Ἐπαινέτου ἐπὶ τούτοις καὶ ἀνελομένου τὴν γραφὴν ἣν ἐδίωκε Στέφανον, γενομένης συνόδου αὐτοῖς καὶ καθεζομένων διαιτητῶν τῶν ἐγγυητῶν, δίκαιον μὲν οὐδὲν εἶχε λέγειν Στέφανος, εἰς ἔκδοσιν δ’ ἠξίου τὸν Ἐπαίνετον τῇ τῆς Νεαίρας θυγατρὶ συμβαλέσθαι, λέγων τὴν ἀπορίαν τὴν αὑτοῦ καὶ τὴν ἀτυχίαν τὴν πρότερον γενομένην τῇ ἀνθρώπῳ πρὸς τὸν Φράστορα, καὶ ὅτι ἀπολωλεκὼς εἴη τὴν προῖκα, καὶ οὐκ ἂν δύναιτο πάλιν αὐτὴν ἐκδοῦναι·", "st": "59.69"}, {"sp": "N", "t": "“σὺ δὲ καὶ κέχρησαι” ἔφη “τῇ ἀνθρώπῳ, καὶ δίκαιος εἶ ἀγαθόν τι ποιῆσαι αὐτήν”, καὶ ἄλλους ἐπαγωγοὺς λόγους, οὓς ἄν τις δεόμενος ἐκ πονηρῶν πραγμάτων εἴποι ἄν. ἀκούσαντες δ’ ἀμφοτέρων αὐτῶν οἱ διαιτηταὶ διαλλάττουσιν αὐτούς, καὶ πείθουσι τὸν Ἐπαίνετον χιλίας δραχμὰς εἰσενεγκεῖν εἰς τὴν ἔκδοσιν τῇ θυγατρὶ τῇ Νεαίρας. καὶ ὅτι πάντα ταῦτα ἀληθῆ λέγω, τούτων ὑμῖν μάρτυρας αὐτοὺς τοὺς ἐγγυητὰς καὶ διαιτητὰς γενομένους καλῶ.", "st": "59.70"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "59.70"}, {"sp": "N", "t": "Ναυσίφιλος Κεφαλῆθεν, Ἀριστόμαχος Κεφαλῆθεν μαρτυροῦσιν ἐγγυηταὶ γενέσθαι Ἐπαινέτου τοῦ Ἀνδρίου, ὅτ’ ἔφη Στέφανος μοιχὸν εἰληφέναι Ἐπαίνετον· καὶ ἐπειδὴ ἐξῆλθεν Ἐπαίνετος παρὰ Στεφάνου καὶ κύριος ἐγένετο αὑτοῦ, γράψασθαι γραφὴν Στέφανον πρὸς τοὺς θεσμοθέτας, ὅτι αὐτὸν ἀδίκως εἷρξεν· καὶ αὐτοὶ διαλλακταὶ γενόμενοι διαλλάξαι Ἐπαίνετον καὶ Στέφανον· τὰς δὲ διαλλαγὰς εἶναι ἃς παρέχεται Ἀπολλόδωρος.", "st": "59.71"}, {"sp": "N", "t": "ΔΙΑΛΛΑΓΑΙ.", "st": "59.71"}, {"sp": "N", "t": "ἐπὶ τοῖσδε διήλλαξαν Στέφανον καὶ Ἐπαίνετον οἱ διαλλακταί, τῶν μὲν γεγενημένων περὶ τὸν εἱργμὸν μηδεμίαν μνείαν ἔχειν, Ἐπαίνετον δὲ δοῦναι χιλίας δραχμὰς Φανοῖ εἰς ἔκδοσιν, ἐπειδὴ κέχρηται αὐτῇ πολλάκις· στέφανον δὲ παρέχειν Φανὼ Ἐπαινέτῳ, ὁπόταν ἐπιδημῇ καὶ βούληται συνεῖναι αὐτῇ.", "st": "59.71"}, {"sp": "N", "t": "τὴν τοίνυν περιφανῶς ἐγνωσμένην ξένην εἶναι καὶ ἐφ’ ᾗ μοιχὸν οὗτος ἐτόλμησε λαβεῖν, εἰς τοσοῦτον ὕβρεως καὶ ἀναιδείας ἦλθεν Στέφανος οὑτοσὶ καὶ Νέαιρα αὑτηί, ὥστε ἐτόλμησαν μὴ ἀγαπᾶν εἰ ἔφασκον αὐτὴν ἀστὴν εἶναι, ἀλλὰ κατιδόντες Θεογένην Κοιρωνίδην λαχόντα βασιλέα, ἄνθρωπον εὐγενῆ μέν, πένητα δὲ καὶ ἄπειρον πραγμάτων, συμπαραγενόμενος αὐτῷ δοκιμαζομένῳ καὶ συνευπορήσας ἀναλωμάτων, ὅτε εἰσῄει εἰς τὴν ἀρχήν, Στέφανος οὑτοσί, καὶ ὑπελθὼν καὶ τὴν ἀρχὴν παρ’ αὐτοῦ πριάμενος, πάρεδρος γενόμενος, δίδωσι τὴν ἄνθρωπον ταύτην γυναῖκα, τὴν τῆς Νεαίρας θυγατέρα, καὶ ἐγγυᾷ Στέφανος οὑτοσὶ ὡς αὑτοῦ θυγατέρα οὖσαν· οὕτω πολὺ τῶν νόμων καὶ ὑμῶν κατεφρόνησεν.", "st": "59.72"}, {"sp": "N", "t": "καὶ αὕτη ἡ γυνὴ ὑμῖν ἔθυε τὰ ἄρρητα ἱερὰ ὑπὲρ τῆς πόλεως, καὶ εἶδεν ἃ οὐ προσῆκεν αὐτὴν ὁρᾶν ξένην οὖσαν, καὶ τοιαύτη οὖσα εἰσῆλθεν οἷ οὐδεὶς ἄλλος Ἀθηναίων τοσούτων ὄντων εἰσέρχεται ἀλλ’ ἢ ἡ τοῦ βασιλέως γυνή, ἐξώρκωσέν τε τὰς γεραρὰς τὰς ὑπηρετούσας τοῖς ἱεροῖς, ἐξεδόθη δὲ τῷ Διονύσῳ γυνή, ἔπραξε δὲ ὑπὲρ τῆς πόλεως τὰ πάτρια τὰ πρὸς τοὺς θεούς, πολλὰ καὶ ἅγια καὶ ἀπόρρητα. ἃ δὲ μηδ’ ἀκοῦσαι πᾶσιν οἷόν τ’ ἐστίν, πῶς ποιῆσαί γε τῇ ἐπιτυχούσῃ εὐσεβῶς ἔχει, ἄλλως τε καὶ τοιαύτῃ γυναικὶ καὶ τοιαῦτα ἔργα διαπεπραγμένῃ;", "st": "59.73"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν ἀκριβέστερον περὶ αὐτῶν ἄνωθεν διηγήσασθαι καθ’ ἕκαστον, ἵνα μᾶλλον ἐπιμέλειαν ποιήσησθε τῆς τιμωρίας, καὶ εἰδῆτε ὅτι οὐ μόνον ὑπὲρ ὑμῶν αὐτῶν καὶ τῶν νόμων τὴν ψῆφον οἴσετε, ἀλλὰ καὶ τῆς πρὸς τοὺς θεοὺς εὐλαβείας, τιμωρίαν ὑπὲρ τῶν ἠσεβημένων ποιούμενοι καὶ κολάζοντες τοὺς ἠδικηκότας. τὸ γὰρ ἀρχαῖον, ὦ ἄνδρες Ἀθηναῖοι, δυναστεία ἐν τῇ πόλει ἦν καὶ ἡ βασιλεία τῶν ἀεὶ ὑπερεχόντων διὰ τὸ αὐτόχθονας εἶναι, τὰς δὲ θυσίας ἁπάσας ὁ βασιλεὺς ἔθυε, καὶ τὰς σεμνοτάτας καὶ ἀρρήτους ἡ γυνὴ αὐτοῦ ἐποίει, εἰκότως, βασίλιννα οὖσα.", "st": "59.74"}, {"sp": "N", "t": "ἐπειδὴ δὲ Θησεὺς συνῴκισεν αὐτοὺς καὶ δημοκρατίαν ἐποίησεν καὶ ἡ πόλις πολυάνθρωπος ἐγένετο, τὸν μὲν βασιλέα οὐδὲν ἧττον ὁ δῆμος ᾑρεῖτο ἐκ προκρίτων κατ’ ἀνδραγαθίαν χειροτονῶν, τὴν δὲ γυναῖκα αὐτοῦ νόμον ἔθεντο ἀστὴν εἶναι καὶ μὴ ἐπιμεμειγμένην ἑτέρῳ ἀνδρὶ ἀλλὰ παρθένον γαμεῖν, ἵνα κατὰ τὰ πάτρια θύηται τὰ ἄρρητα ἱερὰ ὑπὲρ τῆς πόλεως, καὶ τὰ νομιζόμενα γίγνηται τοῖς θεοῖς εὐσεβῶς καὶ μηδὲν καταλύηται μηδὲ καινοτομῆται.", "st": "59.75"}, {"sp": "N", "t": "καὶ τοῦτον τὸν νόμον γράψαντες ἐν στήλῃ λιθίνῃ ἔστησαν ἐν τῷ ἱερῷ τοῦ Διονύσου παρὰ τὸν βωμὸν ἐν Λίμναις (καὶ αὕτη ἡ στήλη ἔτι καὶ νῦν ἕστηκεν, ἀμυδροῖς γράμμασιν Ἀττικοῖς δηλοῦσα τὰ γεγραμμένα), μαρτυρίαν ποιούμενος ὁ δῆμος ὑπὲρ τῆς αὑτοῦ εὐσεβείας πρὸς τὸν θεὸν καὶ παρακαταθήκην καταλείπων τοῖς ἐπιγιγνομένοις, ὅτι τήν γε θεῷ γυναῖκα δοθησομένην καὶ ποιήσουσαν τὰ ἱερὰ τοιαύτην ἀξιοῦμεν εἶναι. καὶ διὰ ταῦτα ἐν τῷ ἀρχαιοτάτῳ ἱερῷ τοῦ Διονύσου καὶ ἁγιωτάτῳ ἐν Λίμναις ἔστησαν, ἵνα μὴ πολλοὶ εἰδῶσιν τὰ γεγραμμένα· ἅπαξ γὰρ τοῦ ἐνιαυτοῦ ἑκάστου ἀνοίγεται, τῇ δωδεκάτῃ τοῦ ἀνθεστηριῶνος μηνός.", "st": "59.76"}, {"sp": "N", "t": "ὑπὲρ τοίνυν ἁγίων καὶ σεμνῶν ἱερῶν, ὧν οἱ πρόγονοι ὑμῶν οὕτως καλῶς καὶ μεγαλοπρεπῶς ἐπε- μελήθησαν, ἄξιον καὶ ὑμᾶς σπουδάσαι, ὦ ἄνδρες Ἀθηναῖοι, καὶ τοὺς ἀσελγῶς μὲν καταφρονοῦντας τῶν νόμων τῶν ὑμετέρων, ἀναιδῶς δ’ ἠσεβηκότας εἰς τοὺς θεοὺς ἄξιον τιμωρήσασθαι δυοῖν ἕνεκα, ἵνα οὗτοί τε τῶν ἠδικημένων δίκην δῶσιν, οἵ τ’ ἄλλοι πρόνοιαν ποιῶνται καὶ φοβῶνται μηδὲν εἰς τοὺς θεοὺς καὶ τὴν πόλιν ἁμαρτάνειν.", "st": "59.77"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν καὶ τὸν ἱεροκήρυκα καλέσαι, ὃς ὑπηρετεῖ τῇ τοῦ βασιλέως γυναικί, ὅταν ἐξορκοῖ τὰς γεραρὰς ⟨τὰς⟩ ἐν κανοῖς πρὸς τῷ βωμῷ, πρὶν ἅπτεσθαι τῶν ἱερῶν, ἵνα καὶ τοῦ ὅρκου καὶ τῶν λεγομένων ἀκούσητε, ὅσα οἷόν τ’ ἐστὶν ἀκούειν, καὶ εἰδῆτε ὡς σεμνὰ καὶ ἅγια καὶ ἀρχαῖα τὰ νόμιμά ἐστιν.", "st": "59.78"}, {"sp": "N", "t": "ΟΡΚΟΣ ΓΕΡΑΡΩΝ.", "st": "59.78"}, {"sp": "N", "t": "ἁγιστεύω καὶ εἰμὶ καθαρὰ καὶ ἁγνὴ ἀπό ⟨τε⟩ τῶν ἄλλων τῶν οὐ καθαρευόντων καὶ ἀπ’ ἀνδρὸς συνουσίας, καὶ τὰ θεοίνια καὶ τὰ ἰοβάκχεια γεραρῶ τῷ Διονύσῳ κατὰ τὰ πάτρια καὶ ἐν τοῖς καθήκουσι χρόνοις.", "st": "59.78"}, {"sp": "N", "t": "τοῦ μὲν ὅρκου τοίνυν καὶ τῶν νομιζομένων πατρίων, ὅσα οἷόν τ’ ἐστὶν εἰπεῖν, ἀκηκόατε, καὶ ὡς ἣν Στέφανος ἠγγύησεν τῷ Θεογένει γυναῖκα βασιλεύοντι ὡς αὑτοῦ οὖσαν θυγατέρα, αὕτη ἐποίει τὰ ἱερὰ ταῦτα καὶ ἐξώρκου τὰς γεραράς, καὶ ὅτι οὐδ’ αὐταῖς ταῖς ὁρώσαις τὰ ἱερὰ ταῦτα οἷόν τ’ ἐστὶν λέγειν πρὸς ἄλλον οὐδένα. φέρε δὴ καὶ μαρτυρίαν παράσχωμαι ὑμῖν δι’ ἀπορρήτου μὲν γεγενημένην, ὅμως δὲ αὐτοῖς τοῖς πεπραγμένοις ἐπιδείξω φανερὰν οὖσαν αὐτὴν καὶ ἀληθῆ.", "st": "59.79"}, {"sp": "N", "t": "ὡς γὰρ ἐγένετο τὰ ἱερὰ ταῦτα καὶ ἀνέβησαν εἰς Ἄρειον πάγον οἱ ἐννέα ἄρχοντες ταῖς καθηκούσαις ἡμέραις, εὐθὺς ἡ βουλὴ ἡ ἐν Ἀρείῳ πάγῳ, ὥσπερ καὶ τἄλλα πολλοῦ ἀξία ἐστὶν τῇ πόλει περὶ εὐσέβειαν, ἐζήτει τὴν γυναῖκα ταύτην τοῦ Θεογένους ἥτις ἦν, καὶ ἐξήλεγχεν, καὶ περὶ τῶν ἱερῶν πρόνοιαν ἐποιεῖτο, καὶ ἐζημίου τὸν Θεογένην ὅσα κυρία ἐστίν, ἐν ἀπορρήτῳ δὲ καὶ διὰ κοσμιότητος· οὐ γὰρ αὐτοκράτορές εἰσιν, ὡς ἂν βούλωνται, Ἀθηναίων τινὰ κολάσαι.", "st": "59.80"}, {"sp": "N", "t": "γενομένων δὲ λόγων, καὶ χαλεπῶς φερούσης τῆς ἐν Ἀρείῳ πάγῳ βουλῆς καὶ ζημιούσης τὸν Θεογένην ὅτι τοιαύτην ἔλαβεν γυναῖκα καὶ ταύτην εἴασε ποιῆσαι τὰ ἱερὰ τὰ ἄρρητα ὑπὲρ τῆς πόλεως, ἐδεῖτο ὁ Θεογένης ἱκετεύων καὶ ἀντιβολῶν, λέγων ὅτι οὐκ ᾔδει Νεαίρας αὐτὴν οὖσαν θυγατέρα, ἀλλ’ ἐξαπατηθείη ὑπὸ Στεφάνου, ὡς αὐτοῦ θυγατέρα οὖσαν αὐτὴν λαμβάνων γνησίαν κατὰ τὸν νόμον, καὶ διὰ τὴν ἀπειρίαν τῶν πραγμάτων καὶ τὴν ἀκακίαν τὴν ἑαυτοῦ τοῦτον πάρεδρον ποιήσαιτο, ἵνα διοικήσῃ τὴν ἀρχήν, ὡς εὔνουν ὄντα, καὶ διὰ τοῦτο κηδεύσειεν αὐτῷ.", "st": "59.81"}, {"sp": "N", "t": "“ὅτι δὲ” ἔφη “οὐ ψεύδομαι, μεγάλῳ τεκμηρίῳ καὶ περιφανεῖ ἐπιδείξω ὑμῖν· τὴν γὰρ ἄνθρωπον ἀποπέμψω ἐκ τῆς οἰκίας, ἐπειδὴ οὐκ ἔστιν Στεφάνου θυγάτηρ ἀλλὰ Νεαίρας. κἂν μὲν ταῦτα ποιήσω, ἤδη πιστοὶ ὑμῖν ὄντων οἱ λόγοι οἱ παρ’ ἐμοῦ λεγόμενοι, ὅτι ἐξηπατήθην· ἐὰν δὲ μὴ ποιήσω, τότ’ ἤδη με κολάζετε ὡς πονηρὸν ὄντα καὶ εἰς τοὺς θεοὺς ἠσεβηκότα.”", "st": "59.82"}, {"sp": "N", "t": "ὑποσχομένου δὲ ταῦτα τοῦ Θεογένους καὶ δεομένου, ἅμα μὲν καὶ ἐλεήσασα αὐτὸν ἡ ἐν Ἀρείῳ πάγῳ βουλὴ διὰ τὴν ἀκακίαν τοῦ τρόπου, ἅμα δὲ καὶ ἐξηπατῆσθαι τῇ ἀληθείᾳ ἡγουμένη ὑπὸ τοῦ Στεφάνου, ἐπέσχεν. ὡς δὲ κατέβη ἐξ Ἀρείου πάγου ὁ Θεογένης, εὐθὺς τήν τε ἄνθρωπον τὴν ταυτησὶ Νεαίρας θυγατέρα ἐκβάλλει ἐκ τῆς οἰκίας, τόν τε Στέφανον τὸν ἐξαπατήσαντα αὐτὸν τουτονὶ ἀπελαύνει ἀπὸ τοῦ συνεδρίου. καὶ οὕτως ἐπαύσαντο οἱ Ἀρεοπαγῖται κρίνοντες τὸν Θεογένην καὶ ὀργιζόμενοι αὐτῷ, καὶ συγγνώμην εἶχον ἐξα- πατηθέντι.", "st": "59.83"}, {"sp": "N", "t": "καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν μάρτυρα αὐτὸν τὸν Θεογένην καλῶ καὶ ἀναγκάσω μαρτυρεῖν. κάλει μοι Θεογένην Ἑρχιέα.", "st": "59.84"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.84"}, {"sp": "N", "t": "Θεογένης Ἑρχιεὺς μαρτυρεῖ, ὅτε αὐτὸς ἐβασίλευεν, γῆμαι Φανὼ ὡς Στεφάνου οὖσαν θυγατέρα, ἐπεὶ δὲ ᾔσθετο ἐξηπατημένος, τήν τε ἄνθρωπον ἐκβαλεῖν καὶ οὐκέτι συνοικεῖν αὐτῇ, καὶ Στέφανον ἀπελάσαι ἀπὸ τῆς παρεδρίας καὶ οὐκ ἐᾶν ἔτι παρεδρεύειν αὑτῷ.", "st": "59.84"}, {"sp": "N", "t": "λαβὲ δή μοι τὸν νόμον ⟨τὸν⟩ ἐπὶ τούτοις τουτονὶ καὶ ἀνάγνωθι, ἵν’ εἰδῆτε ὅτι οὐ μόνον προσῆκεν αὐτὴν ἀπέχεσθαι τῶν ἱερῶν τούτων τοιαύτην οὖσαν καὶ τοιαῦτα διαπεπραγμένην, τοῦ ὁρᾶν καὶ θύειν καὶ ποιεῖν τι τῶν νομιζομένων ὑπὲρ τῆς πόλεως πατρίων, ἀλλὰ καὶ τῶν ἄλλων τῶν Ἀθήνησιν ἁπάντων. ἐφ’ ᾗ γὰρ ἂν μοιχὸς ἁλῷ γυναικί, οὐκ ἔξεστιν αὐτῇ ἐλθεῖν εἰς οὐδὲν τῶν ἱερῶν τῶν δημοτελῶν, εἰς ἃ καὶ τὴν ξένην καὶ τὴν δούλην [ἐλθεῖν] ἐξουσίαν ἔδοσαν οἱ νόμοι καὶ θεασομένην καὶ ἱκετεύσουσαν εἰσιέναι·", "st": "59.85"}, {"sp": "N", "t": "ἀλλὰ μόναις ταύταις ἀπαγορεύουσιν οἱ νόμοι ταῖς γυναιξὶ μὴ εἰσιέναι εἰς τὰ ἱερὰ τὰ δημοτελῆ, ἐφ’ ᾗ ἂν μοιχὸς ἁλῷ, ἐὰν δ’ εἰσίωσι καὶ παρανομῶσι, νηποινεὶ πάσχειν ὑπὸ τοῦ βουλομένου ὅ τι ἂν πάσχῃ, πλὴν θανάτου, καὶ ἔδωκεν ὁ νόμος τὴν τιμωρίαν ὑπὲρ αὐτῶν τῷ ἐντυχόντι, διὰ τοῦτο δ’ ἐποίησεν ὁ νόμος, πλὴν θανάτου, τἄλλα ὑβρισθεῖσαν αὐτὴν μηδαμοῦ λαβεῖν δίκην, ἵνα μὴ μιάσματα μηδ’ ἀσεβήματα γίγνηται ἐν τοῖς ἱεροῖς, ἱκανὸν φόβον ταῖς γυναιξὶ παρασκευάζων τοῦ σωφρονεῖν καὶ μηδὲν ἁμαρτάνειν, ἀλλὰ δικαίως οἰκουρεῖν, διδάσκων ὡς, ἄν τι ἁμάρτῃ τοιοῦτον, ἅμα ἐκ τε τῆς οἰκίας τοῦ ἀνδρὸς ἐκβεβλημένη ἔσται καὶ ἐκ τῶν ἱερῶν τῶν τῆς πόλεως.", "st": "59.86"}, {"sp": "N", "t": "καὶ ὅτι ταῦτα οὕτως ἔχει, τοῦ νόμου αὐτοῦ ἀκούσαντες ἀναγνωσθέντος εἴσεσθε. καί μοι λαβέ.", "st": "59.87"}, {"sp": "N", "t": "ΝΟΜΟΣ ΜΟΙΧΕΙΑΣ.", "st": "59.87"}, {"sp": "N", "t": "ἐπειδὰν δὲ ἕλῃ τὸν μοιχόν, μὴ ἐξέστω τῷ ἑλόντι συνοικεῖν τῇ γυναικί· ἐὰν δὲ συνοικῇ, ἄτιμος ἔστω. μηδὲ τῇ γυναικὶ ἐξέστω εἰσιέναι εἰς τὰ ἱερὰ τὰ δημοτελῆ, ἐφ’ ᾗ ἂν μοιχὸς ἁλῷ· ἐὰν δ’ εἰσίῃ, νηποινεὶ πασχέτω ὅ τι ἂν πάσχῃ, πλὴν θανάτου.", "st": "59.87"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, καὶ τοῦ δήμου τοῦ Ἀθηναίων μαρτυρίαν παρασχέσθαι, ὡς σπουδάζει περὶ τὰ ἱερὰ ταῦτα καὶ ὡς πολλὴν πρόνοιαν περὶ αὐτῶν πεποίηται. ὁ γὰρ δῆμος ὁ Ἀθηναίων κυριώτατος ὢν τῶν ἐν τῇ πόλει ἁπάντων, καὶ ἐξὸν αὐτῷ ποιεῖν ὅ τι ἂν βούληται, οὕτω καλὸν καὶ σεμνὸν ἡγήσατ’ εἶναι δῶρον τὸ Ἀθηναῖον γενέσθαι, ὥστε νόμους ἔθετο αὑτῷ καθ’ οὓς ποιεῖσθαι δεῖ, ἐάν τινα βούλωνται, πολίτην, οἳ νῦν προπεπηλακισμένοι εἰσὶν ὑπὸ Στεφάνου τουτουὶ καὶ τῶν οὕτω γεγαμηκότων.", "st": "59.88"}, {"sp": "N", "t": "ὅμως δ’ ἀκούοντες αὐτῶν βελτίους ἔσεσθε, καὶ τὰ κάλλιστα καὶ τὰ σεμνότατα δῶρα τοῖς εὐεργετοῦσι τὴν πόλιν διδόμενα γνώσεσθε ὡς λελυμασμένοι εἰσίν. πρῶτον μὲν γὰρ νόμος ἐστὶ τῷ δήμῳ κείμενος μὴ ἐξεῖναι ποιήσασθαι Ἀθηναῖον, ὃν ἂν μὴ δι’ ἀνδραγαθίαν εἰς τὸν δῆμον τὸν Ἀθηναίων ἄξιον ᾖ γενέσθαι πολίτην. ἔπειτ’ ἐπειδὰν πεισθῇ ὁ δῆμος καὶ δῷ τὴν δωρεάν, οὐκ ἐᾷ κυρίαν γενέσθαι τὴν ποίησιν, ἐὰν μὴ τῇ ψήφῳ εἰς τὴν ἐπιοῦσαν ἐκκλησίαν ὑπερεξακισχίλιοι Ἀθηναίων ψηφίσωνται κρύβδην ψηφιζόμενοι.", "st": "59.89"}, {"sp": "N", "t": "τοὺς δὲ πρυτάνεις κελεύει τιθέναι τοὺς καδίσκους ὁ νόμος καὶ τὴν ψῆφον διδόναι προσιόντι τῷ δήμῳ πρὶν τοὺς ξένους εἰσιέναι, καὶ τὰ γέρρα ἀναιρεῖν, ἵνα κύριος ὢν αὐτὸς αὑτοῦ ἕκαστος σκοπῆται πρὸς αὑτὸν ὅντινα μέλλει πολίτην ποιήσεσθαι, εἰ ἄξιός ἐστι τῆς δωρεᾶς ὁ μέλλων λήψεσθαι. ἔπειτα μετὰ ταῦτα παρανόμων γραφὴν ἐποίησε κατ’ αὐτοῦ τῷ βουλομένῳ Ἀθηναίων, καὶ ἔστιν εἰσελθόντα εἰς τὸ δικαστήριον ἐξελέγξαι ὡς οὐκ ἄξιός ἐστι τῆς δωρεᾶς, ἀλλὰ παρὰ τοὺς νόμους Ἀθηναῖος γέγονεν.", "st": "59.90"}, {"sp": "N", "t": "καὶ ἤδη τισὶ τοῦ δήμου δόντος τὴν δωρεάν, λόγῳ ἐξαπατηθέντος ὑπὸ τῶν αἰτούντων, παρανόμων γραφῆς γενομένης καὶ εἰσελθούσης εἰς τὸ δικαστήριον, ἐξελεγχθῆναι συνέβη τὸν εἰληφότα τὴν δωρεὰν μὴ ἄξιον εἶναι αὐτῆς, καὶ ἀφείλετο τὸ δικαστήριον. καὶ τοὺς μὲν πολλοὺς καὶ παλαιοὺς ἔργον διηγήσασθαι· ἃ δὲ πάντες μνημονεύετε, Πειθόλαν τε τὸν Θετταλὸν καὶ Ἀπολλωνίδην τὸν Ὀλύνθιον πολίτας ὑπὸ τοῦ δήμου γενομένους ἀφείλετο τὸ δικαστήριον·", "st": "59.91"}, {"sp": "N", "t": "ταῦτα γὰρ οὐ πάλαι ἐστὶ γεγενημένα ὥστε ἀγνοεῖν ὑμᾶς. οὕτως τοίνυν καλῶς καὶ ἰσχυρῶς τῶν νόμων κειμένων ὑπὲρ τῆς πολιτείας, δι’ ὧν δεῖ Ἀθηναῖον γενέσθαι, ἕτερός ἐστιν ἐφ’ ἅπασι τούτοις κυριώτατος νόμος κείμενος· οὕτω πολλὴν ὁ δῆμος πρόνοιαν ἐποιεῖτο ὑπὲρ αὑτοῦ καὶ τῶν θεῶν ὥστε δι’ εὐσεβείας τὰ ἱερὰ θύεσθαι ὑπὲρ τῆς πόλεως. ὅσους γὰρ ἂν ποιήσηται ὁ δῆμος ὁ Ἀθηναίων πολίτας, ὁ νόμος ἀπαγορεύει διαρρήδην μὴ ἐξεῖναι αὐτοῖς τῶν ἐννέα ἀρχόντων γενέσθαι, μηδὲ ἱερωσύνης μηδεμιᾶς μετασχεῖν· τοῖς δ’ ἐκ τούτων μετέδωκεν ἤδη ὁ δῆμος ἁπάντων, καὶ προσέθηκεν “ἐὰν ὦσιν ἐκ γυναικὸς ἀστῆς καὶ ἐγγυητῆς κατὰ τὸν νόμον.”", "st": "59.92"}, {"sp": "N", "t": "καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, μεγάλῃ καὶ περιφανεῖ μαρτυρίᾳ ἐγὼ ὑμῖν δηλώσω. βούλομαι δ’ ὑμῖν τὸν νόμον πόρρωθεν προδιηγήσασθαι, ὡς ἐτέθη καὶ πρὸς οὓς διωρίσθη, ὡς ἄνδρας ἀγαθοὺς ὄντας καὶ βεβαίους φίλους περὶ τὸν δῆμον γεγονότας. ἐκ τούτων γὰρ ἁπάντων εἴσεσθε τήν τε τοῦ δήμου δωρεὰν τὴν ἀπόθετον τοῖς εὐεργέταις προ- πηλακιζομένην, καὶ ὅσων ὑμᾶς ἀγαθῶν κωλύουσι κυρίους εἶναι Στέφανός τε οὑτοσὶ καὶ οἱ τὸν αὐτὸν τρόπον τούτῳ γεγαμηκότες καὶ παιδοποιούμενοι.", "st": "59.93"}, {"sp": "N", "t": "Πλαταιῆς γάρ, ὦ ἄνδρες Ἀθηναῖοι, μόνοι τῶν Ἑλλήνων ὑμῖν ἐβοήθησαν Μαραθῶνάδε, ὅτε Δᾶτις ὁ βασιλέως Δαρείου στρατηγὸς ἀναχωρῶν ἐξ Ἐρετρίας Εὔβοιαν ὑφ’ ἑαυτῷ ποιησάμενος, ἀπέβη εἰς τὴν χώραν πολλῇ δυνάμει καὶ ἐπόρθει. καὶ ἔτι καὶ νῦν τῆς ἀνδραγαθίας αὐτῶν ὑπομνήματα ⟨ἡ⟩ ἐν τῇ ποικίλῃ στοᾷ γραφὴ δεδήλωκεν· ὡς ἕκαστος γὰρ τάχους εἶχεν, εὐθὺς προσβοηθῶν γέγραπται, οἱ τὰς κυνᾶς τὰς Βοιωτίας ἔχοντες.", "st": "59.94"}, {"sp": "N", "t": "πάλιν δὲ Ξέρξου ἰόντος ἐπὶ τὴν Ἑλλάδα, Θηβαίων μηδισάντων, οὐκ ἐτόλμησαν ἀποστῆναι τῆς ὑμετέρας φιλίας, ἀλλὰ μόνοι τῶν ἄλλων Βοιωτῶν οἱ μὲν ἡμίσεις αὐτῶν μετὰ Λακεδαιμονίων καὶ Λεωνίδου ἐν Θερμοπύλαις παραταξάμενοι τῷ βαρβάρῳ ἐπιόντι συναπώλοντο, οἱ δὲ λοιποὶ ἐμβάντες εἰς τὰς ὑμετέρας τριήρεις, ἐπειδὴ αὐτοῖς οἰκεῖα σκάφη οὐχ ὑπῆρχεν, συνεναυμάχουν ὑμῖν ἐπί τε Ἀρτεμισίῳ καὶ ἐν Σαλαμῖνι,", "st": "59.95"}, {"sp": "N", "t": "καὶ τὴν τελευταίαν μάχην Πλαταιᾶσι Μαρδονίῳ τῷ βασιλέως στρατηγῷ μεθ’ ὑμῶν καὶ τῶν συνελευθερούντων τὴν Ἑλλάδα μαχεσάμενοι, εἰς κοινὸν τὴν ἐλευθερίαν τοῖς ἄλλοις Ἕλλησι κατέθηκαν. ἐπεὶ δὲ Παυσανίας ὁ Λακεδαιμονίων βασιλεὺς ὑβρίζειν ἐνεχείρει ὑμᾶς, καὶ οὐκ ἠγάπα ὅτι τῆς ἡγεμονίας μόνοι ἠξιώθησαν Λακεδαιμόνιοι ὑπὸ τῶν Ἑλλήνων, καὶ ἡ πόλις τῇ μὲν ἀληθείᾳ ἡγεῖτο τῆς ἐλευθερίας τοῖς Ἕλλησιν, τῇ δὲ φιλοτιμίᾳ οὐκ ἠναντιοῦτο τοῖς Λακεδαιμονίοις,", "st": "59.96"}, {"sp": "N", "t": "ἵνα μὴ φθονηθῶσιν ὑπὸ τῶν συμμάχων—ἐφ’ οἷς φυσηθεὶς Παυσανίας ὁ τῶν Λακεδαιμονίων βασιλεὺς ἐπέγραψεν ἐπὶ τὸν τρίποδα ⟨τὸν⟩ ἐν Δελφοῖς, ὃν οἱ Ἕλληνες οἱ συμμαχεσάμενοι τὴν Πλαταιᾶσι μάχην καὶ τὴν ἐν Σαλαμῖνι ναυμαχίαν ναυμαχήσαντες κοινῇ ποιησάμενοι ἀνέθηκαν ἀριστεῖον τῷ Ἀπόλλωνι ἀπὸ τῶν βαρβάρων,", "st": "59.97"}, {"sp": "N", "t": "Ἑλλήνων ἀρχηγός, ἐπεὶ στρατὸν ὤλεσε Μήδων,<br>Παυσανίας Φοίβῳ μνῆμ’ ἀνέθηκε τόδε,", "st": "59.97"}, {"sp": "N", "t": "ὡς αὑτοῦ τοῦ ἔργου ὄντος καὶ τοῦ ἀναθήματος, ἀλλ’ οὐ κοινοῦ τῶν συμμάχων·", "st": "59.97"}, {"sp": "N", "t": "ὀργισθέντων δὲ τῶν Ἑλλήνων, οἱ Πλαταιεῖς λαγχάνουσι δίκην τοῖς Λακεδαιμονίοις εἰς τοὺς Ἀμφικτύονας χιλίων ταλάντων ὑπὲρ τῶν συμμάχων, καὶ ἠνάγκασαν αὐτοὺς ἐκκολάψαντας τὰ ἐλεγεῖα ἐπιγράψαι τὰς πόλεις τὰς κοινωνούσας τοῦ ἔργου. δι’ ὅπερ αὐτοῖς οὐχ ἥκιστα παρηκολούθει ἡ ἔχθρα ⟨ἡ⟩ παρὰ Λακεδαιμονίων καὶ ἐκ τοῦ γένους τοῦ βασιλείου. καὶ ἐν μὲν τῷ παρόντι οὐκ εἶχον αὐτοῖς ὅ τι χρήσωνται οἱ Λακεδαιμόνιοι, ὕστερον δὲ ὡς πεντήκοντα ἔτεσιν Ἀρχίδαμος ὁ Ζευξιδάμου Λακεδαιμονίων βασιλεὺς εἰρήνης οὔσης ἐνεχείρησεν αὐτῶν καταλαβεῖν τὴν πόλιν.", "st": "59.98"}, {"sp": "N", "t": "ἔπραξε δὲ ταῦτ’ ἐκ Θηβῶν δι’ Εὐρυμάχου τοῦ Λεοντιάδου βοιωταρχοῦντος, ἀνοιξάντων τὰς πύλας τῆς νυκτὸς Ναυκλείδου καὶ ἄλλων τινῶν μετ’ αὐτοῦ, πεισθέντων χρήμασιν. αἰσθόμενοι δ’ οἱ Πλαταιεῖς ἔνδον ὄντας τοὺς Θηβαίους τῆς νυκτὸς καὶ ἐξαπίνης [αὑτῶν] τὴν πόλιν ἐν εἰρήνῃ κατειλημμένην, προσεβοήθουν καὶ αὐτοὶ καὶ συνετάττοντο. καὶ ἐπειδὴ ἡμέρα ἐγένετο καὶ εἶδον οὐ πολλοὺς ὄντας τοὺς Θηβαίους, ἀλλὰ τοὺς πρώτους αὐτῶν εἰσεληλυθότας (ὕδωρ γὰρ γενόμενον τῆς νυκτὸς πολὺ ἐκώλυσεν αὐτοὺς πάντας εἰσελθεῖν· ὁ γὰρ Ἀσωπὸς ποταμὸς μέγας ἐρρύη καὶ διαβῆναι οὐ ῥᾴδιον ἦν, ἄλλως τε καὶ νυκτός),", "st": "59.99"}, {"sp": "N", "t": "ὡς οὖν εἶδον οἱ Πλαταιεῖς τοὺς Θηβαίους ἐν τῇ πόλει καὶ ἔγνωσαν ὅτι οὐ πάντες πάρεισιν, ἐπιτίθενται καὶ εἰς μάχην ἐλθόντες κρατοῦσι καὶ φθάνουσιν ἀπολέσαντες αὐτοὺς πρὶν τοὺς ἄλλους προσβοηθῆσαι, καὶ ὡς ὑμᾶς πέμπουσιν εὐθὺς ἄγγελον τήν τε πρᾶξιν φράσοντα καὶ τὴν μάχην δηλώσοντα ὅτι νικῶσι, καὶ βοηθεῖν ἀξιοῦντες, ἂν οἱ Θηβαῖοι τὴν χώραν αὐτῶν δῃῶσιν. ἀκούσαντες δὲ οἱ Ἀθηναῖοι τὰ γεγονότα διὰ τάχους ἐβοήθουν εἰς τὰς Πλαταιάς· καὶ οἱ Θηβαῖοι ὡς ἑώρων τοὺς Ἀθηναίους βεβοηθηκότας τοῖς Πλαταιεῦσιν, ἀνεχώρησαν ἐπ’ οἴκου.", "st": "59.100"}, {"sp": "N", "t": "ὡς οὖν ἀπέτυχον οἱ Θηβαῖοι τῆς πείρας καὶ οἱ Πλαταιεῖς τοὺς ἄνδρας οὓς ἔλαβον αὐτῶν ἐν τῇ μάχῃ ζῶντας, ἀπέκτειναν, ὀργισθέντες οἱ Λακεδαιμόνιοι ἀπροφασίστως ἤδη στρατεύουσιν ἐπὶ τὰς Πλαταιάς, Πελοποννησίοις μὲν ἅπασι πλὴν Ἀργείων τὰ δύο μέρη τῆς στρατιᾶς ἀπὸ τῶν πόλεων ἑκάστων πέμπειν ἐπιτάξαντες, Βοιωτοῖς δὲ τοῖς ἄλλοις ἅπασι καὶ Λοκροῖς καὶ Φωκεῦσι καὶ Μαλιεῦσι καὶ Οἰταίοις καὶ Αἰνιᾶσιν πανδημεὶ ἐπαγγείλαντες στρατεύειν.", "st": "59.101"}, {"sp": "N", "t": "καὶ περικαθεζόμενοι αὐτῶν τὸ τεῖχος πολλῇ δυνάμει ἐπηγγέλλοντο, εἰ βούλοιντο τὴν μὲν πόλιν αὑτοῖς παραδοῦναι, τὴν δὲ χώραν ἔχειν καὶ καρποῦσθαι τὰ αὑτῶν, ἀφίστασθαι [δὲ] τῆς Ἀθηναίων συμμαχίας. οὐκ ἐθελησάντων δὲ τῶν Πλαταιέων, ἀλλ’ ἀποκριναμένων ὅτι ἄνευ Ἀθηναίων οὐδὲν ἂν πράξειαν, ἐπολιόρκουν αὐτοὺς διπλῷ τείχει περιτειχίσαντες δύο ἔτη, πολλὰς καὶ παντοδαπὰς πείρας προσάγοντες.", "st": "59.102"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀπειρήκεσαν οἱ Πλαταιεῖς καὶ ἐνδεεῖς ἦσαν ἁπάντων καὶ ἠποροῦντο τῆς σωτηρίας, διακληρωσάμενοι πρὸς σφᾶς αὐτοὺς οἱ μὲν ὑπομείναντες ἐπολιορκοῦντο, οἱ δὲ τηρήσαντες νύκτα καὶ ὕδωρ καὶ ἄνεμον πολύν, ἐξελθόντες ἐκ τῆς πόλεως καὶ ὑπερβάντες τὸ περιτείχισμα τῶν πολεμίων λαθόντες τὴν στρατιάν, ἀποσφάξαντες τοὺς φύλακας διασῴζονται δεῦρο, δεινῶς διακείμενοι καὶ ἀπροσδοκήτως· οἱ δ’ ὑπομείναντες αὐτῶν ἁλούσης τῆς πόλεως κατὰ κράτος ἀπεσφάγησαν πάντες οἱ ἡβῶντες, παῖδες δὲ καὶ γυναῖκες ἐξηνδραποδίσθησαν, ὅσοι μὴ αἰσθόμενοι ἐπιόντας τοὺς Λακεδαιμονίους ὑπεξῆλθον Ἀθήναζε.", "st": "59.103"}, {"sp": "N", "t": "τοῖς οὖν οὕτω φανερῶς ἐνδεδειγμένοις τὴν εὔνοιαν τῷ δήμῳ, καὶ προεμένοις ἅπαντα τὰ αὑτῶν καὶ παῖδας καὶ γυναῖκας, πάλιν σκοπεῖτε πῶς μετέδοτε τῆς πολιτείας. ἐκ γὰρ τῶν ψηφισμάτων τῶν ὑμετέρων καταφανὴς πᾶσιν ἔσται ὁ νόμος, καὶ γνώσεσθ’ ὅτι ἀληθῆ λέγω. καί μοι λαβὲ τὸ ψήφισμα τοῦτο καὶ ἀνάγνωθι αὐτοῖς.", "st": "59.104"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ ΠΕΡΙ ΠΛΑΤΑΙΕΩΝ.", "st": "59.104"}, {"sp": "N", "t": "Ἱπποκράτης εἶπεν, Πλαταιέας εἶναι Ἀθηναίους ἀπὸ τῆσδε τῆς ἡμέρας, ἐπιτίμους καθάπερ οἱ ἄλλοι Ἀθηναῖοι, καὶ μετεῖναι αὐτοῖς ὧνπερ Ἀθηναίοις μέτεστι πάντων, καὶ ἱερῶν καὶ ὁσίων, πλὴν εἴ τις ἱερωσύνη ἢ τελετή ἐστιν ἐκ γένους, μηδὲ τῶν ἐννέα ἀρχόντων, τοῖς δ’ ἐκ τούτων. κατανεῖμαι δὲ τοὺς Πλαταιέας εἰς τοὺς δήμους καὶ τὰς φυλάς. ἐπειδὰν δὲ νεμηθῶσι, μὴ ἐξέστω ἔτι Ἀθηναίῳ μηδενὶ γίγνεσθαι Πλαταιέων, μὴ εὑρομένῳ παρὰ τοῦ δήμου τοῦ Ἀθηναίων.", "st": "59.104"}, {"sp": "N", "t": "ὁρᾶτε, ὦ ἄνδρες Ἀθηναῖοι, ὡς καλῶς καὶ δικαίως ἔγραψεν ὁ ῥήτωρ ὑπὲρ τοῦ δήπου τοῦ Ἀθηναίων, καὶ ἠξίωσε τοὺς Πλαταιέας λαμβάνοντας τὴν δωρεὰν πρῶτον μὲν δοκιμασθῆναι ἐν τῷ δικαστηρίῳ κατ’ ἄνδρα ἕκαστον, εἰ ἔστιν Πλαταιεὺς καὶ εἰ τῶν φίλων τῶν τῆς πόλεως, ἵνα μὴ ἐπὶ ταύτῃ τῇ προφάσει πολλοὶ μεταλάβωσι τῆς πολιτείας· ἔπειτα τοὺς δοκιμασθέντας ἀναγραφῆναι ἐν στήλῃ λιθίνῃ, καὶ στῆσαι ἐν ἀκροπόλει παρὰ τῇ θεῷ, ἵνα σῴζηται ἡ δωρεὰ τοῖς ἐπιγιγνομένοις καὶ ᾖ ἐξελέγξαι ὅτου ἂν ἕκαστος ᾖ συγγενής.", "st": "59.105"}, {"sp": "N", "t": "καὶ ὕστερον οὐκ ἐᾷ γίγνεσθαι Ἀθηναῖον ἐξεῖναι, ὃς ἂν μὴ νῦν γένηται καὶ δοκιμασθῇ ἐν τῷ δικαστηρίῳ, τοῦ μὴ πολλοὺς φάσκοντας Πλαταιέας εἶναι κατασκευάζειν αὑτοῖς πολιτείαν. ἔπειτα καὶ τὸν νόμον διωρίσατο ἐν τῷ ψηφίσματι πρὸς αὐτοὺς εὐθέως ὑπέρ τε τῆς πόλεως καὶ τῶν θεῶν, [καὶ] μὴ ἐξεῖναι αὐτῶν μηδενὶ τῶν ἐννέα ἀρχόντων λαχεῖν μηδὲ ἱερωσύνης μηδεμιᾶς, τοῖς δ’ ἐκ τούτων, ἂν ὦσιν ἐξ ἀστῆς γυναικὸς καὶ ἐγγυητῆς κατὰ τὸν νόμον.", "st": "59.106"}, {"sp": "N", "t": "οὔκουν δεινόν; πρὸς μὲν τοὺς ἀστυγείτονας καὶ ὁμολογουμένως ἀρίστους τῶν Ἑλλήνων εἰς τὴν πόλιν γεγενημένους οὕτω καλῶς καὶ ἀκριβῶς διωρίσασθε περὶ ἑκάστου, ἐφ’ οἷς δεῖ ἔχειν τὴν δωρεάν, τὴν δὲ περιφανῶς ἐν ἁπάσῃ τῇ Ἑλλάδι πεπορνευμένην οὕτως αἰσχρῶς καὶ ὀλιγώρως ἐάσετε ὑβρίζουσαν εἰς τὴν πόλιν καὶ ἀσεβοῦσαν εἰς τοὺς θεοὺς ἀτιμώρητον, ἣν οὔτε οἱ πρόγονοι ἀστὴν κατέλιπον οὔθ’ ὁ δῆμος πολῖτιν ἐποιήσατο;", "st": "59.107"}, {"sp": "N", "t": "ποῦ γὰρ αὕτη οὐκ εἴργασται τῷ σώματι, ἢ ποῖ οὐκ ἐλήλυθεν ἐπὶ τῷ καθ’ ἡμέραν μισθῷ; οὐκ ἐν Πελοποννήσῳ μὲν πάσῃ, ἐν Θετταλίᾳ δὲ καὶ Μαγνησίᾳ μετὰ Σίμου τοῦ Λαρισαίου καὶ Εὐρυδάμαντος τοῦ Μηδείου, ἐν Χίῳ δὲ καὶ ἐν Ἰωνίᾳ τῇ πλείστῃ μετὰ Σωτάδου τοῦ Κρητὸς ἀκολουθοῦσα, μισθωθεῖσα ὑπὸ τῆς Νικαρέτης, ὅτε ἔτι ἐκείνης ἦν; τὴν δὴ ὑφ’ ἑτέροις οὖσαν καὶ ἀκολουθοῦσαν τῷ διδόντι τί οἴεσθε ποιεῖν; ἆρ’ οὐχ ὑπηρετεῖν τοῖς χρωμένοις εἰς ἁπάσας ἡδονάς; εἶτα τὴν τοιαύτην καὶ περιφανῶς ἐγνωσμένην ὑπὸ πάντων γῆς περίοδον εἰργασμένην ψηφιεῖσθε ἀστὴν εἶναι;", "st": "59.108"}, {"sp": "N", "t": "καὶ τί καλὸν φήσετε πρὸς τοὺς ἐρωτῶντας διαπεπρᾶχθαι, ἢ ποίᾳ αἰσχύνῃ καὶ ἀσεβείᾳ οὐκ ἔνοχοι αὐτοὶ εἶναι; πρὶν μὲν γὰρ γραφῆναι ταύτην καὶ εἰς ἀγῶνα καταστῆναι καὶ πυθέσθαι πάντας ἥτις ἦν καὶ οἷα ἠσέβηκεν, τὰ μὲν ἀδικήματα ταύτης ἦν, ἡ δ’ ἀμέλεια τῆς πόλεως· καὶ οἱ μὲν οὐκ ᾔδεσαν ὑμῶν, οἱ δὲ πυθόμενοι τῷ μὲν λόγῳ ἠγανάκτουν, τῷ δ’ ἔργῳ οὐκ εἶχον ὅ τι χρήσαιντο αὐτῇ, οὐδενὸς εἰς ἀγῶνα καθιστάντος οὐδὲ διδόντος περὶ αὐτῆς τὴν ψῆφον. ἐπειδὴ δὲ καὶ ἴστε πάντες καὶ ἔχετε ἐφ’ ὑμῖν αὐτοῖς καὶ κύριοί ἐστε κολάσαι, ὑμέτερον ἤδη τὸ ἀσέβημα γίγνεται τὸ πρὸς τοὺς θεούς, ἐὰν μὴ ταύτην κολάσητε.", "st": "59.109"}, {"sp": "N", "t": "τί δὲ καὶ φήσειεν ἂν ὑμῶν ἕκαστος εἰσιὼν πρὸς τὴν ἑαυτοῦ γυναῖκ’ ἢ θυγατέρα ἢ μητέρα, ἀποψηφισάμενος ταύτης, ἐπειδὰν ἔρηται ὑμᾶς “ποῦ ἦτε;” καὶ εἴπητε ὅτι “ἐδικάζομεν;” “τῷ;” ἐρήσεται εὐθύς. “Νεαίρᾳ” δῆλον ὅτι φήσετε (οὐ γάρ;) “ὅτι ξένη οὖσα ἀστῷ συνοικεῖ παρὰ τὸν νόμον, καὶ ὅτι τὴν θυγατέρα μεμοιχευμένην ἐξέδωκεν Θεογένει τῷ βασιλεύσαντι, καὶ αὕτη ἔθυσε τὰ ἱερὰ τὰ ἄρρητα ὑπὲρ τῆς πόλεως καὶ τῷ Διονύσῳ γυνὴ ἐδόθη”, καὶ τἄλλα διηγούμενοι τὴν κατηγορίαν αὐτῆς, ὡς καὶ μνημονικῶς καὶ ἐπιμελῶς περὶ ἑκάστου κατηγορήθη.", "st": "59.110"}, {"sp": "N", "t": "αἱ δὲ ἀκούσασαι ἐρήσονται “τί οὖν ἐποιήσατε;” ὑμεῖς δὲ φήσετε “ἀπεψηφίσμεθα.” οὐκοῦν ἤδη αἱ μὲν σωφρονέσταται τῶν γυναικῶν ὀργισθήσονται ὑμῖν, διότι ὁμοίως αὐταῖς ταύτην κατηξιοῦτε μετέχειν τῶν τῆς πόλεως καὶ τῶν ἱερῶν· ὅσαι δ’ ἀνόητοι, φανερῶς ἐπιδείκνυτε ποιεῖν ὅ τι ἂν βούλωνται, ὡς ἄδειαν ὑμῶν καὶ τῶν νόμων δεδωκότων· δόξετε γὰρ ὀλιγώρως καὶ ῥᾳθύμως φέροντες ὁμογνώμονες καὶ αὐτοὶ εἶναι τοῖς ταύτης τρόποις.", "st": "59.111"}, {"sp": "N", "t": "ὥστε πολὺ μᾶλλον ἐλυσιτέλει μὴ γενέσθαι τὸν ἀγῶνα τουτονὶ ἢ γενομένου ἀποψηφίσασθαι ὑμᾶς. κομιδῇ γὰρ ἤδη [παντελῶς] ἐξουσία ἔσται ταῖς πόρναις συνοικεῖν οἷς ἂν βούλωνται, καὶ τοὺς παῖδας φάσκειν οὗ ἂν τύχωσιν εἶναι· καὶ οἱ μὲν νόμοι ἄκυροι ὑμῖν ἔσονται, οἱ δὲ τρόποι τῶν ἑταιρῶν κύριοι ὅ τι ἂν βούλωνται διαπράττεσθαι. ὥστε καὶ ὑπὲρ τῶν πολιτίδων σκοπεῖτε, τοῦ μὴ ἀνεκδότους γενέσθαι τὰς τῶν πενήτων θυγατέρας.", "st": "59.112"}, {"sp": "N", "t": "νῦν μὲν γάρ, κἂν ἀπορηθῇ τις, ἱκανὴν προῖκ’ αὐτῇ ὁ νόμος συμβάλλεται, ἂν καὶ ὁπωστιοῦν μετρίαν ἡ φύσις ὄψιν ἀποδῷ· προπηλακισθέντος δὲ τοῦ νόμου ὑφ’ ὑμῶν ἀποφυγούσης ταύτης, καὶ ἀκύρου γενομένου, παντελῶς ἤδη ἡ μὲν τῶν πορνῶν ἐργασία ἥξει εἰς τὰς τῶν πολιτῶν θυγατέρας, δι’ ἀπορίαν ὅσαι ἂν μὴ δύνωνται ἐκδοθῆναι, τὸ δὲ τῶν ἐλευθέρων γυναικῶν ἀξίωμα εἰς τὰς ἑταίρας, ἂν ἄδειαν λάβωσι τοῦ ἐξεῖναι αὐταῖς παιδοποιεῖσθαι ὡς ἂν βούλωνται καὶ τελετῶν καὶ ἱερῶν καὶ τιμῶν μετέχειν τῶν ἐν τῇ πόλει.", "st": "59.113"}, {"sp": "N", "t": "ὥστε εἷς ἕκαστος ὑμῶν νομιζέτω, ὁ μὲν ὑπὲρ γυναικός, ὁ δ’ ὑπὲρ θυγατρός, ὁ δ’ ὑπὲρ μητρός, ὁ δ’ ὑπὲρ τῆς πόλεως καὶ τῶν νόμων καὶ τῶν ἱερῶν τὴν ψῆφον φέρειν, τοῦ μὴ ἐξ ἴσου φανῆναι ἐκείνας τιμωμένας ταύτῃ τῇ πόρνῃ, μηδὲ τὰς μετὰ πολλῆς καὶ καλῆς σωφροσύνης καὶ ἐπιμελείας τραφείσας ὑπὸ τῶν προσηκόντων καὶ ἐκδοθείσας κατὰ τοὺς νόμους, ταύτας ἐν τῷ ἴσῳ φαίνεσθαι μετεχούσας τῇ μετὰ πολλῶν καὶ ἀσελγῶν τρόπων πολλάκις πολλοῖς ἑκάστης ἡμέρας συγγεγενημένῃ, ὡς ἕκαστος ἐβούλετο.", "st": "59.114"}, {"sp": "N", "t": "ἡγεῖσθε δὲ μήτ’ ἐμὲ τὸν λέγοντα εἶναι Ἀπολλόδωρον μήτε τοὺς ἀπολογησομένους καὶ συνεροῦντας πολίτας, ἀλλὰ τοὺς νόμους καὶ Νέαιραν ταυτηνὶ περὶ τῶν πεπραγμένων αὐτῇ πρὸς ἀλλήλους δικάζεσθαι. καὶ ὅταν μὲν ἐπὶ τῆς κατηγορίας γένησθε, τῶν νόμων αὐτῶν ἀκούετε, δι’ ὧν οἰκεῖται ἡ πόλις καὶ καθ’ οὓς ὀμωμόκατε δικάσειν, τί κελεύουσι καὶ τί παραβεβήκασιν· ὅταν δὲ ἐπὶ τῆς ἀπολογίας ἦτε, μνημονεύοντες τὴν τῶν νόμων κατηγορίαν καὶ τὸν ἔλεγχον τὸν τῶν εἰρημένων, τήν τε ὄψιν αὐτῆς ἰδόντες, ἐνθυμεῖσθε τοῦτο μόνον, εἰ Νέαιρα οὖσα ταῦτα διαπέπρακται.", "st": "59.115"}, {"sp": "N", "t": "ἄξιον δὲ κἀκεῖνο ἐνθυμηθῆναι, ὦ ἄνδρες Ἀθηναῖοι, ὅτι Ἀρχίαν τὸν ἱεροφάντην γενόμενον, ἐξελεγχθέντα ἐν τῷ δικαστηρίῳ ἀσεβεῖν θύοντα παρὰ τὰ πάτρια τὰς θυσίας, ἐκολάσατε ὑμεῖς, καὶ ἄλλα τε κατηγορήθη αὐτοῦ καὶ ὅτι Σινώπῃ τῇ ἑταίρᾳ Ἁλῴοις ἐπὶ τῆς ἐσχάρας τῆς ἐν τῇ αὐλῇ Ἐλευσῖνι προσαγούσῃ ἱερεῖον θύσειεν, οὐ νομίμου ὄντος ἐν ταύτῃ τῇ ἡμέρᾳ ἱερεῖα θύειν, οὐδ’ ἐκείνου οὔσης τῆς θυσίας ἀλλὰ τῆς ἱερείας.", "st": "59.116"}, {"sp": "N", "t": "οὔκουν δεινὸν τὸν μὲν καὶ ἐκ γένους ὄντα τοῦ Εὐμολπιδῶν καὶ προγόνων καλῶν κἀγαθῶν καὶ πολίτην τῆς πόλεως, ὅτι ἐδόκει τι παραβῆναι τῶν νομίμων, δοῦναι δίκην (καὶ οὔθ’ ἡ τῶν συγγενῶν οὔθ’ ἡ τῶν φίλων ἐξαίτησις ὠφέλησεν αὐτόν, οὔθ’ αἱ λῃτουργίαι ἃς ἐλῃτούργησε τῇ πόλει αὐτὸς καὶ οἱ πρόγονοι αὐτοῦ, οὔτε τὸ ἱεροφάντην εἶναι, ἀλλ’ ἐκολάσατε δόξαντα ἀδικεῖν)· Νέαιραν δὲ ταυτηνὶ εἴς τε τὸν αὐτὸν θεὸν τοῦτον ἠσεβηκυῖαν καὶ τοὺς νόμους, καὶ αὐτὴν καὶ τὴν θυγατέρα αὐτῆς, οὐ τιμωρήσεσθε;", "st": "59.117"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε τί ποτε καὶ ἐροῦσι πρὸς ὑμᾶς ἐν τῇ ἀπολογίᾳ. πότερον ὡς ἀστή ἐστιν Νέαιρα αὑτηὶ καὶ κατὰ τοὺς νόμους συνοικεῖ αὐτῷ; ἀλλὰ μεμαρτύρηται ἑταίρα οὖσα καὶ δούλη Νικαρέτης γεγενημένη. ἀλλ’ οὐ γυναῖκα εἶναι αὐτοῦ, ἀλλὰ παλλακὴν ἔχειν ἔνδον; ἀλλ’ οἱ παῖδες ταύτης ὄντες καὶ εἰσηγμένοι εἰς τοὺς φράτερας ὑπὸ Στεφάνου καὶ ἡ θυγάτηρ ἀνδρὶ Ἀθηναίῳ ἐκδοθεῖσα περιφανῶς αὐτὴν ἀποφαίνουσι γυναῖκα ἔχοντα.", "st": "59.118"}, {"sp": "N", "t": "ὡς μὲν τοίνυν οὐκ ἀληθῆ ἐστιν τὰ κατηγορημένα καὶ μεμαρτυρημένα, οὔτ’ αὐτὸν Στέφανον οὔτ’ ἄλλον ὑπὲρ τούτου οἶμαι ἐπιδείξειν, ὡς ἔστιν ἀστὴ Νέαιρα αὑτηί· ἀκούω δὲ αὐτὸν τοιοῦτόν τι μέλλειν ἀπολογεῖσθαι, ὡς οὐ γυναῖκα ἔχει αὐτὴν ἀλλ’ ἑταίραν, καὶ οἱ παῖδες οὐκ εἰσὶν ταύτης ἀλλ’ ἐξ ἑτέρας γυναικὸς αὐτῷ ἀστῆς, ἣν φήσει πρότερον γῆμαι συγγενῆ αὑτοῦ.", "st": "59.119"}, {"sp": "N", "t": "πρὸς δὴ τὴν ἀναίδειαν αὐτοῦ τοῦ λόγου καὶ τὴν παρασκευὴν τῆς ἀπολογίας καὶ τῶν μαρτυρεῖν αὐτῷ παρεσκευασμένων πρόκλησιν αὐτὸν προὐκαλεσάμην ἀκριβῆ καὶ δικαίαν, δι’ ἧς ἐξῆν ὑμῖν πάντα τἀληθῆ εἰδέναι, παραδοῦναι τὰς θεραπαίνας τὰς Νεαίρᾳ τότε προσκαρτερούσας ὅτ’ ἦλθεν ὡς Στέφανον ἐκ Μεγάρων, Θρᾷτταν καὶ Κοκκαλίνην, καὶ ἃς ὕστερον παρὰ τούτῳ οὖσα ἐκτήσατο, Ξεννίδα καὶ Δροσίδα·", "st": "59.120"}, {"sp": "N", "t": "αἳ ἴσασιν ἀκριβῶς Πρόξενόν τε τὸν τελευτήσαντα καὶ Ἀρίστωνα τὸν νῦν ὄντα καὶ Ἀντιδωρίδην τὸν σταδιοδρομοῦντα καὶ Φανὼ τὴν Στρυβήλην καλουμένην, ἣ Θεογένει τῷ βασιλεύσαντι συνῴκησεν, Νεαίρας ὄντας. καὶ ἐὰν φαίνηται ἐκ τῆς βασάνου γήμας Στέφανος οὑτοσὶ ἀστὴν γυναῖκα καὶ ὄντες αὐτῷ οἱ παῖδες οὗτοι ἐξ ἑτέρας γυναικὸς ἀστῆς καὶ μὴ Νεαίρας, ἤθελον ἀφίστασθαι τοῦ ἀγῶνος καὶ μὴ εἰσιέναι τὴν γραφὴν ταύτην.", "st": "59.121"}, {"sp": "N", "t": "τὸ γὰρ συνοικεῖν τοῦτ’ ἔστιν, ὃς ἂν παιδοποιῆται καὶ εἰσάγῃ εἴς τε τοὺς φράτερας καὶ δημότας τοὺς υἱεῖς, καὶ τὰς θυγατέρας ἐκδιδῷ ὡς αὑτοῦ οὔσας τοῖς ἀνδράσιν. τὰς μὲν γὰρ ἑταίρας ἡδονῆς ἕνεκ’ ἔχομεν, τὰς δὲ παλλακὰς τῆς καθ’ ἡμέραν θεραπείας τοῦ σώματος, τὰς δὲ γυναῖκας τοῦ παιδοποιεῖσθαι γνησίως καὶ τῶν ἔνδον φύλακα πιστὴν ἔχειν. ὥστ’ εἰ πρότερον ἔγημεν γυναῖκα ἀστὴν καὶ εἰσὶν οὗτοι οἱ παῖδες ἐξ ἐκείνης καὶ μὴ Νεαίρας, ἐξῆν αὐτῷ ἐκ τῆς ἀκριβεστάτης μαρτυρίας ἐπιδεῖξαι, παραδόντι τὰς θεραπαίνας ταύτας.", "st": "59.122"}, {"sp": "N", "t": "ὡς δὲ προὐκαλεσάμην, τούτων ὑμῖν τήν τε μαρτυρίαν καὶ τὴν πρόκλησιν ἀναγνώσεται. λέγε τὴν μαρτυρίαν, ἔπειτα τὴν πρόκλησιν.", "st": "59.123"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "59.123"}, {"sp": "N", "t": "Ἱπποκράτης Ἱπποκράτους Προβαλίσιος, Δημοσθένης Δημοσθένους Παιανιεύς, Διοφάνης Διοφάνους Ἀλωπεκῆθεν, Δεινομένης Ἀρχελάου Κυδαθηναιεύς, Δεινίας Φόρμου Κυδαντίδης, Λυσίμαχος Λυσίππου Αἰγιλιεὺς μαρτυροῦσι παρεῖναι ἐν ἀγορᾷ ὅτ’ Ἀπολλόδωρος προὐκαλεῖτο Στέφανον, ἀξιῶν παραδοῦναι εἰς βάσανον τὰς θεραπαίνας περὶ ὧν ᾐτιᾶτο Ἀπολλόδωρος Στέφανον περὶ Νεαίρας· στέφανον δ’ οὐκ ἐθελῆσαι παραδοῦναι τὰς θεραπαίνας· τὴν δὲ πρόκλησιν εἶναι ἣν παρέχεται Ἀπολλόδωρος.", "st": "59.123"}, {"sp": "N", "t": "λέγε δὴ αὐτὴν τὴν πρόκλησιν, ἣν προὐκαλούμην ἐγὼ Στέφανον τουτονί.", "st": "59.124"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "59.124"}, {"sp": "N", "t": "τάδε προὐκαλεῖτο Ἀπολλόδωρος Στέφανον περὶ ὧν τὴν γραφὴν γέγραπται Νέαιραν, ξένην οὖσαν ἀστῷ συνοικεῖν, ἕτοιμος ὢν τὰς θεραπαίνας παραλαμβάνειν τὰς Νεαίρας, ἃς ἐκ Μεγάρων ἔχουσα ἦλθεν, Θρᾷτταν καὶ Κοκκαλίνην, καὶ ἃς ὕστερον παρὰ Στεφάνῳ ἐκτήσατο, Ξεννίδα καὶ Δροσίδα, τὰς εἰδυίας ἀκριβῶς περὶ τῶν παίδων τῶν ὄντων Νεαίρᾳ, ὅτι ⟨οὐκ⟩ ἐκ Στεφάνου εἰσίν, Πρόξενός τε ὁ τελευτήσας καὶ Ἀρίστων ὁ νῦν ὢν καὶ Ἀντιδωρίδης ὁ σταδιοδρομῶν καὶ Φανώ, ἐφ’ ᾧ τε βασανίσαι αὐτάς. καὶ εἰ μὲν ὁμολογοῖεν [ἐκ Στεφάνου] εἶναι [καὶ] Νεαίρας τούτους τοὺς παῖδας, πεπρᾶσθαι Νέαιραν κατὰ τοὺς νόμους καὶ τοὺς παῖδας ξένους εἶναι· εἰ δὲ μὴ ὁμολογοῖεν ἐκ ταύτης εἶναι αὐτοὺς ἀλλ’ ἐξ ἑτέρας γυναικὸς ἀστῆς, ἀφίστασθαι τοῦ ἀγῶνος ἤθελον τοῦ Νεαίρας, καὶ εἴ τι ἐκ τῶν βασάνων βλαφθείησαν αἱ ἄνθρωποι, ἀποτίνειν ὅ τι βλαβείησαν.", "st": "59.124"}, {"sp": "N", "t": "ταῦτα προκαλεσαμένου ἐμοῦ, ἄνδρες δικασταί, Στέφανον τουτονί, οὐκ ἠθέλησεν δέξασθαι. οὔκουν ἤδη δοκεῖ ὑμῖν δεδικάσθαι ὑπ’ αὐτοῦ Στεφάνου τουτουί, ὦ ἄνδρες δικασταί, ὅτι ἔνοχός ἐστι τῇ γραφῇ Νέαιρα ἣν ἐγὼ αὐτὴν ἐγραψάμην, καὶ ὅτι ἐγὼ μὲν ἀληθῆ εἴρηκα πρὸς ὑμᾶς καὶ τὰς μαρτυρίας παρεσχόμην ἀληθεῖς, οὑτοσὶ δ’ ὅ τι ἂν λέγῃ πάντα ψεύσεται, καὶ ἐξελέγξει αὐτὸς αὑτὸν ὅτι οὐδὲν ὑγιὲς λέγει, οὐκ ἐθελήσας παραδοῦναι εἰς βασάνους τὰς θεραπαίνας ἃς ἐγὼ ἐξῄτουν αὐτόν;", "st": "59.125"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, ὦ ἄνδρες δικασταί, καὶ τοῖς θεοῖς, εἰς οὓς οὗτοι ἠσεβήκασιν, καὶ ἐμαυτῷ τιμωρῶν, κατέστησά τε τουτουσὶ εἰς ἀγῶνα καὶ ὑπὸ τὴν ὑμετέραν ψῆφον ἤγαγον. καὶ ὑμᾶς δὲ χρὴ νομίσαντας μὴ λήσειν τοὺς θεούς, εἰς οὓς οὗτοι παρανενομήκασιν, ὅ τι ἂν ἕκαστος ὑμῶν ψηφίσηται, ψηφίσασθαι τὰ δίκαια καὶ τιμωρεῖν μάλιστα μὲν τοῖς θεοῖς, ἔπειτα δὲ καὶ ὑμῖν αὐτοῖς. καὶ ταῦτα ποιήσαντες δόξετε πᾶσι καλῶς καὶ δικαίως δικάσαι ταύτην τὴν γραφήν, ἣν Νέαιραν ἐγὼ ἐγραψάμην, ξένην οὖσαν ἀστῷ συνοικεῖν.", "st": "59.126"}], []);})();
